UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Detection.DataObfuscation
description: Detect potential C2 data obfuscation via network traffic and steganography artifacts
sources:
- name: SuspiciousNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           EventData.ProcessId AS PID,
           EventData.Image AS ProcessImage,
           EventData.DestinationIp AS DestIP,
           EventData.DestinationPort AS DestPort
    FROM source(artifact="Windows.EventLogs.parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')")
    WHERE Channel = "Microsoft-Windows-Sysmon/Operational"
      AND System.EventID.Value = 3
      AND EventData.DestinationPort IN ("80", "443")
      AND NOT EventData.Image =~ "(?i)(chrome|firefox|msedge|iexplore)"
- name: SteganographyTools
  query: |
    SELECT OSPath, Name, Hash, Size
    FROM glob(globs='C:/Windows/appcompat/Programs/Amcache.hve')
    WHERE Name =~ "(?i)(openstego|stegosuite|steghide|outguess|upx|binwalk)"
- name: SuspiciousMediaFiles
  query: |
    SELECT OSPath, Size, Mtime, Atime
    FROM glob(globs=["C:/Users/*/Downloads/**", "C:/Users/*/Pictures/**", "C:/Windows/Temp/**"])
    WHERE Size > 10000000
      AND OSPath =~ "\\.(jpg|png|gif|bmp|wav|mp3|avi|mp4)$"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'f769cef6562b25e41b4f0d23bd5af6d8';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.ProcessId AS PID, EventData.Image AS ProcessImage, EventData.DestinationIp AS DestIP, EventData.DestinationPort AS DestPort, EventData.Protocol AS Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.DestinationPort IN (80, 443, 8080, 8443) AND NOT EventData.Image =~ '(?i)(chrome|firefox|msedge|iexplore|opera|brave)'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'c4b2b45e5899954291d26237cc918dfb';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$\\appdata\\|\\programdata\\') ORDER BY TimeCreated DESC|name: T1001.001_JunkDataC2Detection
description: |
  Detects potential junk data in C2 channels by analyzing network connections
  and correlating with process execution patterns across multiple log sources
sources:
- name: SysmonNetworkConnections
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer AS Computer, EventData.ProcessId as PID,\n       EventData.Image as Process, EventData.DestinationIp as DestIP,\n       EventData.DestinationPort as DestPort, EventData.Protocol as Protocol\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 3 \n  AND NOT (EventData.DestinationPort IN (80, 443, 53, 22, 21, 25, 110, 993, 995))\nORDER BY TimeCreated DESC\n"
- name: ProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer AS Computer, EventData.ProcessId as PID,
           EventData.Image as Process, EventData.CommandLine as CmdLine,
           EventData.ParentImage as ParentProcess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.Image =~ '(?i)\\\\temp\\\\|\\\\appdata\\\\|\\\\programdata\\\\'
           OR EventData.CommandLine =~ '(?i)-enc|-e |powershell|cmd\\.exe.*&')
    ORDER BY TimeCreated DESC
name: ''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1001.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a258550170623303028df18850ffbc11';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as ProcessImage, EventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort, EventData.Protocol as Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (NOT (EventData.DestinationPort IN (80, 443, 53, 22, 21, 25, 110, 993, 995)) OR EventData.Image =~ '''(?i)\\temp\|\\appdata\|\\programdata\\''') ORDER BY TimeCreated DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1001.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'd5fe51cf38d10e858102e68cb8163f73';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.Steganography
description: Detect steganographic C2 activity by correlating media file manipulation with network connections
sources:
- name: ProcessExecution
  query: "SELECT System.TimeCreated as Timestamp, EventData.Image, EventData.CommandLine, EventData.ProcessId, EventData.ParentImage\nFROM Artifact.Windows.EventLogs.Evtx \nWHERE Channel = 'Microsoft-Windows-Sysmon/Operational' AND System.EventID.Value = 1 \nAND (EventData.Image =~ '(?i)(steghide|outguess|ffmpeg|imagemagick)' OR EventData.CommandLine =~ '''(?i)\\.(jpg|png|wav|mp4)''')\n"
- name: FileCreation
  query: |
    SELECT System.TimeCreated as Timestamp, EventData.TargetFilename, EventData.ProcessId, EventData.Image
    FROM Artifact.Windows.EventLogs.Evtx
    WHERE Channel = 'Microsoft-Windows-Sysmon/Operational' AND System.EventID.Value = 11
    AND EventData.TargetFilename =~ '''(?i)\.(jpg|jpeg|png|gif|bmp|wav|mp3|mp4|avi)$'''
- name: NetworkConnections
  query: |
    SELECT System.TimeCreated as Timestamp, EventData.Image, EventData.DestinationIp, EventData.DestinationPort, EventData.ProcessId
    FROM Artifact.Windows.EventLogs.Evtx
    WHERE Channel = 'Microsoft-Windows-Sysmon/Operational' AND System.EventID.Value = 3
    AND NOT EventData.DestinationIp =~ '''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|127\.)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1001.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '1ca64f8d74fa035cb74fe71f87251926';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.ProtocolImpersonation
description: Detect T1001.003 Protocol Impersonation via network connections and DNS correlation
sources:
- name: SuspiciousNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image, EventData.ProcessId, EventData.DestinationIp, EventData.DestinationPort, EventData.DestinationHostname
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.DestinationPort IN (80,443,993,995) AND NOT EventData.Image =~ '''(?i)(chrome|firefox|msedge|iexplore|outlook)\.exe$'''
- name: DNSQueries
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image, EventData.ProcessId, EventData.QueryName, EventData.QueryResults
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 22
- name: PowerShellNetworkActivity
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.ScriptBlockText
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104 AND EventData.ScriptBlockText =~ '''(?i)(invoke-webrequest|curl|wget|net\.webclient)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1001.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '18d6df63a0656cfbf45b566e6637023a';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.EventID.Value as EventID, EventData.Image as ProcessName, EventData.ProcessId as ProcessId, EventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort, EventData.DestinationHostname as DestHostname FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (EventData.DestinationPort = 80 OR EventData.DestinationPort = 443 OR EventData.DestinationPort = 993 OR EventData.DestinationPort = 995) AND NOT EventData.Image =~ '''(?i)(chrome|firefox|msedge|iexplore|outlook)\.exe$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1001.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '2492aacee57613fbbed2cd4a8d9ea4a3';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.CredentialDumping.Detection
description: Detects OS credential dumping activities across multiple Windows log sources
sources:
- name: LSASS_ProcessAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceProcessId as SourcePID, EventData.SourceImage as SourceProcess, EventData.TargetImage as TargetProcess, EventData.GrantedAccess, EventData.CallTrace
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10 AND EventData.TargetImage =~ 'lsass.exe'
    AND EventData.GrantedAccess IN (0x1010, 0x1038, 0x1f0fff, 0x143a)
- name: SAM_RegistryAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessName, EventData.ObjectName, EventData.AccessMask
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4656, 4663) AND EventData.ObjectName =~ 'SAM'
- name: CredentialDumpingTools
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.Image =~ 'mimikatz|procdump|pwdump|lazagne|gsecdump'
    OR EventData.CommandLine =~ 'sekurlsa|lsadump|MiniDumpWriteDump|comsvcs.dll.*MiniDump')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '7c6344c64cf644d1e57f6dcc8f310417';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated,
       System.Computer AS Computer,
       EventData.SourceProcessId AS SourcePID,
       EventData.SourceImage AS SourceProcess,
       EventData.TargetProcessId AS TargetPID,
       EventData.TargetImage AS TargetProcess,
       EventData.GrantedAccess AS GrantedAccess,
       EventData.CallTrace AS CallTrace
FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
WHERE System.EventID.Value = 10
  AND EventData.TargetImage =~ '''(?i)lsass\.exe'''
  AND (EventData.GrantedAccess = 0x1010
    OR EventData.GrantedAccess = 0x1038
    OR EventData.GrantedAccess = 0x1f0fff
    OR EventData.GrantedAccess = 0x143a)$orcafix$, updated_at = NOW()
WHERE t_code = 'T1003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '6cdf28f6ff4282924d8eb9ca23a32a08';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.LSASSCredentialDumping
description: Detects LSASS credential dumping through process access and file creation correlation
sources:
- name: ProcessAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceImage as SourceImage, EventData.TargetImage as TargetImage, EventData.GrantedAccess as AccessMask
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10 AND TargetImage =~ '''lsass\.exe$''' AND EventData.GrantedAccess IN (0x1f0fff, 0x1010, 0x1410)
- name: DumpFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.TargetFilename as FilePath
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '''\.dmp$''' OR EventData.TargetFilename =~ 'lsass')
- name: SuspiciousCommands
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.CommandLine as CommandLine
