UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.LSASecretsAccess
description: Detect LSA Secrets dumping via registry access and memory extraction
sources:
- name: RegistryAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessName as ProcessName, EventData.ObjectName as ObjectName, EventData.AccessMask as AccessMask FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4656, 4663, 4670) AND EventData.ObjectName =~ 'HKLM.*SECURITY.*Policy.*Secrets'
