UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.CachedCredentialDumping
description: Detect cached domain credential dumping via registry access and process execution
sources:
- name: SecurityEventLogs
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.ObjectName as TargetObject, \n       EventData.ProcessName as ProcessName, EventData.SubjectUserName as User\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value IN (4656, 4663, 4670) \n  AND EventData.ObjectName =~ '(?i).*\\\\\\\\(SAM|SECURITY)'\n  AND format(format='0x%x', args=EventData.AccessMask) =~ '(?i).*(0x20006|0x20019|0x2001f)'\n"
- name: SysmonProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage,
           EventData.CommandLine as CommandLine, EventData.User as User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.CommandLine =~ '(?i).*(reg\\s+save|secretsdump|mimikatz|cache.*dump)'
           OR EventData.Image =~ '(?i).*(mimikatz|secretsdump)\\.exe$')
- name: SysmonProcessAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceImage as SourceImage,
           EventData.TargetImage as TargetImage, EventData.GrantedAccess as Access
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10
      AND EventData.TargetImage =~ '(?i).*lsass\\.exe$'
      AND format(format='0x%x', args=EventData.GrantedAccess) =~ '(?i).*(0x1010|0x1fffff|0x143a)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1003.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '2ccf35821494b2ed69d461770f6535c7';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, EventData.ObjectName as TargetObject, EventData.ProcessName as ProcessName, EventData.SubjectUserName as User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4656, 4663, 4670) AND EventData.ObjectName =~ '''(?i).*\\(SAM|SECURITY)''' AND format(format='0x%x', args=EventData.AccessMask) =~ '(?i).*(0x20006|0x20019|0x2001f)'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1003.005' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '411fdf2c1854e410bb451340c656363f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.DCSync
description: Detect DCSync attacks via replication API abuse across multiple log sources
sources:
- name: SecurityEventLog
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.SubjectUserName AS User, EventData.SubjectDomainName AS Domain, EventData.ObjectName AS Target, EventData.Properties AS ReplicationGUID\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') \nWHERE System.Channel = 'Security' AND System.EventID.Value IN (4662, 4929) AND (EventData.Properties =~ '1131f6aa-9c07-11d1-f79f-00c04fc2dcd2' OR System.EventID.Value = 4929)\n"
- name: AuthenticationCorrelation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.SubjectUserName AS User, EventData.LogonType AS LogonType, EventData.IpAddress AS SourceIP
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.Channel = 'Security' AND System.EventID.Value IN (4624, 4672) AND EventData.LogonType IN (2, 3, 10)
- name: PowerShellActivity
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.ScriptBlockText AS Command
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.Channel = 'Microsoft-Windows-PowerShell/Operational' AND System.EventID.Value = 4104 AND EventData.ScriptBlockText =~ '(?i)(lsadump|dcsync|mimikatz)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1003.006' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a288d306b4e506fbf43127311817209b';

