WHERE t_code = 'T1003.006' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '39d751d208e171763de2b581f2c3b33f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1005.LocalDataCollection
description: Detect local data collection activities across multiple log sources
sources:
- name: ProcessCreation
  query: "SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.NewProcessName, EventData.CommandLine, EventData.ParentProcessName \nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') \nWHERE System.EventID.Value = 4688 AND (EventData.CommandLine =~ '(?i)(dir\\\\s+/s|findstr|Get-ChildItem.*-Recurse)' OR EventData.CommandLine =~ '(?i)\\\\*\\\\.(pdf|docx?|xlsx?|kdbx|key|pem|p12)')\n"
- name: FileCreation
  query: "SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.Image, EventData.TargetFilename, EventData.ProcessId \nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '(?i)(temp|appdata).*\\\\.(zip|rar|7z|tar)$'\n"
- name: PowerShellActivity
  query: "SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.ScriptBlockText \nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx') \nWHERE System.EventID.Value = 4104 AND EventData.ScriptBlockText =~ '(?i)(Get-ChildItem|Copy-Item|Select-String).*(-Recurse|-Include|-Filter)'\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '0b8330540c2fb7f273d5fbed1b5c6088';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND ((EventData.CommandLine =~ '''(?i)(dir\s+/s|findstr|Get-ChildItem.*-Recurse)''' OR EventData.CommandLine =~ '''(?i)\*\.(pdf|docx?|xlsx?|kdbx|key|pem|p12)''') AND EventData.Image =~ '''(?i)(powershell|cmd|wmic)\.exe''') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND ((EventData.CommandLine =~ '''(?i)(dir\s+/s|findstr|Get-ChildItem.*-Recurse)''' OR EventData.CommandLine =~ '''(?i)\*\.(pdf|docx?|xlsx?|kdbx|key|pem|p12)''') AND EventData.NewProcessName =~ '''(?i)(powershell|cmd|wmic)\.exe''') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1005' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '5b447e5c06340d21068452b54041cc46';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.DirectVolumeAccess
description: Detect direct volume access techniques bypassing file system monitoring
sources:
- name: SysmonProcessAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           EventData.SourceImage as SourceImage,
           EventData.TargetObject as TargetObject,
           EventData.GrantedAccess as GrantedAccess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10
      AND EventData.TargetObject =~ '(?i)(PhysicalDrive|HarddiskVolume|\\\\\\.[\\\\][A-Z]:)'
- name: SecurityProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           EventData.NewProcessName as ProcessName,
           EventData.CommandLine as CommandLine,
           EventData.ParentProcessName as ParentProcess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688
      AND (EventData.CommandLine =~ '(?i)(ninja|vssadmin|wbadmin|esentutl|PhysicalDrive)'
           OR EventData.NewProcessName =~ '''(?i)(dd\.exe|ftk)''')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1006' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'f3c446982cb5000f9022534b8e19f172';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.T1007.SystemServiceDiscovery
