UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.FallbackChannels
description: Detect potential fallback C2 channels through network connection analysis
sources:
- name: NetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.ProcessId as PID, EventData.Image as Process,
           EventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort,
           EventData.Protocol as Protocol
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND DestPort IN (53, 80, 443, 8080, 8443)
    ORDER BY PID
- name: DNSQueries
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.ProcessId as PID, EventData.Image as Process,
           EventData.QueryName as Domain
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 22 AND Domain =~ '''\.(tk|ml|ga|cf|xyz)$'''
    ORDER BY PID
- name: FirewallBlocks
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Application as Process,
           EventData.DestAddress as BlockedIP, EventData.DestPort as BlockedPort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 5157
    ORDER BY timestamp
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1008' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '4d0cf047b3e991e7ca1432cabd57ba86';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as ProcessName, EventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort, EventData.Protocol as Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (DestPort > 1024 OR Protocol != 'tcp') AND NOT ProcessName =~ '(?i)(chrome|firefox|outlook|teams)' ORDER BY timestamp$orcafix$, updated_at = NOW()
WHERE t_code = 'T1008' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '88c5be81ee5f481c8efd37e289f5db79';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer, EventData.SourceImage, EventData.TargetImage, EventData.CallTrace FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 10 AND (EventData.CallTrace =~ 'user32.dll.*EnumWindows' OR EventData.CallTrace =~ 'user32.dll.*GetForegroundWindow' OR EventData.CallTrace =~ 'user32.dll.*GetWindowText')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1010' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '20880c0c0162861410e951ba0ce73f2a';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1011.ExfiltrationOverOtherNetworkMedium
description: Detect exfiltration over alternate network mediums (WiFi, Bluetooth, cellular)
sources:
- name: SystemEventLogs
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, System.EventID.Value, System.Provider.Name AS Provider, EventData FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx') WHERE System.EventID.Value IN (5005, 302, 20001) AND System.Provider.Name =~ "(?i)(wlansvc|bthport|wwansvc)"
- name: SysmonNetworkConnections
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.ProcessId, EventData.Image, EventData.SourceIp, EventData.DestinationIp, EventData.DestinationPort FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (EventData.Image =~ '''(?i)(rundll32|powershell|regsvr32|fsquirt)\.exe''' OR EventData.DestinationIp =~ '''^(169\.254\.|192\.168\.(43|137|173)\.)''')
- name: BluetoothRegistry
  query: |
    SELECT OSPath, Data FROM Artifact.Windows.Registry.NTUser() WHERE OSPath =~ '''HKEY_LOCAL_MACHINE\\SYSTEM\\.*ControlSet.*\\Services\\BTHPORT\\Parameters\\Devices'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1011' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '70124f174401cd3ec0dd64f0afcd2f4d';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.EventID.Value, EventData.ProcessId, EventData.Image, EventData.DestinationIp, EventData.DestinationPort, EventData.Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (EventData.Image =~ '''(?i)(rundll32|powershell|regsvr32|fsquirt)\.exe''' OR EventData.DestinationIp =~ '''^(192\.168\.(43|137|173)\.|172\.(20|21|22|23)\.|10\.(42|43)\.)''' OR EventData.DestinationIp =~ '''^169\.254\.''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1011' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'e35b5c9cfc095ace9acb117c1381799f';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.EventID.Value as EventID, System.Provider.Name as Provider, EventData.Data as EventData FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx') WHERE System.EventID.Value = 8001 AND Provider =~ "bth|bluetooth"$orcafix$, updated_at = NOW()
WHERE t_code = 'T1011.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '57b12da8d409c2cc1636993001f6cc42';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS TimeCreated, System.Computer, System.EventID.Value, EventData.Image AS ProcessImage, EventData.CommandLine, EventData.ParentImage, EventData.TargetObject AS RegistryPath FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value IN (1, 12, 13) AND (EventData.Image =~ '''reg\.exe|regedit\.exe''' OR EventData.CommandLine =~ '''reg\s+query|Get-ItemProperty|HKLM:|HKCU:''' OR EventData.TargetObject =~ '''HKLM\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion|HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1012' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'f16cb1cde83818b4f001649e5f5af90c';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1014.Rootkit
description: Detect rootkit indicators through driver loading, service installation, and file system artifacts
sources:
- name: SuspiciousDriverLoads
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ImageLoaded, EventData.Signature, EventData.SignatureStatus
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 6 AND (EventData.SignatureStatus != 'Valid' OR EventData.Signed = 'false')
- name: NewKernelServices
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ServiceName, EventData.ServiceType, EventData.ImagePath
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx')
    WHERE System.EventID.Value = 7045 AND EventData.ServiceType = 'kernel mode driver'
- name: SystemDriverFiles
  query: |
    SELECT OSPath, Name, Size, Mtime, Authenticode.Trusted, Authenticode.Subject
    FROM glob(globs='C:/Windows/System32/drivers/*.sys')
    WHERE NOT Authenticode.Trusted OR Authenticode.Subject = ''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1014' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '920a361c4bba564c1424e4b113c2d46b';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ImageLoaded, EventData.Signature, EventData.SignatureStatus, EventData.Signed FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 6 AND (EventData.SignatureStatus != 'Valid' OR EventData.Signed = 'false' OR EventData.ImageLoaded =~ '''(?i)\\temp\|\\users\|\\appdata\|[a-f0-9]{8,}\.(sys|dll)$''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1014' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '727bb3099e4651e2cc30561f1dad09a1';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1016.NetworkDiscovery
description: |
  Detects System Network Configuration Discovery across multiple log sources
  covering process execution and PowerShell activity.
sources:
- name: ProcessExecution
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.Image AS ProcessPath,
           EventData.CommandLine AS CommandLine,
           EventData.ParentImage AS ParentProcess,
           EventData.User AS User,
           'Process' AS SourceType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.Image =~ '''(?i)(ipconfig|route|arp|nbtstat|netsh)\.exe$'''
           OR EventData.CommandLine =~ '(?i)(esxcli network|show ip)')
- name: PowerShellActivity
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ScriptBlockText AS ScriptContent,
           EventData.ScriptBlockId AS ScriptId,
           'PowerShell' AS SourceType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104
      AND EventData.ScriptBlockText =~ '(?i)(Get-NetIPConfiguration|NetworkInterface|Get-NetRoute|Win32_NetworkAdapter)'
- name: PrefetchEvidence
  query: |
    SELECT OSPath, LastRunTimes, RunCount, Executable
    FROM Artifact.Windows.Forensics.Prefetch()
    WHERE Executable =~ '''(?i)(IPCONFIG|ROUTE|ARP|NBTSTAT|NETSH)\.EXE'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1016' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '31dbc6529f10bd4aed4bb4e1d6d26b81';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, EventData.Image AS ProcessPath, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(ipconfig|route|arp|nbtstat|netsh)\.exe$''' OR EventData.CommandLine =~ '(?i)(Get-NetIPConfiguration|NetworkInterface|Get-NetRoute|esxcli network)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1016' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '91ef4383314dc431dd694d548d1992b1';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: T1016_001_InternetConnectivityDiscovery
description: Detects Internet connection discovery attempts across multiple data sources
sources:
- name: SysmonProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.Computer AS Computer, EventData.Image AS Image, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentImage, EventData.User AS User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(ping|tracert|nslookup)\.exe$''' OR EventData.CommandLine =~ '''(?i)(8\.8\.8\.8|1\.1\.1\.1|google\.com|example\.com)''')
- name: PowerShellScriptExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer AS Computer, EventData.ScriptBlockText AS ScriptBlockText, EventData.Path AS Path
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value IN (4103, 4104) AND EventData.ScriptBlockText =~ '''(?i)(test-netconnection|invoke-webrequest|8\.8\.8\.8|1\.1\.1\.1)'''
- name: NetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer AS Computer, EventData.Application AS Application, EventData.SourceAddress AS SourceAddress, EventData.DestAddress AS DestAddress, EventData.DestPort AS DestPort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (5156, 5157) AND (DestAddress = '8.8.8.8' OR DestAddress = '1.1.1.1' OR DestPort = 53)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1016.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'fdc07508205f6de09d1d1029898a31fb';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS Image, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(ping|tracert|nslookup)\.exe$''' OR EventData.CommandLine =~ '''(?i)(test-netconnection|invoke-webrequest|8\.8\.8\.8|1\.1\.1\.1|google\.com|example\.com)''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1016.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '5587a4c0ca49646e930dca927a62aed1';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.WiFiDiscovery
description: Detects Wi-Fi network discovery and credential extraction attempts
sources:
- name: SysmonWiFiCommands
  query: "SELECT System.TimeCreated.SystemTime AS EventTime,\n       EventData.Image AS ProcessName,\n       EventData.CommandLine AS CommandLine,\n       EventData.ParentImage AS ParentProcess,\n       EventData.ProcessId AS PID\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 \n  AND EventData.Image =~ '''(?i)netsh\\.exe$'''\n  AND EventData.CommandLine =~ '''(?i)wlan\\s+show\\s+(profiles?|profile.+key=clear)'''\n"
- name: PowerShellWiFiActivity
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.ScriptBlockText AS ScriptContent,
           EventData.ScriptBlockId AS ScriptId,
           System.Security.UserID AS UserSID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value IN (4103, 4104)
      AND EventData.ScriptBlockText =~ '(?i)(netsh.+wlan|wlanAPI|Get-WiFi)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1016.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '4c10b454e0887dc5a4af529b94693a08';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)netsh\.exe$''' AND EventData.CommandLine =~ '''(?i)wlan\s+show\s+(profiles?|profile.+key=clear)''') OR (EventData.Image =~ '''(?i)(powershell|pwsh)\.exe$''' AND EventData.CommandLine =~ '(?i)(netsh.+wlan|wlanAPI)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1016.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '500ac421826940bad6cd6f2fa0738ff8';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.CommandLine, EventData.User, EventData.ParentImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i).*\\(net|ping|tracert|nltest|nslookup)\.exe$''' OR EventData.CommandLine =~ '(?i).*(net view|ping -[tn]|tracert|nltest /dclist|esxcli network diag).*')*24*60*60$orcafix$, updated_at = NOW()
WHERE t_code = 'T1018' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'fd3bf0e8e4a155a08160e25e1f8a35bf';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.AutomatedExfiltration
description: Detect automated exfiltration through scheduled tasks and network patterns
sources:
- name: ScheduledTaskExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId, EventData.NewProcessName, EventData.CommandLine, EventData.ParentProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND EventData.CommandLine =~ "(?i)(schtasks|taskeng|rclone|winscp|curl|powershell.*downloadstring)"
    ORDER BY EventTime DESC
- name: NetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId, EventData.Image, EventData.DestinationIp, EventData.DestinationPort, EventData.Protocol
    FROM parse_evtx(filename='C:/Windows/System32/winevt/logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.Initiated = "true" AND EventData.DestinationIsIpv6 = "false" AND NOT EventData.DestinationIp =~ '''^(10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.|127\.)'''
    ORDER BY EventTime DESC
- name: TaskSchedulerLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, EventData
    FROM parse_evtx(filename='C:/Windows/System32/winevt/logs/Microsoft-Windows-TaskScheduler%4Operational.evtx')
    WHERE System.EventID.Value IN (100, 101, 102, 106, 107, 108, 110, 111, 117, 118, 119, 129, 140, 141)
    ORDER BY EventTime DESC
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1020' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '131c241f820c59cdcfe74e910069b334';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as Image, EventData.CommandLine as CommandLine, EventData.ParentImage as ParentImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ "(?i)(rclone|winscp|curl.*http|wget.*http|powershell.*invoke-webrequest)" OR EventData.Image =~ '''(?i)(rclone\.exe|winscp\.exe|curl\.exe|wget\.exe)$''') ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1020' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '98aa5dee99941e39bbea506fad5f7ff8';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.RemoteServices.Detection
description: Detect T1021 Remote Services lateral movement across multiple log sources
sources:
- name: RemoteLogons
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.LogonType, EventData.IpAddress, EventData.TargetUserName, EventData.ProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4624, 4648) AND EventData.LogonType IN (3, 10, 4) AND EventData.IpAddress != '-'
- name: PostAccessActivity
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image AS Image, EventData.CommandLine AS CommandLine, EventData.User AS User, SourceIp
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ 'net user|whoami|tasklist|systeminfo|ipconfig'
      OR EventData.Image =~ 'powershell.exe|cmd.exe|wmic.exe')
- name: LateralConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceIp AS SourceIp, EventData.DestinationIp AS DestinationIp, EventData.DestinationPort AS DestinationPort, EventData.Image AS Image
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.DestinationPort IN (22, 3389, 445, 5985, 5986)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1021' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '4a2f15d841d7ce5625a19eb1af17569b';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.LogonType, EventData.IpAddress, EventData.TargetUserName, EventData.WorkstationName, EventData.ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4648) AND EventData.LogonType IN (3, 10, 4) AND EventData.IpAddress != '-' AND EventData.IpAddress != '127.0.0.1' ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1021' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '012075cb27871e33403e234465b3c380';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.RDP.Investigation
description: Collect RDP-related artifacts including logon events, connection manager logs, and bitmap cache
sources:
- name: RDP_Logon_Events
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.LogonType, EventData.IpAddress, EventData.TargetUserName, EventData.WorkstationName, EventData.ProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.Channel = 'Security' AND (System.EventID.Value = 4624 AND EventData.LogonType = 10) OR System.EventID.Value = 4778 OR System.EventID.Value = 4779
- name: RDP_Connection_Manager
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-TerminalServices-RemoteConnectionManager%4Operational.evtx')
    WHERE System.Channel = 'Microsoft-Windows-TerminalServices-RemoteConnectionManager/Operational' AND System.EventID.Value = 1149
- name: RDP_Bitmap_Cache
  query: |
    SELECT OSPath, Mtime, Atime, Size
    FROM glob(globs=['C:/Users/*/AppData/Local/Microsoft/Terminal Server Client/Cache/*'])
    WHERE Size > 0
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1021.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '88d37dadf90098714cd8809726b0f275';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.LogonType, EventData.IpAddress, EventData.TargetUserName, EventData.WorkstationName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4624 AND EventData.LogonType = 10 AND EventData.IpAddress != '-' AND EventData.IpAddress != NULL AND NOT EventData.TargetUserName =~ '''(?i)(SYSTEM|\$)'''$orcafix$, updated_at = NOW()
