UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.DCOM.LateralMovement
description: Detect DCOM-based lateral movement through correlated authentication, network, and process events
sources:
- name: SecurityLogons
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.LogonType as LogonType, \n       EventData.TargetUserName as Username, EventData.IpAddress as SourceIP,\n       EventData.ProcessName as ProcessName\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value IN (4624, 4648) AND EventData.LogonType = 3\n"
- name: NetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage,
           EventData.DestinationPort as DestPort, EventData.DestinationIp as DestIP
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.DestinationPort = 135
- name: SuspiciousProcesses
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, \n       EventData.ParentImage as ParentImage, EventData.CommandLine as CommandLine\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')  \nWHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(excel|outlook|mmc)\\.exe$''' OR EventData.ParentImage =~ '(?i)svchost.*dcom')\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1021.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a599fd743897640030c5d968dee9774d';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.LogonType as LogonType, EventData.TargetUserName as Username, EventData.IpAddress as SourceIP, EventData.ProcessName as ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4624 AND EventData.LogonType = 3 AND EventData.ProcessName =~ '(?i)svchost.*dcom'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1021.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '30a991b8941fcfc6d4896951ee6ae561';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: VNC.Detection.MultiSource
description: Correlate VNC process execution with authentication events and network activity
sources:
- name: VNC_Processes
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.Image, EventData.ProcessId, EventData.CommandLine, EventData.ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.Image =~ '(?i)(vnc|screensharing)'
- name: Interactive_Logons
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.LogonType, EventData.IpAddress, EventData.TargetUserName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4624, 4648) AND EventData.LogonType = 10
- name: VNC_Registry
  query: |
    SELECT Key.OSPath, Key.ModTime, ValueName, ValueData.value
    FROM Artifact.Windows.Registry.NTUser()
    WHERE Key.OSPath =~ '(?i)(realvnc|tightvnc|ultravnc)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1021.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a7f3cfbb189857359fdc32e394d4032f';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, System.EventID.Value, EventData.LogonType, EventData.IpAddress, EventData.TargetUserName, EventData.ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4648) AND EventData.LogonType = 10$orcafix$, updated_at = NOW()
