UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.WinRM.LateralMovement
description: Detect WinRM lateral movement by correlating authentication, session creation, and process execution
sources:
- name: WinRM_Sessions
  query: |
    SELECT System.TimeCreated.SystemTime, System.Computer, EventData.User as User, EventData.ClientIP as SourceIP, System.EventRecordID as RecordID
    FROM parse_evtx(filename=expand(path='%SystemRoot%/System32/winevt/logs/Microsoft-Windows-WinRM-Operational.evtx'))
    WHERE System.EventID.Value = 6
- name: Authentication_Events
  query: |
    SELECT System.TimeCreated.SystemTime, System.Computer, EventData.LogonType as LogonType, EventData.IpAddress as SourceIP, EventData.TargetUserName as User
    FROM parse_evtx(filename=expand(path='%SystemRoot%/System32/winevt/logs/Security.evtx'))
    WHERE System.EventID.Value IN (4624, 4648) AND EventData.LogonType IN ('3', '10')
- name: Process_Creation
  query: |
    SELECT System.TimeCreated.SystemTime, System.Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.User
    FROM parse_evtx(filename=expand(path='%SystemRoot%/System32/winevt/logs/Microsoft-Windows-Sysmon-Operational.evtx'))
    WHERE System.EventID.Value = 1 AND EventData.Image =~ 'wsmprovhost.exe'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1021.006' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '38de33872e9c5fc64d3e8b2a92013350';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData, Message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx') WHERE System.EventID.Value = 6$orcafix$, updated_at = NOW()
WHERE t_code = 'T1021.006' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'ba18b2600d98e0d3fee1cd23967bd08e';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.CloudServices.RemoteAccess
description: Detect remote access to cloud services via CLI tools and browser sessions
sources:
- name: CloudCLIProcesses
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.SubjectUserName AS User, EventData.NewProcessName AS Process, EventData.CommandLine AS CommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.CommandLine =~ '(?i)(Connect-AzAccount|Connect-MsgGraph|gcloud auth|aws sts)' OR EventData.NewProcessName =~ '''(?i)(aws\.exe|az\.exe|gcloud\.exe)''')
- name: CloudConsoleBrowsing
  query: |
    SELECT url, title, visit_count, last_visit_time FROM Artifact.Windows.Applications.Chrome.History() WHERE url =~ '''(?i)(portal\.azure\.com|console\.aws\.amazon\.com|console\.cloud\.google\.com|admin\.microsoft\.com)'''
- name: CloudCredentialFiles
  query: |
    SELECT OSPath, Size, Mtime, Atime FROM glob(globs=['C:/Users/*/AppData/Roaming/gcloud/credentials_db', 'C:/Users/*/.aws/credentials', 'C:/Users/*/.azure/accessTokens.json']) WHERE Mtime > timestamp(epoch=now() - 86400*7)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1021.007' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '47c2b478301a1f321a08f163f9f0ff60';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '(?i)(Connect-AzAccount|Connect-MgGraph|gcloud auth login|aws sts|az login)' OR EventData.Image =~ '''(?i)(aws\.exe|az\.exe|gcloud\.exe|powershell\.exe)''') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.CommandLine =~ '(?i)(Connect-AzAccount|Connect-MgGraph|gcloud auth login|aws sts|az login)' OR EventData.NewProcessName =~ '''(?i)(aws\.exe|az\.exe|gcloud\.exe|powershell\.exe)''') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1021.007' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'a9fe3510349376114ad414becf6440f6';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.LogonType, EventData.IpAddress, EventData.LogonProcessName, EventData.AuthenticationPackageName, EventData.TargetUserName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4624 AND (EventData.LogonType = 10 OR EventData.LogonType = 3) AND EventData.IpAddress =~ '^(?!192\.168\.|10\.|172\.(1[6-9]|2[0-9]|3[01])\.).*'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1021.008' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'cc2f7d13341f276fc0ab08a38329726b';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.RemovableMediaCollection
description: Detect data collection from removable media by correlating device insertion with file access
sources:
- name: DeviceInsertion
  query: "SELECT System.TimeCreated.SystemTime AS EventTime, \n       System.EventID.Value,\n       EventData.DeviceInstanceID\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Windows Defender%4Operational.evtx')\nWHERE System.EventID.Value = 2003\n"
- name: FileAccess
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.SubjectUserName,
           EventData.ProcessName,
           EventData.ObjectName,
           EventData.AccessMask
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4663, 4656)
      AND EventData.ObjectName =~ '''(?i)[D-Z]:\\.*\.(docx?|xlsx?|pdf|csv|txt|pptx?)$'''
- name: ProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.User,
           EventData.Image,
           EventData.CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND EventData.CommandLine =~ '''(?i)[D-Z]:\\.*'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1025' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '6c10b51247d5860db6983f81b53c8730';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.EventID.Value, EventData.SubjectUserName, EventData.ProcessName, EventData.ObjectName, EventData.AccessMask FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4663, 4656, 4670) AND EventData.ObjectName =~ '''(?i)[D-Z]:\\.*\.(docx?|xlsx?|pdf|csv|txt|pptx?)$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1025' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'd3e0706fa38226beca4f2fb691aa9223';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.ObfuscatedFilesDetection
description: Detects obfuscated files and information across multiple log sources
sources:
- name: ProcessCreationObfuscation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.NewProcessName AS ProcessName,
           EventData.CommandLine AS CommandLine,
           EventData.ParentProcessName AS ParentProcess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.Channel = 'Security' AND System.EventID.Value = 4688
      AND (CommandLine =~ '(?i)(-encodedcommand|-enc\\s+[A-Za-z0-9+/=]{20,})'
           OR CommandLine =~ '(?i)(certutil.*-encode|certutil.*-decode)'
           OR CommandLine =~ '(?i)(gzip|zip|7z|rar).*-')
- name: SuspiciousFileCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.Image AS ProcessName,
           EventData.TargetFilename AS FileName,
           EventData.ProcessId AS PID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.Channel = 'Microsoft-Windows-Sysmon/Operational' AND System.EventID.Value = 11
      AND (EventData.TargetFilename =~ '(?i)\\.(b64|enc|zip|7z|gz|xz)$'
           OR EventData.TargetFilename =~ '''(?i)temp.*\\[a-z0-9]{8,}$''')
- name: PowerShellObfuscation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ScriptBlockText AS ScriptContent,
           EventData.ScriptBlockId AS ScriptID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.Channel = 'Microsoft-Windows-PowerShell/Operational' AND System.EventID.Value = 4104
      AND (EventData.ScriptBlockText =~ '[A-Za-z0-9+/=]{50,}'
           OR EventData.ScriptBlockText =~ '(?i)(frombase64|tobase64|convert.*base64)'
           OR len(list=EventData.ScriptBlockText) > 1000 AND EventData.ScriptBlockText =~ '''[{}\[\]();,]{10,}''')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '4ad4bbf782041ea3aafee65dd2ac3d29';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS SystemTime, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)(-encodedcommand|-enc\s+[A-Za-z0-9+/=]{20,})''' OR EventData.CommandLine =~ '(?i)(certutil.*-encode|certutil.*-decode)' OR EventData.CommandLine =~ '(?i)(powershell.*frombase64|convert.*base64)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'a92b3f899c2677757d396c4451dd4c7a';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.BinaryPadding
description: |
  Detects creation and execution of potentially padded binary files by correlating
  large file creation events with subsequent process execution.
sources:
- name: Large Binary Creation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as FilePath, \n       EventData.ProcessId as ProcessId,\n       file(path=EventData.Image).Size as FileSize\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 11 AND file(path=EventData.Image).Size > 10485760 AND EventData.Image =~ '''\\.(exe|dll|bin|scr)$'''\n"
- name: Large Binary Execution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId,
           EventData.NewProcessName as ImagePath, EventData.CommandLine as CommandLine,
           file(path=EventData.NewProcessName).Size as FileSize
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND file(path=EventData.NewProcessName).Size > 10485760
- name: File Access Audit
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessName as ProcessName,
           EventData.ObjectName as ObjectName, EventData.AccessMask as AccessMask
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value in (4656, 4663, 4670) AND file(path=EventData.ObjectName).Size > 10485760
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a15f6cb17a4d84a8d15381415a15850c';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.NewProcessName as ImagePath, EventData.CommandLine as CommandLine, file(path=EventData.NewProcessName).Size as FileSize FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND file(path=EventData.NewProcessName).Size > 10485760$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '05954f7732f3d248b3a3050cb2227f78';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.SoftwarePacking
description: Detect software packing through process creation and memory access correlation
sources:
- name: ProcessCreation
  query: |
    SELECT *, hash(sha256=FullPath) AS SHA256
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
    AND (EventData.Image =~ '\\.exe$' OR EventData.Image =~ '\\.dll$')
- name: ProcessAccess
  query: |
    SELECT *
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10
    AND EventData.SourceImage != EventData.TargetImage
    AND format(format='0x%x', args=EventData.GrantedAccess) =~ '0x1F3FFF|0x1FFFFF'
    AND EventData.CallTrace =~ 'UNKNOWN'
- name: MemoryProtection
  query: |
    SELECT *
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7
    AND EventData.Signed = 'false'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'bb36afa3bd2c91deb2f3c1632f98f3c2';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT * FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 10 AND EventData.SourceImage != EventData.TargetImage AND format(format='0x%x', args=EventData.GrantedAccess) =~ '0x1F3FFF|0x1FFFFF' AND EventData.CallTrace =~ 'UNKNOWN'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'b8a996e6d671fe70711b648254e3bf47';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.Steganography
description: Detect steganographic abuse through process lineage and file access correlation
sources:
- name: ProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, EventData.Image, EventData.ParentImage, EventData.CommandLine, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)(mspaint|photos|imageview)\.exe''' OR EventData.CommandLine =~ '''(?i)\.(png|jpg|jpeg|gif|bmp)''')
- name: FileAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, EventData.ProcessName, EventData.ObjectName, EventData.AccessMask
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4656, 4663) AND EventData.ObjectName =~ '''(?i)\.(png|jpg|jpeg|gif|bmp)$'''
- name: NetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, EventData.Image, EventData.DestinationIp, EventData.DestinationPort, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.Image =~ '''(?i)(powershell|python|cmd)\.exe'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '4e73dd90b2edb8790a7d6daf30aff7ac';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime), System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ParentImage, EventData.CommandLine, EventData.ProcessId, EventData.ParentProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)(mspaint|photos|imageview|irfanview)\.exe''' OR EventData.CommandLine =~ '''(?i)\.(png|jpg|jpeg|gif|bmp)''' OR EventData.Image =~ '''(?i)(steghide|invoke-psimage|python|powershell)\.exe''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '1db830c592cd8cb5d6f8a70670364d1a';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1027_004.CompileAfterDelivery
description: Detect compile-after-delivery by correlating compiler execution with subsequent binary creation and network activity
sources:
- name: CompilerExecution
  query: |
    SELECT System.TimeCreated.SystemTime AS CompileTime, EventData.Image AS Compiler, EventData.CommandLine AS Args, EventData.ProcessId AS PID, EventData.User AS User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.Image =~ '(?i)(csc|ilasm|msbuild|gcc|clang)'
    AND NOT EventData.ParentImage =~ '(?i)(devenv|visualstudio)'
- name: FileCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS CreateTime, EventData.TargetFilename AS FilePath, EventData.ProcessId AS PID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\.(exe|dll|so|dylib)$'''
    AND (EventData.TargetFilename =~ '(?i)(temp|tmp|public|downloads)' OR EventData.TargetFilename =~ '''(?i)users\\''')
- name: NetworkConnections
  query: |
    SELECT System.TimeCreated.SystemTime AS ConnTime, EventData.Image AS ProcessPath, EventData.DestinationIp AS DestIP, EventData.DestinationPort AS DestPort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.Initiated = 'true'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '2fe55fc0a29ea3cff914874b1762e4db';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image AS ProcessPath, EventData.ParentImage AS ParentProcess, EventData.CommandLine AS CommandLine, EventData.ProcessId AS PID, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(csc|ilasm|msbuild|vbc)\.exe$''' OR EventData.Image =~ '(?i)gcc|clang') AND NOT (EventData.ParentImage =~ '(?i)(devenv|msbuild|visualstudio)' OR EventData.User =~ '(?i)(SYSTEM|LOCAL SERVICE|NETWORK SERVICE)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '173e80aea6b5bd884b37bdcd0e2b6d20';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1027005.IndicatorRemovalCorrelation
description: Correlate AV detections with subsequent file creation and process execution
sources:
- name: AVDetections
  query: |
    SELECT System.TimeCreated.SystemTime AS DetectionTime, EventData.Data AS ThreatInfo, System.EventID.Value FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Windows Defender%4Operational.evtx') WHERE System.EventID.Value = 1000 AND EventData.Data =~ '(?i)(detected|quarantined|threat)'
- name: SubsequentFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.TargetFilename AS TargetFilename, EventData.ProcessGuid AS ProcessGuid, EventData.Image AS Image FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11
- name: ProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image AS Image, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentImage, EventData.ProcessGuid AS ProcessGuid FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '03cbbbe14696d11f367e613ae08bebbe';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Hunt.HTMLSmuggling
description: Detect HTML Smuggling via file creation and Zone.Identifier analysis
sources:
- name: SysmonFileCreation
  query: |
    SELECT System.TimeCreated.SystemTime as EventTime, EventData.ProcessId as PID, EventData.Image as ProcessImage, EventData.TargetFilename as CreatedFile, EventData.ProcessGuid as ProcessGuid FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND EventData.Image =~ '''(?i)(chrome|msedge|iexplore|firefox|outlook)\.exe''' AND EventData.TargetFilename =~ '(?i)(temp|download)' AND EventData.TargetFilename =~ '''(?i)\.(exe|js|hta|zip|iso|img)$'''
- name: ZoneIdentifierADS
  query: |
    SELECT OSPath, Mtime, ZoneId, HostUrl, ReferrerUrl FROM Artifact.Windows.Forensics.AlternateDataStreams() WHERE ZoneId AND (HostUrl =~ 'about:internet' OR HostUrl =~ 'blob:' OR ReferrerUrl =~ '''\.html''')
- name: ProcessExecution
  query: |
    SELECT System.TimeCreated.SystemTime as EventTime, EventData.ProcessId as PID, EventData.Image as ProcessImage, EventData.CommandLine as CommandLine, EventData.ParentImage as ParentImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.ParentImage =~ '''(?i)(chrome|msedge|iexplore|firefox)\.exe''' AND EventData.Image =~ '''(?i)\.(exe|js|hta)$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.006' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '862892566d4b29a99efcb48edb58e917';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) as EventTime, EventData.ProcessId as PID, EventData.Image as ProcessImage, EventData.TargetFilename as CreatedFile, EventData.ProcessGuid as ProcessGuid FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND (EventData.Image =~ '''(?i)(chrome|msedge|iexplore|firefox)\.exe''' OR EventData.Image =~ '''(?i)outlook\.exe''') AND EventData.TargetFilename =~ '(?i)(temp|download)' AND EventData.TargetFilename =~ '''(?i)\.(exe|js|hta|zip|iso|img)$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.006' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '7d3b9f784b2734fa959637dd57518bdb';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.DynamicAPIResolution
description: Detect dynamic API resolution techniques using correlation of process creation, module loading, and API usage patterns
sources:
- name: SysmonProcessAndModules
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           System.EventID.Value,
           EventData.Image AS ProcessPath,
           EventData.ProcessId,
           EventData.ImageLoaded AS LoadedModule,
           EventData.CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE (System.EventID.Value = 1 OR System.EventID.Value = 7)
      AND EventData.ProcessId IN (
        SELECT EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
        WHERE System.EventID.Value = 7 AND NOT EventData.ImageLoaded =~ '''(?i)(kernel32|ntdll|user32|advapi32)\.dll$'''
      )
- name: KernelProcessEvents
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           System.EventID.Value,
           EventData.*
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value IN (1, 2, 5) AND EventData.Image =~ '''(?i)\.(exe|dll|scr)$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.007' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '0536a2f75548ff3fe18ec8e670158bff';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, System.EventID.Value, System.Computer, EventData.Image AS ProcessPath, EventData.ImageLoaded AS LoadedModule, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND NOT EventData.ImageLoaded =~ '''(?i)(kernel32|ntdll|user32|advapi32|shell32|ole32|oleaut32|msvcrt|ws2_32)\.dll$''' AND EventData.Image =~ '''(?i)\.(exe|dll|scr)$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.007' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '5df2db938e5b841480af8c184cfb4fdf';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.StrippedPayloads
description: Detect creation and execution of stripped/obfuscated payloads across file creation and process events
sources:
- name: FileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.Computer AS Computer, EventData.Image as ParentProcess, EventData.TargetFilename as FilePath, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''\.(exe|dll|scr)$'''
- name: ProcessExecution
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.Computer AS Computer, EventData.Image as ProcessPath, EventData.CommandLine, EventData.ParentImage, EventData.ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 1 AND EventData.Image =~ '''\\.(exe|scr)$'''\n"
- name: FileMetadata
  query: |
    SELECT OSPath, Size, hash(path=OSPath) as Hash, Mtime, Ctime
    FROM glob(globs=['C:/Users/*/AppData/**/*.exe', 'C:/Windows/Temp/**/*.exe', 'C:/Temp/**/*.exe'])
    WHERE Mtime > now() - 86400
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.008' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '4a15fc0d5974aede4e52e249eb0d0515';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime), System.Computer AS Computer, EventData.Image as ProcessPath, EventData.CommandLine, EventData.ParentImage, EventData.TargetFilename as CreatedFile, EventData.Hashes FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''\.(exe|dll|scr)$''' AND EventData.ParentImage =~ '(?i)(temp|downloads|appdata|programdata)'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.008' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '196834140f7482cf59baffaddec5b202';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1027_009.EmbeddedPayloads
description: Detect embedded payloads through process creation and file creation correlation
sources:
- name: ProcessCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image as ProcessName, EventData.CommandLine, EventData.ParentImage, EventData.ProcessId, EventData.ParentProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 1 AND EventData.Image =~ '''(?i)\\\\(temp|appdata)\\\\.*\\.(exe|dll|scr)$'''\n"
- name: FileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.TargetFilename, EventData.ProcessId, EventData.Image as CreatingProcess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\\(temp|appdata)\\.*\.(exe|dll|scr)$'''
- name: PEOverlays
  query: |
    SELECT OSPath, Size, hash(path=OSPath) as Hash, Mtime
    FROM glob(globs='C:\\**\\*.{exe,dll,scr}')
    WHERE Size > 1048576 AND OSPath =~ '''(?i)\\(temp|appdata|downloads)\\'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.009' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '5a9d67b680c2273de726588b19ade97f';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image as ProcessName, EventData.CommandLine, EventData.ParentImage, EventData.ProcessId, EventData.ParentProcessId, EventData.User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)\\(explorer|winword|excel|powerpnt|acrobat|acrord32)\.exe$''' OR EventData.ParentImage =~ '''(?i)\\temp\\''' OR EventData.ParentImage =~ '''(?i)\\appdata\\''') AND EventData.Image =~ '''(?i)\\(temp|appdata)\\.*\.(exe|dll|scr)$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.009' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '836fc7d473efdcd12729a4884c2bf2bf';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.CommandObfuscation
description: |
  Detects obfuscated command execution across multiple Windows log sources
  focusing on T1027.010 Command Obfuscation techniques.
sources:
- name: SecurityEventLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           'Security' as LogSource,
           EventData.NewProcessName as ProcessName,
           EventData.CommandLine as CommandLine,
           EventData.ParentProcessName as ParentProcess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688
      AND (EventData.CommandLine =~ '''(?i)(encodedcommand|[A-Za-z0-9+/]{30,}={0,2}|\\\^.{5,}|iex\s|invoke-expression|frombase64string)'''
           OR len(list=EventData.CommandLine) > 200)
- name: PowerShellOperational
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           'PowerShell' as LogSource,
           System.EventID.Value as EventID,
           EventData.ScriptBlockText as ScriptContent
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104
      AND EventData.ScriptBlockText =~ '''(?i)(-join|-replace|\[char\]|frombase64string|-f\s+["\'][^"\']|reverse\(\))'''
- name: SysmonProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           'Sysmon' as LogSource,
           EventData.Image as ProcessName,
           EventData.CommandLine as CommandLine,
           EventData.ParentImage as ParentProcess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.CommandLine =~ '''(?i)(\\\.\.\\.*\\\.\.\|%[A-Z_]+%.*%[A-Z_]+%|\\\^.{8,})'''
           OR len(list=EventData.CommandLine) > 250)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.010' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a19c423330c736b08e55c74951137549';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)(encodedcommand|[A-Za-z0-9+/]{30,}={0,2}|iex\s|invoke-expression|frombase64string)''' OR len(str=EventData.CommandLine) > 300) LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.CommandLine =~ '''(?i)(encodedcommand|[A-Za-z0-9+/]{30,}={0,2}|iex\s|invoke-expression|frombase64string)''' OR len(str=EventData.CommandLine) > 300) SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.010' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '7e137bbb54d1a8c3254181971c3ca78f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.LNKIconSmuggling
description: Detects LNK Icon Smuggling technique T1027.012 by correlating LNK execution with network activity and file creation
sources:
- name: LNKExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as Image, EventData.CommandLine as CommandLine, EventData.ParentImage as ParentImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (CommandLine =~ '''(?i)\.lnk''' OR Image =~ '''(?i)explorer\.exe''' AND CommandLine =~ '''(?i)\.lnk''')
- name: NetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as Image, EventData.DestinationIp as DestinationIp, EventData.DestinationPort as DestinationPort FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (Image =~ '''(?i)explorer\.exe|winword\.exe|excel\.exe|powerpnt\.exe''')
- name: FileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as Image, EventData.TargetFilename as TargetFilename, EventData.Hash as Hash FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 15
- name: LNKFiles
  query: |
    SELECT OSPath, Size, Mtime, Atime, Ctime FROM glob(globs='C:/Users/*/Recent/*.lnk,C:/Users/*/Desktop/*.lnk,C:/Users/*/Downloads/*.lnk') WHERE Mtime > now() - 86400
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.012' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a14b0e07a55d6afe9678fc5fc8e9ce96';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as Image, EventData.CommandLine as CommandLine, EventData.ParentImage as ParentImage, EventData.ParentCommandLine as ParentCommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (CommandLine =~ '''(?i)\.lnk''' OR ParentCommandLine =~ '''(?i)\.lnk''' OR Image =~ '''(?i)explorer\.exe''' AND CommandLine =~ '''(?i)\.lnk''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.012' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '081d05fa3e80d0aa9cbf62397360ca6f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1027_015_Compression
description: Detect compression-based payload obfuscation through process and file correlation
sources:
- name: CompressionProcesses
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ProcessId, EventData.ParentProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.Image =~ '''(?i)(7z|winrar|makecab|compress|zip)\.exe$'''
- name: ArchiveFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.TargetFilename, EventData.ProcessId, EventData.Image FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\.(zip|rar|7z|cab|gz)$'''
- name: PostExtractionExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.Image =~ '''(?i)(temp|tmp|appdata).*\.(exe|dll|scr)$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.015' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '34ec2d5c6b36bed8187a740013317bc3';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image as ProcessName, EventData.CommandLine, EventData.ParentImage, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(7z|winrar|makecab|compress|zip)\.exe$''' OR EventData.CommandLine =~ '''(?i)\.(zip|rar|7z|cab|gz)''' OR EventData.CommandLine =~ '(?i)(compress|archive|extract)') AND EventData.CommandLine =~ '''(?i)\.(exe|dll|scr|bat|ps1)'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.015' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '9eb0a3728773fadf8029371b2853072b';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.Detection.JunkCodeInsertion
description: |
  Detects potential junk code insertion by correlating large executable creation
  with rapid execution and suspicious memory access patterns.
sources:
- name: SuspiciousLargeExecutables
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           EventData.Image as ProcessImage,
           EventData.CommandLine as CommandLine,
           stat(path=EventData.Image).Size as FileSize,
           EventData.CurrentDirectory as CurrentDir
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.Image =~ '(?i)(temp|appdata|public|users)'
           OR EventData.CurrentDirectory =~ '(?i)(temp|appdata|public)')
      AND stat(path=EventData.Image).Size > 5242880
- name: MemoryInjectionAttempts
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           EventData.SourceImage as SourceImage,
           EventData.TargetImage as TargetImage,
           EventData.GrantedAccess as AccessRights,
           EventData.CallTrace as CallTrace
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10
      AND EventData.SourceImage =~ '(?i)(temp|appdata|public)'
      AND format(format='0x%x', args=EventData.GrantedAccess) =~ '(?i)(0x1f0fff|0x1fffff)'
- name: SuspiciousFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           EventData.TargetFilename as FilePath,
           EventData.Image as CreatingProcess,
           stat(path=EventData.TargetFilename).Size as FileSize
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11
      AND EventData.TargetFilename =~ '''(?i)\.(exe|dll|scr|com|bat|cmd)$'''
      AND EventData.TargetFilename =~ '(?i)(temp|appdata|public)'
      AND stat(path=EventData.TargetFilename).Size > 2097152
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.016' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '7d0381f6bb9d7d76afb9ee0d6e380bd3';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.SVGSmuggling
description: Detect SVG smuggling by correlating file creation with script execution and network activity
sources:
- name: SVG_Files
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) as SVGTime, EventData.ProcessGuid AS ProcessGuid, EventData.TargetFilename AS TargetFilename, EventData.Image as Creator
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\.svgz?$'''
- name: Script_Execution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) as ExecTime, EventData.ProcessGuid AS ProcessGuid, EventData.ParentProcessGuid AS ParentProcessGuid, EventData.Image AS Image, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(wscript|cscript|mshta|rundll32|powershell)\.exe$''' OR EventData.ParentImage =~ '''(?i)(chrome|firefox|msedge|iexplore)\.exe$''')
- name: Network_Connections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) as NetTime, EventData.ProcessGuid AS ProcessGuid, EventData.DestinationHostname AS DestinationHostname, EventData.DestinationIp AS DestinationIp, EventData.DestinationPort AS DestinationPort, EventData.Image AS Image
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.017' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'e3340d0a6c715c1d670001bdae0f2b54';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime), System.Computer AS Computer, System.EventID.Value, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.TargetFilename AS TargetFilename, EventData.ProcessGuid AS ProcessGuid FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\.svgz?$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1027.017' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '147883e58f593c9ad9daf1e666d1fd06';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Scheduled.Transfer.Detection
description: Detects scheduled data exfiltration patterns across process execution and network connections
sources:
- name: ScheduledTasks
  query: |
    SELECT Name, TaskPath, State, Actions, Triggers, LastRunTime, NextRunTime
    FROM glob(globs='C:/Windows/System32/Tasks/**')
    WHERE Actions =~ '(ftp|sftp|scp|rsync|curl|wget|powershell.*invoke-webrequest)'
- name: RecurringNetworkConnections
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image AS Image, EventData.DestinationIp AS DestinationIp, EventData.DestinationPort AS DestinationPort, EventData.ProcessId AS ProcessId, \n       count() as ConnectionCount\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 3 AND DestinationIsIpv4 = 'true'\nAND NOT EventData.DestinationIp =~ '''^(10\\.|172\\.(1[6-9]|2[0-9]|3[01])\\.|192\\.168\\.)'''\nGROUP BY DestinationIp, Image\nHAVING ConnectionCount > 5\n"
- name: SchedulerExecutions
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.TaskName AS TaskName, EventData.ActionName AS ActionName, EventData.ResultCode AS ResultCode
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-TaskScheduler%4Operational.evtx')
    WHERE System.EventID.Value IN (106, 200, 201)
    AND EventData.TaskName =~ '(?i)(backup|sync|transfer|export|upload)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1029' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'f008e65369400763a8815f40d95915c6';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, CommandLine, ParentImage, EventData.DestinationIp AS DestinationIp, EventData.DestinationPort AS DestinationPort FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND DestinationIsIpv4 = 'true' AND NOT EventData.DestinationIp =~ '''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.)''' GROUP BY DestinationIp, ProcessName HAVING count() > 3$orcafix$, updated_at = NOW()
