UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.UserDiscovery
description: Detect T1033 System Owner/User Discovery across multiple log sources
sources:
- name: SysmonProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.Computer AS Computer, EventData.Image as Process, EventData.CommandLine, EventData.ParentImage, EventData.User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(whoami|net|quser|query)\.exe$''' OR EventData.CommandLine =~ '(?i)(whoami|net user|quser|query user)')
- name: PowerShellScriptBlock
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer AS Computer, EventData.ScriptBlockText, EventData.Path
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104 AND EventData.ScriptBlockText =~ '''(?i)(Get-LocalUser|Get-WmiObject.*Win32_UserAccount|\$env:USERNAME|whoami)'''
- name: PrefetchEvidence
  query: |
    SELECT OSPath, LastRunTimes, RunCount
    FROM Artifact.Windows.Forensics.Prefetch()
    WHERE OSPath =~ '''(?i)(WHOAMI|NET|QUSER|QUERY)\.EXE'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1033' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'd689281cdee0db537c728ab82f1b1aba';

