UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1036.Masquerading
description: Detect masquerading techniques including renamed system utilities and metadata mismatches
sources:
- name: SysmonProcessCreation
  query: "SELECT System.TimeCreated.SystemTime, System.Computer, EventData.Image as ProcessPath, \n       EventData.CommandLine, EventData.OriginalFileName, \n       EventData.ProcessId, EventData.ParentProcessId\nFROM parse_evtx(filename=expand(path='%SystemRoot%/System32/winevt/logs/Microsoft-Windows-Sysmon%4Operational.evtx'))\nWHERE System.EventID.Value = 1 AND EventData.OriginalFileName AND NOT EventData.OriginalFileName = basename(path=EventData.Image)\n"
- name: ServiceInstallations
  query: "SELECT System.TimeCreated.SystemTime, System.Computer, EventData.ServiceName, \n       EventData.ImagePath, EventData.ServiceType\nFROM parse_evtx(filename=expand(path='%SystemRoot%/System32/winevt/logs/System.evtx'))\nWHERE System.EventID.Value = 7045 AND (EventData.ServiceName =~ '(?i)(svchost|winlogon|lsass|csrss)' OR EventData.ImagePath =~ '(?i)users.public|temp|appdata')\n"
- name: SuspiciousSystemBinaries
  query: |
    SELECT OSPath, Size, Mtime, Ctime, Btime,
           hash(path=OSPath, hashselect='SHA256') as SHA256
    FROM glob(globs=['C:/Users/**/{svchost,lsass,winlogon,csrss,explorer}.exe','C:/Temp/**/{svchost,lsass,winlogon,csrss,explorer}.exe','C:/ProgramData/**/{svchost,lsass,winlogon,csrss,explorer}.exe'])
    WHERE NOT OSPath =~ '(?i)c:.windows.system32'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1036' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '874ad1011c870b51293353475cf95041';

