UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.RTLO_Masquerading
description: Detects Right-to-Left Override character abuse in filenames and process execution
sources:
- name: Sysmon Process Creation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath, EventData.CommandLine, EventData.ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.Image =~ '[\x{202E}]' OR EventData.CommandLine =~ '[\x{202E}]')
- name: MFT RTLO Files
  query: |
    SELECT OSPath.Path as FilePath, OSPath.Basename as FileName, StandardInformation.CreateTime, StandardInformation.ModifyTime
    FROM glob(globs='C:/Users/*/Downloads/*', 'C:/Windows/Temp/*', 'C:/Users/*/AppData/Local/Temp/*')
    WHERE OSPath.Basename =~ '[\x{202E}]'
- name: PowerShell Script Execution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ScriptName, EventData.ScriptBlockText
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE (System.EventID.Value = 4103 OR System.EventID.Value = 4104) AND (EventData.ScriptName =~ '[\x{202E}]' OR EventData.ScriptBlockText =~ '[\x{202E}]')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1036.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'c0e8a9021029e8f044fdcacc71419b33';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.RenamedUtilities
description: Detect renamed legitimate utilities through PE metadata mismatches and suspicious execution paths
sources:
- name: SysmonProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ImagePath,
           EventData.OriginalFileName as PEOriginalName,
           EventData.CommandLine, EventData.User,
           split(sep='\\', string=EventData.Image)[-1] as DiskFileName,
           EventData.ParentImage, EventData.ProcessGuid
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.OriginalFileName
      AND NOT EventData.OriginalFileName = split(sep='\\', string=EventData.Image)[-1]
      AND (EventData.Image =~ '(?i)(temp|appdata|users|public)'
           OR EventData.OriginalFileName =~ '''(?i)(rundll32|powershell|cmd|psexec|regsvr32|mshta|cscript|wscript)\.exe''')
- name: PrefetchAnalysis
  query: "SELECT OSPath, ExecutableName, Hash, RunCount, \n       LastRunTimes, PrefetchHash\nFROM Artifact.Windows.Forensics.Prefetch()\nWHERE ExecutableName != basename(path=OSPath)\n   OR OSPath =~ '''(?i)(temp|appdata|users|public|programdata).*\\.(exe|scr|com|pif)$'''\n"
- name: AmcacheEntries
  query: |
    SELECT OSPath, SHA1, OriginalFileName, FileDescription,
           ProductName, BinaryType, IsOSComponent
    FROM Artifact.Windows.Registry.Amcache()
    WHERE OriginalFileName AND basename(path=OSPath) != OriginalFileName
       AND (OriginalFileName =~ '''(?i)(rundll32|powershell|cmd|psexec|regsvr32|mshta)\.exe'''
            OR OSPath =~ '(?i)(temp|appdata|users|public)')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1036.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a6cee957745cbda1e53f4173f20cd855';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ImagePath, EventData.OriginalFileName as PEOriginalName, EventData.CommandLine, EventData.ParentImage, split(sep='\\', string=EventData.Image)[-1] as DiskFileName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.OriginalFileName AND NOT EventData.OriginalFileName = split(sep='\\', string=EventData.Image)[-1] AND (EventData.OriginalFileName =~ '''(?i)(rundll32|powershell|cmd|psexec|regsvr32|mshta|cscript|wscript)\.exe''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1036.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '35943283f1c4cf592f10ca2dde2e4278';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.MasqueradedTasksServices
description: Detect masqueraded Windows services and scheduled tasks with deceptive naming
sources:
- name: MasqueradedServices
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ServiceName, EventData.ImagePath, EventData.ServiceType\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx')\nWHERE System.EventID.Value = 7045 \nAND EventData.ServiceName =~ '(?i)(microsoft|windows|defender|update|security)'\nAND NOT EventData.ImagePath =~ '(?i)(c:\\\\\\\\windows\\\\\\\\system32|c:\\\\\\\\program files\\\\\\\\windows defender)'\n"
- name: MasqueradedTasks
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TaskName, EventData.ClientProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4698
    AND EventData.TaskName =~ '(?i)(microsoft|windows|defender|update|security)'
- name: SuspiciousTaskFiles
  query: |
    SELECT OSPath, Mtime, Size, hash(path=OSPath, hashselect='MD5') as Hash
    FROM glob(globs=['C:/Windows/System32/Tasks/**'])
    WHERE OSPath =~ '(?i)(microsoft|windows|defender|update|security)'
    AND NOT OSPath =~ '(?i)\\\\microsoft\\\\windows\\\\'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1036.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'becbadf6901b826d130d53d94f1eeeaa';

