WHERE t_code = 'T1036.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '45fbf8c4bde06d0ec70a6726932b8a04';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.DoubleExtensionMasquerading
description: Detect double file extension masquerading by correlating file creation with process execution
sources:
- name: SuspiciousFileCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetFilename as FilePath, EventData.ProcessId as CreatorPID\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 11 \nAND EventData.TargetFilename =~ '(?i)\\\\[^\\\\]+\\.(txt|jpg|pdf|doc|gif|png)\\.(exe|scr|hta|bat|vbs|pif)$'\n"
- name: DoubleExtensionExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath, EventData.CommandLine, EventData.ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
    AND EventData.Image =~ '(?i)\\[^\\]+\.(txt|jpg|pdf|doc|gif|png)\.(exe|scr|hta|bat|vbs|pif)$'
- name: RecentLNKFiles
  query: |
    SELECT OSPath, Mtime, TargetPath, Arguments
    FROM glob(globs='C:/Users/*/AppData/Roaming/Microsoft/Windows/Recent/*.lnk')
    WHERE TargetPath =~ '(?i)\\[^\\]+\.(txt|jpg|pdf|doc)\.(exe|scr|hta)$'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1036.007' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '32e1b1579530621f5da9901e9f46dffa';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer, EventData.Image as ProcessPath, EventData.CommandLine, EventData.ParentImage, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.Image =~ '(?i)\\[^\\]+\.(txt|jpg|pdf|doc|gif|png)\.(exe|scr|hta|bat|vbs|pif)$'$orcafix$, updated_at = NOW()
