UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1036_008.FileTypeMasquerading
description: Detect masquerading via file type modification by correlating file creation and process execution events
sources:
- name: SysmonFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetFilename, EventData.ProcessId, EventData.Image
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\.(jpg|jpeg|gif|png|txt|pdf|doc|docx)$''' AND (EventData.TargetFilename =~ '''(?i)\\(temp|download|appdata)\\''' OR EventData.TargetFilename =~ '(?i)\\users\\[^\\]+\\(downloads|documents|desktop)\\')
- name: SysmonProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)\.(jpg|jpeg|gif|png|txt|pdf|doc|docx)$''' OR EventData.CommandLine =~ '''(?i)\.(jpg|jpeg|gif|png|txt|pdf|doc|docx)''')
- name: FileHeaderAnalysis
  query: |
    SELECT OSPath, Size, Mtime, Atime, Ctime,
           read_file(filename=OSPath, length=16) as FileHeader
    FROM glob(globs=['C:/Users/*/Downloads/**', 'C:/Temp/**', 'C:/Windows/Temp/**', 'C:/Users/*/AppData/**'])
    WHERE Name =~ '''(?i)\.(jpg|jpeg|gif|png|txt|pdf|doc|docx)$'''
    AND Mtime > now() - 604800
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1036.008' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'ce30030eca584214c33853a5ab2b57da';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.ProcessId, EventData.ParentProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)\.(jpg|jpeg|gif|png|txt|pdf|doc|docx)(\.exe)?$''' OR EventData.Image =~ '(?i)\\[^\\]*\.(jpg|jpeg|gif|png|txt|pdf|doc|docx)$')$orcafix$, updated_at = NOW()
