UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1037.BootLogonScripts
description: Detect Boot or Logon Initialization Scripts persistence across registry, file system, and event logs
sources:
- name: RegistryRunKeys
  query: |
    SELECT Key.OSPath as KeyPath, Key.ModTime as LastModified, ValueName, ValueData.value as Value
    FROM Artifact.Windows.Registry.NTUser()
    WHERE KeyPath =~ '''SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\(Run|RunOnce|Group Policy)'''
- name: SecurityEventLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.EventID.Value, EventData.NewProcessName, EventData.CommandLine, EventData.ObjectName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4688, 4657) AND (EventData.CommandLine =~ '(?i)(startup|scripts)' OR EventData.ObjectName =~ '(?i)(run|startup|scripts)')
- name: StartupFiles
  query: |
    SELECT OSPath, Mtime, Size, IsDir
    FROM Artifact.Windows.NTFS.MFT()
    WHERE OSPath =~ '(?i)(startup|sysvol.*scripts|programdata.*startup)' AND NOT IsDir
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1037' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '11a1d1532996c3d9b6dd25b335f2b391';

