UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1039.NetworkShareAccess
description: Detect data collection from network shared drives across multiple log sources
sources:
- name: WindowsSecurityLogs
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ShareName as ShareName, \n       EventData.SubjectUserName as Username, EventData.ProcessName as ProcessName,\n       EventData.AccessMask as AccessMask, EventData.AccessList as AccessList\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value = 5145\n"
- name: SysmonFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName,
           EventData.TargetFilename as TargetFile, EventData.User as Username
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '(?i)^[A-Z]:\\\\.*\\\\.*'
- name: ShellBagsNetworkAccess
  query: |
    SELECT OSPath, Key.ModTime as AccessTime, Username
    FROM Artifact.Windows.Registry.NTUser.ShellBags()
    WHERE OSPath =~ '(?i)\\\\\\\\.*\\\\.*'
$orcafix$, updated_at = NOW()
