UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.WMI.Execution
description: Detect WMI abuse through process creation and WMI activity correlation
sources:
- name: WMI Process Creation
  query: "SELECT System.TimeCreated as ProcessTime, System.Computer, EventData.Image, EventData.CommandLine, EventData.ProcessId, EventData.ParentProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value=1\nAND (EventData.Image =~ '''(?i)wmic\\.exe$''' OR EventData.Image =~ '''(?i)wmiprvse\\.exe$''' \n     OR (EventData.Image =~ '''(?i)powershell\\.exe$''' AND EventData.CommandLine =~ '(?i)(Invoke-WmiMethod|Get-WmiObject)'))\n"
- name: WMI Activity Events
  query: |
    SELECT System.TimeCreated as WMITime, System.Computer, System.EventID.Value, UserData
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-WMI-Activity%4Operational.evtx')
    WHERE System.EventID.Value IN (5857, 5858, 5860, 5861)
- name: WMI Network Connections
  query: |
    SELECT System.TimeCreated as NetTime, System.Computer, EventData.Image, EventData.DestinationIp, EventData.DestinationPort, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value=3
    AND EventData.DestinationPort IN (135, 5985, 5986)
    AND EventData.Image =~ '''(?i)(wmic|wmiprvse|powershell)\.exe$'''
