UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.ExfiltrationAlternativeProtocol
description: Detect exfiltration over alternative protocols by correlating file access with network connections
sources:
- name: NetworkConnections
  query: "SELECT timestamp(epoch=System.TimeCreated) AS EventTime,\n       EventData.ProcessId, EventData.Image, \n       EventData.DestinationIp, EventData.DestinationPort,\n       EventData.Protocol\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 3 \n  AND (EventData.DestinationPort IN (21, 25, 53, 69, 123)\n       OR EventData.Image =~ '''(?i)(ftp|curl|net)\\.exe$''')\n"
- name: FileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated) AS EventTime,
           EventData.ProcessId, EventData.Image,
           EventData.TargetFilename
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11
      AND EventData.TargetFilename =~ '(?i)\\(temp|tmp|users\\[^\\]+\\appdata)\\'
- name: ProcessCreation
