    SELECT timestamp(epoch=TimeCreated) AS EventTime,
           EventData.NewProcessId AS NewProcessId, EventData.NewProcessName AS NewProcessName, EventData.CommandLine AS CommandLine,
           EventData.ParentProcessName AS ParentProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
