UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1048_001_SymmetricExfiltration
description: Detect exfiltration over symmetric encrypted non-C2 protocols by correlating process execution with network connections
sources:
- name: SysmonProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ProcessId
