- name: SysmonNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ProcessId, EventData.DestinationIp, EventData.DestinationPort, EventData.Protocol
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.Initiated = 'true' AND NOT (EventData.Image =~ '''(?i)(chrome|firefox|outlook|teams)\.exe$''') AND NOT (EventData.DestinationIp =~ '''^(10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.|127\.)''')
- name: PowerShellCrypto
