    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ScriptBlockText
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value IN (4103, 4104) AND EventData.ScriptBlockText =~ '(?i)(aes|rc4|encrypt|cipher|convertto-securestring)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1048.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '04d5fee0a8825527644be7d6ffcdb747';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.CommandLine, EventData.DestinationIp, EventData.DestinationPort, EventData.Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND NOT (EventData.Image =~ '''(?i)(chrome|firefox|outlook|teams|skype)\.exe$''') AND EventData.Initiated = 'true' AND NOT (EventData.DestinationIp =~ '''^(10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.)''') ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
