           EventData.ProcessName AS ProcessName,
           EventData.ObjectName AS FilePath,
           EventData.AccessMask AS AccessType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4663
      AND EventData.ObjectName =~ '''(?i)\.(zip|7z|rar|tar|gz|db|xlsx?|docx?|pdf)$'''
      AND EventData.AccessMask = 0x1
