UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.ScheduledTaskAbuse
description: Detect malicious scheduled task creation and execution patterns across multiple log sources
sources:
- name: TaskCreationEvents
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TaskName as TaskName, EventData.TaskContent as Command, EventData.TaskContent as Author
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4698 AND (EventData.TaskContent != 'Microsoft Corporation' OR EventData.TaskContent =~ 'powershell|cmd|wscript')
- name: TaskExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as Image, EventData.CommandLine as CommandLine, EventData.ParentImage as ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
