- name: TaskFiles
  query: |
    SELECT OSPath, Mtime, Size, hash(path=OSPath) as Hash
    FROM glob(globs='C:/Windows/System32/Tasks/**')
    WHERE Mtime > now() - 86400
$orcafix$, updated_at = NOW()
