    SELECT System.TimeCreated.SystemTime, System.Computer, EventData.SourceProcessId as SourcePID, EventData.TargetProcessId as TargetPID, EventData.SourceImage, EventData.TargetImage, EventData.GrantedAccess FROM parse_evtx(filename=srcDir + '/Windows/System32/winevt/logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 10 AND (EventData.GrantedAccess = '0x1F0FFF' OR EventData.GrantedAccess = '0x1FFFFF' OR EventData.GrantedAccess = '0x143A')
