- name: ProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime, System.Computer, EventData.ProcessId as PID, EventData.Image, EventData.CommandLine, EventData.ParentProcessId, EventData.ParentImage FROM parse_evtx(filename=srcDir + '/Windows/System32/winevt/logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1
