UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.ThreadExecutionHijacking
description: |
  Detects Thread Execution Hijacking (T1055.003) by correlating process access,
  remote thread creation, and suspicious API call patterns.
sources:
- name: ProcessAccess
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.SourceProcessId, EventData.SourceImage,
           EventData.TargetProcessId, EventData.TargetImage,
           EventData.GrantedAccess, EventData.CallTrace
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10
      AND (format(format='0x%x', args=EventData.GrantedAccess) =~ '0x1F0FFF' OR format(format='0x%x', args=EventData.GrantedAccess) =~ '0x143A')
      AND NOT EventData.SourceImage =~ '''(?i)(System|csrss\.exe|wininit\.exe)'''
- name: RemoteThreadCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.SourceProcessId, EventData.SourceImage,
           EventData.TargetProcessId, EventData.TargetImage,
           EventData.StartAddress, EventData.StartFunction
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 8
- name: ProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ProcessId, EventData.Image,
           EventData.ParentProcessId, EventData.ParentImage,
           EventData.CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1055.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'd7e128cce625fddfe30026f04be00230';

