UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.ProcessDoppelganging
description: Detect Process Doppelgänging technique using TxF transactions and suspicious process creation patterns
sources:
- name: SysmonProcessCreation
  query: |
    SELECT System.TimeCreated as Timestamp, EventData.Image, EventData.ProcessId, EventData.ParentImage, EventData.CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.Image =~ '''(?i)(svchost|calc|notepad)\.exe$'''
