  query: |
    SELECT System.TimeCreated as Timestamp, EventData.SourceProcessId, EventData.TargetProcessId, EventData.TargetImage, EventData.GrantedAccess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10 AND format(format='0x%x', args=EventData.GrantedAccess) =~ '(?i)(0x1f3fff|0x1fffff)'
- name: KernelProcessETW
  query: |
    SELECT TimeCreated, EventID, EventData
    FROM Artifact.Windows.EventLogs.ETW()
    WHERE Provider.Name = 'Microsoft-Windows-Kernel-Process' AND EventData =~ '(?i)(CreateTransaction|CreateFileTransacted|RollbackTransaction)'
