UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.CredentialAPIHooking
description: Detect credential harvesting via API hooking by correlating process access, image loads, and thread creation in credential-sensitive processes
imports:
- Windows.EventLogs.Evtx
sources:
- name: ProcessAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceImage, EventData.TargetImage, EventData.GrantedAccess, EventData.CallTrace
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10 AND (EventData.TargetImage =~ 'lsass.exe$' OR EventData.TargetImage =~ 'explorer.exe$' OR EventData.TargetImage =~ 'winlogon.exe$')
    AND (EventData.GrantedAccess = 0x1fffff OR EventData.GrantedAccess = 0x1010)
- name: SuspiciousImageLoads
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId, EventData.Image, EventData.ImageLoaded, EventData.Signed
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7 AND (EventData.Image =~ 'lsass.exe$' OR EventData.Image =~ 'explorer.exe$')
    AND (EventData.Signed = 'false' OR EventData.ImageLoaded NOT =~ 'System32')
- name: RemoteThreadCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceProcessId, EventData.SourceImage, EventData.TargetProcessId, EventData.TargetImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 8 AND (EventData.TargetImage =~ 'lsass.exe$' OR EventData.TargetImage =~ 'explorer.exe$' OR EventData.TargetImage =~ 'winlogon.exe$')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1056.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '9fa418143095946d640b3612f6566d2d';

