    WHERE System.EventID.Value = 10 AND CallTrace =~ '(?i)CreateToolhelp32Snapshot'
- name: SysmonProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image as ProcessName,
           EventData.CommandLine as CommandLine, EventData.ParentImage as ParentProcess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
