UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '(?i)(tasklist|wmic.*process|Get-Process)' OR EventData.Image =~ '''(?i)(tasklist\.exe|wmic\.exe)$''') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.CommandLine =~ '(?i)(tasklist|wmic.*process|Get-Process)' OR EventData.NewProcessName =~ '''(?i)(tasklist\.exe|wmic\.exe)$''') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
