UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.PowerShellDetection
description: Comprehensive PowerShell abuse detection across multiple log sources
sources:
- name: PowerShellScriptBlocks
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           System.Computer AS Computer,
           System.EventID.Value AS EventID,
           EventData.ScriptBlockText AS ScriptContent,
           EventData.MessageNumber AS MessageNumber,
           EventData.MessageTotal AS MessageTotal
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value IN (4103, 4104, 4105, 4106)
- name: PowerShellProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           System.Computer AS Computer,
           EventData.Image AS ProcessPath,
           EventData.CommandLine AS CommandLine,
           EventData.ParentImage AS ParentImage,
           EventData.ParentCommandLine AS ParentCommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.Image =~ '''(?i)powershell\.exe$'''
           OR EventData.CommandLine =~ '''(?i)(-enc|-encodedcommand|-nop|-noprofile|-executionpolicy\s+bypass|iex|downloadstring)''')
- name: PowerShellHistory
  query: |
    LET _hist = SELECT OSPath, Mtime FROM glob(globs='C:/Users/*/AppData/Roaming/Microsoft/Windows/PowerShell/PSReadLine/ConsoleHost_history.txt')
    SELECT _hist.OSPath AS OSPath,
           _hist.Mtime AS LastModified,
           Line AS Command
    FROM parse_lines(filename=_hist.OSPath)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1059.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '2d2bebc2122eb11c36be326b48666432';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.T1059_003_CmdShellDetection
description: |
  Detects Windows Command Shell (cmd.exe) abuse by analyzing process creation events,
  parent-child relationships, and associated batch file activity.
sources:
- name: SecurityEventLogs
  query: |
    SELECT System.TimeCreated.SystemTime as EventTime,
           EventData.NewProcessName as ProcessName,
           EventData.ParentProcessName as ParentProcess,
           EventData.CommandLine as CommandLine,
           EventData.SubjectUserName as User,
           EventData.ProcessId as PID,
           EventData.ProcessId as PPID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688
      AND EventData.NewProcessName =~ '''(?i)cmd\.exe$'''
      AND (EventData.CommandLine =~ '''(?i)/[ck]\s+''' OR
           EventData.ParentProcessName =~ '''(?i)(winword|excel|powerpnt|outlook|msedge|chrome|firefox|sqlservr|w3wp)\.exe$''')
- name: BatchFileArtifacts
  query: |
    SELECT OSPath, Name, Size, Mtime, Ctime, Atime
    FROM glob(globs=['C:/Users/*/AppData/Local/Temp/*.bat',
                     'C:/Users/*/AppData/Local/Temp/*.cmd',
                     'C:/Users/Public/*.bat',
                     'C:/Users/Public/*.cmd',
                     'C:/Windows/Temp/*.bat',
                     'C:/Windows/Temp/*.cmd'])
    WHERE Mtime > timestamp(epoch=now() - 7*24*60*60)
- name: ShimcacheAnalysis
  query: |
    SELECT ExecutableName, LastModified, LastUpdate, Path
    FROM Artifact.Windows.Registry.AppCompatCache()
    WHERE ExecutableName =~ '''(?i)cmd\.exe$'''
       OR Path =~ '''(?i)\.(bat|cmd)$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1059.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '5ec42b708552ce5afa00c4919e82c661';

