UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.CloudAPI.CommandExecution
description: Detects cloud API abuse through CLI tools and PowerShell modules
sources:
- name: ProcessCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer AS Computer, EventData.CommandLine, EventData.NewProcessName, EventData.ParentProcessName\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') \nWHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''(?i)(az\\.exe|aws\\.exe|gcloud\\.exe)''' \nOR EventData.CommandLine =~ '''(?i)(Connect-Az|Set-Az|aws\\s+iam|gcloud\\s+compute)''')\n"
- name: PowerShellScriptBlock
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer AS Computer, EventData.ScriptBlockText, EventData.ScriptBlockId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104 AND EventData.ScriptBlockText =~ '''(?i)(Connect-Az|Set-Az|New-Az|Remove-Az|Import-Module.*Az\.)'''
- name: CloudCLIHistory
  query: |
    SELECT OSPath, Size, Mtime, upload(file=OSPath) AS Content
    FROM glob(globs=['C:/Users/*/\.aws/cli/history', 'C:/Users/*/\\.azure/commands/*'])
    WHERE Mtime > now() - 86400*7
