UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Detect.LuaExecution
description: |
  Detects Lua interpreter execution and associated script file creation across Windows systems
  focusing on T1059.011 Command and Scripting Interpreter: Lua
sources:
- name: LuaProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.TimeCreated.SystemTime AS EventTime,
           EventData.Image AS ProcessName,
           EventData.ParentImage AS ParentProcess,
           EventData.CommandLine,
           EventData.User,
           EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.Image =~ '''(?i)lua\.exe$'''
        OR EventData.Image =~ '''(?i)luajit\.exe$'''
        OR EventData.Image =~ '''(?i)luac\.exe$'''
        OR EventData.CommandLine =~ '''(?i)\.lua\b''')
- name: LuaScriptCreation
