UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.PrivilegeEscalationExploitation
description: Detect exploitation for privilege escalation via vulnerable drivers and process spawning patterns
sources:
- name: VulnerableDriverLoads
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ImageLoaded, EventData.ProcessId, EventData.Signature, EventData.SignatureStatus
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 6 AND (EventData.ImageLoaded =~ '''(?i)(capcom\.sys|RTCore64\.sys|HW64\.sys|AsIO64\.sys|WinRing0x64\.sys|procexp\.sys)''' OR EventData.SignatureStatus = 'Expired')
- name: PrivilegeEscalationProcesses
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId, EventData.Image, EventData.CommandLine, EventData.IntegrityLevel, EventData.ParentImage, EventData.ParentProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.IntegrityLevel = 'System' AND EventData.ParentImage =~ '''(?i)(explorer\.exe|cmd\.exe|powershell\.exe|winword\.exe|excel\.exe|outlook\.exe)'''
- name: SpecialPrivilegesAssigned
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName, EventData.PrivilegeList, EventData.ProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4672 AND EventData.PrivilegeList =~ '(?i)(SeDebugPrivilege|SeTakeOwnershipPrivilege|SeLoadDriverPrivilege)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1068' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '0baf778f704b159c4bb75191157327bd';

