UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1070.IndicatorRemoval
description: Detects indicator removal activities across multiple log sources and file operations
sources:
- name: EventLogClearing
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.Channel AS Channel, System.EventID.Value AS EventID, EventData.SubjectUserName as User, Message\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE (System.Channel = 'Security' AND System.EventID.Value = 1102) OR (Channel = 'System' AND System.EventID.Value = 104)\n"
- name: SysmonFileDeletion
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as PID, EventData.Image as Process,
           EventData.TargetFilename as DeletedFile, EventData.User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 23
          AND EventData.TargetFilename =~ '''(?i)\.(evtx|log|pf)$|prefetch'''
- name: RegistryLogTampering
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetObject as RegistryKey,
           EventData.Details as NewValue, EventData.Image as Process
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value IN (13, 14)
          AND EventData.TargetObject =~ '(?i)EventLog|Audit'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1070' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '5ff60cb2cdbfdf1443be2bc5e19fb559';

