UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.ProcessId as PID, EventData.TargetFilename as DeletedFile, EventData.User as User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 23 AND EventData.TargetFilename =~ '''(?i)\\(temp|tmp|programdata|appdata)\\.*\.(exe|dll|bat|ps1|vbs|js)$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1070.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'e662146e88859059f87f3936c90c1f7e';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1070_005.NetworkShareRemoval
description: Detect network share connection removal via multiple data sources
sources:
- name: SysmonProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, 'Sysmon' AS Source, EventData.ProcessId AS PID, EventData.CommandLine AS CommandLine, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)net\s+use.*\/delete''' OR EventData.CommandLine =~ '(?i)Remove-SmbMapping')
- name: PowerShellCommands
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, 'PowerShell' AS Source, EventData.ContextInfo AS HostApp, EventData.ScriptBlockText AS Command FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx') WHERE System.EventID.Value IN (4103, 4104) AND (EventData.ScriptBlockText =~ '(?i)Remove-SmbMapping' OR EventData.ScriptBlockText =~ '''(?i)net\s+use.*\/delete''')
- name: SecurityLogons
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, 'Security' AS Source, EventData.LogonType AS LogonType, EventData.IpAddress AS SourceIP, EventData.TargetUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4624 AND EventData.LogonType = 3
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1070.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '2fa94bbd92e4479712b03b5a27d292e1';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, System.EventID.Value AS EventID, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, System.Security.UserID AS UserSID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)net\s+use.*\/delete''' OR EventData.CommandLine =~ '(?i)Remove-SmbMapping' OR EventData.CommandLine =~ '''(?i)Remove-PSDrive.*-PSProvider\s+FileSystem''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1070.005' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '0d6ac6f8c66837f92babe64b509ae7a7';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData, Message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 15 AND (EventData.CreationUtcTime > EventData.PreviousCreationUtcTime OR EventData.CreationUtcTime != EventData.PreviousCreationUtcTime)$orcafix$, updated_at = NOW()
WHERE t_code = 'T1070.006' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '90a0b2334d149b2d4d75e18d96ddc5e1';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1070_007.NetworkConnectionHistoryClearing
description: Detect clearing of network connection history across registry, files, and process execution
sources:
- name: WindowsRDPRegistryAccess
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.SubjectUserName AS SubjectUserName, EventData.ObjectName AS ObjectName, EventData.ProcessName AS ProcessName\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') \nWHERE System.EventID.Value IN (4663, 4656, 4670) \nAND EventData.ObjectName =~ '(?i).*Terminal Server Client.*'\n"
- name: SuspiciousCommandExecution
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.CommandLine AS CommandLine, EventData.User AS User\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 \nAND (EventData.CommandLine =~ '''(?i).*Terminal Server Client.*|.*Default\\.rdp.*|.*reg.*delete.*''' OR\n     EventData.Image =~ '''(?i).*\\\\reg\\.exe$|.*\\\\powershell\\.exe$''')\n"
- name: RDPFileAccess
  query: "SELECT OSPath, Name, Size, Mtime, Atime, Ctime, Btime\nFROM Artifact.Windows.Sys.Filesystem() \nWHERE OSPath =~ '''(?i).*Default\\.rdp$|.*Terminal Server Client.*Cache.*'''\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1070.007' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '3ce52fb7a07576a748aa01156f718f32';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, EventData.SubjectUserName AS SubjectUserName, EventData.ObjectName AS ObjectName, EventData.ProcessName AS ProcessName, EventData.ProcessId AS ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4663, 4656, 4670) AND EventData.ObjectName =~ '''(?i).*Terminal Server Client.*|.*Default\.rdp.*''' ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1070.007' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '7eed25cb82a873414a4cd4ec7b1e7df9';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.MailboxDataClearing
description: Detect mailbox data clearing via PowerShell cmdlets and file deletion
sources:
- name: PowerShellExchangeCmdlets
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ScriptBlockText as Command, EventData.User as User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value IN (4103, 4104) AND EventData.ScriptBlockText =~ '(?i)(Remove-MailboxExportRequest|Search-Mailbox.*-DeleteContent|Remove-StoreMailbox|New-TransportRule|Set-TransportRule)'
- name: OutlookDataDeletion
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetFilename AS TargetFilename, EventData.User AS User, EventData.Image AS ProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 23 AND (EventData.TargetFilename =~ '''(?i)\\Unistore\\data\\''' OR EventData.TargetFilename =~ '''(?i)\.(ost|pst)$''')
- name: MailboxFileAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ObjectName AS ObjectName, EventData.SubjectUserName AS SubjectUserName, EventData.AccessMask AS AccessMask
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4663, 4656) AND EventData.ObjectName =~ '''(?i)(\.(ost|pst)|Unistore|Exchange)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1070.008' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'fe4c90fda700f45211f81407f53e82b6';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ScriptBlockText as Command, EventData.User as User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell/Operational.evtx') WHERE System.EventID.Value IN (4103, 4104) AND EventData.ScriptBlockText =~ '(?i)(Remove-MailboxExportRequest|Search-Mailbox.*-DeleteContent|Remove-StoreMailbox|New-TransportRule|Set-TransportRule.*header|Get-Mailbox.*-ResultSize)'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1070.008' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '7422a8f93b2bf3ef7ef160591496f1b1';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.ClearPersistence
description: "Detects adversary removal of persistence artifacts including services, \nscheduled tasks, registry entries, and user accounts across multiple log sources.\n"
sources:
- name: SysmonProcessExecution
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, \n       EventData.CommandLine, EventData.ProcessId, EventData.ParentImage\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 AND EventData.CommandLine =~ '''(?i)(sc\\s+delete|schtasks\\s+/delete|reg\\s+delete.*\\\\(run|runonce)|net\\s+user\\s+.*\\s+/delete)'''\n"
- name: SecurityAccountDeletions
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetUserName, EventData.SubjectUserName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4726
- name: TaskSchedulerDeletions
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TaskName, EventData.UserName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-TaskScheduler%4Operational.evtx')
    WHERE System.EventID.Value = 106
- name: RegistryKeyDeletions
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ObjectName, EventData.SubjectUserName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4657 AND EventData.ObjectName =~ '''(?i).*\\(run|runonce|services|currentversion\\windows\\run)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1070.009' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'f8c4dc3e2f54627221eb26681671f20c';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.CommandLine, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)(sc\s+delete|schtasks\s+/delete|reg\s+delete.*\\(run|runonce)|net\s+user\s+.*\s+/delete|userdel|crontab\s+-r|rm\s+.*\.plist)''' OR EventData.Image =~ '''(?i)(sc\.exe|schtasks\.exe|reg\.exe|net\.exe)$''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1070.009' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '512d1278c860e1dd320494550f5bd87f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.MalwareRelocation
description: Detect malware relocation via file creation, deletion, and move patterns
sources:
- name: SysmonFileCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, \n       EventData.TargetFilename as CreatedFile, EventData.ProcessGuid,\n       'FileCreate' as EventType\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 11 \n  AND (EventData.TargetFilename =~ '(?i)(system32|windows|programfiles)' \n       OR EventData.TargetFilename =~ '''(?i)temp.*\\.(exe|dll|bat|js)$''')\n"
- name: SysmonFileDeletion
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage,
           EventData.TargetFilename as DeletedFile, EventData.ProcessGuid,
           'FileDelete' as EventType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 23
- name: MFTFileMovement
  query: "SELECT OSPath, FileName, ParentPath, Created0x10, Modified0x10,\n       Changed0x10, Accessed0x10\nFROM parse_mft(filename='C:/$MFT')\nWHERE (ParentPath =~ '(?i)(system32|windows)' OR OSPath =~ '(?i)temp') \n  AND FileName =~ '''\\.(exe|dll|bat|js)$'''\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1070.010' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '72cc5a7929a633dcdd9da32661f088bc';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.TargetFilename as FilePath, EventData.ProcessGuid FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '(?i)(system32|windows|programfiles)' OR EventData.TargetFilename =~ '''(?i)(temp.*\.(exe|dll|bat|js)$)''') ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1070.010' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '348cdcd5f0ed3a4aeb36ab85460ecbfe';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: T1071.ApplicationLayerProtocol
description: Detect suspicious application layer protocol usage for command and control
sources:
- name: SysmonNetworkConnections
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ProcessId as PID, \n       EventData.Protocol, EventData.SourceIp, EventData.DestinationIp, EventData.DestinationPort\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 3 \n  AND NOT EventData.Image =~ '''(?i)(chrome\\.exe|firefox\\.exe|msedge\\.exe|iexplore\\.exe|teams\\.exe|outlook\\.exe)$'''\n  AND EventData.Initiated = 'true'\n  AND (EventData.DestinationPort IN (80, 443, 53, 8080, 8443))\n"
- name: SysmonDNSQueries
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ProcessId as PID,
           EventData.QueryName, EventData.QueryResults
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 22
      AND NOT EventData.Image =~ '''(?i)(chrome\.exe|firefox\.exe|msedge\.exe|iexplore\.exe|teams\.exe|outlook\.exe|svchost\.exe)$'''
      AND (len(list=EventData.QueryName) > 50 OR EventData.QueryName =~ '[0-9a-f]{20,}')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1071' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '0762c134cafce953f0120dafafa6f3a8';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ProcessId as PID, EventData.Protocol, EventData.SourceIp, EventData.SourcePort, EventData.DestinationIp, EventData.DestinationPort FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND NOT EventData.Image =~ '''(?i)(chrome\.exe|firefox\.exe|msedge\.exe|iexplore\.exe|teams\.exe|outlook\.exe)$''' AND (EventData.DestinationPort = 80 OR EventData.DestinationPort = 443 OR EventData.DestinationPort = 53) AND EventData.Initiated = 'true'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1071' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '47e4a40e21e672a9f07eac83399349b4';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.ProcessId, EventData.DestinationIp, EventData.DestinationPort, EventData.Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.DestinationPort IN (80, 443, 8080, 8443) AND NOT EventData.Image =~ '''(?i)(chrome|firefox|msedge|iexplore|opera)\.exe$''' AND EventData.DestinationIp =~ '^(?!10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|127\.).*'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1071.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'e7b259476b7c2223d2408655f4696233';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1071_002.FileTransferProtocolC2
description: Detect file transfer protocol-based C2 communications across process execution and network activity
sources:
- name: SysmonNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.DestinationIp, EventData.DestinationPort, EventData.Protocol
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND (EventData.DestinationPort IN (21, 69, 445, 990) OR EventData.Image =~ '''(?i)(powershell|cmd|rundll32)\.exe$''') AND EventData.Initiated = "true"
- name: FTPClientConfigs
  query: "SELECT OSPath, Size, Mtime, read_file(filename=OSPath, length=10000) as Content\nFROM glob(globs=[\n  \"C:/Users/*/AppData/Roaming/FileZilla/sitemanager.xml\",\n  \"C:/Users/*/AppData/Roaming/FileZilla/recentservers.xml\", \n  \"C:/Users/*/.ftppass\",\n  \"C:/Users/*/.netrc\"\n])\n"
- name: ProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(ftp|tftp|winscp|filezilla)\.exe$''' OR EventData.CommandLine =~ '''(?i)(ftp\s+-|tftp\s+-|scp\s+-)''')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1071.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '58760a7657cba740e126c329ab8f6759';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image as ProcessPath, EventData.CommandLine, EventData.DestinationIp, EventData.DestinationPort, EventData.Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (EventData.DestinationPort IN (21, 69, 445, 990) OR EventData.Image =~ '''(?i)(ftp|tftp|winscp|filezilla)\.exe$''' OR EventData.Image =~ '''(?i)(powershell|cmd|rundll32)\.exe$''') AND EventData.Initiated = "true"$orcafix$, updated_at = NOW()
WHERE t_code = 'T1071.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '8f2779c0a488e7273fe18b7370a05e93';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: T1071_003_MailProtocolC2Detection
description: Detect suspicious mail protocol usage for C2 communication
sources:
- name: SysmonNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer as Computer, EventData.Image as ProcessImage, EventData.ProcessId as PID, EventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND (EventData.DestinationPort = 25 OR EventData.DestinationPort = 587 OR EventData.DestinationPort = 993 OR EventData.DestinationPort = 995 OR EventData.DestinationPort = 465)
    AND EventData.Image =~ '''(?i)(powershell|rundll32|cmd|cscript|wscript)\.exe$'''
- name: SysmonProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer as Computer, EventData.Image as ProcessImage, EventData.CommandLine as CommandLine, EventData.ProcessId as PID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)(smtp|imap|pop3|Send-MailMessage|System\.Net\.Mail)''' OR EventData.Image =~ '''(?i)(sendmail|mailx)\.exe$''')
- name: PowerShellHistory
  query: |
    SELECT OSPath, Mtime, Line
    FROM glob(globs='C:/Users/*/AppData/Roaming/Microsoft/Windows/PowerShell/PSReadLine/ConsoleHost_history.txt')
    WHERE Line =~ '''(?i)(Send-MailMessage|System\.Net\.Mail|smtp|imap|pop3)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1071.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '4e53c184c60621ec769f66aeebcd2068';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ProcessId as PID, EventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort, EventData.Protocol as Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (EventData.DestinationPort = 25 OR EventData.DestinationPort = 587 OR EventData.DestinationPort = 993 OR EventData.DestinationPort = 995 OR EventData.DestinationPort = 465) AND EventData.Image =~ '''(?i)(powershell|rundll32|cmd|cscript|wscript)\.exe$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1071.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '9f1ea3ef8fc2f7c991d7b3da3d2de088';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.DNS.Tunneling.Detection
description: Detect DNS tunneling and C2 communication via DNS queries
sources:
- name: SysmonDNSQueries
  query: |
    SELECT timestamp, System.Computer, ProcessId, Image, EventData.QueryName as QueryName, EventData.QueryResults as QueryResults,
           len(list=split(string=EventData.QueryName, sep='.')[0]) as SubdomainLength
    FROM parse_evtx(filename=expand(path='%SystemRoot%/System32/winevt/logs/Microsoft-Windows-Sysmon%4Operational.evtx'))
    WHERE System.EventID.Value = 22 AND (
      len(list=split(string=EventData.QueryName, sep='.')[0]) > 40 OR
      EventData.QueryName =~ '''(?i)[a-z0-9]{15,}\.''' OR
      EventData.Image =~ '''(?i)(powershell|rundll32|python|cmd|wscript|cscript)\.exe$'''
    )
- name: SysmonNetworkConnections
  query: |
    SELECT timestamp, System.Computer, ProcessId, Image, DestinationPort, DestinationIp
    FROM parse_evtx(filename=expand(path='%SystemRoot%/System32/winevt/logs/Microsoft-Windows-Sysmon%4Operational.evtx'))
    WHERE System.EventID.Value = 3 AND DestinationPort = 53 AND
          Image =~ '''(?i)(powershell|rundll32|python|cmd|wscript|cscript)\.exe$'''
- name: PowerShellDNSCommands
  query: |
    SELECT timestamp, System.Computer, EventData.ScriptBlockText as Command
    FROM parse_evtx(filename=expand(path='%SystemRoot%/System32/winevt/logs/Microsoft-Windows-PowerShell%4Operational.evtx'))
    WHERE System.EventID.Value = 4104 AND EventData.ScriptBlockText =~ '''(?i)(resolve-dnsname|nslookup|\[system\.net\.dns\])'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1071.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '662c19c4fbf5c3c6dec89362b57b7213';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.ProcessGuid AS ProcessGuid, EventData.Image AS Image, EventData.QueryName AS QueryName, EventData.QueryResults AS QueryResults FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 22 AND (len(list=split(string=EventData.QueryName, sep='.')[0]) > 50 OR EventData.QueryName =~ '''(?i)[a-z0-9]{20,}\.''' OR EventData.Image =~ '''(?i)(powershell|rundll32|python|cmd)\.exe$''') ORDER BY timestamp DESC$orcafix$, updated_at = NOW()
