UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1071_005.PubSubProtocols
description: Detect publish/subscribe protocol abuse for C2 communications
sources:
- name: SysmonNetworkConnections
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.ProcessId, EventData.Image, EventData.User,
           EventData.DestinationIp, EventData.DestinationPort,
           EventData.Protocol
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
      AND (EventData.DestinationPort IN (1883, 5222, 5672, 8883, 61613))
      AND NOT EventData.Image =~ '''(?i)(chrome|firefox|edge|safari)\.exe$'''
- name: SysmonDNSQueries
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.ProcessId, EventData.Image,
           EventData.QueryName, EventData.QueryResults
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 22
      AND EventData.QueryName =~ '(?i)(mqtt|broker|hivemq|emqx|rabbitmq|activemq)'
- name: ProcessExecution
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.ProcessId, EventData.Image,
           EventData.CommandLine, EventData.User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.CommandLine =~ '(?i)(mqtt|amqp|stomp|xmpp|mosquitto)'
           OR EventData.Image =~ '(?i)(mosquitto|paho)')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1071.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '7877674fc38ea9d009230d045d97bdff';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.ProcessId, EventData.Image, EventData.DestinationIp, EventData.DestinationPort, EventData.Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (EventData.DestinationPort = 1883 OR EventData.DestinationPort = 5222 OR EventData.DestinationPort = 5672 OR EventData.DestinationPort = 8883 OR EventData.DestinationPort = 61613) AND NOT EventData.Image =~ '''(?i)(chrome|firefox|edge|safari)\.exe$'''$orcafix$, updated_at = NOW()
