UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1072.SoftwareDeploymentTools
description: Detect abuse of software deployment tools across multiple log sources
sources:
- name: SecurityEventLogs
  query: "SELECT System.TimeCreated.SystemTime AS EventTime, EventData.NewProcessName AS ProcessName, EventData.ParentProcessName AS ParentProcess, EventData.CommandLine AS CommandLine\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') \nWHERE System.EventID.Value = 4688 AND EventData.ParentProcessName =~ '''(?i)(ccmexec\\.exe|pdqinventory\\.exe|IntuneManagementExtension\\.exe)''' AND EventData.SubjectUserName = 'SYSTEM'\n"
- name: SystemServiceInstalls
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.ServiceName AS ServiceName, EventData.ImagePath AS ImagePath
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx')
    WHERE System.EventID.Value = 7045
- name: SCCMClientLogs
  query: "SELECT OSPath, Size, Mtime\nFROM glob(globs='C:/Windows/CCM/Logs/*.log') \nWHERE Mtime > timestamp(epoch=now() - 86400)\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1072' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '85459fbf4c47ce617ce7ab875dd2f521';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)(ccmexec\.exe|pdqinventory\.exe|IntuneManagementExtension\.exe|wsmprovhost\.exe)''' AND EventData.User =~ '(?i)(system|networkservice)' AND EventData.Image =~ '''(?i)(powershell\.exe|cmd\.exe|wscript\.exe|cscript\.exe|mshta\.exe)''') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.ParentProcessName =~ '''(?i)(ccmexec\.exe|pdqinventory\.exe|IntuneManagementExtension\.exe|wsmprovhost\.exe)''' AND EventData.SubjectUserName =~ '(?i)(system|networkservice)' AND EventData.NewProcessName =~ '''(?i)(powershell\.exe|cmd\.exe|wscript\.exe|cscript\.exe|mshta\.exe)''') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1072' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '2291df08a240034fc41d68e42a082af0';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.DataStaging
description: Detect data staging activities by correlating file creation in staging directories with compression tool execution
sources:
- name: CompressionProcesses
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.Image AS ProcessPath, EventData.CommandLine AS CmdLine, EventData.ProcessId AS PID, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.Image =~ '''(?i)(7z|rar|zip|tar)\.exe$'''
- name: StagingFileCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.TargetFilename AS FilePath, EventData.ProcessId AS PID, EventData.Image AS ProcessImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '''(?i)(temp|public|programdata).*\.(zip|rar|7z|tar)$''' OR EventData.TargetFilename =~ '''(?i)C:\\(Windows\\Temp|ProgramData|Users\\Public)''')
- name: SensitiveFileAccess
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.ObjectName AS ObjectPath, EventData.ProcessName AS ProcessPath, EventData.AccessMask AS AccessType, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4663 AND EventData.ObjectType = 'File'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1074' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'c6a076372ec31d19a6716c262d3683ca';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, EventData.Image AS ProcessPath, EventData.CommandLine AS CmdLine, EventData.ProcessId AS PID, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(7z|rar|zip|tar)\.exe$''' OR EventData.CommandLine =~ '(?i)(compress|archive|zip|rar|7z)' OR EventData.CommandLine =~ '''(?i)(temp|public|programdata).*\.(zip|rar|7z|tar)''') ORDER BY Timestamp DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1074' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '6450e460d37c4279b323fa892b516ad2';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: T1074_001.DataStaging.Detection
description: Detect local data staging activities across file creation and process execution
sources:
- name: StagingFileCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.TargetFilename, EventData.ProcessId,\n       EventData.ProcessGuid FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 11 AND \n      (EventData.TargetFilename =~ '(?i)C:\\\\\\\\(Temp|Windows\\\\\\\\Tasks|Users\\\\\\\\Public)' OR \n       EventData.TargetFilename =~ '(?i)\\\\\\\\AppData\\\\\\\\(Local|Roaming)')\n"
- name: ArchivingProcesses
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ProcessId,\n       EventData.ProcessGuid FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 AND \n      (EventData.Image =~ '''(?i)(7z|rar|zip)\\.exe$''' OR \n       EventData.CommandLine =~ '(?i)(compress-archive|tar|gzip)')\n"
- name: FileAccessPatterns
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName, EventData.ObjectName,\n       EventData.ProcessName, EventData.AccessMask FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value IN (4663, 4656) AND \n      EventData.ObjectName =~ '(?i)C:\\\\\\\\(Temp|Windows\\\\\\\\Tasks|Users\\\\\\\\Public)'\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1074.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '776dcfeb29ddb740ba76efd4639f9941';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.CommandLine, EventData.TargetFilename as FilePath, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '''(?i)C:\\(Temp|Windows\\Tasks|Users\\Public)''' OR EventData.TargetFilename =~ '''(?i)\\AppData\\(Local|Roaming)\\Temp''') AND EventData.TargetFilename =~ '''(?i)\.(zip|rar|7z|tar|gz)$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1074.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '8f8f73a5812b8bc806eee516ef0db4f0';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Remote.Data.Staging.Detection
description: Detects remote data staging activities across multiple log sources
sources:
- name: SMB_Remote_Connections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-SmbClient%4Security.evtx')
    WHERE System.Channel = 'Microsoft-Windows-SMBClient/Security' AND System.EventID.Value = 31001
- name: File_Staging_Activity
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image AS Image, EventData.TargetFilename AS TargetFilename, ProcessCommandLine, EventData.User AS User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.Channel = 'Microsoft-Windows-Sysmon/Operational' AND System.EventID.Value = 11 AND (EventData.TargetFilename =~ '(?i)C:\\\\(Temp|Users\\\\.*\\\\Downloads)\\\\.*'
         OR EventData.TargetFilename =~ '(?i).*\\\\AppData\\\\Local\\\\Temp\\\\.*')
- name: PowerShell_Copy_Commands
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.ScriptBlockText AS ScriptBlockText, EventData.Path AS Path
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.Channel = 'Microsoft-Windows-PowerShell/Operational' AND System.EventID.Value IN (4103, 4104) AND EventData.ScriptBlockText =~ '(?i).*(copy-item|robocopy|xcopy).*\\\\\\\\.*'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1074.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'ec880afa8995690762136e04ce14df09';

