  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetUserName as Username, EventData.LogonType as LogonType, EventData.IpAddress as SourceIP FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4648) AND (EventData.TargetUserName =~ '(?i)(administrator|guest)' OR EventData.TargetUserSid =~ 'S-1-5-.*-500$|S-1-5-.*-501$')
- name: SAMAccounts
  query: |
    SELECT Name, RID, Enabled, LastLogin, Comment FROM Artifact.Windows.Registry.SAM.Users() WHERE Name =~ '(?i)(administrator|guest)' OR RID IN (500, 501)
