UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: CloudAccountCompromise.Detection
description: Detect cloud account abuse through local artifacts and authentication events
sources:
- name: WindowsCloudAuthentication
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.EventID.Value AS EventID, EventData.Data as AuthData, UserData
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.Channel = 'Microsoft-Windows-AAD/Operational'
    AND (System.EventID.Value = 1006 OR System.EventID.Value = 1007 OR System.EventID.Value = 1021 OR System.EventID.Value = 1074)
- name: BrowserCloudArtifacts
  query: |
    SELECT OSPath, Mtime, Size, URL, Title
    FROM Artifact.Windows.Applications.Chrome.History()
    WHERE URL =~ '''(?i)(portal\.azure\.com|console\.aws\.amazon\.com|admin\.google\.com|login\.microsoftonline\.com)'''
    OR Title =~ '(?i)(azure|aws console|google admin)'
- name: StoredCloudCredentials
  query: |
    SELECT OSPath, Mtime, Size, Data
    FROM Artifact.Windows.NTFS.MFT()
    WHERE OSPath =~ '''(?i)\.(aws|azure|gcloud)\\'''
    OR FileName =~ '(?i)(credentials|config|token)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1078.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'b20c1edc5202a6b9c45d577c0e749eaf';

