WHERE t_code = 'T1078.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'a5737bbee4d044d2cc3daa764e36bb8e';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.TaintSharedContent
description: Detects tainted shared content via file drops and network share access
sources:
- name: FileCreationOnShares
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.TargetFilename AS TargetFilename, EventData.ProcessGuid AS ProcessGuid\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 11 \nAND EventData.TargetFilename =~ '^\\\\\\\\[^\\\\]+\\\\[^\\\\]+\\\\.*\\.(lnk|exe|dll|scr|bat|vbs)$'\nORDER BY Timestamp DESC\n"
- name: NetworkShareAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer AS Computer, EventData.SubjectUserName, EventData.ShareName, EventData.RelativeTargetName, EventData.AccessMask
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 5145
    AND EventData.ShareName != 'IPC$'
    ORDER BY TimeCreated DESC
- name: ProcessExecutionFromShares
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.Computer AS Computer, EventData.Image AS Image, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentImage, EventData.ProcessGuid AS ProcessGuid
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
    AND EventData.Image =~ '^\\\\[^\\]+\\[^\\]+\\.*'
    ORDER BY Timestamp DESC
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1080' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '055b61805c05de87a6c93503680f4191';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime), System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.TargetFilename AS TargetFilename, EventData.ProcessGuid AS ProcessGuid FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '^\\\\[^\\]+\\[^\\]+\\.*\.(lnk|exe|dll|scr|bat|vbs)$' OR EventData.TargetFilename =~ '''^[A-Z]:\\.*\\.*\.(lnk|exe|dll|scr|bat|vbs)$''') AND EventData.Image != '' ORDER BY Timestamp DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1080' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '7a1eaaccf3d84bb28eeba91dc92b6628';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.FileDirectoryDiscovery
description: Detects file and directory discovery activities across multiple log sources
sources:
- name: SecurityEventLog
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.NewProcessName AS ProcessName,
           EventData.CommandLine AS CommandLine,
           EventData.SubjectUserName AS Username
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688
      AND EventData.CommandLine =~ '''(?i)(dir\s+.*(/s|/b)|tree\s+.*(/f|/a)|findstr\s+.*(/s|/r))'''
- name: PowerShellScriptBlocks
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ScriptBlockText AS ScriptContent,
           EventData.Path AS ScriptPath
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104
      AND EventData.ScriptBlockText =~ '''(?i)(Get-ChildItem.*-Recurse|Get-Item.*\*|dir.*-Recurse)'''
- name: UserAssistAnalysis
  query: |
    SELECT Key.ModTime AS AccessTime,
           Key.Name AS ExecutedProgram,
           Value.ValueData.RunCount AS RunCount
    FROM Artifact.Windows.Registry.NTUser()
    WHERE Key.Name =~ 'Software/Microsoft/Windows/CurrentVersion/Explorer/UserAssist/.*'
      AND Key.Name =~ '''(?i)(explorer\.exe|cmd\.exe)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1083' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '0e99e6e6a8d6461feb9ee5d47faf2f44';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)(dir\s+.*(/s|/b)|tree\s+.*(/f|/a)|findstr\s+.*(/s|/r)|forfiles\s+.*(/s|/m))''' OR EventData.CommandLine =~ '''(?i)(Get-ChildItem\s+.*-Recurse|ls\s+.*-R|find\s+.*-type\s+f)''') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.CommandLine =~ '''(?i)(dir\s+.*(/s|/b)|tree\s+.*(/f|/a)|findstr\s+.*(/s|/r)|forfiles\s+.*(/s|/m))''' OR EventData.CommandLine =~ '''(?i)(Get-ChildItem\s+.*-Recurse|ls\s+.*-R|find\s+.*-type\s+f)''') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1083' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '724eb94613eee0ad06a264cc501aeac2';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.CommandLine, EventData.User, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)(net\s+user|Get-ADUser|dsquery|Get-LocalUser|Get-ADGroup|whoami /all)''' OR EventData.Image =~ '''(?i)(net\.exe|powershell\.exe|cmd\.exe)$''') AND EventData.CommandLine =~ '(?i)(user|group|account|domain|member)'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1087' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '218777434a75b7d659cf2250ead13f70';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image as Image, EventData.CommandLine as CommandLine, EventData.User as User, EventData.ParentImage as ParentImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (CommandLine =~ '''(?i)net\s+(user|localgroup)''' OR CommandLine =~ '(?i)Get-LocalUser' OR CommandLine =~ '''(?i)wmic\s+useraccount''' OR CommandLine =~ '''(?i)whoami\s+/all''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1087.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '5f3d3a48d61acea4958ce0b6cb7b64b2';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.DomainAccountEnumeration
description: Detect domain account enumeration across multiple log sources
sources:
- name: SysmonProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.Image AS ProcessPath, EventData.CommandLine AS CommandLine, EventData.User AS ExecutingUser FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)net\s+(user|group).*\/domain''' OR EventData.Image =~ '''(?i)\\(ldapsearch|wbinfo|dscacheutil)\.exe$''')
- name: PowerShellScriptBlocks
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, EventData.ScriptBlockText AS ScriptBlockText, EventData.Path AS Path FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx') WHERE System.EventID.Value = 4104 AND (EventData.ScriptBlockText =~ '(?i)Get-AD(User|Group|Computer|GroupMember)' OR EventData.ScriptBlockText =~ '''(?i)\[adsisearcher\]''' OR EventData.ScriptBlockText =~ '(?i)DirectorySearcher')
- name: BloodHoundArtifacts
  query: |
    SELECT OSPath, Mtime, Size FROM glob(globs=['C:/Users/*/AppData/Local/Temp/*.json', 'C:/Windows/Temp/*.json', 'C:/Temp/*.json']) WHERE Size > 1000 AND OSPath =~ '(?i)(users|groups|computers|domains|bloodhound)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1087.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '6ef1d572e7851cb3534659c5e4e3f7cd';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image AS ProcessPath, EventData.CommandLine AS CommandLine, EventData.User AS ExecutingUser, EventData.ParentImage AS ParentProcess FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)net\s+(user|group|localgroup).*\/domain''' OR EventData.CommandLine =~ '(?i)Get-AD(User|Group|Computer|Object)' OR EventData.CommandLine =~ '''(?i)\[adsisearcher\]''' OR EventData.CommandLine =~ '''(?i)ldapsearch.*\(objectClass=user\)''' OR EventData.CommandLine =~ '(?i)(wbinfo|dscacheutil|dscl).*(-u|users|group)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1087.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '94fc71d322de5fe93ea4045e1ea29980';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Exchange.EmailAccountDiscovery
description: Detect email account discovery via Exchange PowerShell cmdlets and related artifacts
sources:
- name: PowerShellScriptBlocks
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           System.EventID.Value,
           System.Computer,
           EventData.ScriptBlockText,
           EventData.ScriptBlockId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104
      AND EventData.ScriptBlockText =~ '(?i)(Get-GlobalAddressList|Get-Recipient|Get-Mailbox|Get-DistributionGroup|Get-AddressList)'
- name: SysmonProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           System.Computer,
           EventData.Image,
           EventData.CommandLine,
           EventData.User,
           EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND EventData.Image =~ '''(?i)powershell\.exe$'''
      AND EventData.CommandLine =~ '(?i)(Get-GlobalAddressList|Get-Recipient|Get-Mailbox|Exchange)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1087.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'd5db97ca0d3a0756778bd04115fda0a1';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: CloudAccountEnumeration
description: Detect cloud account enumeration across PowerShell, CLI history, and browser artifacts
imports:
- Windows.Forensics.Chrome.History
sources:
- name: PowerShell_Cloud_Commands
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ScriptBlockText as Command, EventData.ScriptBlockId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104 AND EventData.ScriptBlockText =~ '(?i)(Get-MsolRoleMember|Get-MgUser|az ad user|aws iam list|gcloud iam service-accounts)'
- name: CLI_History_Enumeration
  query: "SELECT OSPath, Mtime, Size, \n       read_file(filename=OSPath, length=10000) as Content\nFROM glob(globs=['C:/Users/*/AppData/Roaming/Microsoft/Windows/PowerShell/PSReadLine/ConsoleHost_history.txt',\n                 'C:/Users/*/.azure/commands*',\n                 'C:/Users/*/.aws/cli/history'])\nWHERE Content =~ '(?i)(list-users|list-roles|ad user list|iam service-accounts|Get-MsolRole)'\n"
- name: Browser_GraphAPI_Access
  query: |
    SELECT url, title, visit_time, visit_count
    FROM glob(globs='C:/Users/*/AppData/Local/Google/Chrome/User Data/*/History')
    WHERE url =~ '''(?i)(graph\.microsoft\.com|console\.aws\.amazon\.com|console\.cloud\.google\.com)'''
       AND url =~ '(?i)(users|roles|directory|iam)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1087.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'b6b51c811927db7ac0b085be41035aec';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ScriptBlockText as Command, EventData.ScriptBlockId, System.Channel AS Channel FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell/Operational.evtx') WHERE System.EventID.Value = 4104 AND (EventData.ScriptBlockText =~ '(?i)(Get-MsolRoleMember|Get-MgUser|Get-User|az ad user list|aws iam list-users|aws iam list-roles|gcloud iam service-accounts list|Get-Recipient|Get-Mailbox)' OR EventData.ScriptBlockText =~ '''(?i)(Directory\.Read\.All|RoleManagement\.Read\.Directory)''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1087.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '31348f9d271e4093fab8d678c6faeb06';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.ProxyDetection
description: Detect proxy tool usage and configuration changes across process creation and network activity
sources:
- name: ProxyProcesses
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, \n       EventData.CommandLine as CommandLine, EventData.ProcessId as ProcessId,\n       EventData.ParentImage as ParentImage, \"Process Creation\" as EventType\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 \nAND (EventData.Image =~ '''(?i)(socat|ncat|chisel|frp|gost|htran|netsh)\\.exe$''' \n     OR EventData.CommandLine =~ \"(?i)(winhttp set proxy|portproxy add|socat.*TCP|ncat.*-l.*-e|chisel server|frp[sc])\")\n"
- name: ProxyNetworkConnections
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage,\n       EventData.DestinationIp as DestinationIP, EventData.DestinationPort as DestinationPort,\n       EventData.ProcessId as ProcessId, \"Network Connection\" as EventType\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 3\nAND (int(int=EventData.DestinationPort) IN (1080, 8080, 4444, 9050) \n     OR int(int=EventData.DestinationPort) > 49152)\n"
- name: ProxyRegistrySettings
  query: |
    SELECT OSPath, Data.value as ProxyValue, "Registry" as EventType
    FROM glob(globs="C:/Users/*/NTUSER.DAT", accessor="registry")
    WHERE OSPath =~ "Software.*Internet Settings.*(ProxyServer|ProxyEnable)$"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1090' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '6eb00ea09e078cfc719cbae10332eda3';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.CommandLine as CommandLine, EventData.ProcessId as ProcessId, EventData.ParentImage as ParentImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(socat|ncat|chisel|frp|gost|htran|netsh)\.exe$''' OR EventData.CommandLine =~ "(?i)(winhttp set proxy|portproxy add|socat.*TCP|ncat.*-l.*-e|chisel server|frp[sc])")$orcafix$, updated_at = NOW()
WHERE t_code = 'T1090' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '6adacd85a7fa197cce92814f7c02ef58';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.InternalProxy
description: Detect internal proxy activity through process execution and network connections
sources:
- name: ProxyProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.CommandLine =~ '(netsh.*portproxy|socat|htran|chisel|proxychains)'
- name: SuspiciousInternalConnections
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.Computer AS Computer, EventData.Image, EventData.SourceIp, EventData.DestinationIp, EventData.DestinationPort\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 3 AND EventData.DestinationIp =~ '''^(10\\.|172\\.(1[6-9]|2[0-9]|3[01])\\.|192\\.168\\.)''' AND EventData.DestinationPort IN (1080, 8080, 4444, 9999)\n"
- name: PortProxyRegistry
  query: |
    SELECT OSPath, Data.value as ProxyConfig FROM Artifact.Windows.Registry.Glob()
    WHERE KeyGlob = 'HKEY_LOCAL_MACHINE/SYSTEM/CurrentControlSet/Services/PortProxy/**' AND Data
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1090.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '058740ba1a076e99a34d585a8b9e7ac8';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime), System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ProcessId as PID, EventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort, EventData.Protocol, EventData.SourceIp as SrcIP FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.Image =~ '''(rundll32|svchost|cmd|powershell)\.exe$''' AND EventData.DestinationIp =~ '''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.)''' AND EventData.DestinationPort IN (1080, 8080, 4444, 3389, 22) ORDER BY Timestamp DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1090.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'a03f9185ae75cbaa96b1a3c88ba8ac9e';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1090_002_ExternalProxy
description: Detect external proxy usage through network connections and registry settings
imports:
- Windows.EventLogs.Evtx
sources:
- name: SysmonNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.CommandLine, EventData.DestinationIp, EventData.DestinationPort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.Channel =~ 'Microsoft-Windows-Sysmon' AND System.EventID.Value = 3
    AND (EventData.Image =~ '''(rundll32|mshta|wscript|powershell)\.exe$''' OR EventData.CommandLine =~ '(htran|zxproxy|socat)')
    AND NOT (EventData.DestinationPort IN (80, 443, 53))
    AND NOT EventData.DestinationIp =~ '''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|127\.)'''
- name: ProxyRegistrySettings
  query: |
    SELECT OSPath, Data.value as ProxyServer, ModTime
    FROM read_reg_key(key='Software/Microsoft/Windows/CurrentVersion/Internet Settings/*')
    WHERE Key =~ '(ProxyServer|ProxyEnable)' AND Data.value != '' AND Data.value != 0
- name: SysmonProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.Channel =~ 'Microsoft-Windows-Sysmon' AND System.EventID.Value = 1
    AND EventData.CommandLine =~ '(htran|zxproxy|zxportmap|proxychains|socat.*tcp|nc.*-e)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1090.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a1840bc16ad0c12afc2b2093824b25e4';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS TimeCreated, System.Computer, System.EventID.Value, EventData.Image AS ProcessName, EventData.CommandLine, EventData.DestinationIp, EventData.DestinationPort, EventData.Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (EventData.Image =~ '''(?i)(rundll32|mshta|wscript|powershell)\.exe$''' OR EventData.CommandLine =~ '(?i)(htran|zxproxy|socat|proxychains)') AND NOT EventData.DestinationPort IN (80, 443, 53) AND NOT EventData.DestinationIp =~ '''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|127\.|169\.254\.)'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1090.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'b3d7e89f9f7c234f1eb6030fe31d8714';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.MultiHopProxy
description: Detect multi-hop proxy activity through process execution and network connection correlation
sources:
- name: ProxyProcesses
  query: "SELECT Timestamp, System.Computer, EventData.Image as ProcessPath, \n       EventData.CommandLine as CmdLine, EventData.ProcessId as PID,\n       EventData.ParentImage as ParentProcess\nFROM parse_evtx(filename=expand(path='%SystemRoot%/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'))\nWHERE System.EventID.Value = 1 \n  AND (EventData.Image =~ '''(?i)(tor\\.exe|proxychains|chisel|plink\\.exe|ncat\\.exe)'''\n       OR EventData.CommandLine =~ '(?i)(socks|proxy|tunnel|relay)'\n       OR EventData.Image =~ '''(?i)\\\\(temp|appdata)\\\\.*\\.(exe|bat|ps1)$''')\n"
- name: NetworkConnections
  query: |
    SELECT Timestamp, System.Computer, EventData.Image as ProcessPath,
           EventData.ProcessId as PID, EventData.DestinationIp as DestIP,
           EventData.DestinationPort as DestPort, EventData.SourcePort as SrcPort,
           count() as ConnectionCount
    FROM parse_evtx(filename=expand(path='%SystemRoot%/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx'))
    WHERE System.EventID.Value = 3
      AND (EventData.DestinationPort IN ('9050', '9150', '9001', '9030', '443', '80')
           OR EventData.DestinationIp =~ '''^(10\.|172\.|192\.168\.)''')
    GROUP BY EventData.ProcessId, EventData.DestinationIp
    HAVING count() > 5
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1090.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '3f7ae225ff6ead2bbcf6d01fe220695c';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Detection.DomainFronting
description: Detect potential domain fronting by correlating DNS queries with network connections to CDN providers
sources:
- name: Sysmon_Network_Connections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.DestinationHostname AS DestinationHostname, EventData.DestinationIp AS DestinationIp, EventData.DestinationPort AS DestinationPort, EventData.ProcessGuid AS ProcessGuid
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.DestinationPort = 443 AND (EventData.DestinationHostname =~ '(?i)(cloudflare|akamai|fastly|amazonaws|azureedge)' OR EventData.DestinationIp =~ '''^(104\.1[6-9]|104\.2[0-9]|172\.64|172\.65|172\.66|172\.67)''')
- name: Sysmon_DNS_Queries
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.QueryName AS QueryName, EventData.QueryResults AS QueryResults, EventData.ProcessGuid AS ProcessGuid
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 22 AND EventData.QueryName =~ '(?i)(cloudflare|akamai|fastly|amazonaws|azureedge|googleusercontent)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1090.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '7ab3889d0f28c96305ac257a6587a80c';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.DestinationHostname AS DestinationHostname, EventData.DestinationIp AS DestinationIp, EventData.DestinationPort AS DestinationPort, EventData.ProcessGuid AS ProcessGuid FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.DestinationPort = 443 AND (EventData.DestinationHostname =~ '(?i)(cloudflare|akamai|fastly|amazonaws|azureedge|googleusercontent)' OR EventData.Image =~ '(?i)(powershell|cmd|certutil|curl|wget|python|cscript|wscript)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1090.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'cbe063c26c6ecd06275c0ffce1e161e9';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1091.RemovableMediaReplication
description: Detect malware replication through removable media via process execution and file creation correlation
sources:
- name: USBMountEvents
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.Data as MountData, Message
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Windows Defender%4Operational.evtx')
    WHERE System.EventID.Value = 1006
    ORDER BY EventTime DESC
- name: RemovableMediaExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.Image as ProcessPath, EventData.CommandLine, EventData.ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.Image =~ '[E-Z]:\\\\.*\\.exe'
    ORDER BY EventTime DESC
- name: RemovableMediaFiles
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.TargetFilename, EventData.Image
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '[E-Z]:\\\\'
    ORDER BY EventTime DESC
- name: USBDeviceHistory
  query: |
    SELECT OSPath, ModTime, Size, Data.value as DeviceInfo
    FROM Artifact.Windows.Registry.NTUser()
    WHERE OSPath =~ 'MountPoints2'
    ORDER BY ModTime DESC
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1091' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a462f7e4ac035012df38ba53e01e5614';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, System.Channel AS Channel, EventData.Data as EventData, Message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE (System.EventID.Value = 1 AND Message =~ '[E-Z]:\\\\.*\\.exe') OR (System.EventID.Value = 11 AND EventData.TargetFilename =~ '[E-Z]:\\\\') ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
