UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1092.RemovableMediaC2
description: Detects potential C2 communication through removable media by correlating USB mounts with file operations
sources:
- name: USBMountEvents
  query: |
    SELECT System.TimeCreated.SystemTime AS MountTime, EventData.DeviceInstanceId AS DeviceID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Windows Defender%4Operational.evtx')
    WHERE System.EventID.Value = 1006
- name: RemovableMediaFiles
  query: |
    SELECT System.TimeCreated.SystemTime AS FileTime, EventData.TargetFilename AS FilePath, EventData.Image AS Process
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''^[D-Z]:\\'''
- name: RemovableMediaExecution
  query: |
    SELECT System.TimeCreated.SystemTime AS ExecTime, EventData.Image AS ExecutablePath, EventData.CommandLine AS CmdLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.Image =~ '''^[D-Z]:\\'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1092' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '45693309ed77f35dbd5a1c835359fefd';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.NonApplicationProtocols
description: Detect non-application layer protocol usage for potential C2 communication
imports:
- Windows.EventLogs.Evtx
- Windows.System.Pslist
sources:
- name: SysmonNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ProcessId, EventData.Protocol, EventData.DestinationIp, EventData.DestinationPort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.Protocol != '6' AND NOT EventData.Image =~ '''(?i)(svchost\.exe|system|ping\.exe|nslookup\.exe)$'''
- name: ProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.CommandLine =~ '''(?i)(ping|ncat|nc\.exe|hping|nmap|python.*socket|powershell.*raw)'''
- name: RawSocketCapabilities
  query: |
    SELECT Name, CommandLine, Pid FROM Artifact.Windows.System.Pslist()
    WHERE CommandLine =~ '(?i)(raw.*socket|icmp|scapy|packet.*craft)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1095' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'd6d51c884193f39bc5e6c023c958db43';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer, EventData.Image as ProcessImage, EventData.ProcessId as PID, EventData.Protocol, EventData.DestinationIp, EventData.DestinationPort, EventData.SourcePort FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.Protocol != '6' AND NOT EventData.Image =~ '''(?i)(svchost\.exe|system|ping\.exe|nslookup\.exe|dns\.exe)$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1095' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '7f3e9868ad9ac74051d0acb0be905f8b';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.AccountManipulation
description: Detect account manipulation activities across multiple log sources
sources:
- name: SecurityEventLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.TargetUserName as TargetUser,
           EventData.SubjectUserName as SubjectUser, EventData.SamAccountName as ModifiedAccount,
           EventData.GroupName as GroupName, EventData.Changes as AttributeChanges,
           "Security" as LogSource
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4738, 4728, 4670)
- name: SysmonProcessEvents
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.Image as ProcessImage,
           EventData.CommandLine as CommandLine, EventData.User as ExecutingUser,
           EventData.ParentImage as ParentProcess, "Sysmon" as LogSource
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (CommandLine =~ "(?i)(net user|net group|net localgroup|dsmod|dscl|usermod|groupmod)"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1098' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '6efcb4dae9c3bc942dcba28d23d4b876';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.EmailDelegatePermissions
description: Detect mailbox delegation and permission changes across multiple data sources
imports:
- Windows.EventLogs.Evtx
sources:
- name: PowerShellHistory
  query: |
    LET _hist = SELECT OSPath FROM glob(globs=expand(path='%APPDATA%/Microsoft/Windows/PowerShell/PSReadLine/ConsoleHost_history.txt'))
    SELECT _hist.OSPath AS OSPath, Line
    FROM parse_lines(filename=_hist.OSPath)
    WHERE Line =~ '(?i)Add-MailboxPermission|Set-MailboxFolderPermission|Get-MailboxPermission|UpdateFolderPermissions'
- name: SecurityEventLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           System.Computer AS Computer,
           EventData.SubjectUserName AS SubjectUserName,
           EventData.NewProcessName AS ProcessName,
           EventData.CommandLine AS CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688
      AND EventData.CommandLine =~ '(?i)Add-MailboxPermission|Set-MailboxFolderPermission|mailbox.*permission'
- name: PowerShellOperationalLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           System.Computer AS Computer,
           EventData.ContextInfo AS UserId,
           EventData.ScriptBlockText AS ScriptBlockText
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value IN (4103, 4104)
      AND EventData.ScriptBlockText =~ '(?i)Add-MailboxPermission|Set-MailboxFolderPermission|Exchange.*Permission'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1098.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '6111e6bfff823d410917b8aa36ddc9c6';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND ((EventData.CommandLine =~ '(?i)Add-MailboxPermission|Set-MailboxFolderPermission|UpdateFolderPermissions' OR EventData.Image =~ '''(?i)powershell\.exe|pwsh\.exe''') AND EventData.CommandLine =~ '(?i)Exchange|mailbox|delegate') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND ((EventData.CommandLine =~ '(?i)Add-MailboxPermission|Set-MailboxFolderPermission|UpdateFolderPermissions' OR EventData.NewProcessName =~ '''(?i)powershell\.exe|pwsh\.exe''') AND EventData.CommandLine =~ '(?i)Exchange|mailbox|delegate') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1098.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '09ef5c3b27d4847fb16b6ed6819653b4';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: CloudRoleEscalation
description: Detect cloud privilege escalation through role additions across multiple platforms
sources:
- name: PowerShellCloudCommands
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Data as CommandDetails\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx') \nWHERE System.EventID.Value IN (4103, 4104) AND CommandDetails =~ '(?i)(Add-AzRoleAssignment|AttachUserPolicy|Add-MsolRoleMember|Set-AzureADUser.*Role)'\n"
- name: BrowserCloudConsoleActivity
  query: |
    SELECT url, title, visit_time as Timestamp
    FROM glob(globs='C:/Users/*/AppData/Local/Google/Chrome/User Data/*/History')
    WHERE url =~ '''(?i)(portal\.azure|console\.aws|admin\.microsoft)''' AND title =~ '(?i)(role|permission|admin|policy)'
- name: CredentialManagerTokens
  query: |
    SELECT Key, Username, Resource, LastWritten
    FROM Artifact.Windows.Registry.NTUser()
    WHERE Key =~ 'Software.*Microsoft.*Identity' OR Key =~ 'Software.*Amazon.*Credentials'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1098.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '92eb829585527b610e2e020671ba54f4';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Data as EventDetails, System.EventID.Value as EventID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell/Operational.evtx') WHERE System.EventID.Value IN (4103, 4104) AND EventDetails =~ '(?i)(Add-AzRoleAssignment|Set-AzureADUser.*Role|AttachUserPolicy|CreatePolicyVersion|Add-MsolRoleMember)'$orcafix$, updated_at = NOW()
