UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.DeviceRegistration.Hunt
description: Detect suspicious device registration activities across Windows and Azure environments
sources:
- name: WindowsDeviceEnrollment
  query: "SELECT Key.OSPath as RegistryPath, Key.ModTime as ModificationTime, \n       ProviderID, UPN, EnrollmentState, EnrollmentType\nFROM source(artifact='Windows.Registry.NTUser/**')\nWHERE Key.OSPath =~ 'SOFTWARE/Microsoft/Enrollments/.*'\nAND ModTime > timestamp(epoch=now() - 2592000)\n"
- name: AzureDeviceRegistration
  query: |
    SELECT EventTime, ActivityDisplayName, InitiatedBy, TargetResources,
           Result, AdditionalDetails
    FROM source(artifact='Exchange.Reporting.AuditLogs')
    WHERE ActivityDisplayName IN ('Add device', 'Add registered users to device', 'Add registered owner to device')
- name: SecurityEventDeviceObjects
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetUserName as DeviceName,
           EventData.SubjectUserName as ActorUser, System.EventID.Value
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4741, 4742, 4743)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1098.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '189eca8195552736bf2420a8f60160cd';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetUserName as TargetUser, EventData.TargetDomainName as Domain, EventData.SubjectUserName as ActorUser, EventData.SubjectLogonId as LogonId, System.EventID.Value as EventID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4741, 4742, 4743) AND EventData.TargetUserName =~ '(?i)(DESKTOP-|VM-|WIN-|LAPTOP-|COMPUTER-)'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1098.005' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '2d3be8f3931f6bddfc523ec79b8b237d';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, UserData, Message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4728, 4729, 4732, 4733, 4756, 4757) AND Message =~ '(?i)(administrators|domain admins|remote desktop users|enterprise admins)'$orcafix$, updated_at = NOW()
