UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1102.WebServiceC2Detection
description: Detect potential C2 communication via legitimate web services across network connections and DNS queries
sources:
- name: SysmonNetworkConnections
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as Image, \n       EventData.DestinationHostname as DestinationHostname, EventData.DestinationPort as DestinationPort,\n       EventData.Protocol as Protocol, 'NetworkConnection' as EventType\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 3 AND EventData.DestinationPort = 443 \nAND (EventData.DestinationHostname =~ '''discord|slack|dropbox|pastebin|github|telegram|twitter|graph\\.microsoft|googleapis|onedrive|drive\\.google|mega\\.nz''')\n"
- name: SysmonDNSQueries
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as Image,
           EventData.QueryName as QueryName, 'DNSQuery' as EventType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 22
    AND (EventData.QueryName =~ '''discord|slack|dropbox|pastebin|github|telegram|twitter|graph\.microsoft|googleapis|onedrive|drive\.google|mega\.nz''')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1102' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'c1e69ac234525154cad4b265e5386185';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as Image, EventData.DestinationHostname as DestinationHostname, EventData.DestinationPort as DestinationPort, EventData.Protocol as Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.DestinationPort = 443 AND (EventData.DestinationHostname =~ '''discord|slack|dropbox|pastebin|github|telegram|twitter|graph\.microsoft|googleapis''' OR EventData.DestinationHostname =~ '''\.onedrive\.|drive\.google\.|mega\.nz''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1102' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '9abd7fa5e829d1e992a14e190db963eb';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.DeadDropResolver
description: |
  Detects dead drop resolver behavior by correlating legitimate web service access with subsequent C2 connections
sources:
- name: SysmonNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath,
           EventData.DestinationHostname as Domain,
           EventData.DestinationIp as DestIP,
           EventData.ProcessId as PID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
