UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath, EventData.DestinationHostname as Domain, EventData.DestinationIp as DestIP, EventData.DestinationPort as Port FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (EventData.DestinationHostname =~ '''(?i)(github\.com|pastebin\.com|twitter\.com|docs\.google\.com|dropbox\.com)''' OR EventData.DestinationHostname =~ '''(?i)(facebook\.com|instagram\.com|reddit\.com|discord\.com)''')$orcafix$, updated_at = NOW()
