UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: T1102_002.BidirectionalWebServiceC2
description: Detect bidirectional web service C2 via process and network correlation
sources:
- name: SysmonNetworkConnections
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.DestinationHostname AS DestinationHostname, EventData.DestinationPort AS DestinationPort\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 3 AND EventData.DestinationPort = 443 \nAND EventData.DestinationHostname =~ '(?i)(github|pastebin|googleapis|twitter|discord|slack)'\nAND NOT EventData.Image =~ '''(?i)(chrome|firefox|msedge|iexplore)\\.exe$'''\n"
- name: SusProcessCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentImage\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 \nAND (EventData.Image =~ '''(?i)(powershell|rundll32|python|curl|wget)\\.exe$'''\nOR EventData.CommandLine =~ '''(?i)(Invoke-WebRequest|wget|curl|Net\\.WebClient)''')\n"
- name: PrefetchWebTools
  query: |
    SELECT OSPath, Name, LastRunTimes, RunCount
    FROM Artifact.Windows.Forensics.Prefetch()
    WHERE Name =~ '''(?i)(CURL|WGET|POWERSHELL|PYTHON).*\.EXE'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1102.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '08a1e81ba5ed44226d59ffaaa7cd2067';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS TimeCreated, System.Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.DestinationHostname, EventData.DestinationPort, EventData.Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.Protocol = 'tcp' AND EventData.DestinationPort = 443 AND (EventData.DestinationHostname =~ '''(?i)(github\.com|pastebin\.com|googleapis\.com|twitter\.com|discord\.com|slack\.com)''' OR EventData.DestinationHostname =~ '''(?i).*\.(dropbox|google|microsoft|amazon)\.''') AND NOT EventData.Image =~ '''(?i)(chrome\.exe|firefox\.exe|msedge\.exe|iexplore\.exe)$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1102.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '646b3309c119371d19241bbd497ef64e';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.OneWayWebC2
description: Detect processes using web services for one-way command and control communication
sources:
- name: SysmonNetworkConnections
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ProcessId, EventData.Image, EventData.DestinationHostname,
           EventData.DestinationPort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
      AND EventData.DestinationPort = 443
      AND EventData.DestinationHostname =~ '''googleapis\.com|github\.com|pastebin\.com|twitter\.com'''
- name: SysmonDNSQueries
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ProcessId, EventData.Image, EventData.QueryName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 22
      AND EventData.QueryName =~ '''api\.|raw\.|gist\.|pastebin\.|discord\.'''
- name: ProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ProcessId, EventData.Image, EventData.CommandLine, EventData.ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.Image =~ '''(?i)(curl|certutil|bitsadmin)\.exe$'''
           OR EventData.CommandLine =~ '(?i)(invoke-webrequest|wget|downloadstring)')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1102.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '9bd3c41b94033669d4dbdb3c4b92daea';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, System.Computer, System.ProcessID, EventData.ProcessId, EventData.Image, EventData.DestinationHostname, EventData.DestinationPort, EventData.Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (EventData.DestinationHostname =~ '''googleapis\.com|github\.com|pastebin\.com|twitter\.com|discord\.com''' OR EventData.DestinationHostname =~ '''.*\.githubusercontent\.com''') AND EventData.DestinationPort = 443$orcafix$, updated_at = NOW()
