UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.MultiStageC2
description: Detect multi-stage command and control by correlating process creation with network connections to different destinations
sources:
- name: ProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ProcessId as PID, EventData.ParentProcessId as PPID, EventData.ParentImage, EventData.CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
- name: NetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ProcessId as PID, EventData.DestinationIp, EventData.DestinationHostname, EventData.DestinationPort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.Initiated = 'true' AND EventData.DestinationIp NOT =~ '10.' AND EventData.DestinationIp NOT =~ '192.168.'
- name: DNSQueries
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ProcessId as PID, EventData.QueryName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 22
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1104' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'c46fcfee9b80c7856535c0c013c94059';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ProcessId as PID, EventData.ParentImage, EventData.DestinationIp, EventData.DestinationHostname, EventData.DestinationPort FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.Initiated = 'true' AND NOT EventData.DestinationIp =~ '(?i)10.' AND NOT EventData.DestinationIp =~ '(?i)192.168.' AND NOT EventData.DestinationIp =~ '(?i)172.' ORDER BY EventTime$orcafix$, updated_at = NOW()
WHERE t_code = 'T1104' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'c68029aeae4de20e748b64f9f2e8a28c';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Ingress.Tool.Transfer
description: Detect ingress tool transfer activities across multiple data sources
sources:
- name: SysmonProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.CommandLine =~ '(?i)(certutil.*-urlcache|bitsadmin.*transfer|invoke-webrequest|downloadstring)'
- name: SysmonNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.DestinationIp, EventData.DestinationPort, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.Image =~ '''(?i)(powershell\.exe|cmd\.exe|certutil\.exe|bitsadmin\.exe)$'''
- name: SysmonFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.TargetFilename, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)(temp|public|programdata).*\.(exe|dll|bat|ps1|vbs|scr)$'''
- name: PowerShellScriptBlock
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ScriptBlockText
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104 AND EventData.ScriptBlockText =~ '(?i)(downloadstring|invoke-webrequest|new-object.*webclient)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1105' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '9a0c481d5e009613dce63e7317e08106';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as Process, EventData.CommandLine, EventData.ParentImage, EventData.User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)(certutil.*-urlcache|bitsadmin.*transfer|powershell.*downloadstring|invoke-webrequest|new-object.*webclient|curl\s+.*http|wget\s+.*http)''' OR EventData.Image =~ '''(?i)(certutil\.exe|bitsadmin\.exe|curl\.exe|wget\.exe)$''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1105' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'd77889f3e5ed4eb4f839b98749854725';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.NativeAPI.T1106
description: Detect Native API usage through DLL loads and process access patterns
sources:
- name: SuspiciousDLLLoads
  query: "SELECT System.TimeCreated.SystemTime AS EventTime,\n       EventData.Image AS ProcessPath,\n       EventData.ImageLoaded AS DLLPath,\n       EventData.ProcessId AS PID\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 7 \n  AND EventData.ImageLoaded =~ '''(?i)(ntdll\\.dll|kernel32\\.dll)'''\n  AND NOT EventData.Image =~ '''(?i)(explorer\\.exe|winlogon\\.exe|services\\.exe)'''\n"
- name: SuspiciousProcessAccess
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.SourceImage AS SourceProcess,
           EventData.TargetImage AS TargetProcess,
           EventData.CallTrace AS CallTrace,
           EventData.GrantedAccess AS Access
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10
      AND (EventData.TargetImage =~ '''(?i)(lsass\.exe|csrss\.exe|winlogon\.exe)'''
           OR EventData.CallTrace =~ 'UNKNOWN')
      AND format(format='0x%x', args=EventData.GrantedAccess) =~ '0x1410|0x1010|0x1F3FFF'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1106' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '7728a3d9d08920beba8c7d61cee26753';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image AS ProcessPath, EventData.ImageLoaded AS DLLPath, EventData.ProcessId AS PID, EventData.User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND (EventData.ImageLoaded =~ 'ntdll.dll' OR EventData.ImageLoaded =~ 'kernel32.dll') AND NOT EventData.Image =~ '''(?i)(explorer\.exe|winlogon\.exe|services\.exe|csrss\.exe|dwm\.exe)'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1106' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '1086b5f2bdbdf72bb513e51e5adf844d';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, UserName, EventData.WorkstationName AS WorkstationName, SourceIP, EventData.Status AS Status, EventData.SubStatus AS SubStatus, EventData.ProcessName AS ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4625, 4776) ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1110' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '6a9876caf88a91c5e295af526589dbdf';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer, EventData.TargetUserName as Username, EventData.IpAddress as SourceIP, EventData.SubStatus as FailureReason, EventData.LogonType as LogonType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4625 AND EventData.IpAddress != '-' GROUP BY SourceIP, Username HAVING count() > 5$orcafix$, updated_at = NOW()
WHERE t_code = 'T1110.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '95de26f03c808b4759438fa5aacece03';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1110002.PasswordCracking
description: Detect password cracking activities across multiple data sources
sources:
- name: HashCrackingProcesses
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.Image, EventData.CommandLine, EventData.User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.Channel = 'Microsoft-Windows-Sysmon/Operational' AND System.EventID.Value = 1
    AND (EventData.Image =~ '(?i)(hashcat|john|hydra)' OR EventData.CommandLine =~ '(?i)(--hash-type|--wordlist)')
- name: CredentialFileAccess
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.ProcessName, EventData.ObjectName, EventData.AccessMask
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.Channel = 'Security' AND System.EventID.Value IN (4663, 4656)
    AND EventData.ObjectName =~ '''(?i)(SAM|SYSTEM|NTDS\.dit)'''
- name: PostCrackingLogins
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.TargetUserName, EventData.IpAddress, EventData.LogonType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.Channel = 'Security' AND System.EventID.Value = 4624
    AND EventData.TargetUserName != 'SYSTEM' AND EventData.LogonType IN (2, 3, 10)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1110.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '2ff0e8ca63bb03be4fddaf252ad4858d';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image AS ProcessPath, EventData.CommandLine AS CmdLine, EventData.User AS ExecutingUser, EventData.ProcessId AS PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.Channel = 'Microsoft-Windows-Sysmon/Operational' AND System.EventID.Value = 1 AND (EventData.Image =~ '(?i)(hashcat|john|hydra|medusa|brutespray)' OR EventData.CommandLine =~ '(?i)(--hash-type|--wordlist|--rules|-a [0-3]|--increment)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1110.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '349651e6936d21f18d11de15e9463c3f';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.IpAddress as SourceIP, EventData.TargetUserName as Username, EventData.Status as FailureReason, EventData.SubStatus FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4625 AND EventData.IpAddress != '-' ORDER BY SourceIP$orcafix$, updated_at = NOW()
WHERE t_code = 'T1110.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'aba58ab9575347742da3a0f25c0b4e4e';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.MFA.InterceptionDetection
description: |
  Detects MFA interception through keylogger process access and smart card authentication anomalies
sources:
- name: SysmonProcessAccess
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceImage, EventData.TargetImage, EventData.GrantedAccess, EventData.SourceProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 10 \nAND (EventData.TargetImage =~ 'lsass.exe' OR EventData.TargetImage =~ 'winlogon.exe')\nAND format(format='0x%x', args=EventData.GrantedAccess) =~ '(0x10|0x1010|0x1400)'\n"
- name: SmartCardLogons
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.LogonType, EventData.AuthenticationPackageName, EventData.WorkstationName, EventData.IpAddress
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4624, 4648)
    AND EventData.AuthenticationPackageName = 'Kerberos'
    AND EventData.LogonType = 3
    AND EventData.IpAddress != '-'
- name: RegistrySmartCardMods
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetObject, EventData.Image, EventData.Details
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value IN (13, 14)
    AND EventData.TargetObject =~ 'Authentication'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1111' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '778e0263cc0f7012beaafeb87ab83b1e';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceProcessId as SourcePID, EventData.SourceImage as SourceImage, EventData.TargetProcessId as TargetPID, EventData.TargetImage as TargetImage, EventData.GrantedAccess as AccessMask, EventData.CallTrace FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 10 AND (EventData.TargetImage =~ 'lsass.exe' OR EventData.TargetImage =~ 'winlogon.exe') AND format(format='0x%x', args=EventData.GrantedAccess) =~ '0x10' AND NOT EventData.SourceImage =~ '(explorer.exe|dwm.exe|csrss.exe)'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1111' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '8bf07214a5b73233cadb52dc54e21f30';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.RegistryModifications
description: Detect T1112 Registry modifications across multiple data sources
sources:
- name: SysmonRegistryEvents
  query: |
    SELECT EventTime, Computer, EventID, Message, EventData.TargetObject as RegistryKey, EventData.Details as RegistryValue, EventData.Image as ProcessPath FROM parse(file='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx', accessor='file') WHERE System.EventID.Value IN (13, 14) AND Message =~ '(?i)(Run|Winlogon|Services|Image File Execution Options)'
- name: ProcessExecution
  query: |
    SELECT EventTime, Computer, EventData.Image as ProcessPath, EventData.CommandLine, EventData.ParentImage FROM parse(file='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx', accessor='file') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)reg\.exe$''' OR EventData.CommandLine =~ '(?i)(Set-ItemProperty|New-ItemProperty|Remove-ItemProperty)')
- name: RegistryPersistenceKeys
  query: |
    SELECT Key.Name as RegistryKey, Key.ModTime as LastModified, ValueName, ValueData FROM Artifact.Windows.Registry.NTUser() WHERE Key.Name =~ '(?i)(Run|RunOnce|Winlogon)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1112' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a4530fe79ed0d01b172dc44e3d5e3f9f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Forensics.ScreenCaptureHunt
description: |
  Detect screen capture activity across Windows systems by analyzing
  process execution and file creation patterns
author: DFIR Team
type: CLIENT
parameters:
- name: ImageExtensions
  default: (?i)\.(bmp|png|jpg|jpeg|tiff)$
- name: ScreenCaptureTools
  default: (?i)(screencap|nircmd|screenshot|snip)
- name: ScreenCaptureAPIs
  default: (?i)(copyfromscreen|bitblt|printwindow)
sources:
- name: SysmonProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath,
           EventData.CommandLine, EventData.ParentImage, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.Image =~ ScreenCaptureTools
           OR EventData.CommandLine =~ ScreenCaptureAPIs
           OR EventData.CommandLine =~ ImageExtensions)
- name: MFTImageFiles
  query: |
    SELECT OSPath, FileName, FileSize, Created0x10 as Created,
           LastModified0x10 as Modified, EntryNumber, InUse
    FROM Artifact.Windows.NTFS.MFT()
    WHERE FileName =~ ImageExtensions
      AND (FileName =~ '(?i)(screen|capture|shot)'
           OR OSPath =~ '(?i)(temp|appdata)')
      AND Created0x10 > '2024-01-01'
- name: PrefetchScreenCapture
  query: |
    SELECT Executable, RunCount, LastRunTimes, ExecutablePath
    FROM Artifact.Windows.Forensics.Prefetch()
    WHERE Executable =~ ScreenCaptureTools
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1113' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'c565bf5e690574e2fdd086348e2f6cc4';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer, EventData.Image as ProcessPath, EventData.CommandLine, EventData.ParentImage, EventData.ParentCommandLine, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '(?i)(screencap|nircmd|screenshot)' OR EventData.CommandLine =~ '(?i)(copyfromscreen|bitblt|printwindow|screencapture)' OR EventData.CommandLine =~ '''(?i)\.(bmp|png|jpg|jpeg)$''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1113' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '3611691f2796447303057f650c26e151';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.EmailCollection.Detection
description: Detects email collection activities across multiple data sources
sources:
- name: OutlookFileAccess
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName as User, \n       EventData.RelativeTargetName as EmailFile, EventData.ProcessName as AccessingProcess\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value = 5145 AND EventData.RelativeTargetName =~ '(?i)\\\\.(pst|ost)$'\n"
- name: PowerShellEmailCmdlets
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ScriptBlockText as Command,
           EventData.UserId as User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104 AND EventData.ScriptBlockText =~ '(?i)(Search-Mailbox|Export-Mailbox|Get-Mailbox|New-InboxRule)'
- name: SMTPConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as PID,
           EventData.DestinationIp as SMTPServer, EventData.DestinationPort as Port,
           EventData.Image as Process
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.DestinationPort IN (25, 587, 993, 995)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1114' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'ddfdf73036e5267e1ab1359981d17033';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName as User, EventData.RelativeTargetName as FilePath, EventData.ProcessName as Process, EventData.AccessMask as Access FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 5145 AND EventData.RelativeTargetName =~ '(?i)\\.(pst|ost|edb)$'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1114' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'e6ecea6cf364f9c291b0cae41bfaba55';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.EmailCollection
description: Detect local email collection activities targeting Outlook data files
sources:
- name: SecurityFileAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, UserName, EventData.ProcessName AS ProcessName, EventData.ObjectName AS ObjectName, EventData.AccessMask AS AccessMask
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4663, 4656, 4670)
      AND EventData.ObjectName =~ '(?i)\\.(pst|ost)$'
      AND NOT EventData.ProcessName =~ '''(?i)(outlook\.exe|scanpst\.exe)$'''
- name: SuspiciousProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.User AS User, EventData.Image AS Image, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.CommandLine =~ '(?i)\\.(pst|ost)'
           OR EventData.CommandLine =~ '(?i)(outlook files|microsoft\\\\outlook)'
           OR (EventData.Image =~ '''(?i)(7z|winrar|tar)\.exe''' AND EventData.CommandLine =~ '(?i)(documents|appdata)'))
- name: NetworkExfiltration
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.User AS User, EventData.Image AS Image, EventData.DestinationIp AS DestinationIp, EventData.DestinationPort AS DestinationPort, EventData.ProcessId AS ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
      AND EventData.DestinationPort IN (21, 22, 80, 443, 993, 995)
      AND EventData.Image =~ '''(?i)(powershell|cmd|7z|winrar|curl|wget)\.exe'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1114.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '793123ff5ee546a04e70015f0276f931';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, UserName, EventData.Image AS ProcessName, EventData.ProcessId AS ProcessId, EventData.TargetFilename AS TargetFilename, Details FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '(?i)\\.(pst|ost)$' AND EventData.TargetFilename =~ '(?i)(temp|staging|desktop|downloads)' AND NOT EventData.Image =~ '''(?i)(outlook\.exe|scanpst\.exe|scanost\.exe)$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1114.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'adb214281022f2d91abc390927ed41c8';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.RemoteEmailCollection
description: Detect T1114.002 Remote Email Collection via PowerShell and network activity
sources:
- name: PowerShell_Email_Commands
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, Message, EventData.ScriptBlockText as ScriptBlock FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx') WHERE System.EventID.Value IN (4103, 4104) AND (Message =~ '(?i)(Connect-ExchangeOnline|Search-Mailbox|Export-Mailbox|Get-Mailbox|MailSniper)' OR EventData.ScriptBlockText =~ '(?i)(ExchangeOnlineManagement|EWS|Graph.*Mail)')
- name: Network_Connections_Email
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.DestinationHostname AS DestinationHostname, EventData.DestinationPort AS DestinationPort FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (EventData.DestinationHostname =~ '''(?i)(outlook\.office365\.com|graph\.microsoft\.com|.*\.exchange\.microsoft\.com)''' OR DestinationPort = 993)
- name: PowerShell_Command_History
  query: |
    SELECT OSPath, Mtime, read_file(filename=OSPath) as Content FROM glob(globs='C:/Users/*/AppData/Roaming/Microsoft/Windows/PowerShell/PSReadLine/ConsoleHost_history.txt') WHERE Content =~ '(?i)(Connect-ExchangeOnline|Search-Mailbox|Export-Mailbox|MailSniper)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1114.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '67a5cf1ae2a57d2661d2a0ee6bde934a';

