UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.ClipboardAccess
description: Detect clipboard data collection via OS utilities and API access
sources:
- name: ClipboardProcessExecution
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath, \n       EventData.CommandLine, EventData.ParentImage, EventData.User,\n       'Process Creation' as EventType\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 \n  AND (EventData.Image =~ '''clip\\.exe$''' OR EventData.CommandLine =~ '(?i)get-clipboard')\n  AND EventData.ParentImage =~ '(?i)(powershell|cmd|wscript|cscript|rundll32)'\n"
- name: ClipboardAPIAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceImage, EventData.TargetImage,
           EventData.CallTrace, 'API Access' as EventType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10
      AND EventData.CallTrace =~ '(?i)(OpenClipboard|GetClipboardData|user32.dll)'
      AND NOT EventData.SourceImage =~ '(?i)(explorer|notepad|winword|excel)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1115' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'ca052f0a088b5380de18aa0c549dde5b';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath, EventData.CommandLine, EventData.ParentImage, EventData.ParentCommandLine, EventData.User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''clip\.exe$''' OR EventData.CommandLine =~ '(?i)get-clipboard' OR EventData.CommandLine =~ '(?i)pbpaste|xclip|xsel') AND (EventData.ParentImage =~ '(?i)(powershell|cmd|wscript|cscript|rundll32)' OR EventData.User =~ '(?i)(system|network service|local service)')$orcafix$, updated_at = NOW()
