UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.AutomatedCollection
description: Detect automated collection activities across multiple data sources
sources:
- name: SysmonProcessCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS System.TimeCreated.SystemTime,\n       EventData.Image as ProcessPath,\n       EventData.CommandLine as CommandLine,\n       EventData.ProcessId as PID\nFROM parse_evtx(filename=expand(path='%SystemRoot%/System32/winevt/logs/Microsoft-Windows-Sysmon%4Operational.evtx'))\nWHERE System.EventID.Value = 1 \n  AND (EventData.CommandLine =~ '''(?i)(Get-ChildItem.*-Recurse|dir.*\\/s|find.*-name|copy.*\\*\\.)'''\n       OR EventData.Image =~ '''(?i)(powershell\\.exe|python\\.exe|perl\\.exe)''')\n"
- name: SysmonFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS System.TimeCreated.SystemTime,
           EventData.TargetFilename as FilePath,
           EventData.ProcessId as PID,
           EventData.Image as ProcessPath
    FROM parse_evtx(filename=expand(path='%SystemRoot%/System32/winevt/logs/Microsoft-Windows-Sysmon%4Operational.evtx'))
    WHERE System.EventID.Value = 11
      AND EventData.TargetFilename =~ '(?i)(temp|staging|collection)'
- name: PowerShellScriptBlock
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS System.TimeCreated.SystemTime,
           EventData.ScriptBlockText as ScriptContent,
           EventData.ScriptBlockId as ScriptID
    FROM parse_evtx(filename=expand(path='%SystemRoot%/System32/winevt/logs/Microsoft-Windows-PowerShell%4Operational.evtx'))
    WHERE System.EventID.Value = 4104
      AND EventData.ScriptBlockText =~ '''(?i)(Get-ChildItem.*-Recurse|ForEach-Object|Copy-Item.*\*)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1119' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '67d074aa5e7a95338dfd0ba60cb43a93';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.EventID.Value as EventID, EventData.Image as ProcessPath, EventData.CommandLine as CommandLine, EventData.ProcessId as PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)(Get-ChildItem.*-Recurse|dir.*\/s|find.*-name|for.*in.*\*\.|copy.*\*\.)''' OR EventData.Image =~ '''(?i)(powershell\.exe|python\.exe|perl\.exe|wscript\.exe)''') ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1119' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '7bc4306bc466b78ce1d663bff7a9f2f4';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1120.PeripheralDiscovery
description: Detect peripheral device discovery across multiple data sources
sources:
- name: WindowsProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.NewProcessName AS ProcessName,
           EventData.CommandLine AS CommandLine,
           EventData.SubjectUserName AS User,
           'Windows Security Log' AS Source
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688
      AND EventData.CommandLine =~ '(?i)(wmic.*Win32_PnPEntity|wmic.*Win32_USBController|Get-PnpDevice)'
- name: SysmonProcessAccess
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.SourceImage AS SourceProcess,
           EventData.TargetImage AS TargetProcess,
           EventData.SourceUser AS User,
           'Sysmon Process Access' AS Source
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10
      AND EventData.TargetImage =~ '(?i)(winlogon|csrss|services)'
- name: RegistryDeviceEnum
  query: |
    SELECT ModTime AS Timestamp,
           OSPath AS RegistryPath,
           Data.value AS DeviceInfo,
           'Registry Analysis' AS Source
    FROM Artifact.Windows.Registry.NTUser()
    WHERE OSPath =~ '(?i)CurrentControlSet.*Enum.*(USB|PCI|HID)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1120' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '40a75acf7e8ac1c6f98de19b3a286df5';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.AudioCapture
description: Detect T1123 Audio Capture across multiple data sources
sources:
- name: AudioAPIAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceImage as ProcessImage, EventData.TargetImage, EventData.CallTrace
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10 AND (EventData.TargetImage =~ '''audiodg\.exe''' OR EventData.CallTrace =~ '''(winmm|avrt)\.dll''')
    AND NOT EventData.SourceImage =~ '''(teams|zoom|discord|skype)\.exe'''
- name: AudioFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.TargetFilename
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''\.(wav|mp3|m4a|aiff)$'''
    AND (EventData.TargetFilename =~ '(temp|tmp|appdata)' OR NOT EventData.TargetFilename =~ 'Users\\[^\\]+\\(Music|Documents|Desktop)')
- name: MicrophoneRegistryAccess
  query: |
    SELECT OSPath, Data.value as AppName, Data.LastUsedTimeStop
    FROM Artifact.Windows.Registry.NTUser()
    WHERE OSPath =~ 'CapabilityAccessManager/ConsentStore/microphone/[^/]+$'
    AND Data.LastUsedTimeStop > timestamp(epoch=now() - 604800)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1123' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'c17d2087f2a089cb5d375dc09cb8a654';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceImage as ProcessImage, EventData.TargetImage as TargetImage, EventData.CallTrace FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 10 AND (EventData.TargetImage =~ '''audiodg\.exe''' OR EventData.CallTrace =~ '''(winmm|avrt)\.dll''') AND NOT EventData.SourceImage =~ '''(teams|zoom|discord|skype)\.exe'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1123' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '1fdacecd096827ab30c5dd943a96058d';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.System.TimeDiscovery
description: Detect system time discovery across multiple log sources
sources:
