UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)(w32tm|net\s+time|Get-Date|Get-TimeZone|timedatectl|hwclock)''' OR EventData.Image =~ '''(?i)(w32tm\.exe|net\.exe)$''') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.CommandLine =~ '''(?i)(w32tm|net\s+time|Get-Date|Get-TimeZone|timedatectl|hwclock)''' OR EventData.NewProcessName =~ '''(?i)(w32tm\.exe|net\.exe)$''') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1124' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '37400172de5016e7409871aaeae7f6cf';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1125.VideoCapture
description: Detect video capture activity through camera device access, DLL loading, and file artifacts
sources:
- name: CameraDLLLoading
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ImageLoaded, EventData.ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 7 \nAND (EventData.ImageLoaded =~ '''(?i)(avicap32\\.dll|mf\\.dll|ksproxy\\.ax|mfplat\\.dll)''' OR EventData.ImageLoaded =~ '''(?i).*camera.*\\.dll''')\nAND NOT EventData.Image =~ '''(?i).*(teams\\.exe|zoom\\.exe|skype\\.exe|chrome\\.exe|firefox\\.exe|obs.*\\.exe)'''\n"
- name: CameraFrameServerLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, EventData
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-TaskScheduler%4Operational.evtx')
    WHERE System.EventID.Value IN (100, 101, 200)
- name: VideoFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.TargetFilename, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11
    AND EventData.TargetFilename =~ '''(?i)\.(mp4|avi|mov|yuv|mkv|h264)$'''
    AND (EventData.TargetFilename =~ '(?i)(temp|tmp|appdata|programdata|windows)' OR EventData.TargetFilename =~ '''(?i)\\\.''')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1125' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '6fc1e4363188147dba91b8087503f757';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS TimeCreated, System.Computer, EventData.Image, EventData.ImageLoaded, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND (EventData.ImageLoaded =~ '''(?i)(avicap32\.dll|mf\.dll|ksproxy\.ax|mfplat\.dll)''' OR EventData.ImageLoaded =~ '''(?i).*camera.*\.dll''') AND NOT EventData.Image =~ '''(?i).*(teams\.exe|zoom\.exe|skype\.exe|chrome\.exe|firefox\.exe|obs.*\.exe)'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1125' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'c1cd32e6b9a2b74c2fdd7776ed597c83';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1127.TrustedDeveloperUtilities
description: Detects trusted developer utilities proxy execution across multiple log sources
sources:
- name: DeveloperUtilityProcesses
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.Image AS ProcessName,
           EventData.CommandLine,
           EventData.ParentImage,
           EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND EventData.Image =~ '''(?i)(MSBuild\.exe|csc\.exe|dnx\.exe|rcsi\.exe|windbg\.exe)$'''
      AND (EventData.CommandLine =~ '''(?i)\\(temp|appdata|public|users\\public)'''
           OR EventData.ParentImage =~ '''(?i)(explorer\.exe|winword\.exe|excel\.exe|outlook\.exe)''')
- name: SuspiciousChildProcesses
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.Image AS ChildProcess,
           EventData.ParentImage AS ParentProcess,
           EventData.CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND EventData.ParentImage =~ '''(?i)(MSBuild\.exe|csc\.exe|dnx\.exe|rcsi\.exe)$'''
      AND EventData.Image =~ '''(?i)(powershell\.exe|cmd\.exe|rundll32\.exe|regsvr32\.exe|wscript\.exe|mshta\.exe)$'''
- name: NetworkConnections
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.Image AS ProcessName,
           EventData.DestinationIp,
           EventData.DestinationPort,
           EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
      AND EventData.Image =~ '''(?i)(MSBuild\.exe|csc\.exe|dnx\.exe)$'''
      AND NOT EventData.DestinationIp =~ '''^(127\.|10\.|192\.168\.|172\.1[6-9]\.|172\.2[0-9]\.|172\.3[0-1]\.)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1127' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'cf1772d246d9c8add01d09a1d4219bc9';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND ((EventData.Image =~ '''(?i)(MSBuild\.exe|csc\.exe|dnx\.exe|rcsi\.exe|windbg\.exe)$''' AND EventData.CommandLine =~ '''(?i)\\(temp|appdata|public|programdata)''') OR (EventData.ParentImage =~ '''(?i)(MSBuild\.exe|csc\.exe|dnx\.exe)$''' AND EventData.Image =~ '''(?i)(powershell\.exe|cmd\.exe|rundll32\.exe|regsvr32\.exe|wscript\.exe|mshta\.exe)$''')) LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND ((EventData.NewProcessName =~ '''(?i)(MSBuild\.exe|csc\.exe|dnx\.exe|rcsi\.exe|windbg\.exe)$''' AND EventData.CommandLine =~ '''(?i)\\(temp|appdata|public|programdata)''') OR (EventData.ParentProcessName =~ '''(?i)(MSBuild\.exe|csc\.exe|dnx\.exe)$''' AND EventData.NewProcessName =~ '''(?i)(powershell\.exe|cmd\.exe|rundll32\.exe|regsvr32\.exe|wscript\.exe|mshta\.exe)$''')) SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1127' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '9c6dd85b4517c088dec7c5cfb764b95d';

