UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''dfsvc\.exe$''' OR (EventData.Image =~ '''rundll32\.exe$''' AND EventData.CommandLine =~ '''dfshim\.dll.*ShOpenVerbApplication''')) LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''dfsvc\.exe$''' OR (EventData.NewProcessName =~ '''rundll32\.exe$''' AND EventData.CommandLine =~ '''dfshim\.dll.*ShOpenVerbApplication''')) SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1127.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '7b9a5817edbc3ba636f0af87139153b1';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.JamPlusAbuse
description: Detects potential abuse of JamPlus.exe for proxy execution
sources:
- name: ProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.NewProcessName AS ProcessName,
           EventData.CommandLine AS CommandLine,
           EventData.ParentProcessName AS ParentProcess,
           EventData.SubjectUserName AS User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND EventData.NewProcessName =~ '''(?i)jamplus\.exe$'''
- name: FileCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.Image AS ProcessName,
           EventData.TargetFilename AS CreatedFile,
           EventData.User AS User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.Image =~ '''(?i)jamplus\.exe$'''
- name: NetworkConnections
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.Image AS ProcessName,
           EventData.DestinationIp AS DestIP,
           EventData.DestinationPort AS DestPort,
           EventData.User AS User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value IN (3, 22) AND EventData.Image =~ '''(?i)jamplus\.exe$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1127.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'd130221c44ff89aaf244ddad0cc12670';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)jamplus\.exe$''') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''(?i)jamplus\.exe$''') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1127.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '100e67a21efa66c9f50a0f3c1cb7678c';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.SharedModules
description: Detect T1129 Shared Module loading from suspicious locations with correlation
sources:
- name: SuspiciousDLLLoads
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ImageLoaded as LoadedDLL, EventData.Signed, EventData.SignatureStatus, EventData.ProcessId as PID\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 7 AND (EventData.ImageLoaded =~ '''(?i)(\\\\users\\|\\\\temp\\|\\\\appdata\\|\\\\programdata\\|\\\\)''' OR EventData.SignatureStatus != 'Valid')\n"
- name: RecentDLLCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetFilename as CreatedFile, EventData.ProcessId as CreatorPID, EventData.Image as CreatorProcess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\.dll$'''
- name: NetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.DestinationIp, EventData.DestinationPort, EventData.ProcessId as PID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1129' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '5251ff1e841f680bfdcd8be628dbaa23';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ImageLoaded as LoadedDLL, EventData.Signed, EventData.SignatureStatus FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND (EventData.ImageLoaded =~ '''(?i)(\\users\|\\temp\|\\appdata\|\\programdata\|\\)''' OR EventData.SignatureStatus != 'Valid') ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1129' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '9a340904802d43e275028e5191323b91';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$? cmd|regsvr32|rundll32)\.exe$' OR CommandLine =~ '(?i)(base64|gzip|[A-Za-z0-9+/]{20,}=*)') AND NOT (DestinationPort IN (80, 443, 53, 135, 445))|name
: T1132.DataEncoding.Detection
description: Detect data encoding in C2 communications across process execution and network activity
sources:
- name: SysmonProcessNetwork
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.CommandLine AS CommandLine, EventData.DestinationIp AS DestinationIp, EventData.DestinationPort AS DestinationPort\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE (System.EventID.Value = 1 AND EventData.CommandLine =~ '(?i)(base64|gzip|[A-Za-z0-9+/]{50,}=*)') \n   OR (System.EventID.Value = 3 AND EventData.Image =~ '''(?i)(powershell|cmd|regsvr32)\\.exe$''' AND NOT (EventData.DestinationPort IN (80, 443, 53, 135, 445)))\n"
- name: PowerShellScriptBlocks
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.Computer AS Computer, EventData.ScriptBlockText AS ScriptBlockText, EventData.Path AS Path\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')\nWHERE System.EventID.Value = 4104 AND (EventData.ScriptBlockText =~ '(?i)(FromBase64String|ToBase64String|IEX|Invoke-Expression)' \n                           OR EventData.ScriptBlockText =~ '[A-Za-z0-9+/]{100,}=*')\n"
- name: CommandHistory
  query: |
    SELECT OSPath, Mtime, Data
    FROM glob(globs='C:/Users/*/AppData/Roaming/Microsoft/Windows/PowerShell/PSReadLine/ConsoleHost_history.txt')
    WHERE Data =~ '(?i)(base64|gzip|[A-Za-z0-9+/]{50,}=*)'
name: ''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1132' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '3123eac53fe9282ba644ce0f5aef7b28';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime), System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, CommandLine, EventData.DestinationIp AS DestinationIp, EventData.DestinationPort AS DestinationPort, EventData FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (EventData.Image =~ '''(?i)(powershell|cmd|regsvr32|rundll32)\.exe$''' OR CommandLine =~ '(?i)(base64|gzip|[A-Za-z0-9+/]{20,}=*)') AND NOT (EventData.DestinationPort IN (80, 443, 53, 135, 445))$orcafix$, updated_at = NOW()
WHERE t_code = 'T1132' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '77b78d5728a2573125cc113213855126';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.T1132001.DataEncoding
description: Detect standard data encoding techniques used for C2 communication
sources:
- name: ProcessCreationWithEncoding
  query: |
    SELECT System.TimeCreated as Timestamp, EventData.NewProcessName as ProcessName, EventData.CommandLine as CommandLine, EventData.ProcessId as PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.CommandLine =~ '''(?i)(certutil.*-encode|powershell.*-enc|\[System\.Convert\]::FromBase64String|base64)''' OR EventData.CommandLine =~ '(?i)[A-Za-z0-9+/]{100,}={0,2}')
- name: PowerShellScriptBlockEncoding
  query: |
    SELECT System.TimeCreated as Timestamp, EventData.ScriptBlockText as ScriptBlock, EventData.ScriptBlockId as BlockId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx') WHERE System.EventID.Value = 4104 AND (EventData.ScriptBlockText =~ '(?i)(FromBase64String|ToBase64String|ConvertFrom-Base64|ConvertTo-Base64)' OR EventData.ScriptBlockText =~ '[A-Za-z0-9+/]{100,}={0,2}')
- name: NetworkConnectionsFromEncodingProcesses
  query: |
    SELECT System.TimeCreated as Timestamp, EventData.Image as ProcessPath, EventData.ProcessId as PID, EventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.Image =~ '''(?i)(certutil\.exe|powershell\.exe)$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1132.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '68f13ae6976be062a15d3a61207c9e4a';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.NonStandardEncoding
description: Detect processes using non-standard encoding schemes for C2
sources:
- name: ProcessCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as Image, EventData.CommandLine as CommandLine\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '[A-Za-z0-9+/]{120,}' OR EventData.CommandLine =~ 'alphabet\\\\s*=|custom.*encod|translate.*table') \nAND NOT EventData.CommandLine =~ '^[A-Za-z0-9+/]*={0,2}$'\n"
- name: NetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as Image, EventData.DestinationIp, EventData.DestinationPort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.DestinationPort IN (80,443,53)
- name: PowerShellScripts
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ScriptBlockText
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value IN (4103,4104) AND EventData.ScriptBlockText =~ '''\$[a-z]+\s*=\s*["\'][A-Za-z0-9]{32,}|alphabet|custom.*encod'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1132.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '0b5bacbefd2413e8d17e6f5efc3cd2fc';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as Image, EventData.CommandLine as CommandLine, EventData.ParentCommandLine as ParentCommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '[A-Za-z0-9+/]{120,}' OR EventData.CommandLine =~ 'alphabet\\s*=|custom.*encod|translate.*table|base64.*modif') AND NOT EventData.CommandLine =~ '^[A-Za-z0-9+/]*={0,2}$'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1132.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '567e5fa87b6b57b71f3dee1bb153444a';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer, System.EventID.Value, System.Channel AS Channel, EventData.LogonType, EventData.IpAddress, EventData.TargetUserName, EventData.WorkstationName, EventData.LogonProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4625, 4776) AND EventData.LogonType IN (3, 10, 12) AND EventData.IpAddress =~ '^(?!10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.).*' AND EventData.IpAddress != '-' AND EventData.IpAddress != '127.0.0.1'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1133' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'cfe069fd8fe5888aef0d1889b7485379';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.TokenManipulation
description: Detect Access Token Manipulation across multiple log sources
sources:
- name: SecurityEvents
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, Message, EventData.SubjectUserName as User, EventData.ProcessName as Process, EventData.PrivilegeList as Privileges
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4672, 4634, 5136) AND (EventData.PrivilegeList =~ '(?i)SeDebugPrivilege|SeImpersonatePrivilege|SeTcbPrivilege' OR EventData.AttributeLDAPDisplayName =~ '(?i)msDS-AllowedToDelegateTo|userAccountControl')
- name: SysmonProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.Image as Image, EventData.CommandLine as CommandLine, EventData.User as User, EventData.ParentImage as ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '(?i)runas' OR EventData.User =~ '(?i)SYSTEM|NT AUTHORITY')
- name: SysmonProcessAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.SourceImage as SourceImage, EventData.TargetImage as TargetImage, EventData.GrantedAccess as Access, EventData.CallTrace as CallTrace
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10 AND (format(format='0x%x', args=EventData.GrantedAccess) =~ '0x1410|0x1010|0x40' AND EventData.TargetImage =~ '(?i)lsass.exe')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1134' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '6dac774770da8ea3b40864cd7fc4db3e';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, Message, EventData.SubjectUserName as User, EventData.ProcessName as Process, EventData.PrivilegeList as Privileges FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4672, 4634, 5136) AND (EventData.PrivilegeList =~ '(?i)SeDebugPrivilege|SeImpersonatePrivilege|SeTcbPrivilege' OR EventData.AttributeLDAPDisplayName =~ '(?i)msDS-AllowedToDelegateTo|userAccountControl')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1134' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'a94bb2f31470a6b2b3c29ebd263f7220';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.TokenMakeImpersonate
description: Detects T1134.003 Make and Impersonate Token through correlated logon events, API calls, and process creation
sources:
- name: LogonEvents
  query: |
    SELECT System.TimeCreated as Timestamp, System.EventID.Value as EventID, EventData.LogonType as LogonType, EventData.LogonProcessName as LogonProcess, EventData.TargetUserName as TargetUser, EventData.TargetLogonId as LogonId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4672) AND (EventData.LogonType = 9 OR EventData.LogonProcessName = 'seclogo')
- name: ProcessCreation
  query: |
    SELECT System.TimeCreated as Timestamp, EventData.Image as ProcessName, EventData.CommandLine as CommandLine, EventData.LogonId as LogonId, EventData.ParentImage as ParentProcess FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1
- name: PowerShellLogs
  query: |
    SELECT System.TimeCreated as Timestamp, EventData.ScriptBlockText as ScriptBlock FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx') WHERE System.EventID.Value = 4104 AND EventData.ScriptBlockText =~ '(?i)(LogonUser|SetThreadToken|ImpersonateLoggedOnUser)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1134.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a0d36fe0f873fd0808c72b7cfa6d4d80';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS SystemTime, System.EventID.Value as EventID, EventData.LogonType as LogonType, EventData.LogonProcessName as LogonProcess, EventData.SubjectUserName as SubjectUser, EventData.TargetUserName as TargetUser, EventData.TargetLogonId as LogonId, EventData.IpAddress as SourceIP FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4624 AND (EventData.LogonType = 9 OR (EventData.LogonType IN (2,3) AND EventData.LogonProcessName = 'seclogo'))$orcafix$, updated_at = NOW()
WHERE t_code = 'T1134.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'e9701d037fbe444b4f6ca7046bae7582';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.PPIDSpoofing
description: |
  Detects Parent PID spoofing by correlating Security 4688 events with Sysmon process creation
  and identifying mismatched parent-child relationships indicating PPID manipulation.
sources:
- name: SecurityEventLog
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.NewProcessId as PID,
           EventData.NewProcessName, EventData.ProcessId as ParentPID,
           EventData.ParentProcessName as ParentName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.Channel = 'Security' AND System.EventID.Value = 4688
      AND EventData.ParentProcessName =~ '''(?i)(lsass|services|wininit|explorer)\.exe'''
- name: SysmonProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as PID,
           EventData.Image, EventData.ParentProcessId as SysmonParentPID,
           EventData.ParentImage, EventData.ParentProcessGuid
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.Channel = 'Microsoft-Windows-Sysmon/Operational' AND System.EventID.Value = 1
      AND EventData.ParentImage =~ '''(?i)(lsass|services|wininit|explorer)\.exe'''
- name: ProcessAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceProcessId,
           EventData.TargetProcessId, EventData.GrantedAccess,
           EventData.SourceImage, EventData.TargetImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.Channel = 'Microsoft-Windows-Sysmon/Operational' AND System.EventID.Value = 10
      AND format(format='0x%x', args=EventData.GrantedAccess) =~ '(0x1000|0x0040)' AND EventData.TargetImage =~ '''(?i)(lsass|services|wininit)\.exe'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1134.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'b1d1a612f1eec91e5b1dcea5fd35e83d';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)(lsass|services|wininit|csrss)\.exe''' OR EventData.Image =~ '''(?i)(powershell|rundll32|regsvr32|mshta)\.exe''') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.ParentProcessName =~ '''(?i)(lsass|services|wininit|csrss)\.exe''' OR EventData.NewProcessName =~ '''(?i)(powershell|rundll32|regsvr32|mshta)\.exe''') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1134.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '338bb6c43535259d14b4f9640bb9e525';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Attack.T1134_005.SIDHistoryInjection
description: Detects SID-History injection attacks through multiple correlation points
sources:
- name: ADAttributeChanges
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, System.EventID.Value AS EventID, EventData.SubjectUserName AS Actor, EventData.ObjectDN AS TargetUser, EventData.AttributeLDAPDisplayName AS Attribute, EventData.AttributeValue AS SIDHistoryValue FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 5136 AND EventData.AttributeLDAPDisplayName =~ 'sIDHistory'
- name: UserAccountModifications
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, System.EventID.Value AS EventID, EventData.SubjectUserName AS Actor, EventData.TargetUserName AS TargetUser, EventData.SidHistory AS SIDHistory FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4720, 4738) AND EventData.SidHistory != ''
- name: SuspiciousLogons
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.TargetUserName AS Username, EventData.LogonType AS LogonType, EventData.ElevatedToken AS TokenType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4624 AND EventData.ElevatedToken = 'TokenElevationTypeFull'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1134.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '707eefd7e4056a208648d33c1adcef00';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1135.NetworkShareDiscovery
description: Detect network share discovery across multiple data sources
sources:
- name: ProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.CommandLine as CommandLine, EventData.NewProcessName as ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND EventData.CommandLine =~ '(?i)(net\\s+view|net\\s+share|Get-SmbShare|smbclient\\s+-L)'
- name: NetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.DestinationIp AS DestinationIp, EventData.DestinationPort AS DestinationPort, EventData.Image AS ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.DestinationPort IN (139, 445) AND EventData.DestinationIp =~ '^(10\\.|172\\.(1[6-9]|2[0-9]|3[01])\\.|192\\.168\\.)'
- name: PowerShellExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ScriptBlockText as ScriptBlock FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx') WHERE System.EventID.Value IN (4103, 4104) AND EventData.ScriptBlockText =~ '(?i)(Get-SmbShare|Win32_Share|Invoke-ShareFinder|Find-DomainShare)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1135' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '5c590280a3c40157136c7c00e43f3785';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)(net\s+view|net\s+share|Get-SmbShare|Find-DomainShare|Invoke-ShareFinder|Win32_Share)''' OR EventData.Image =~ '(?i)(smbclient|smbmap|rpcclient|crackmapexec)') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.CommandLine =~ '''(?i)(net\s+view|net\s+share|Get-SmbShare|Find-DomainShare|Invoke-ShareFinder|Win32_Share)''' OR EventData.NewProcessName =~ '(?i)(smbclient|smbmap|rpcclient|crackmapexec)') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1135' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'f8b87922c6bb896437a8edb95e725b92';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1136.AccountCreation
description: |
  Detect account creation activities across multiple data sources for T1136
  Correlates Security logs, Sysmon process creation, and SAM registry changes
sources:
- name: SecurityLogs
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetUserName as CreatedAccount, \n       EventData.SubjectUserName as Creator, Message\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value IN (4720, 4722, 4738)\n"
- name: ProcessCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, \n       EventData.ParentImage, EventData.User\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 1 AND (EventData.Image =~ '''net\\.exe$''' OR EventData.Image =~ '''powershell\\.exe$''')\nAND EventData.CommandLine =~ '(user.*add|New-LocalUser|New-ADUser)'\n"
- name: SAMRegistry
  query: "SELECT OSPath, ModTime, Data\nFROM Artifact.Windows.Registry.SAM() \nWHERE OSPath =~ 'ROOT/SAM/Domains/Account/Users/'\nAND ModTime > now() - 86400*7\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1136' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '60416cec50598320876128286fa98ee8';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData, Message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4720 OR (System.EventID.Value = 4722 AND EventData.TargetUserName != 'Guest') OR System.EventID.Value = 4738$orcafix$, updated_at = NOW()
WHERE t_code = 'T1136' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '40a7db7df3b973f7e77910a56e8706b2';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1136001.LocalAccountCreation
description: Detect local account creation across Windows event logs and process execution
sources:
- name: SecurityEventLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetUserName as NewAccount, EventData.TargetSid as AccountSID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4720
    ORDER BY EventTime DESC
- name: SysmonProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath, EventData.CommandLine, EventData.User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)net\.exe$''' OR EventData.Image =~ '''(?i)powershell\.exe$''')
    AND (EventData.CommandLine =~ '''(?i)net\s+user.*\/add''' OR EventData.CommandLine =~ '(?i)New-LocalUser')
    ORDER BY EventTime DESC
- name: SAMRegistryAnalysis
  query: |
    SELECT Name, Type, Size, Mtime as LastModified
    FROM Artifact.Windows.Registry.SAM()
    WHERE Key =~ '''SAM\\Domains\\Account\\Users'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1136.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'dddc2b54e8ab741b4b1316113ceaf57e';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer, EventData, UserData, System FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4720 OR System.EventID.Value = 4732 ORDER BY TimeCreated DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1136.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'e1aa2c27efcd7c6cb9ba41619e1c8617';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated as CreationTime, EventData.SubjectUserName as Creator, EventData.TargetUserName as NewAccount, EventData.SubjectLogonId as CreatorLogonId, System.Computer as DomainController FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4720$orcafix$, updated_at = NOW()
