UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.CloudAccountCreation
description: Detect cloud account creation activities across multiple platforms
sources:
- name: PowerShellCloudCommands
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ScriptBlockText AS Command, \n       EventData.ContextInfo AS ExecutingUser\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx') \nWHERE System.EventID.Value IN (4103, 4104) \n  AND EventData.ScriptBlockText =~ 'New-MsolUser|New-MgUser|New-AzureADUser|CreateUser|AttachUserPolicy'\n"
- name: PowerShellHistory
  query: "SELECT OSPath, Mtime, \n       split(sep='\\n', string=Data) AS Commands\nFROM glob(globs='C:/Users/*/AppData/Roaming/Microsoft/Windows/PowerShell/PSReadLine/*_history.txt')\nWHERE Commands =~ 'New-.*User|CreateUser|New-AzureAD'\n"
- name: BrowserCloudConsoleAccess
  query: |
    SELECT url, visit_time, title
    FROM Artifact.Windows.Applications.Chrome.History()
    WHERE url =~ 'portal.azure.com|console.aws.amazon.com|admin.google.com|admin.microsoft.com'
      AND title =~ 'Users|Identity|IAM|Admin'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1136.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'f0da403f48862c9059365b020821c261';

