UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Office.Startup.Persistence
description: Detect Office application startup-based persistence mechanisms including registry modifications, file creation, and process execution
sources:
- name: OfficeProcessExecution
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.Image AS ProcessPath, EventData.ParentImage AS ParentProcess, EventData.CommandLine AS CmdLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)(outlook|winword|excel|powerpnt)\.exe$''' AND EventData.Image =~ '''(?i)(cmd|powershell|cscript|wscript|mshta)\.exe$''')
- name: OfficeFileCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.TargetFilename AS FilePath, EventData.Image AS ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)(templates|startup|xlstart|addins).*\.(dot|dotm|xla|xlam|otm)$'''
- name: OfficeRegistryMods
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.TargetObject AS RegistryPath, EventData.Details AS Value, EventData.Image AS ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value IN (13,14) AND EventData.TargetObject =~ '''(?i)software\\microsoft\\office.*\\(addins|today|security)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1137' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'ec8547e17ad160acd45f69ac142afc53';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image AS ProcessPath, EventData.ParentImage AS ParentProcess, EventData.CommandLine AS CmdLine, EventData.ProcessId AS PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)(outlook|winword|excel|powerpnt)\.exe$''' AND EventData.Image =~ '''(?i)(cmd|powershell|cscript|wscript|mshta)\.exe$''') OR (EventData.Image =~ '''(?i)(outlook|winword|excel|powerpnt)\.exe$''' AND EventData.CommandLine =~ '(?i)(startup|template|addin|macro)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1137' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'e750161efff00d82a7df7618a3650c97';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.OfficeTemplateMacros
description: Detect Office template macro persistence via file monitoring and registry hijacking
sources:
- name: TemplateFiles
  query: |
    SELECT OSPath, Size, Mtime, Atime, Ctime FROM glob(globs=[
      expand(path='%APPDATA%/Microsoft/Templates/Normal.dotm'),
      expand(path='%APPDATA%/Microsoft/Excel/XLSTART/PERSONAL.XLSB'),
      expand(path='%APPDATA%/Microsoft/Excel/XLSTART/*.xls*'),
      expand(path='%APPDATA%/Microsoft/Word/STARTUP/*')
    ])
- name: GlobalDotNameRegistry
  query: |
    SELECT Key.OSPath.Path AS KeyPath, Data.value AS Value, Data.type AS Type FROM glob(globs=[
      'HKEY_USERS/*/Software/Microsoft/Office/*/Word/Data',
      'HKEY_USERS/*/Software/Microsoft/Office/*/Excel/Security'
    ], accessor='registry') WHERE Data.value =~ '(?i)(globaldotname|workgroupdot|usertemplate)'
- name: SysmonOfficeEvents
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, System.EventID.Value AS EventID, EventData FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value IN (1,11,13,14) AND (EventData.Image =~ '''(?i)(winword|excel)\.exe$''' OR EventData.TargetFilename =~ '''(?i)(normal\.dotm|personal\.xlsb)''' OR EventData.TargetObject =~ '(?i)globaldotname')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1137.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'ea6cd139b70a07d1f4de833570d11d6e';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, EventData.Image AS ProcessImage, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)(winword|excel)\.exe$''' OR EventData.Image =~ '''(?i)(winword|excel)\.exe$''') AND (EventData.CommandLine =~ '''(?i)(normal\.dotm|personal\.xlsb|/t\s+)''' OR EventData.Image =~ '''(?i)(cmd|powershell|wscript|cscript)\.exe$''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1137.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '12b7c039069d65ebe876210dd27edeaf';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.OfficeTest
description: Detect Office Test registry persistence mechanism (T1137.002)
sources:
- name: OfficeTestRegistry
  query: "SELECT Key.OSPath as RegistryPath, Key.ModTime as LastModified, \n       Data.value as DLLPath\nFROM glob(globs=ntuser_path(), accessor='registry') as OSPath\nCALL registry_enum_values(root_path=OSPath, key_path='Software/Microsoft/Office test/Special/Perf')\nWHERE Data.value\n"
- name: SysmonOfficeTestEvents
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.TargetObject as RegistryPath, \n       EventData.Details as Value, EventData.Image\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value IN (13, 14) AND EventData.TargetObject =~ 'Office test'\n"
- name: OfficeDLLLoading
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image as OfficeProcess, \n       EventData.ImageLoaded as LoadedDLL, EventData.Signed\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 7 \n  AND EventData.Image =~ '''(winword|excel|powerpnt|outlook)\\.exe$'''\n  AND EventData.Signed != 'true'\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1137.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'e95da306b9f2f9fd28400b0a195a92d4';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetObject as RegistryPath, EventData.Details as DLLPath, EventData.Image as ModifyingProcess FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 13 AND EventData.TargetObject =~ 'Office test.*Special.*Perf'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1137.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '9933c1ca8da623bb5bbaf3908f3c82d6';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.OutlookFormsPersistence
description: Detect T1137.003 Outlook Forms persistence via process creation and form artifacts
sources:
- name: SuspiciousOutlookChildren
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ParentImage as ParentImage, EventData.CommandLine as CommandLine, EventData.User as User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.ParentImage =~ '''outlook\.exe$''' AND (EventData.Image =~ '''(powershell|rundll32|mshta|wscript|cscript)\.exe$''' OR EventData.CommandLine =~ '''(IPM\.Note|Get-OutlookInbox|MAPI)''')
- name: OutlookFormErrors
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.Provider.Name as Provider, System.EventID.Value as EventID, EventData
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.Provider.Name = 'Microsoft Office 16' AND EventData =~ '''(?i)(form|template|IPM\.Note)'''
- name: OutlookProfileFiles
  query: |
    SELECT OSPath, Size, Mtime, Atime, Ctime
    FROM glob(globs=['C:/Users/*/AppData/Local/Microsoft/Outlook/*.ost', 'C:/Users/*/AppData/Local/Microsoft/Outlook/*.pst', 'C:/Users/*/Documents/Outlook Files/*.pst'])
    WHERE Mtime > now() - 2592000
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1137.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a6584d7cf8fbbf0a69e4efeb04ae7d55';

