UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.OutlookHomePage
description: Detect Outlook Home Page persistence via registry analysis and process monitoring
sources:
- name: OutlookWebViewRegistry
  query: |
    SELECT Key.OSPath.Path AS RegistryPath,
           Key.Name AS KeyName,
           Data.value AS HomePageURL,
           Key.ModTime AS ModifiedTime
    FROM read_reg_key(globs='HKEY_USERS/*/Software/Microsoft/Office/*/Outlook/WebView/**',
                      accessor='registry')
    WHERE Data.value AND Data.value =~ '^https?://'
- name: OutlookSuspiciousChildProcesses
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.Image AS ChildProcess,
           EventData.ParentImage AS ParentProcess,
           EventData.CommandLine AS CommandLine,
           EventData.ProcessId AS PID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND EventData.ParentImage =~ '''outlook\.exe$'''
      AND (EventData.Image =~ '''mshta\.exe$''' OR
           EventData.Image =~ '''wscript\.exe$''' OR
           EventData.Image =~ '''cscript\.exe$''')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1137.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '55102d79a48237ab867c20a67e6ef79f';

