UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.OutlookRulesPersistence
description: Detect malicious Outlook rules used for persistence by monitoring process creation and application events
sources:
- name: SysmonProcessCreation
  query: "SELECT System.TimeCreated.SystemTime AS Timestamp,\n       EventData.Image AS ChildProcess,\n       EventData.ParentImage AS ParentProcess,\n       EventData.CommandLine AS CommandLine,\n       EventData.ProcessId AS PID,\n       EventData.ParentProcessId AS PPID\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 \n  AND EventData.ParentImage =~ '''outlook\\.exe$'''\n  AND (EventData.Image =~ '''mshta\\.exe$''' OR EventData.Image =~ '''powershell\\.exe$''' \n       OR EventData.Image =~ '''wscript\\.exe$''' OR EventData.Image =~ '''cscript\\.exe$''')\n"
- name: PowerShellExecutionFromOutlook
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ContextInfo AS HostApp,
           EventData.ContextInfo AS PSCommandLine,
           UserData.EventXML.Data AS ScriptBlock
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE (System.EventID.Value = 4103 OR System.EventID.Value = 4104)
      AND EventData.ContextInfo =~ 'outlook'
- name: OutlookApplicationEvents
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           System.EventID.Value AS EventID,
           EventData.param1 AS EventParam1,
           EventData.param2 AS EventParam2,
           System.Provider.Name AS Provider
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Application.evtx')
    WHERE System.Provider.Name =~ 'Outlook' OR System.Provider.Name =~ 'Microsoft Office'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1137.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '70b0cbd69c57c307c9e8f42b0e5ec80a';

