UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.OfficeAddins
description: Detect malicious Office add-ins via process execution, file creation, and registry modifications
sources:
- name: SuspiciousOfficeChildProcesses
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ChildProcess, EventData.ParentImage as ParentProcess, EventData.CommandLine as CommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.ParentImage =~ '''(?i)(winword\.exe|excel\.exe|outlook\.exe)''' AND EventData.Image =~ '''(?i)(powershell\.exe|mshta\.exe|rundll32\.exe|wscript\.exe)'''
- name: OfficeAddinRegistryModifications
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetObject as RegistryKey, EventData.Details as Value FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value IN (13, 14) AND EventData.TargetObject =~ '''(?i).*\\Microsoft\\Office\\.*\\(Word|Excel|Outlook)\\Addins\\.*'''
- name: OfficeAddinFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetFilename as FilePath, EventData.Image as ProcessImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '''(?i).*\\(STARTUP|XLSTART)\\.*\.(wll|xll|dll|vsto)$''' OR EventData.TargetFilename =~ '''(?i).*\.xll$''')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1137.006' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '73562b32ad6bddc413ee74401f354e64';

