UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1140.DeobfuscateFiles
description: Detect file deobfuscation and decoding activities across multiple data sources
sources:
- name: DecodingProcesses
  query: "SELECT System.TimeCreated AS Timestamp, EventData.Image, EventData.CommandLine, EventData.ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.Channel = 'Microsoft-Windows-Sysmon/Operational' AND System.EventID.Value = 1 \nAND (EventData.CommandLine =~ '(?i)certutil.*(decode|decodehex)' OR EventData.CommandLine =~ '''(?i)copy\\s+.*\\/b''' OR EventData.Image =~ '(?i)expand')\n"
- name: PowerShellDecoding
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, EventData.ScriptBlockText AS ScriptBlockText
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE EventData.ScriptBlockText =~ '(?i)(FromBase64String|decode|decrypt|deobfusc)'
- name: FileCreationPost
  query: |
    SELECT System.TimeCreated, EventData.TargetFilename, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.Channel = 'Microsoft-Windows-Sysmon/Operational' AND System.EventID.Value = 11
    AND EventData.TargetFilename =~ '''\.(exe|dll|ps1|bat|vbs)$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1140' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '67d4685bfe338871c8d39b33eebd9cfa';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS TimeCreated, EventData.Image, EventData.CommandLine, EventData.ProcessId, EventData.ParentImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '(?i)certutil.*(decode|decodehex)' OR EventData.CommandLine =~ '''(?i)copy\s+.*\/b''' OR EventData.CommandLine =~ '''(?i)expand\s+.*\.(zip|cab|gz)''' OR (EventData.Image =~ '(?i)powershell' AND EventData.CommandLine =~ '(?i)(FromBase64String|Convert::FromBase64)'))$orcafix$, updated_at = NOW()
WHERE t_code = 'T1140' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '6ea20b65727a4a3c56ae2db04d887255';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1176.SoftwareExtensions
description: |
  Detects malicious software extension installation and activity across multiple data sources
sources:
- name: ExtensionFileCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath, \n       EventData.TargetFilename as FilePath, EventData.ProcessId as PID\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 11 \n  AND EventData.TargetFilename =~ '''(?i).*\\\\Extensions\\\\.*\\\\manifest\\.json$'''\n"
- name: ExtensionRegistryChanges
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetObject as RegistryPath,
           EventData.Details as Value, EventData.Image as ProcessPath
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value IN (13, 14)
      AND EventData.TargetObject =~ '''(?i).*\\Software\\(Google\\Chrome|Microsoft\\Edge)\\Extensions\\.*'''
- name: BrowserNetworkActivity
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath,
           EventData.DestinationIp, EventData.DestinationPort, EventData.ProcessId as PID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
      AND EventData.Image =~ '''(?i).*(chrome|edge|firefox|browser)\.exe$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1176' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '8a28766ec3d2430923ab65965108a008';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath, EventData.TargetFilename as FilePath, EventData.ProcessId as PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i).*\\Extensions\\.*\\manifest\.json$|.*\\Extensions\\.*\\.+\\[0-9]+\\.*\.(js|json)$''' ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1176' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'b66aaba46524a6fa09f6b6197caa0b2f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Browser.Extensions.Investigation
description: Collect browser extension artifacts and related network activity
sources:
- name: ExtensionFiles
  query: |
    SELECT OSPath, Mtime, Atime, Ctime, Size, hash(path=OSPath) as Hash
    FROM glob(globs=['C:/Users/*/AppData/Local/Google/Chrome/User Data/*/Extensions/*/manifest.json',
                    'C:/Users/*/AppData/Local/Microsoft/Edge/User Data/*/Extensions/*/manifest.json',
                    'C:/Users/*/AppData/Roaming/Mozilla/Firefox/Profiles/*/extensions/*.xpi'])
- name: BrowserPreferences
  query: |
    SELECT OSPath, Mtime, read_file(filename=OSPath) as Content
    FROM glob(globs=['C:/Users/*/AppData/Local/Google/Chrome/User Data/*/Preferences',
                    'C:/Users/*/AppData/Local/Google/Chrome/User Data/*/Secure Preferences'])
- name: ExtensionNetworkActivity
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image, EventData.ProcessId, EventData.QueryName, EventData.DestinationPort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 22 AND (EventData.Image =~ '''(?i).*chrome\.exe$''' OR EventData.Image =~ '''(?i).*firefox\.exe$''' OR EventData.Image =~ '''(?i).*msedge\.exe$''')
    ORDER BY EventTime DESC LIMIT 1000
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1176.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '3ad3f10bd9c44427e0d44feed3f2a96f';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.TargetFilename as FilePath, EventData.ProcessId as PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '''(?i).*\\Extensions\\.*\\manifest\.json$''' OR EventData.TargetFilename =~ '''(?i).*\\User Data\\.*\\Preferences$''' OR EventData.TargetFilename =~ '''(?i).*\\User Data\\.*\\Secure Preferences$''') ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1176.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '4dfbac96a9c9d357c2457e2327ef9701';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.IDEExtensionPersistence
description: Detect IDE extension installation and tunneling activity across process execution, file creation, and network connections
sources:
- name: ProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''(?i)(code\.exe|idea64\.exe|eclipse\.exe)$''' OR EventData.CommandLine =~ "(?i)(--install-extension|tunnel|remote)")
- name: ExtensionFiles
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.TargetFilename AS FilePath, EventData.Image AS ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)(vscode.*extensions|\.jetbrains.*plugins|eclipse.*plugins).*\.(vsix|jar|json)$'''
- name: NetworkConnections
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.Image AS ProcessName, EventData.DestinationHostname AS Destination, EventData.DestinationPort AS Port FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.Image =~ '''(?i)(code\.exe|idea64\.exe|eclipse\.exe)$''' AND EventData.DestinationHostname =~ '''(?i)(visualstudio\.com|jetbrains\.com|github|marketplace)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1176.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '291bcfe47462a0eeb703fa97d783841c';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(code\.exe|idea64\.exe|idea\.exe|eclipse\.exe|jetbrains-gateway\.exe)$''' OR EventData.CommandLine =~ '(?i)(--install-extension|--force|--disable-extensions|tunnel|remote-ssh)') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''(?i)(code\.exe|idea64\.exe|idea\.exe|eclipse\.exe|jetbrains-gateway\.exe)$''' OR EventData.CommandLine =~ '(?i)(--install-extension|--force|--disable-extensions|tunnel|remote-ssh)') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1176.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'e1a367bf5981100a804d5d703e9a415c';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.BrowserSessionHijacking
description: |
  Detects browser session hijacking by correlating privilege escalation,
  process injection into browsers, and suspicious network activity.
sources:
- name: PrivilegeEscalation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           EventData.SubjectUserName as User,
           EventData.PrivilegeList as Privileges,
           EventData.ProcessName as ProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4672 AND EventData.PrivilegeList =~ 'SeDebugPrivilege'
- name: BrowserInjection
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           EventData.SourceImage as SourceProcess,
           EventData.TargetImage as TargetBrowser,
           format(format='0x%x', args=EventData.GrantedAccess) as AccessMask
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10
      AND EventData.TargetImage =~ '''(?i)(chrome|msedge|firefox|iexplore)\.exe'''
      AND EventData.GrantedAccess > 1000
- name: RemoteThreadCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           EventData.SourceImage as SourceProcess,
           EventData.TargetImage as TargetBrowser,
           EventData.NewThreadId as ThreadID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 8
      AND EventData.TargetImage =~ '''(?i)(chrome|msedge|firefox|iexplore)\.exe'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1185' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '939adecfc793b6b62276fe0c71003a5d';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.EventID.Value as EventID, EventData.SubjectUserName as User, EventData.SourceImage as SourceProcess, EventData.TargetImage as TargetProcess, format(format='0x%x', args=EventData.GrantedAccess) as AccessMask FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 10 AND EventData.TargetImage =~ '''(?i)(chrome|msedge|firefox|iexplore)\.exe''' AND EventData.GrantedAccess > 1000$orcafix$, updated_at = NOW()
WHERE t_code = 'T1185' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'fc7c209359dc0351a535c9ba3602f12b';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.ForcedAuthentication
description: Detect T1187 Forced Authentication via lure files and outbound NTLM attempts
sources:
- name: SuspiciousLureFiles
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image, EventData.TargetFilename, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11
      AND (EventData.TargetFilename =~ '''(?i)\\(Desktop|Downloads|Public|Temp)\\.*\.(lnk|scf|url)$'''
           OR EventData.TargetFilename =~ '''(?i)\\(Normal|Document)\.dot[mx]?$''')
    ORDER BY timestamp DESC
- name: OutboundNTLMConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image, EventData.DestinationIp, EventData.DestinationPort, EventData.Protocol
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
      AND (EventData.DestinationPort = 445 OR EventData.DestinationPort = 139 OR EventData.DestinationPort = 80 OR EventData.DestinationPort = 443)
      AND NOT EventData.DestinationIp =~ '''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|127\.)'''
    ORDER BY timestamp DESC
- name: FileAccessEvents
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.SubjectUserName, EventData.ObjectName, EventData.AccessMask
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4663, 4670, 4656)
      AND EventData.ObjectName =~ '''(?i)\.(lnk|scf|url|dot[mx]?)$'''
    ORDER BY timestamp DESC
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1187' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '596a11f470d5f23bb35aaa9ce97ca7fd';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image, EventData.DestinationIp, EventData.DestinationPort, EventData.Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (EventData.DestinationPort = 445 OR EventData.DestinationPort = 139 OR EventData.DestinationPort = 80 OR EventData.DestinationPort = 443) AND NOT EventData.DestinationIp =~ '''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|127\.)''' ORDER BY timestamp DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1187' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '9b7fb1cecf47a82c548cb0043557f013';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.DriveByCompromise.Detection
description: Detects drive-by compromise by correlating suspicious browser child processes with network connections and file drops.
sources:
- name: SuspiciousBrowserChildren
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ProcessId AS PID,
           EventData.Image AS Image,
           EventData.ParentImage AS ParentImage,
           EventData.CommandLine AS CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND EventData.ParentImage =~ '''(?i)(chrome|msedge|firefox)\.exe$'''
      AND EventData.Image =~ '''(?i)(cmd|powershell|wscript|cscript|mshta|rundll32)\.exe$'''
- name: BrowserNetworkConnections
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ProcessId AS PID,
           EventData.Image AS Image,
           EventData.DestinationHostname AS DestHost,
           EventData.DestinationPort AS DestPort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
      AND EventData.Image =~ '''(?i)(chrome|msedge|firefox)\.exe$'''
- name: TempFileCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ProcessId AS PID,
           EventData.Image AS Image,
           EventData.TargetFilename AS TargetFilename
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11
      AND EventData.TargetFilename =~ '''(?i)(temp|appdata).*\.(exe|scr|bat|vbs|js)$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1189' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '56e835707179cf69652146f3d1ab5772';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS TimeCreated, EventData.ProcessId, EventData.Image, EventData.ParentImage, EventData.CommandLine, EventData.ParentProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.ParentImage =~ '''(?i)(chrome|msedge|firefox)\.exe$''' AND EventData.Image =~ '''(?i)(cmd|powershell|wscript|cscript|mshta|rundll32)\.exe$'''$orcafix$, updated_at = NOW()
