UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.SupplyChainCompromise
description: Detect supply chain compromise through correlated installation and execution events
sources:
- name: RecentInstalls
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image, EventData.CommandLine, EventData.ProcessId,
           EventData.ParentImage, hash(path=EventData.Image) as FileHash
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i).*\\(setup|install|update).*\.exe$'''
           OR EventData.CommandLine =~ '(?i).*(install|update|setup)')
- name: UnsignedImageLoads
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image, EventData.ImageLoaded, EventData.Signed,
           EventData.Signature, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7 AND (EventData.Signed = 'false' OR EventData.Signature = '')
- name: CodeIntegrityViolations
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData, System.EventID.Value as EventID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-CodeIntegrity%4Operational.evtx')
    WHERE EventData =~ '(?i).*(invalid.*hash|unsigned.*image).*'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1195' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'd4906ea4297bc1ae3282dafcf120b8f9';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.ParentCommandLine, EventData.ProcessId, EventData.ParentProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i).*\\(setup|install|update).*\.exe$''' OR EventData.ParentImage =~ '''(?i).*\\(setup|install|update).*\.exe$''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1195' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '2459b776329c3fea80664ae9cc0137c8';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.SupplyChainCompromise
description: Detect compromise of software dependencies and development tools
sources:
- name: PackageManagerActivity
  query: |
