- name: SuspiciousFileWrites
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.TargetFilename as TargetFile FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)(node_modules|site-packages|\.nuget|\.gradle|\.m2).*\.(exe|dll|ps1|bat|js)$'''
- name: PostInstallExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.Computer AS Computer, EventData.ParentImage as ParentImage, EventData.Image as Image, EventData.CommandLine as CommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.ParentImage =~ '''(?i)(npm|node|python|pip)\.exe$''' AND EventData.Image =~ '''(?i)(cmd|powershell|cscript|wscript)\.exe$'''
- name: NetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.DestinationHostname as Destination, EventData.DestinationPort as Port FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.Image =~ '''(?i)(npm|node|python|pip|dotnet)\.exe$''' AND NOT EventData.DestinationHostname =~ '''(?i)(npmjs\.org|pypi\.org|nuget\.org|maven\.apache\.org)$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1195.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '91929dbebcdf967a961c7c3da125976f';

