  query: |
    SELECT timestamp, Computer, ProcessId, TargetFilename, Image
    FROM Artifact.Windows.EventLogs.Evtx
    WHERE Channel = 'Microsoft-Windows-Sysmon/Operational' AND System.EventID.Value = 11 AND TargetFilename =~ '''(?i)c:\\program files|c:\\programdata'''
- name: NetworkConnections
