UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Hardware.SupplyChain.Compromise
description: Detect hardware supply chain compromise through firmware integrity and boot process monitoring
sources:
- name: CodeIntegrityViolations
  query: |
    SELECT System.TimeCreated, System.EventID.Value, EventData.FileNameBuffer, EventData.ProcessId, EventData.Hash
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (3001, 3002, 3023) AND EventData.FileNameBuffer =~ '(?i)(boot|firmware|efi)'
- name: SuspiciousServices
  query: |
    SELECT System.TimeCreated, EventData.ServiceName, EventData.ImagePath, EventData.StartType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx')
    WHERE System.EventID.Value = 7045 AND EventData.StartType IN (0, 1)
- name: BootDriverLoads
  query: |
    SELECT System.TimeCreated, EventData.ImageLoaded, EventData.ProcessId, EventData.Signed, EventData.SignatureStatus
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 6 AND (NOT EventData.Signed = 'true' OR EventData.ImageLoaded =~ '(?i)(boot|firmware)')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1195.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'eedb2cc8fa4d19ad181ab52b2fe3eb8b';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated, EventData.ServiceName, EventData.ImagePath, EventData.ServiceType, EventData.StartType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx') WHERE System.EventID.Value = 7045 AND (EventData.StartType = 0 OR EventData.StartType = 1) AND NOT EventData.ImagePath =~ '''(?i)\\windows\\system32\\'''$orcafix$, updated_at = NOW()
