UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.BITSJobs
description: Detect BITS job abuse across process creation, BITS operations, and network activity
sources:
- name: BITSProcessExecution
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, System.Computer, EventData.SubjectUserName, EventData.NewProcessName, EventData.CommandLine, 'Process Creation' AS EventType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''(?i)bitsadmin\.exe$''' OR (EventData.NewProcessName =~ '''(?i)powershell\.exe$''' AND EventData.CommandLine =~ '(?i)(Start-BitsTransfer|Add-BitsFile|Set-BitsTransfer)'))
- name: BITSOperationalEvents
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, System.Computer, System.EventID.Value, UserData AS JobData, 'BITS Operation' AS EventType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (3, 4, 59, 60)
- name: PowerShellBITSCommands
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, System.Computer, EventData.ScriptBlockText, 'PowerShell Script' AS EventType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx') WHERE System.EventID.Value = 4104 AND EventData.ScriptBlockText =~ '(?i)(Start-BitsTransfer|Add-BitsFile|Set-BitsTransfer|New-BitsTransfer)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1197' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'ef5b7847930c615ebc6089971d627052';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)bitsadmin\.exe$''' OR (EventData.Image =~ '''(?i)powershell\.exe$''' AND EventData.CommandLine =~ '(?i)(Start-BitsTransfer|Add-BitsFile|Set-BitsTransfer|Get-BitsTransfer)')) LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''(?i)bitsadmin\.exe$''' OR (EventData.NewProcessName =~ '''(?i)powershell\.exe$''' AND EventData.CommandLine =~ '(?i)(Start-BitsTransfer|Add-BitsFile|Set-BitsTransfer|Get-BitsTransfer)')) SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1197' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'dacf50a94eaf0409d04157da488f5435';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.TrustedRelationshipAbuse
description: Detect abuse of trusted third-party relationships through correlated authentication and privilege escalation events
sources:
