    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName as Username, EventData.ObjectName as AccessedObject, EventData.AccessMask as Permissions FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4663 AND EventData.SubjectUserName =~ '(?i)(service|admin|msp|vendor|contractor)' AND EventData.ObjectName =~ '''(?i)(ntds\.dit|sam|system|security|admin\$|c\$)'''
$orcafix$, updated_at = NOW()
