UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetUserName as Username, EventData.TargetDomainName as Domain, EventData.LogonType as LogonType, EventData.IpAddress as SourceIP, EventData.WorkstationName as Workstation FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4624 AND (EventData.LogonType = 3 OR EventData.LogonType = 10) AND EventData.IpAddress != '-' AND EventData.IpAddress != '127.0.0.1' AND EventData.TargetUserName =~ '(?i)(service|admin|msp|vendor|contractor)'$orcafix$, updated_at = NOW()
