UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.HardwareAdditions
description: Detect hardware additions via device installation events and correlate with process activity
sources:
- name: DeviceInstallation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value as EventID, EventData.SubjectUserName as User, EventData.DeviceId as DeviceID, EventData.DeviceDescription as Description
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 6416
- name: USBDeviceEnum
  query: |
    SELECT Key.Name as DevicePath, Key.OSPath as OSPath, FriendlyName, DeviceDesc, Mfg, HardwareID
    FROM glob(globs='HKEY_LOCAL_MACHINE\\SYSTEM\\*ControlSet*\\Enum\\USB\\*\\*', accessor='registry')
    WHERE Data.value
- name: RecentProcesses
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.CommandLine as CommandLine, EventData.User as User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1200' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'f20041fbb204d1e24807a15bb0d36e13';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System, EventData FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 6416 ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1200' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '3c2f6f510dae022d7a05f6cc65a996a8';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.EventID.Value as EventID, EventData.Image as ProcessPath, EventData.CommandLine as CommandLine, EventData.User as User, EventData.ProcessId as PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)net\s+accounts''' OR EventData.CommandLine =~ '(?i)secedit.*export' OR EventData.CommandLine =~ '(?i)Get-ADDefaultDomainPasswordPolicy' OR EventData.CommandLine =~ '(?i)pwpolicy.*getaccountpolicies' OR EventData.CommandLine =~ '''(?i)chage\s+-l''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1201' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'a6ed6ad42e02e9df7de3bdb46cddccb4';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.T1202.IndirectCommandExecution
description: Detect indirect command execution via Windows utilities like forfiles, pcalua, wsl, scriptrunner, ssh
sources:
- name: ProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.ParentCommandLine, EventData.ProcessId, EventData.ParentProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(forfiles|pcalua|scriptrunner|wsl|ssh)\.exe$''' OR EventData.ParentImage =~ '''(?i)(forfiles|pcalua|scriptrunner|wsl|ssh)\.exe$''')
- name: NetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ProcessId, EventData.DestinationIp, EventData.DestinationPort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.Image =~ '''(?i)(forfiles|pcalua|scriptrunner|wsl|ssh)\.exe$'''
- name: FileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ProcessId, EventData.TargetFilename
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND (EventData.Image =~ '''(?i)(forfiles|pcalua|scriptrunner|wsl|ssh)\.exe$''' OR EventData.TargetFilename =~ '''(?i)\.ssh\\config$''')
- name: Prefetch
  query: |
    SELECT OSPath, Name, LastRunTimes, RunCount, FilesAccessed
    FROM Artifact.Windows.Forensics.Prefetch()
    WHERE Name =~ '''(?i)(FORFILES|PCALUA|SCRIPTRUNNER|WSL|SSH)\.EXE'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1202' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '663733cbba72c419e31ec694e354b2e2';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.ParentCommandLine, EventData.ProcessId, EventData.ParentProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(forfiles|pcalua|scriptrunner|wsl|ssh)\.exe$''' OR EventData.ParentImage =~ '''(?i)(forfiles|pcalua|scriptrunner|wsl|ssh)\.exe$''') AND (EventData.CommandLine =~ '''(?i)(/c|/a|-o\s+(ProxyCommand|LocalCommand)|ProxyCommand|LocalCommand)''' OR EventData.ParentImage =~ '''(?i)(forfiles|pcalua|scriptrunner|wsl|ssh)\.exe$''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1202' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '6fc6b6d10e3f4271db978a2894d38999';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.ClientExploitChain
description: Detects exploitation for client execution by correlating application crashes, suspicious child processes, file writes, and network connections.
sources:
- name: ApplicationCrashes
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           System.Computer AS Computer,
           EventData.Application AS App,
           EventData.ModuleName AS ModuleName,
           EventData.ApplicationPath AS AppPath
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Application.evtx')
    WHERE System.EventID.Value IN (1000, 1001)
      AND EventData.Application =~ '(?i)(iexplore|chrome|firefox|winword|excel|powerpnt|acrord32)'
- name: SuspiciousChildren
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           System.Computer AS Computer,
           EventData.Image AS ProcessName,
           EventData.ParentImage AS ParentImage,
           EventData.CommandLine AS CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND EventData.ParentImage =~ '(?i)(iexplore|chrome|firefox|winword|excel|powerpnt|acrord32)'
      AND EventData.Image =~ '''(?i)(cmd|powershell|wscript|mshta|rundll32)\.exe$'''
- name: FileWrites
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           System.Computer AS Computer,
           EventData.TargetFilename AS TargetFilename,
           EventData.Image AS Image
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11
      AND EventData.Image =~ '(?i)(iexplore|chrome|firefox|winword|excel|powerpnt|acrord32)'
      AND (EventData.TargetFilename =~ '(?i)Downloads'
           OR EventData.TargetFilename =~ '''(?i)\\Temp\\'''
           OR EventData.TargetFilename =~ '''(?i)\\AppData\\''')
- name: NetworkConnections
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           System.Computer AS Computer,
           EventData.Image AS Image,
           EventData.DestinationIp AS DestIP,
           EventData.DestinationPort AS DestPort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
      AND EventData.Image =~ '(?i)(iexplore|chrome|firefox|winword|excel|powerpnt|acrord32)'
      AND NOT EventData.DestinationIp =~ '''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|127\.)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1203' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '326fc65ec06619347918d6c6d0ba6b38';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, EventData.Application as FaultingApp, EventData.ModuleName as FaultingModule, EventData.ApplicationPath, EventData.FaultingApplicationStartTime FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Application.evtx') WHERE LogFile = 'Application.evtx' AND System.EventID.Value IN (1000, 1001) AND EventData.Application =~ '(?i)(iexplore|chrome|firefox|msedge|winword|excel|powerpnt|acrord32|flashplayerplugin)' ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1203' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '47e01d7c2414b51320551e2e20a29c9d';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.UserExecutionChain
description: Detect user execution chains from document/browser apps spawning system utilities with network egress
sources:
- name: ProcessCreation
