    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ChildProcess, EventData.CommandLine, EventData.ParentImage, EventData.ProcessId, EventData.ParentProcessId
