    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.DestinationIp, EventData.DestinationHostname, EventData.DestinationPort, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND NOT EventData.DestinationIp =~ '''^(10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.)'''
