WHERE t_code = 'T1204' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '81d294290a22b8da72db9370cf8fd696';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer, EventData.Image as ParentImage, EventData.CommandLine, EventData.ParentImage, EventData.ParentCommandLine, EventData.ProcessId, EventData.ParentProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.ParentImage =~ '''(?i)(winword|excel|powerpnt|acrord32|chrome|msedge|firefox|7zFM|winrar)\.exe$''' AND EventData.Image =~ '''(?i)(powershell|cmd|wscript|cscript|mshta|rundll32|regsvr32|msiexec|curl|bitsadmin)\.exe$'''$orcafix$, updated_at = NOW()
