UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.MaliciousLinkExecution
description: Detect malicious link execution through behavioral chaining of browser network activity and file creation
sources:
- name: SysmonNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.ProcessId as PID, EventData.DestinationIp as DestIP, EventData.DestinationHostname as Hostname
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.Image =~ '''(?i)(chrome|firefox|msedge|outlook|winword)\.exe$'''
- name: SysmonFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.TargetFilename as FilePath
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)(Downloads|Temp|AppData).*\.(exe|zip|iso|js|bat|scr|jar|msi)$'''
- name: BrowserHistory
  query: |
    SELECT url, title, visit_count, datetime(last_visit_time/1000000-11644473600,'unixepoch') as LastVisit
    FROM sqlite(file=expand(path='%LOCALAPPDATA%/Google/Chrome/User Data/Default/History'), query='SELECT url, title, visit_count, last_visit_time FROM urls WHERE url LIKE "http%"')
    WHERE url =~ '''(?i)\.(top|xyz|tk|ml|ga|cf|monster|click)/''' OR url =~ '''bit\.ly|tinyurl|short'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1204.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '7d486e99a44415b2696906629222e00f';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.ProcessId as PID, EventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort, EventData.DestinationHostname as Hostname FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (EventData.Image =~ '''(?i)(chrome|firefox|msedge|outlook|winword)\.exe$''') AND NOT EventData.DestinationIp =~ '''^(10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.)'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1204.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '5cedd4796c37de75dc35ea4c89842526';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1204_002.MaliciousFileExecution
description: Detects malicious file execution via document handlers spawning suspicious processes
sources:
- name: SuspiciousProcessSpawn
  query: |
    SELECT System.TimeCreated, EventData.Image, EventData.ParentImage, EventData.CommandLine, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.ParentImage =~ '''(?i)(winword|excel|powerpnt|acrord32|foxit)\.exe$'''
    AND EventData.Image =~ '''(?i)(powershell|cmd|wscript|regsvr32|rundll32)\.exe$'''
- name: SuspiciousFileCreation
  query: |
    SELECT System.TimeCreated, EventData.Image, EventData.TargetFilename, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)(Downloads|Desktop|Temp).*\.(exe|scr|bat|cmd|ps1|vbs|js)$'''
- name: ZoneIdentifierStreams
  query: |
    SELECT System.TimeCreated, EventData.TargetFilename, EventData.Contents
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 15 AND EventData.TargetFilename =~ '''Zone\.Identifier$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1204.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '54daaa6c4bfeab3377582af3df91d47e';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated, EventData.Image, EventData.ParentImage, EventData.CommandLine, EventData.ProcessId, EventData.ParentProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)(winword|excel|powerpnt|acrord32|foxit|chrome|firefox|msedge)\.exe$''') AND (EventData.Image =~ '''(?i)(powershell|cmd|wscript|cscript|regsvr32|rundll32|msiexec|certutil)\.exe$''' OR EventData.CommandLine =~ '(?i)(powershell|cmd|wscript|rundll32)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1204.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '0fea1fd1ccfa9e57eb4ad2ac696d498e';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeStamp, EventData.Image, EventData.CommandLine, EventData.ProcessId, EventData.ParentImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(curl|wget|bash|sh|python|nc)\.exe$''' OR EventData.CommandLine =~ '(?i)(curl|wget|python|powershell).*(http|https|ftp)') AND System.TimeStamp > timestamp(epoch=now() - 3600)$orcafix$, updated_at = NOW()
WHERE t_code = 'T1204.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'cee29aef37129a07b337c7571901037b';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.T1204004.MaliciousCopyPaste
description: Detects malicious copy-paste execution chains from browsers/email to command interpreters
sources:
- name: ProcessCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId, EventData.ProcessId, EventData.NewProcessName, EventData.CommandLine, EventData.ParentProcessName\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value = 4688 \n  AND EventData.ParentProcessName =~ '''(?i)(chrome\\.exe|firefox\\.exe|msedge\\.exe|outlook\\.exe|winword\\.exe|excel\\.exe)$'''\n  AND EventData.CommandLine =~ '''(?i)(-enc|FromBase64String|IEX\\s*\\(|DownloadString|Invoke-WebRequest|curl.*\\||wget.*\\|)'''\n"
- name: PowerShellScriptBlocks
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ScriptBlockText, EventData.ScriptBlockId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104
      AND EventData.ScriptBlockText =~ '''(?i)(FromBase64String|IEX|Invoke-Expression|DownloadString|Net\.WebClient)'''
- name: FileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.TargetFilename
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11
      AND EventData.TargetFilename =~ '''(?i)(temp|appdata|public).*\.(exe|bat|ps1|vbs|js)$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1204.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '07e8734876b52712b6fb35f5e7fdbe3e';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.MaliciousLibraryInstall
description: Detect malicious library installation via package managers on Windows
sources:
- name: PackageManagerExecution
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath, \n       EventData.CommandLine, EventData.User, EventData.ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 \n  AND (EventData.Image =~ '''(?i)(pip\\.exe|npm\\.cmd|gem\\.exe)'''\n       OR EventData.CommandLine =~ '(?i)(pip install|npm install|gem install)')\nORDER BY EventTime DESC\n"
- name: SuspiciousFileCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetFilename, \n       EventData.ProcessId, EventData.Image\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 11\n  AND EventData.TargetFilename =~ '''(?i)(AppData|Temp|LocalAppData).*\\.(py|js|rb|exe)$'''\nORDER BY EventTime DESC\n"
- name: InterpreterNetworkActivity
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.DestinationHostname,
           EventData.DestinationPort, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
      AND EventData.Image =~ '''(?i)(python\.exe|node\.exe|ruby\.exe)'''
    ORDER BY EventTime DESC
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1204.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'b5f84bbc81695b794f4c91325e7f57ce';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath, EventData.CommandLine, EventData.User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(pip\.exe|npm\.cmd|gem\.exe)''' OR EventData.CommandLine =~ '(?i)(pip install|npm install|gem install)') ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1204.005' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '99df1a014d63fd0a0527c2a8232b0ed0';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.TrafficSignaling
description: Detect port knocking and traffic signaling by correlating failed connections with firewall changes and successful backdoor access
sources:
- name: SysmonNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as Process, EventData.SourceIp as SrcIP, EventData.DestinationPort as DestPort, EventData.Protocol, EventData.Initiated
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
- name: FirewallRuleChanges
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.RuleName, EventData.Origin, EventData.ApplicationPath
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Windows Defender%4Operational.evtx')
    WHERE System.EventID.Value IN (2004, 2005, 2006)
- name: ProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.Image =~ 'netsh.exe' OR EventData.CommandLine =~ 'New-NetFirewallRule')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1205' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'fd8a76e6c1f6b257955b024f6e8630ba';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort, EventData.Protocol, EventData.Initiated FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.Initiated = 'true' ORDER BY EventTime$orcafix$, updated_at = NOW()
WHERE t_code = 'T1205' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '6d487bc2c72b2e2ff833ce0465f64d31';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.PortKnocking
description: Detect port knocking sequences by correlating network connections and firewall rule changes
sources:
- name: FirewallDrops
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.SourceAddress as SourceIP, \n       EventData.DestPort as DestPort, EventData.Protocol\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value = 5152 AND EventData.Direction = 'Inbound'\nORDER BY EventTime\n"
- name: SysmonConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceIp as SourceIP,
           EventData.DestinationPort as DestPort, EventData.Initiated
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
    ORDER BY EventTime
- name: FirewallRuleChanges
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.RuleName, EventData.Action,
           EventData.Direction, Message
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Windows Defender%4Operational.evtx')
    WHERE System.EventID.Value IN (2004, 2005, 2006)
    ORDER BY EventTime
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1205.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '90e569021ba1d400d754e06ee7453e99';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceAddress as SourceIP, EventData.DestPort as DestPort, EventData.Protocol, Message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (2004, 2005, 2006) OR (System.EventID.Value = 5152 AND EventData.Direction = 'Inbound') ORDER BY EventTime$orcafix$, updated_at = NOW()
WHERE t_code = 'T1205.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'd04105565ed64c6a5b38160070e7daf6';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath, EventData.ImageLoaded as LoadedDLL, EventData.ProcessId as PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND (EventData.ImageLoaded =~ '''(?i)wpcap\.dll$''' OR EventData.ImageLoaded =~ '''(?i)packet\.dll$''' OR EventData.ImageLoaded =~ '(?i)npcap')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1205.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '70f09b93736f4fa7ea7d84dea70395e6';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.RogueDomainController
description: Detects DCShadow and rogue Domain Controller activity through AD object creation and replication events
sources:
- name: ADObjectModification
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, \n       EventData.SubjectUserName as User,\n       EventData.ObjectName as ADObject,\n       EventData.ObjectType,\n       EventData.AccessMask,\n       EventData.Properties as AccessedProperties\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value = 4662 \n  AND EventData.ObjectName =~ 'CN=Configuration'\n  AND (EventData.ObjectType =~ 'nTDSDSA' OR EventData.ObjectType =~ 'server')\n"
- name: ReplicationEvents
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID,
           EventData.SubjectUserName as User,
           EventData.SourceDRA as SourceDRA,
           EventData.DestinationDRA as DestinationDRA,
           EventData.NamingContext
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4928, 4929)
- name: SuspiciousProcesses
  query: |
    SELECT Pid, Ppid, Name, CommandLine, Username, Exe
    FROM Artifact.Windows.System.Pslist()
    WHERE Name =~ '(?i)(mimikatz|dcshadow)' OR CommandLine =~ '(?i)(dcshadow|lsadump::dcshadow)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1207' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '628acce97b00ffec6d265d24036e1fad';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, EventData.SubjectUserName as User, EventData.ObjectName as ADObject, EventData.ObjectType, EventData.AccessMask, EventData.Properties as AccessedProperties FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4662, 4928, 4929) AND (EventData.ObjectName =~ 'CN=Configuration' OR EventData.ObjectType =~ 'nTDSDSA' OR EventData.ObjectType =~ 'server')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1207' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '80b4a9aa941b370ee5de12a019f07aee';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1210.RemoteServiceExploitation
description: |
  Detect exploitation of remote services by correlating service crashes with network activity and suspicious process creation
sources:
- name: ServiceCrashes
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.ServiceName as ServiceName, Message
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (7031, 7034, 1000) AND (EventData.ServiceName =~ '(?i)(server|lanman|termservice|winrm|spooler)' OR
         Message =~ '(?i)(smb|rpc|terminal|remote|winrm)')
- name: SuspiciousProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.ParentImage as ParentProcess,
           EventData.CommandLine as CommandLine, EventData.User as User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.ParentImage =~ '''(?i)(services\.exe|lsass\.exe|spoolsv\.exe|winlogon\.exe)''' AND EventData.Image =~ '''(?i)(cmd\.exe|powershell\.exe|wscript\.exe|cscript\.exe|mshta\.exe)'''
- name: NetworkAuthentication
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.LogonType as LogonType,
           EventData.IpAddress as SourceIP, EventData.TargetUserName as TargetUser
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4624, 4625) AND EventData.LogonType = 3 AND EventData.IpAddress != '-' AND (EventData.TargetUserName = 'ANONYMOUS LOGON' OR EventData.Status = 0xc000006d)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1210' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '51776238dac9133025e776537d47cd60';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.Channel AS Channel, System.EventID.Value, EventData, Message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx') WHERE System.EventID.Value IN (7031, 7034, 1000)*3600 AND (Message =~ '(?i)(smb|rpc|terminal|remote|winrm)' OR EventData.ServiceName =~ '(?i)(server|lanman|termservice|winrm|spooler)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1210' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '4d06502ccb0e08380736955160b2ea30';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.DefenseEvasionExploitation
description: Detect exploitation attempts against defensive security software through process crashes and module loading
sources:
- name: SecurityProcessCrashes
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ApplicationName as CrashedApp, EventData.FaultingModule as FaultModule
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Application.evtx')
    WHERE System.EventID.Value = 1000 AND EventData.ApplicationName =~ '(?i)(defender|symantec|mcafee|crowdstrike|carbon|sentinel|kaspersky)'
- name: SuspiciousModuleLoads
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as TargetProcess, EventData.ImageLoaded as LoadedModule, EventData.Signed
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7 AND EventData.Image =~ '(?i)(defender|symantec|mcafee|crowdstrike|carbon|sentinel)' AND (EventData.Signed = 'false' OR EventData.ImageLoaded =~ '(?i)(temp|appdata|programdata)')
- name: PrivilegeEscalation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName, EventData.PrivilegeList
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4672 AND EventData.SubjectUserName =~ '(?i)(system|defender|av|security)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1211' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'ce59d73169eff740f0033ba23c2c4e05';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer, EventData, UserData FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Application.evtx') WHERE System.EventID.Value = 1000 AND EventData.ApplicationName =~ '(?i)(defender|symantec|mcafee|crowdstrike|carbon|sentinel)'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1211' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '6938f503b864e5ea44a431246d04af45';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.CredentialExploitation
description: Detects exploitation attempts targeting credential access mechanisms including Kerberos exploitation and LSASS memory access
sources:
- name: KerberosAnomalies
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetUserName as Username, EventData.ServiceName as Service, EventData.TicketEncryptionType as EncryptionType, EventData.IpAddress as SourceIP, EventData.Status as FailureCode\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value IN (4768, 4769, 4770, 4771) AND \n(EventData.TicketEncryptionType IN ('0x17', '0x18') OR \n EventData.Status = '0x9' OR \n EventData.TicketOptions =~ '(?i)0x40810010')\n"
- name: LSASSMemoryAccess
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceImage as SourceProcess, EventData.TargetImage as TargetProcess, EventData.GrantedAccess as AccessRights, EventData.SourceProcessId as PID\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 10 AND EventData.TargetImage =~ 'lsass.exe' AND \nEventData.GrantedAccess IN (0x1010, 0x1038, 0x1410, 0x147a, 0x143a)\n"
- name: AuthServiceCrashes
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.param1 as ServiceName, EventData.param2 as ExitCode
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx')
    WHERE System.EventID.Value = 7031 AND EventData.param1 IN ('lsass', 'netlogon', 'spooler', 'kdc')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1212' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '9ad71222864f9afc41f9935c1b8cb2ea';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetUserName as Username, EventData.ServiceName as Service, EventData.TicketEncryptionType as EncryptionType, EventData.TicketOptions as Options, EventData.IpAddress as SourceIP FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4768, 4769, 4770) AND (EventData.TicketEncryptionType = '0x17' OR EventData.TicketEncryptionType = '0x18' OR EventData.Status = '0x9' OR EventData.TicketOptions =~ '(?i)0x40810010')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1212' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'df2128ed2b6db3cf42c5050ae6d969dd';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS SystemTime, EventData.SubjectUserName AS Username, EventData.ShareName AS ShareName, EventData.RelativeTargetName AS FileName, EventData.IpAddress AS SourceIP FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 5145 AND EventData.ShareName =~ '''SharePoint|IPC\$|ADMIN\$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1213' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '427186ad895cab2b3532a2ee198b2419';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.SharePointCollection
description: Detect SharePoint data collection activities across multiple sources
sources:
- name: PowerShellSharePointActivity
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName as Username, EventData.ScriptBlockText as ScriptContent
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104 AND EventData.ScriptBlockText =~ '''(?i)(SharePoint|PnP\.|Connect-PnPOnline|Get-PnPFile|Export-PnPFile)'''
- name: OneDriveSyncLogs
  query: |
    SELECT OSPath, Size, Mtime as ModifiedTime
    FROM glob(globs='''C:/Users/*/AppData/Local/Microsoft/OneDrive/logs/*.log''')
    WHERE Size > 0 AND Mtime > now() - 604800
- name: SharePointBrowserHistory
  query: |
    SELECT url, title, visit_count, last_visit_time as LastVisit
    FROM sqlite(file='''C:/Users/*/AppData/Local/Google/Chrome/User Data/Default/History''', query='SELECT url, title, visit_count, last_visit_time FROM urls')
    WHERE url =~ '''(?i)sharepoint\.com.*/_layouts/'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1213.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'bfc3629ad1981840718a9ac915e6ca28';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName as Username, EventData.ProcessName as Process, EventData.CommandLine as CommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell/Operational.evtx') WHERE System.EventID.Value = 4104 AND (EventData.ScriptBlockText =~ '''(?i)(SharePoint|PnP\.|Connect-PnPOnline|Get-PnPFile|Export-PnPFile|Get-PnPListItem)''' OR EventData.CommandLine =~ '''(?i)(sharepoint\.com|Download.*\.aspx)''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1213.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '047fdc947d35f6c0f810a79251d7dd24';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.SubjectUserName as Username, EventData.ProcessName as Process, EventData.CommandLine as Command FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell/Operational.evtx') WHERE System.EventID.Value = 4103 AND (EventData.CommandLine =~ '''(?i)git\s+(clone|pull|download)''' OR EventData.CommandLine =~ '''(?i)(github|gitlab|bitbucket)\.(com|org)''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1213.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'b59e27682e645553bd095e7f96ba435c';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: CRM_Data_Access_Detection
description: Detect suspicious access to Customer Relationship Management software data
sources:
- name: Windows_CRM_Authentication
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeGenerated, EventData.TargetUserName as Username, EventData.IpAddress as SourceIP, EventData.LogonProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4624 AND EventData.ProcessName =~ '(?i)(salesforce|dynamics|hubspot|zendesk|zoho)'
- name: Browser_CRM_Downloads
  query: |
    SELECT OSPath, Name, Size, Created, Modified
    FROM glob(globs=['C:/Users/*/Downloads/*.csv', 'C:/Users/*/Downloads/*.xlsx'])
    WHERE Name =~ '(?i)(customer|contact|lead|account|export)' AND Created > now() - 7*24*60*60
- name: CRM_Process_Execution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeGenerated, EventData.Image, EventData.CommandLine, EventData.User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.Image =~ '(?i)(salesforce|dynamics365|hubspot)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1213.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'fe9a625debf200a3c574f288a0fdee07';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeGenerated, EventData.TargetUserName as Username, EventData.IpAddress as SourceIP, EventData.LogonType, EventData.ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4624 AND EventData.ProcessName =~ '(?i)(salesforce|dynamics|hubspot|zendesk)'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1213.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '808ff4584063125e19941a4119f7a2db';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Messaging.DataCollection
description: Detect data collection from Teams and Slack messaging applications
sources:
- name: TeamsProcessExecution
  query: "SELECT timestamp, Exe, CommandLine, User, ParentName \nFROM Artifact.Windows.Sysmon.Evtx()\nWHERE System.EventID.Value = 1 AND (Exe =~ '(?i)teams' OR CommandLine =~ '(?i)(graph|export|ediscovery)')\n"
- name: BrowserMessageDownloads
  query: |
    SELECT url, received_bytes, start_time, target_path
    FROM Artifact.Windows.Browsers.Chrome.Downloads()
    WHERE url =~ '''(?i)(teams\.microsoft|slack\.com|export|download)'''
    AND received_bytes > 1000000
- name: SlackTeamsFileAccess
  query: |
    SELECT OSPath, Mtime, Size
    FROM glob(globs=['C:/Users/*/AppData/Roaming/Microsoft/Teams/**/*.json',
                    'C:/Users/*/AppData/Roaming/Slack/**/*.json'])
    WHERE Mtime > now() - 86400*14
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1213.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '199d4ef1a7313b19be28a249bcbe620f';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, System.Channel AS Channel, EventData, Message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4624 AND EventData.LogonType = 10 AND EventData.ProcessName =~ '(?i)(teams|slack)'*7$orcafix$, updated_at = NOW()
WHERE t_code = 'T1213.005' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '3b45c473aefbc3e60922d1d59a35ac14';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(sqlcmd|mysql|psql|mongo|sqlite3|isql)\.exe$''' OR EventData.CommandLine =~ '(?i)(mysqldump|pg_dump|mongodump|SELECT .* FROM|SHOW DATABASES)') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''(?i)(sqlcmd|mysql|psql|mongo|sqlite3|isql)\.exe$''' OR EventData.CommandLine =~ '(?i)(mysqldump|pg_dump|mongodump|SELECT .* FROM|SHOW DATABASES)') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1213.006' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'c289201e2c82ac6cc26b87b0850667b0';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.T1216.ScriptProxyExecution
description: |
  Detects T1216 System Script Proxy Execution through Microsoft-signed scripts
  proxying execution of malicious payloads via cscript, wscript, and installutil.
sources:
- name: SysmonProcessCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage,\n       EventData.CommandLine, EventData.ParentImage, \n       EventData.ParentCommandLine, EventData.ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 \n  AND (EventData.Image =~ '''(?i)(cscript|wscript|installutil)\\.exe$''' \n       OR EventData.ParentImage =~ '''(?i)(pubprn\\.vbs|SyncAppvPublishingServer\\.vbs)''')\n  AND (EventData.CommandLine =~ '(?i)(http|script:|javascript:)' \n       OR EventData.CommandLine =~ '''(?i)/c\\s.*powershell''')\n"
- name: PowerShellScriptBlock
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ScriptBlockText, \n       EventData.ScriptBlockId, EventData.Path\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx') \nWHERE System.EventID.Value IN (4104, 4103)\n  AND EventData.ScriptBlockText =~ '(?i)(DownloadString|IEX|Invoke-Expression|FromBase64String)'\n"
- name: FileCreationByScripts
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.TargetFilename,
           EventData.ProcessId, EventData.ProcessGuid
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11
      AND EventData.Image =~ '''(?i)(cscript|wscript|installutil)\.exe$'''
      AND EventData.TargetFilename =~ '''(?i)\.(exe|dll|bat|ps1|vbs)$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1216' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '4610ea03def72cf4a5586419751fc219';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.CommandLine, EventData.ParentImage, EventData.ParentCommandLine, EventData.ProcessId, EventData.ParentProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(cscript|wscript|installutil)\.exe$''' OR EventData.ParentImage =~ '''(?i)(pubprn\.vbs|SyncAppvPublishingServer\.vbs)''') AND (EventData.CommandLine =~ '(?i)(http|https|ftp|script:|javascript:)' OR EventData.CommandLine =~ '''(?i)\.(vbs|js|jse).*["\s]+(http|/c\s|powershell)''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1216' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'a60a995c812b04f5878a1b61ab95fe2c';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer, EventData.Image as ProcessImage, EventData.CommandLine as CommandLine, EventData.ProcessId as PID, EventData.ParentImage as ParentImage, EventData.ParentCommandLine as ParentCommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.CommandLine =~ '(?i)pubprn.*script:http' AND EventData.Image =~ '''(?i)(cscript|wscript)\.exe$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1216.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '02034f8b4be24564c7fdf7a84284bcae';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1216002.SyncAppvProxy
description: Detect SyncAppvPublishingServer.vbs proxy execution with PowerShell commands
sources:
- name: SysmonProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.User, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.CommandLine =~ '''(?i)SyncAppvPublishingServer\.vbs'''
- name: PowerShellScriptBlocks
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.ScriptBlockText, EventData.ScriptBlockId, EventData.Path
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104 AND EventData.ScriptBlockText != ''
- name: ProcessAccess
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.SourceImage, EventData.TargetImage, EventData.GrantedAccess, EventData.CallTrace\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 10 AND (EventData.SourceImage =~ '''(?i)wscript\\.exe$''' OR EventData.TargetImage =~ '''(?i)powershell\\.exe$''')\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1216.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '2fe44106cb9c914ff350ebcdf577027d';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.CommandLine as CommandLine, EventData.ParentImage, EventData.ParentCommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.CommandLine =~ '''(?i)SyncAppvPublishingServer\.vbs''' AND (EventData.CommandLine =~ '(?i)powershell' OR EventData.CommandLine =~ '''(?i)\{.*\}''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1216.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '5793bcdbef5d2b882ecfacac075bfd30';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.BrowserInformationDiscovery
description: Detect unauthorized access to browser artifacts across multiple data sources
sources:
- name: SysmonFileAccess
  query: "SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.Image AS ProcessPath, EventData.CommandLine AS CommandLine, EventData.TargetFilename AS AccessedFile\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 11 \nAND EventData.TargetFilename =~ '''(?i).*\\\\(Google|Mozilla|Microsoft)\\\\.*\\\\(History|Bookmarks|Login Data|Cookies)'''\nAND NOT EventData.Image =~ '''(?i).*(chrome|firefox|msedge)\\.exe$'''\n"
- name: PowerShellBrowserEnum
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.ScriptBlockText AS ScriptContent
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104
    AND EventData.ScriptBlockText =~ '''(?i).*(AppData.*Chrome|AppData.*Firefox|\.sqlite|Get-ChildItem.*History|Bookmarks)'''
- name: ProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.Image AS ProcessPath, EventData.CommandLine AS CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
    AND EventData.CommandLine =~ '(?i).*(AppData.*Chrome|AppData.*Firefox|BrowsingHistoryView|ChromeHistoryView)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1217' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'c171e6f9b281d4c5b0a4e5f576f3ba83';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS SystemTime, EventData.Image AS ProcessPath, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.TargetFilename AS AccessedFile FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '(?i).*(Google|Mozilla|Microsoft).*(History|Bookmarks|Login Data|Cookies|Web Data)' OR EventData.TargetFilename =~ '''(?i).*\.sqlite$''') AND NOT EventData.Image =~ '''(?i).*(chrome|firefox|msedge|browser)\.exe$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1217' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '5eb008e3e42739a747e7fbc82ede5c7c';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1218.SignedBinaryProxyExecution
description: Detect signed binary proxy execution across process creation, network activity, and image loads
sources:
- name: ProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime, System.Computer, EventData.Image as ProcessImage, EventData.CommandLine, EventData.ParentImage, EventData.ParentCommandLine FROM parse_evtx(filename=expand(path='C:/Windows/System32/winevt/logs/Microsoft-Windows-Sysmon%4Operational.evtx')) WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(rundll32|regsvr32|msiexec|mshta|certutil)\.exe$''') AND (EventData.CommandLine =~ '(?i)(http|ftp|temp|appdata)' OR EventData.CommandLine =~ '''(?i)(\.dll|\.js|\.vbs|\.hta)''')
- name: NetworkConnections
  query: |
    SELECT System.TimeCreated.SystemTime, System.Computer, EventData.Image, EventData.DestinationHostname, EventData.DestinationIp, EventData.DestinationPort FROM parse_evtx(filename=expand(path='C:/Windows/System32/winevt/logs/Microsoft-Windows-Sysmon%4Operational.evtx')) WHERE System.EventID.Value = 3 AND EventData.Image =~ '''(?i)(rundll32|regsvr32|msiexec|mshta|certutil)\.exe$'''
- name: ImageLoads
  query: |
    SELECT System.TimeCreated.SystemTime, System.Computer, EventData.Image, EventData.ImageLoaded, EventData.Signed FROM parse_evtx(filename=expand(path='C:/Windows/System32/winevt/logs/Microsoft-Windows-Sysmon%4Operational.evtx')) WHERE System.EventID.Value = 7 AND EventData.Image =~ '''(?i)(rundll32|regsvr32|msiexec|mshta)\.exe$''' AND (EventData.Signed = 'false' OR EventData.ImageLoaded =~ '(?i)(temp|appdata|programdata)')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1218' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'e5a31ec295d517fedad6fa4601ba1fff';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.CommandLine, EventData.ParentImage, EventData.ParentCommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(rundll32|regsvr32|msiexec|mshta|certutil)\.exe$''') AND (EventData.CommandLine =~ '(?i)(http|ftp|temp|appdata|programdata|public)' OR EventData.CommandLine =~ '''(?i)(\.dll|\.js|\.vbs|\.hta|\.exe)''' OR EventData.CommandLine =~ '(?i)(javascript:|vbscript:|/c |/k )')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1218' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '43e8bfd7fa19b02426cbef3c54225152';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.CHMExecution
description: Detect malicious Compiled HTML Help file execution via hh.exe
sources:
- name: HHProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as HH_PID, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.CurrentDirectory, EventData.User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.Image =~ '''(?i)hh\.exe$'''
- name: SuspiciousChildProcesses
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId, EventData.ParentProcessId, EventData.Image as ChildImage, EventData.CommandLine as ChildCommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.ParentImage =~ '''(?i)hh\.exe$''' AND EventData.Image =~ '''(?i)(cmd\.exe|powershell\.exe|wscript\.exe|cscript\.exe|mshta\.exe)$'''
- name: CHMFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetFilename, EventData.ProcessId, EventData.Image
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\.chm$''' AND (EventData.TargetFilename =~ '(?i)(temp|download|appdata)' OR NOT EventData.TargetFilename =~ '(?i)program files')
- name: NetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId, EventData.Image, EventData.DestinationIp, EventData.DestinationPort, EventData.Protocol
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.Image =~ '''(?i)hh\.exe$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1218.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '96a79e72ac966cbb803507acc9024d39';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.CommandLine, EventData.ParentImage, EventData.ParentCommandLine, EventData.CurrentDirectory, EventData.User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.Image =~ '''(?i)hh\.exe$''' AND (EventData.CommandLine =~ '''(?i)\.chm''' OR EventData.CurrentDirectory =~ '(?i)(temp|download|appdata)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1218.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '9aa834c0af9e6f9e174b85e921cecdc3';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.ControlPanelExecution
description: Detects T1218.002 Control Panel proxy execution through control.exe and rundll32.exe with CPL files
sources:
- name: ProcessExecution
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, \n       EventData.CommandLine as CommandLine, EventData.ParentImage as ParentImage,\n       EventData.ProcessId as PID, EventData.ParentProcessId as PPID\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 AND \n      (EventData.Image =~ '''(?i)control\\.exe''' OR EventData.Image =~ '''(?i)rundll32\\.exe''') AND \n      EventData.CommandLine =~ '''(?i)\\.cpl'''\n"
- name: FileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetFilename as FilePath,
           EventData.ProcessId as PID, EventData.Image as ProcessImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\.cpl$''' AND
          NOT EventData.TargetFilename =~ '''(?i)Windows\\System32'''
- name: RegistryModification
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetObject as RegistryKey,\n       EventData.Details as Value, EventData.ProcessId as PID\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 12 AND \n      EventData.TargetObject =~ '''(?i)Control Panel\\\\Cpls'''\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1218.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'e1e2bfcaf1afc154de3696ae082e5ffa';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.CommandLine as CommandLine, EventData.ParentImage as ParentImage, EventData.ProcessId as PID, EventData.ParentProcessId as PPID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)control\.exe''' OR EventData.Image =~ '''(?i)rundll32\.exe''') AND EventData.CommandLine =~ '''(?i)\.cpl'''$orcafix$, updated_at = NOW()
