UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.CMSTP.Abuse
description: Detect CMSTP.exe abuse for defense evasion via malicious INF files
sources:
- name: CMSTPProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.CommandLine, EventData.ProcessId, EventData.ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.Image =~ '''(?i)cmstp\.exe$'''
- name: CMSTPNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.DestinationIp, EventData.DestinationPort, EventData.Protocol
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.Image =~ '''(?i)cmstp\.exe$'''
- name: SuspiciousINFFiles
  query: |
    SELECT OSPath, Size, Mtime, Atime, Ctime
    FROM glob(globs=['C:/Users/*/**.inf', 'C:/Temp/**.inf', 'C:/Windows/Temp/**.inf'])
    WHERE NOT OSPath =~ '(?i)system32|syswow64'
$orcafix$, updated_at = NOW()
