    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId,
           EventData.Image as Image, EventData.DestinationIp as DestIP,
           EventData.DestinationHostname as DestHostname, EventData.DestinationPort as DestPort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/logs/Microsoft-Windows-Sysmon%4Operational.evtx')
