UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as Image, EventData.CommandLine as CommandLine, EventData.ParentImage as ParentImage, EventData.ParentCommandLine as ParentCommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND Image =~ '''(?i).*mshta\.exe$''' AND (CommandLine =~ "(?i).*(javascript:|vbscript:|http://|https://|script:|.hta).*" OR CommandLine =~ "(?i).*GetObject.*script:.*")$orcafix$, updated_at = NOW()
