UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.T1218_007.MsiexecAbuse
description: Detect msiexec.exe abuse for proxy execution via remote MSI, UNC paths, or DLL execution
sources:
- name: ProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime as EventTime, EventData.NewProcessName, EventData.CommandLine, EventData.ProcessId, EventData.ParentProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND EventData.NewProcessName =~ 'msiexec.exe' AND (EventData.CommandLine =~ 'http[s]?://' OR EventData.CommandLine =~ '''\\.*\\.*\.msi''' OR EventData.CommandLine =~ '''/a\s''' OR EventData.CommandLine =~ '''\.dll''')
- name: NetworkConnections
  query: |
    SELECT System.TimeCreated.SystemTime as EventTime, EventData.Image, EventData.DestinationHostname, EventData.DestinationIp, EventData.DestinationPort, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value IN (3, 22) AND EventData.Image =~ 'msiexec.exe'
- name: ImageLoads
  query: |
    SELECT System.TimeCreated.SystemTime as EventTime, EventData.Image, EventData.ImageLoaded, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7 AND EventData.Image =~ 'msiexec.exe'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1218.007' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a12c3184a49e85731e43c0452caa3089';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''msiexec\.exe''' AND (EventData.CommandLine =~ 'http[s]?://' OR EventData.CommandLine =~ '''/a\s''' OR EventData.CommandLine =~ '''\.dll''')) LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''msiexec\.exe''' AND (EventData.CommandLine =~ 'http[s]?://' OR EventData.CommandLine =~ '''/a\s''' OR EventData.CommandLine =~ '''\.dll''')) SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1218.007' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '204391aab6cea8e384ce1514a9596ccf';

