UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1218_011.Rundll32Abuse
description: Detects rundll32.exe abuse for defense evasion including suspicious DLL loading, network activity, and file access patterns
sources:
- name: SuspiciousRundll32Execution
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 AND EventData.Image =~ '''(?i)rundll32\\.exe$''' AND \n(EventData.CommandLine =~ '''(?i)(javascript:|mshtml|Control_RunDLL|,#\\d+)''' OR \n EventData.CommandLine =~ '''(?i)(AppData|Temp|Public).*\\.(dll|cpl)''')\n"
- name: SuspiciousDLLLoads
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ImageLoaded, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7 AND EventData.Image =~ '''(?i)rundll32\.exe$''' AND
    (EventData.ImageLoaded =~ '(?i)(AppData|Temp|Public|Downloads)' OR EventData.Signed = 'false')
- name: Rundll32NetworkActivity
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.DestinationIp, EventData.DestinationHostname, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE (System.EventID.Value = 3 OR System.EventID.Value = 22) AND EventData.Image =~ '''(?i)rundll32\.exe$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1218.011' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'f0f338c93749e954fc99d9b9704b6c36';

