UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.MavinjectAbuse
description: Detect mavinject.exe abuse for DLL injection including process creation, cross-process access, and module loads
sources:
- name: MavinjectProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.NewProcessName AS ProcessName,
           EventData.CommandLine AS CommandLine,
           EventData.ParentProcessName AS ParentProcess,
           EventData.ProcessId AS PID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND EventData.NewProcessName =~ '''mavinject\.exe$'''
      AND (EventData.CommandLine =~ '/INJECTRUNNING' OR EventData.CommandLine =~ '/HMODULE')
- name: ProcessAccess
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.SourceProcessId AS SourcePID,
           EventData.SourceImage AS SourceImage,
           EventData.TargetProcessId AS TargetPID,
           EventData.TargetImage AS TargetImage,
           EventData.GrantedAccess AS GrantedAccess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10 AND EventData.SourceImage =~ '''mavinject\.exe$'''
      AND (format(format='0x%x', args=EventData.GrantedAccess) =~ '0x1FFFFF' OR format(format='0x%x', args=EventData.GrantedAccess) =~ '0x1F3FFF')
- name: SuspiciousDLLLoads
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ProcessId AS PID,
           EventData.Image AS ProcessImage,
           EventData.ImageLoaded AS DLLPath,
           EventData.Signed AS IsSigned
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7 AND (EventData.ImageLoaded =~ '\\\\Temp\\\\' OR EventData.ImageLoaded =~ '\\\\Downloads\\\\' OR EventData.ImageLoaded =~ '^\\\\\\\\.*')
      AND EventData.Signed = 'false'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1218.013' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '22eadbcd1f13181f72e3f24150d28b64';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''mavinject\.exe$''' AND (EventData.CommandLine =~ '/INJECTRUNNING' OR EventData.CommandLine =~ '/HMODULE')) LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''mavinject\.exe$''' AND (EventData.CommandLine =~ '/INJECTRUNNING' OR EventData.CommandLine =~ '/HMODULE')) SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1218.013' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '2ac4209263a7fb6d48f8668de02aeb2f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.MMC.ProxyExecution
description: Detect MMC proxy execution via malicious .msc files and COM CLSID abuse
sources:
- name: MMC_ProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.Image AS ProcessPath, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.Image =~ '''(?i)mmc\.exe$''' AND (EventData.CommandLine =~ '(?i)-embedding|/a' OR EventData.CommandLine =~ '''(?i)\\users\\.*\.msc''')
- name: MMC_ImageLoads
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.ProcessId AS PID, EventData.ImageLoaded AS LoadedImage, EventData.Signed AS IsSigned FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND EventData.Image =~ '''(?i)mmc\.exe$''' AND (EventData.ImageLoaded =~ '''(?i)\\users\|\\temp\|\\appdata\\''' OR EventData.Signed = 'false')
- name: Suspicious_MSC_Files
  query: |
    SELECT OSPath, Size, Mtime, Atime, Ctime FROM glob(globs=['C:/Users/*/Downloads/*.msc', 'C:/Users/*/AppData/**/*.msc', 'C:/Users/*/Desktop/*.msc', 'C:/Windows/Temp/*.msc']) WHERE Size > 0
- name: CLSID_Registry_Analysis
  query: |
    SELECT Key.OSPath.Path AS RegistryPath, Key.ModTime AS ModifiedTime, Data.value AS CLSIDValue FROM read_reg_key(key='SOFTWARE/Classes/CLSID/*/InprocServer32') WHERE Data.value =~ '''(?i)\\users\|\\temp\|\\appdata\\'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1218.014' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'c2450f797b3c4042ccb41ed8d4aa903c';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image AS ProcessPath, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.ProcessId AS PID, EventData.ParentProcessId AS PPID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.Image =~ '''(?i)mmc\.exe$''' AND (EventData.CommandLine =~ '(?i)-embedding|/a' OR EventData.CommandLine =~ '''(?i)\\users\\.*\.msc|\\appdata\\.*\.msc|\\temp\\.*\.msc|\\downloads\\.*\.msc''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1218.014' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '0ca1ec36693c440d9e04f0544740286f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.ElectronAbuseHunt
description: Hunt for T1218.015 Electron application abuse across process creation and file modification events
sources:
- name: SuspiciousElectronProcesses
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.Image AS ProcessPath, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.ParentCommandLine AS ParentCommandLine, EventData.ProcessId AS PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)(teams|slack|discord|signal|code)\.exe$''') AND (EventData.Image =~ '''(?i)(cmd|powershell|wscript|python)\.exe$''' OR EventData.CommandLine =~ '(?i)(--gpu-launcher|--disable-gpu-sandbox)')
- name: ElectronFileModifications
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.TargetFilename AS FilePath, EventData.ProcessId AS PID, EventData.Image AS ProcessImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i).*\\(teams|slack|discord|signal)\\.*\\(app\.asar|\.js)$'''
- name: ElectronNetworkConnections
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.Image AS ProcessImage, EventData.DestinationIp AS DestIP, EventData.DestinationPort AS DestPort, EventData.ProcessId AS PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.Image =~ '''(?i)(teams|slack|discord|signal)\.exe$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1218.015' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '177fd89fe6f5ab301d8993498f1b1d9b';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image AS ProcessPath, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.ParentCommandLine AS ParentCommandLine, EventData.ProcessId AS PID, EventData.ParentProcessId AS PPID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)(teams|slack|discord|signal|code|chrome)\.exe$''') AND (EventData.Image =~ '''(?i)(cmd|powershell|wscript|cscript|rundll32)\.exe$''' OR EventData.CommandLine =~ '(?i)(--gpu-launcher|--disable-gpu-sandbox)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1218.015' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '68753eacc0bf85f742eb87e6ba260fdb';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.RemoteAccessTools
description: Detect remote access tool execution, persistence, and network activity
sources:
- name: ProcessExecution
  query: "SELECT System.TimeCreated.SystemTime AS Timestamp,\n       EventData.Image AS ProcessPath,\n       EventData.CommandLine AS CommandLine,\n       EventData.User AS User,\n       EventData.ProcessId AS PID\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 \n  AND (EventData.Image =~ '(?i)(teamviewer|anydesk|screenconnect|vnc|remotepc)'\n  OR EventData.CommandLine =~ '(?i)(remote|connect|tunnel|listen|reverse)')\n"
- name: NetworkConnections
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.Image AS ProcessPath,
           EventData.ProcessId AS PID,
           EventData.DestinationIp AS DestIP,
           EventData.DestinationPort AS DestPort,
           EventData.Protocol AS Protocol
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
      AND EventData.Image =~ '(?i)(teamviewer|anydesk|screenconnect|vnc|remotepc|chrome)'
      AND NOT EventData.DestinationIp =~ '''^(10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.)'''
- name: ServiceInstallation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ServiceName AS ServiceName,
           EventData.ImagePath AS ServicePath,
           EventData.ServiceType AS ServiceType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx')
    WHERE System.EventID.Value = 7045
      AND (EventData.ServiceName =~ '(?i)(teamviewer|anydesk|screenconnect|remote)'
      OR EventData.ImagePath =~ '(?i)(teamviewer|anydesk|screenconnect|vnc|remote)')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1219' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a89ed9e51e5ebae98aa49e215a8d81d6';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.IDETunneling
description: Detect IDE tunneling activity via process creation, file artifacts, and network connections
sources:
- name: ProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as Image, EventData.CommandLine as CommandLine, EventData.ParentImage as ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.CommandLine =~ "(?i)(code|jetbrains).*(tunnel|--remote|--host)"
- name: NetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as Image, EventData.DestinationHostname as DestHost, EventData.DestinationPort as DestPort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND (EventData.DestinationHostname =~ '''(?i)(tunnels\.api\.visualstudio\.com|.*\.devtunnels\.ms)''' OR EventData.Image =~ '''(?i)code\.exe''')
- name: TunnelConfigs
  query: |
    SELECT OSPath, Size, Mtime, Atime, Ctime
    FROM glob(globs=[environ(var="USERPROFILE") + "/.vscode-cli/code_tunnel.json", environ(var="USERPROFILE") + "/.jetbrains/**/tunnel*"])
- name: FileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetFilename as TargetFile, EventData.ProcessId as ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ "(?i)(vscode-cli|jetbrains).*(tunnel|config)"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1219.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '3a4d50607ed858b9db5ea3b695eaf90a';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as Image, EventData.CommandLine as CommandLine, EventData.ParentImage as ParentImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ "(?i)(code|jetbrains).*(tunnel|--remote|--host)" OR EventData.Image =~ '''(?i)(code\.exe|jetbrains)''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1219.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '421d59b36a2d1006ad1df4440f13010a';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.RMM.Detection
description: Detect Remote Desktop Software installation and network beaconing activity
sources:
- name: RMM_File_Creation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.TargetFilename as CreatedFile, EventData.ProcessGuid as ProcessGuid\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 11 \nAND (EventData.TargetFilename =~ 'TeamViewer|AnyDesk|ScreenConnect|LogMeIn|AmmyyAdmin|vnc|tightvnc'\n     OR EventData.Image =~ 'TeamViewer|AnyDesk|ScreenConnect|LogMeIn|AmmyyAdmin|vnc')\n"
- name: RMM_Network_Connections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.DestinationIp, EventData.DestinationPort, EventData.ProcessGuid
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
    AND EventData.Image =~ 'TeamViewer|AnyDesk|ScreenConnect|LogMeIn|AmmyyAdmin|vnc|tightvnc'
    AND NOT EventData.DestinationIp =~ '''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.)'''
- name: RMM_Application_Logs
  query: |
    SELECT OSPath, Size, Mtime, Atime, Ctime
    FROM glob(globs=['C:/Users/*/AppData/Roaming/TeamViewer/Connections_incoming.txt',
                     'C:/ProgramData/AnyDesk/ad.trace',
                     'C:/ProgramData/AnyDesk/service.conf',
                     'C:/Users/*/AppData/Local/ScreenConnect Client*/user.config'])
    WHERE Size > 0
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1219.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '33e30dfa459feabf58053753b28b2384';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.TargetFilename as CreatedFile, EventData.ProcessGuid as ProcessGuid FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ 'TeamViewer|AnyDesk|ScreenConnect|LogMeIn|AmmyyAdmin|vnc|tightvnc|x11vnc' OR EventData.Image =~ 'TeamViewer|AnyDesk|ScreenConnect|LogMeIn|AmmyyAdmin|vnc')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1219.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '3d5bcc7c40f666620fbef7e0fc7a5915';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.RemoteAccessHardware
description: Detect TinyPilot, PiKVM and similar remote access hardware via USB enumeration and file artifacts
sources:
- name: USBDeviceEnumeration
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.VendorID as VendorID, EventData.DeviceInstanceId as DeviceID, EventData.FriendlyName as DeviceName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Windows Defender%4Operational.evtx')
    WHERE System.EventID.Value = 2003 AND (EventData.VendorID =~ '(?i)(tinypilot|pikvm)' OR EventData.FriendlyName =~ '(?i)(tinypilot|pikvm|remote.*kvm)')
- name: RemoteAccessFiles
  query: |
    SELECT OSPath, Size, Mtime, Atime, Ctime
    FROM glob(globs=['C:/Program Files/TinyPilot/**', 'C:/opt/tinypilot*/**', 'C:/Users/*/AppData/*/tinypilot*', 'C:/Users/*/AppData/*/pikvm*'])
- name: USBRegistryArtifacts
  query: |
    SELECT Key.Name as KeyPath, Name, Data.value as Value
    FROM glob(globs=['HKEY_LOCAL_MACHINE/SYSTEM/CurrentControlSet/Enum/USB/**'], accessor='registry')
    WHERE Name = 'FriendlyName' AND str(str=Data.value) =~ '(?i)(tinypilot|pikvm|remote.*kvm)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1219.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '20646fffa54939de5e3bb08d19a5377e';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1220.XSLScriptProcessing
description: Detects XSL Script Processing via msxsl.exe and wmic.exe with embedded script execution
sources:
- name: SysmonProcessCreation
  query: "SELECT System.TimeCreated.SystemTime AS Timestamp,\n       EventData.Image AS ProcessImage,\n       EventData.CommandLine AS CommandLine,\n       EventData.ParentImage AS ParentImage,\n       EventData.ProcessId AS ProcessId,\n       EventData.ParentProcessId AS ParentProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 \n  AND (EventData.Image =~ '''(?i)msxsl\\.exe$''' OR \n       (EventData.Image =~ '''(?i)wmic\\.exe$''' AND EventData.CommandLine =~ '(?i)/FORMAT'))\n"
- name: SysmonImageLoads
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.Image AS ProcessImage,
           EventData.ImageLoaded AS LoadedDLL,
           EventData.ProcessId AS ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7
      AND EventData.ImageLoaded =~ '''(?i)(jscript\.dll|vbscript\.dll)$'''
      AND EventData.Image =~ '''(?i)(msxsl\.exe|wmic\.exe)$'''
- name: XSLFiles
  query: |
    SELECT OSPath, Size, Mtime, Atime, Ctime,
           read_file(filename=OSPath, length=8192) AS FileContent
    FROM glob(globs=['C:/Users/*/AppData/Local/Temp/*.xsl',
                     'C:/Windows/Temp/*.xsl',
                     'C:/Users/*/Downloads/*.xsl'])
    WHERE FileContent =~ '(?i)<msxsl:script|javascript|vbscript'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1220' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '2cda22a0da4fba0a1e2a6286341b0777';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, EventData.Image AS ProcessImage, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentImage, EventData.ProcessId AS ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)msxsl\.exe$''' OR (EventData.Image =~ '''(?i)wmic\.exe$''' AND EventData.CommandLine =~ '(?i)/FORMAT'))$orcafix$, updated_at = NOW()
WHERE t_code = 'T1220' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'c6f6fbf8822e66ffc1b811d48fcf37a8';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.TemplateInjection
description: Detect Office Template Injection attacks through process and network correlation
imports:
- Windows.EventLogs.Evtx
sources:
- name: Office Process Creation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.ProcessId, EventData.ParentProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 \nAND (EventData.ParentImage =~ '''(?i)(winword|excel|powerpnt)\\.exe$''' OR EventData.Image =~ '''(?i)(winword|excel|powerpnt)\\.exe$''')\nAND EventData.Image =~ '''(?i)(powershell|cmd|wscript|cscript|mshta)\\.exe$'''\n"
- name: Office Network Connections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.DestinationIp, EventData.DestinationPort, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
    AND EventData.Image =~ '''(?i)(winword|excel|powerpnt)\.exe$'''
    AND NOT EventData.DestinationIp =~ '''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|127\.0\.0\.1)'''
- name: Office DNS Queries
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.QueryName, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 22
    AND EventData.Image =~ '''(?i)(winword|excel|powerpnt)\.exe$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1221' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'f31e1e9a428d31b5a294b98524e3ade8';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.ParentCommandLine, EventData.ProcessId, EventData.ParentProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)(winword|excel|powerpnt)\.exe$''' OR EventData.Image =~ '''(?i)(winword|excel|powerpnt)\.exe$''') AND (EventData.Image =~ '''(?i)(powershell|cmd|wscript|cscript|mshta)\.exe$''' OR EventData.CommandLine =~ '(?i)(http|https|ftp)://')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1221' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '38f9aa75adba0ac79769d25de1f07ab9';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1222.PermissionModification
description: Detect file and directory permission modifications across multiple log sources
sources:
- name: WindowsPermissionTools
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId,
           EventData.NewProcessName as Image, EventData.CommandLine as CommandLine,
           EventData.SubjectUserName as User, EventData.ParentProcessName as ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''(?i)(icacls|takeown|attrib|cacls)\.exe$'''
                              OR EventData.CommandLine =~ '(?i)(icacls|takeown|attrib|cacls)')
- name: PermissionChanges
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ObjectName as ObjectName,
           EventData.SubjectUserName as User, EventData.PermissionChangeList as Changes
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4670 AND EventData.ObjectName =~ '(?i)(C:\\\\Windows|C:\\\\Program Files|C:\\\\Users)'
- name: PowerShellACLCommands
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ScriptBlockText as ScriptBlock,
           EventData.UserID as User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value IN (4103, 4104) AND EventData.ScriptBlockText =~ '(?i)(Set-Acl|Get-Acl|icacls|takeown)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1222' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '708c851cc1bcf05b388c8b7e2557474a';

