UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.DACLManipulation
description: Multi-stage detection of Windows DACL manipulation activities
sources:
- name: ProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName as User, EventData.NewProcessName as Process, EventData.CommandLine as CommandLine, 'ProcessCreation' as Source
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND (CommandLine =~ '''(?i)(icacls|takeown|attrib|cacls)\.exe''' OR CommandLine =~ '(?i)powershell.*Set-Acl')
- name: PermissionChanges
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName as User, EventData.ObjectName as Object, EventData.OldSd as OldPermissions, EventData.NewSd as NewPermissions, 'PermissionChange' as Source
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4670
- name: FileAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName as User, EventData.ObjectName as Object, EventData.AccessMask as AccessMask, 'FileAccess' as Source
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4663, 4656, 4658) AND AccessMask =~ '(?i)(WriteData|AppendData|WriteAttributes)'
- name: PowerShellACL
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.UserId as User, EventData.ScriptBlockText as ScriptBlock, 'PowerShellACL' as Source
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104 AND ScriptBlock =~ '(?i)(Set-Acl|Get-Acl|SetAccessControl|DACL)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1222.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'c2c04abaaaff9a6c143b61d00ebc81e4';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.ExecutionGuardrails
description: Detect execution guardrails through environmental validation behavioral chains
sources:
- name: ProcessCreationChains
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.NewProcessName, EventData.CommandLine,\n       EventData.ParentProcessName, EventData.ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value = 4688 \n  AND (EventData.NewProcessName =~ '''(?i)(wmic|systeminfo|whoami|hostname|net\\.exe|ipconfig|nltest|dsquery)'''\n  OR EventData.CommandLine =~ '(?i)(win32_computersystem|win32_operatingsystem|win32_networkadapter|registry.*currentversion|domain.*member)')\nORDER BY EventTime\n"
- name: WMIReconnaissance
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, UserData
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-WMI-Activity%4Operational.evtx')
    WHERE System.EventID.Value IN (5857, 5858, 5860, 5861)
      AND UserData =~ '(?i)(win32_computersystem|win32_operatingsystem|win32_processor|win32_physicalmemory)'
    ORDER BY EventTime
- name: PowerShellConditionalExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ScriptBlockText
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104
      AND EventData.ScriptBlockText =~ '(?i)(if.*hostname|if.*domain|if.*computername|if.*registry.*currentversion)'
    ORDER BY EventTime
- name: NetworkValidation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.DestinationHostname, \n       EventData.DestinationIp, EventData.DestinationPort\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 3\n  AND (EventData.DestinationHostname =~ '(?i)(geoip|geolocation|whatismyip|ipinfo)'\n  OR EventData.DestinationPort IN (53, 80, 443))\nORDER BY EventTime\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1480' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '2a92d23058e2e17661ee7c8f747c263f';

