UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.EnvironmentalKeying
description: Detects environmental keying behavioral chains including rapid system discovery followed by cryptographic operations and payload execution.
sources:
- name: SystemDiscovery
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.Image AS ProcessName,
           EventData.CommandLine AS CommandLine,
           EventData.ProcessId AS PID,
           'Discovery' AS ActivityType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.Image =~ '(?i)(wmic|systeminfo|hostname|whoami|net|reg|nltest)'
           OR EventData.CommandLine =~ '(?i)(win32_computersystem|win32_networkadapter|domain|shares)')
- name: CryptographicActivity
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.Image AS ProcessName,
           EventData.ImageLoaded AS LoadedDLL,
           EventData.ProcessId AS PID,
           'Cryptographic' AS ActivityType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7
      AND EventData.ImageLoaded =~ '''(?i)(advapi32|bcrypt|ncrypt|crypt32)\.dll'''
- name: WMIQueries
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ClientProcessId AS PID,
           EventData.Query AS Query,
           'WMI_Discovery' AS ActivityType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-WMI-Activity%4Operational.evtx')
    WHERE System.EventID.Value IN (5857, 5860, 5861)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1480.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '97b5ecde3fafa24baa0635f440ae4609';

