UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1484.DomainPolicyModification
description: Detect Domain or Tenant Policy Modifications across AD and cloud environments
sources:
- name: WindowsADChanges
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.ObjectDN as ObjectDN, \n       EventData.AttributeName as AttributeModified, \n       EventData.SubjectUserName as ModifiedBy,\n       EventData.AttributeValue as NewValue\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') \nWHERE System.EventID.Value IN (5136, 4670, 4656) \n  AND (ObjectDN =~ 'CN=Policies' OR ObjectDN =~ 'CN=System' OR \n       AttributeModified =~ 'gPCFileSysPath|ntSecurityDescriptor|trustDirection')\n"
- name: CorrelatedProcesses
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.User AS User, EventData.ProcessId AS ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 \n  AND (EventData.Image =~ 'powershell|gpmc|dsmod|gpupdate' OR \n       EventData.CommandLine =~ 'Set-GPO|New-GPO|Set-ADTrust|Add-FederatedDomain')\n"
- name: GPOFileChanges
  query: |
    SELECT OSPath, Mtime, Ctime, Size
    FROM glob(globs='C:/Windows/SYSVOL/sysvol/*/Policies/*/gpt.ini')
    WHERE Mtime > now() - 2592000
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1484' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'ed7b455faf2a265fe32e6fd7378779e8';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, EventData.ObjectDN as ObjectDN, EventData.AttributeName as AttributeModified, EventData.SubjectUserName as ModifiedBy, EventData.AttributeValue as NewValue FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (5136, 4670) AND (ObjectDN =~ 'CN=Policies' OR ObjectDN =~ 'CN=System' OR ObjectDN =~ 'trustDirection' OR AttributeModified =~ 'gPCFileSysPath|ntSecurityDescriptor|trustDirection|federationSettings')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1484' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '3d378bbaa88f57be9bd07fcb558c2d01';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.GPOModifications
description: Detect Group Policy Object modifications through AD changes and SYSVOL file activity
sources:
- name: ADObjectChanges
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName as User, \n       EventData.ObjectDN as ObjectPath, EventData.AttributeLDAPDisplayName as Attribute,\n       EventData.AttributeValue as NewValue\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value = 5136 AND \n      (EventData.ObjectDN =~ 'CN=Policies,CN=System' OR EventData.ObjectDN =~ 'groupPolicyContainer')\n"
- name: SysvolFileActivity
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName as User,\n       EventData.ObjectName as FilePath, EventData.AccessMask as Access\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value IN (4663, 4656, 4670) AND \n      EventData.ObjectName =~ 'SYSVOL' AND\n      (EventData.ObjectName =~ 'ScheduledTasks.xml' OR EventData.ObjectName =~ 'GptTmpl.inf' OR EventData.ObjectName =~ 'Registry.pol')\n"
- name: GPOProcessExecution
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.User as User, EventData.Image as ProcessName,\n       EventData.CommandLine as CommandLine\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 AND \n      (CommandLine =~ 'New-GPOImmediateTask' OR CommandLine =~ 'Set-GPRegistryValue' OR \n       CommandLine =~ 'New-GPO' OR EventData.Image =~ 'gpmc.msc')\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1484.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '737c2a26083ba2473a0aea988df2e651';

