UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.TrustModificationHunt
description: |
  Detects domain trust modifications across multiple event sources including
  AD object changes, process execution, and PowerShell activity.
sources:
- name: SecurityEventLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.ObjectClass, EventData.ObjectDN,
           EventData.AttributeLDAPDisplayName, EventData.AttributeValue,
           EventData.SubjectUserName, EventData.SubjectLogonId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (5136, 4704, 4706, 4716) AND
          (EventData.ObjectClass =~ 'trustedDomain' OR
           EventData.AttributeLDAPDisplayName =~ '(?i)(trustPartner|trustDirection|trustType|trustAttributes)' OR
           Message =~ '(?i)(trust.*domain|federat)')
- name: SysmonProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.Image, EventData.CommandLine,
           EventData.User, EventData.ProcessId, EventData.ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND
          (EventData.Image =~ '''(?i)(netdom\.exe|nltest\.exe)''' OR
           EventData.CommandLine =~ '(?i)(trust|federat|domain_trusts)')
- name: PowerShellActivity
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.ScriptBlockText,
           EventData.Path, UserData.EventXML.Event.UserData.ScriptBlockInvocationStartedEventData.UserId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value IN (4103, 4104) AND
          EventData.ScriptBlockText =~ '(?i)(Set-MsolDomainAuthentication|Update-MsolFederatedDomain|ConvertTo-MsolFederatedDomain|New-MsolFederatedDomain|netdom|nltest)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1484.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '4d09a61a2422dd12f1f4a4ff569ddccc';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, EventData.ObjectClass, EventData.ObjectDN, EventData.AttributeLDAPDisplayName, EventData.AttributeValue, EventData.SubjectUserName, EventData.SubjectLogonId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (5136, 4704, 4706, 4716) AND (EventData.ObjectClass =~ 'trustedDomain' OR EventData.AttributeLDAPDisplayName =~ '(?i)(trustPartner|trustDirection|trustType|trustAttributes|msDS-TrustForestTrustInfo)' OR Message =~ '(?i)(trust.*domain|federat)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1484.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'a8586d393c63e1f14372a155bb962d2c';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.DataDestruction
description: Detect T1485 Data Destruction across multiple Windows event sources
sources:
- name: ProcessExecution
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.ProcessId as PID, EventData.Image as ProcessPath, EventData.CommandLine as CmdLine, EventData.User as User, 'Process Creation' as EventType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)(del\s+/[qs]|cipher\s+/w|sdelete|rm\s+-rf|shred\s+-[vfz])''' OR EventData.Image =~ '''(?i)(sdelete|cipher)\.exe$''')
- name: FileDeletion
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.ProcessId as PID, EventData.Image as ProcessPath, EventData.TargetFilename as DeletedFile, EventData.User as User, 'File Deleted' as EventType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 23 AND (EventData.TargetFilename =~ '''(?i)(system32|documents|users\\.*\\desktop|programdata)''' OR EventData.Image =~ '''(?i)(sdelete|cipher)\.exe$''')
- name: FileOverwrite
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.ProcessId as PID, EventData.Image as ProcessPath, EventData.TargetFilename as CreatedFile, EventData.User as User, 'File Created' as EventType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\.(tmp|temp)$''' AND EventData.Image =~ '''(?i)(sdelete|cipher|del|erase)\.exe$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1485' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'b7eb7db1083c1736b9473f982d897016';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, EventData.ProcessId as PID, EventData.Image as ProcessPath, EventData.CommandLine as CmdLine, EventData.User as User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)(del\s+/[qs]|cipher\s+/w|sdelete|rm\s+-rf|shred\s+-[vfz]|dd\s+if=/dev/(zero|urandom))''' OR EventData.Image =~ '''(?i)(sdelete|cipher)\.exe$''')$orcafix$, updated_at = NOW()
