UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.RansomwareDetection
description: Multi-source detection for T1486 Data Encrypted for Impact
sources:
- name: SuspiciousProcessExecution
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.Image, EventData.CommandLine, EventData.User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '(?i)(vssadmin.*delete.*shadows|wbadmin.*delete.*catalog|cipher.*/w)' OR EventData.Image =~ '''(?i)\\(temp|appdata)\\[a-f0-9]{6,}\.exe$''')
- name: MassFileCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.TargetFilename, EventData.Image AS ProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '''(?i)\.(locked|encrypted|enc|decrypt|readme)''' OR EventData.TargetFilename =~ '''(?i)(readme|decrypt|help_decrypt|recover)\.(txt|html|hta)$''')
- name: RegistryModifications
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.TargetObject, EventData.Details
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 13 AND EventData.TargetObject =~ '''(?i)(\\classes\|\\policies\\system\|\\currentversion\\run)'''
