UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1495.FirmwareCorruption
description: Detect firmware corruption attempts across multiple log sources
sources:
- name: SecurityLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.NewProcessName as ProcessName, EventData.CommandLine as CommandLine, EventData.SubjectUserName as User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '(?i)(flashrom|fwupd|nvflash|phoenixtool|afuwin|winflash)' OR EventData.CommandLine =~ '(?i)(bios|uefi|firmware|flash|efi).*(-f|-force|-silent)')
- name: SysmonDrivers
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ImageLoaded as DriverPath, EventData.Hashes as Hashes, EventData.Signed as Signed
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 6 AND (EventData.ImageLoaded =~ '(?i)(flash|firmware|bios|uefi)' OR EventData.Signed = 'false')
- name: KernelBootLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value as EventID, EventData as Details
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE EventData =~ '(?i)(firmware.*integrity|boot.*configuration|validation.*failed)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1495' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '73546d13b330209a7a54eff99116128d';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.ResourceHijacking
description: Detect resource hijacking activities including cryptomining and proxy abuse through process execution, network connections, and system performance indicators.
sources:
- name: SuspiciousProcesses
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath, EventData.CommandLine, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '(?i)(xmrig|cgminer|bfgminer|cpuminer|--donate-level|stratum\\+tcp|--algo=cryptonight)' OR EventData.Image =~ '(?i)\\\\(temp|tmp|appdata\\\\roaming)\\\\.*\\.(exe|bin)$')
- name: MiningNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ProcessId, EventData.DestinationIp, EventData.DestinationPort FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (EventData.DestinationPort IN (3333, 4444, 8333, 9999) OR EventData.DestinationIp =~ '(?i)(pool\\.|mining\\.|stratum\\.|nicehash|nanopool|miningpoolhub)')
- name: MiningDNSQueries
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.QueryName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 22 AND EventData.QueryName =~ '(?i)(pool\\.|mining\\.|stratum\\.|nicehash\\.|nanopool\\.|miningpoolhub\\.|xmrpool\\.|moneropool\\.)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1496' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'e4ca606d9ff57c11752f361e38104736';

