UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.ComputeHijacking
description: Detect cryptocurrency mining and compute hijacking activities across process creation, network connections, and scheduled tasks.
sources:
- name: SuspiciousProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.Image AS ProcessPath,
           EventData.CommandLine AS CommandLine,
           EventData.ParentImage AS ParentProcess,
           EventData.ProcessId AS PID
    FROM parse_evtx(file='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (
        EventData.Image =~ '(?i)(xmrig|cpuminer|cgminer|bfgminer|sgminer|ccminer)'
        OR EventData.CommandLine =~ '(?i)(stratum|mining|pool\\.|--donate-level|--algo)'
        OR (
          EventData.Image =~ '(?i)(svchost|winlogon|csrss)\\.exe$'
          AND NOT EventData.ParentImage =~ '(?i)(services|winlogon|system)'
        )
      )
- name: MiningPoolConnections
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.Image AS ProcessPath,
           EventData.DestinationIp AS DestIP,
           EventData.DestinationPort AS DestPort,
           EventData.ProcessId AS PID
    FROM parse_evtx(file='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND (
        EventData.DestinationPort IN ('3333', '4444', '5555', '8333', '14433')
        OR EventData.DestinationHostname =~ '(?i)(pool|mine|stratum|xmr|btc|eth)'
        OR EventData.DestinationIp =~ '^(45\\.|185\\.|192\\.)'
      )
- name: SuspiciousScheduledTasks
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.TaskName AS TaskName,
           EventData.TaskContent AS TaskContent
    FROM parse_evtx(file='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4698 AND EventData.TaskContent =~ '(?i)(xmrig|cpuminer|mining|stratum|pool)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1496.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '3a8ad23c7743e3d2a04963f83249cd6f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.BandwidthHijacking.Detection
description: Detect bandwidth hijacking through network connections and process execution correlation
sources:
- name: SysmonNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.User AS User, EventData.DestinationIp AS DestinationIp, EventData.DestinationPort AS DestinationPort, EventData.Protocol AS Protocol, EventData.SourcePort AS SourcePort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND (EventData.DestinationPort IN (8080, 3128, 1080, 9050, 4444, 8888) OR Protocol = 'tcp')
    AND EventData.Image =~ '(?i)(proxy|tor|scan|wget|curl|masscan|3proxy|proxychains)'
    ORDER BY timestamp DESC
- name: ProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.CommandLine AS CommandLine, EventData.User AS User, EventData.ParentImage AS ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '(?i)(proxy|scan|wget|curl|masscan|torrent|mining)'
    OR EventData.Image =~ '(?i)(proxy|tor|scan|wget|curl|masscan|3proxy|proxychains)')
    ORDER BY timestamp DESC
- name: NetworkPerformance
  query: |
    SELECT timestamp, Computer, ProcessId, ProcessName, WorkingSetSize, PageFileUsage
    FROM Artifact.Windows.System.Pslist()
    WHERE ProcessName =~ '(?i)(proxy|tor|scan|wget|curl|masscan|3proxy|proxychains)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1496.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '1b2acdd34dbc2921daf6e318573048f4';

