UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: CloudServiceHijacking.Detection
description: Detects T1496.004 Cloud Service Hijacking through authentication events and cloud service artifacts
sources:
- name: WindowsAuthenticationLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.LogonType as LogonType, EventData.TargetUserName as Username, EventData.IpAddress as SourceIP, Message
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4624, 4625) AND (Message =~ '(?i)aws|amazon|cloud|api' OR EventData.ProcessName =~ '(?i)aws|boto|python|curl')
- name: AWSCredentialFiles
  query: |
    SELECT OSPath, Mtime, Atime, Size, hash(path=OSPath) as SHA256
    FROM glob(globs='C:/Users/*/.aws/**', accessor='file')
    WHERE Mtime > timestamp(epoch=now()) - 604800
- name: BrowserCloudConsoleAccess
  query: |
    SELECT url, title, visit_count, last_visit_time
    FROM sqlite(file='C:/Users/*/AppData/Local/Google/Chrome/User Data/Default/History', query='SELECT url, title, visit_count, last_visit_time FROM urls WHERE url LIKE "%console.aws%" OR url LIKE "%platform.openai%" OR url LIKE "%sendgrid%" OR url LIKE "%twilio%"')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1496.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '348e61637bab1698f444a060ef2d1688';

