    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.CommandLine =~ '(?i)(Desktop|Recent|History|Bookmarks|AppData|GetLastInputInfo)'
- name: ProcessAccess
  query: "SELECT System.TimeCreated.SystemTime AS EventTime, EventData.SourceImage, EventData.TargetImage, EventData.GrantedAccess\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 10 AND EventData.TargetImage =~ '''(?i)(explorer\\.exe|dwm\\.exe)'''\n"
- name: WorkstationEvents
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, System.EventID.Value AS EventID, EventData.TargetUserName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4800, 4801)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1497.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '57243e20881c5ce8892d8bc15e3c6315';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image AS ProcessPath, EventData.CommandLine AS CmdLine, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)\\(cmd|powershell|wscript|cscript)\.exe$''' OR EventData.CommandLine =~ '(?i)(Desktop|Recent|History|Bookmarks|AppData)') AND timestamp(epoch=System.TimeCreated.SystemTime) > timestamp(epoch=now() - 3600)$orcafix$, updated_at = NOW()
