UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.TimeBasedEvasion
description: Detect time-based sandbox evasion techniques across multiple data sources
sources:
- name: SysmonProcessCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath, EventData.CommandLine, EventData.ParentImage, EventData.ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 1 \nAND (EventData.CommandLine =~ '''ping\\s+-n\\s+\\d+''' OR EventData.CommandLine =~ '''timeout\\s+/t\\s+\\d+''' OR EventData.CommandLine =~ '''sleep\\s+\\d+''' OR EventData.CommandLine =~ 'Start-Sleep')\n"
- name: ImageLoads
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath, EventData.ImageLoaded
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7
    AND (EventData.ImageLoaded =~ 'kernel32.dll' OR EventData.ImageLoaded =~ 'ntdll.dll')
- name: ExecutableStrings
  query: |
    SELECT OSPath, String
    FROM glob(globs='C:/Users/**')
    WHERE String =~ '(GetTickCount|GetSystemTimeAsFileTime|Sleep|WaitForSingleObject)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1497.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'c645197b27b1979fa7f70b0fb788c2ab';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath, EventData.CommandLine, EventData.ParentImage, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''ping\s+-n\s+\d+''' OR EventData.CommandLine =~ '''timeout\s+/t\s+\d+''' OR EventData.CommandLine =~ '''sleep\s+\d+''' OR EventData.CommandLine =~ 'Start-Sleep' OR EventData.CommandLine =~ 'WaitForSingleObject')$orcafix$, updated_at = NOW()
