UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ProcessId, EventData.DestinationIp, EventData.DestinationPort, EventData.Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.Initiated = "true" GROUP BY EventData.ProcessId, EventData.DestinationPort HAVING count() > 100$orcafix$, updated_at = NOW()
WHERE t_code = 'T1498' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '306338bb769434a6c5e1b2da5138c7c2';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.NetworkFlood
description: Detect Direct Network Flood attacks via high-volume outbound connections
sources:
- name: SysmonNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.DestinationIp AS DestinationIp, EventData.DestinationPort AS DestinationPort, EventData.Protocol AS Protocol, count() as ConnectionCount
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
    GROUP BY ProcessId, DestinationIp, DestinationPort
    HAVING ConnectionCount > 50
    ORDER BY ConnectionCount DESC
- name: ProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND (EventData.CommandLine =~ 'ping.*-t' OR EventData.CommandLine =~ 'curl.*--connect-timeout' OR EventData.CommandLine =~ 'powershell.*while')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1498.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '8f9928990a68a836141509fb415b3c42';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.DestinationIp AS DestinationIp, EventData.DestinationPort AS DestinationPort, EventData.Protocol AS Protocol, count() as ConnectionCount FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 GROUP BY ProcessId, DestinationIp, DestinationPort HAVING ConnectionCount > 100 ORDER BY ConnectionCount DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1498.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '3ae0c21b1cbcd1fc4d9b5d523ee8456d';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Network.ReflectionAmplificationDetection
description: Detect potential reflection amplification DoS attacks across multiple log sources
sources:
- name: SysmonNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) as EventTime,
           EventData.SourceIp as SourceIP,
           EventData.DestinationIp as DestIP,
           EventData.DestinationPort as DestPort,
           EventData.Image as ProcessName,
           'Sysmon' as LogSource
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.Protocol = 'udp'
      AND (EventData.DestinationPort = 53 OR EventData.DestinationPort = 123 OR EventData.DestinationPort = 11211)
      AND NOT EventData.DestinationIp =~ '''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.)'''
- name: SysmonDNSQueries
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) as EventTime,
           EventData.QueryName as QueryName,
           EventData.Image as ProcessName,
           EventData.QueryResults as QueryResults,
           'Sysmon-DNS' as LogSource
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 22
      AND EventData.QueryName =~ '''\.(com|net|org)$'''
- name: ProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image as ProcessPath,
           EventData.CommandLine as CommandLine,
           'Process-Exec' as LogSource
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.Image =~ '(?i)(hping|nping|scapy)' OR EventData.CommandLine =~ '(?i)(udp|amplif|reflect)')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1498.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'cd4a49bfbec22002996025b18e3070bc';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) as EventTime, System.EventID.Value as EventID, EventData.SourceIp as SourceIP, EventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort, EventData.Protocol as Protocol, EventData.Image as ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.Protocol = 'udp' AND (EventData.DestinationPort = 53 OR EventData.DestinationPort = 123 OR EventData.DestinationPort = 11211 OR EventData.DestinationPort = 1900) AND NOT EventData.DestinationIp =~ '''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.)'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1498.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'f2667633f62e68247658a0a39a27116a';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.T1499001.OSExhaustionFlood
description: Detect OS exhaustion flood attacks via TCP state exhaustion
sources:
- name: TCPIPEvents
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           System.EventID.Value,
           System.Computer,
           EventData.Data AS Details
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4226, 4231, 4227)
      AND System.Provider.Name = 'Microsoft-Windows-Tcpip'
      AND EventData.Data =~ '(?i)(connection.*fail|state.*exhaust|queue.*overflow)'
- name: SysmonProcesses
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.Image,
           EventData.CommandLine,
           EventData.ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.Image =~ '(?i)(hping|nping|scapy|flood)'
           OR EventData.CommandLine =~ '(?i)(syn.*flood|ack.*flood|tcp.*flood)')
- name: FirewallConnections
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.SourceAddress,
           EventData.DestPort,
           count() AS ConnectionCount
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 5156
      AND EventData.Protocol = 6
    GROUP BY EventData.SourceAddress, bin(System.TimeCreated.SystemTime, '60s')
    HAVING ConnectionCount > 100
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1499.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '5038d35787659f94b8c25effeddf94d1';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.ServiceExhaustionFlood
description: Detect endpoint denial of service via service exhaustion flood attacks
sources:
- name: SysmonNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.SourceIp as SourceIP, EventData.DestinationPort as Port, EventData.ProcessId as PID, EventData.Image as Process
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.DestinationPort IN (80, 443, 8080, 8443)
- name: ApplicationErrors
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, System.EventID.Value as EventID, EventData.Data as ErrorData
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Windows Defender%4Operational.evtx')
    WHERE System.EventID.Value IN (1000, 1001, 1002) AND EventData.Data =~ 'w3wp|httpd|nginx'
- name: WebServerLogs
  query: |
    SELECT OSPath, ModTime, Size
    FROM glob(globs='C:/inetpub/logs/LogFiles/**/*.log')
    WHERE ModTime > now() - 86400
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1499.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '676b19a2ee96a0af7a1c553f7dbe8035';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.SourceIp as SourceIP, EventData.DestinationPort as Port, EventData.ProcessId as PID, EventData.Image as Process FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.DestinationPort IN (80, 443, 8080, 8443)$orcafix$, updated_at = NOW()
