UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.ApplicationExhaustionFlood
description: Detect application exhaustion flood attacks through multiple data sources
sources:
- name: ApplicationCrashes
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, System.EventID.Value, System.Provider.Name, EventData.Data FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (1000, 1001, 1002, 1026)
- name: ProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime, EventData.Image, EventData.CommandLine, EventData.ParentImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '(?i)(iexplore|chrome|firefox|winword|excel|powerpnt)' OR EventData.CommandLine =~ '(?i)(curl|wget|invoke-webrequest)')
- name: SystemPerformance
  query: |
    SELECT System.TimeCreated.SystemTime, System.EventID.Value, EventData.Data FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (2004, 6008, 1074)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1499.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a78809aae6cc6224fdb7da8727fa885f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Server.SoftwareComponent.Detection
description: Detect malicious server software components across web servers and scheduled tasks
sources:
- name: WebServerProcessSpawning
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.Image AS ProcessImage,
           EventData.ParentImage AS ParentImage,
           EventData.CommandLine AS CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND EventData.ParentImage =~ '''(?i)(w3wp\.exe|httpd\.exe|nginx\.exe|apache\.exe)$'''
      AND EventData.Image =~ '''(?i)(cmd\.exe|powershell\.exe|bash\.exe|sh\.exe)$'''
- name: ScheduledTaskCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.TaskName AS TaskName,
           EventData.SubjectUserName AS CreatedBy
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4698
- name: WebServerModules
  query: |
    SELECT OSPath, Size, Mtime, Ctime
    FROM glob(globs=['C:/Windows/System32/inetsrv/*.dll', 'C:/Program Files*/Apache*/modules/*.dll'])
    WHERE Mtime > timestamp(epoch=now() - 86400*7)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1505' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '68dae3b38135d89f9e3bcc7427ac4cf0';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image AS ProcessImage, EventData.ParentImage AS ParentImage, EventData.CommandLine AS CommandLine, EventData.ParentCommandLine AS ParentCommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)(w3wp\.exe|httpd\.exe|nginx\.exe|apache\.exe)$''' AND EventData.Image =~ '''(?i)(cmd\.exe|powershell\.exe|wscript\.exe|cscript\.exe|rundll32\.exe)$''')$orcafix$, updated_at = NOW()
