UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Exchange.TransportAgent.Detection
description: Detect Microsoft Exchange Transport Agent abuse through PowerShell commands, process execution, and file system changes
sources:
- name: PowerShell Transport Agent Commands
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ContextInfo, EventData.ScriptBlockText
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value IN (4103, 4104) AND (EventData.ContextInfo =~ '(?i)(Install-TransportAgent|Enable-TransportAgent|Set-TransportAgent)' OR EventData.ScriptBlockText =~ '(?i)TransportAgent')
- name: Exchange Process and DLL Loading
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ImageLoaded, EventData.ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 7 AND EventData.Image =~ '''(?i)EdgeTransport\\.exe''' AND EventData.ImageLoaded =~ '''(?i)\\.(dll|exe)$'''\n"
- name: Transport Agent Registry Configuration
  query: "SELECT OSPath, Data.value as AgentConfig FROM Artifact.Windows.Registry.NTUser() \nWHERE OSPath =~ '''(?i)SOFTWARE\\\\Microsoft\\\\ExchangeServer.*TransportAgents'''\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1505.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '6c35844614a70cd60b19e19bb30d8acf';

