UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ParentImage as ParentImage, EventData.CommandLine as CommandLine, EventData.ParentCommandLine as ParentCommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)(w3wp\.exe|php-cgi\.exe|httpd\.exe|nginx\.exe)''' AND EventData.Image =~ '''(?i)(cmd\.exe|powershell\.exe|bash\.exe|sh\.exe|python\.exe|perl\.exe)''')$orcafix$, updated_at = NOW()
