UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.IISComponents
description: Detect malicious IIS ISAPI filters, extensions, and modules through configuration changes and DLL loading
sources:
- name: IISConfigurationChanges
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, \n       EventData.ObjectName as FilePath,\n       EventData.SubjectUserName as User,\n       EventData.ProcessName as Process\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value IN (4663, 4670, 4656) \nAND EventData.ObjectName =~ '''(?i)(applicationhost\\.config|web\\.config|inetsrv)'''\n"
- name: SuspiciousDLLLoads
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage,\n       EventData.ImageLoaded as LoadedDLL,\n       EventData.Signed as IsSigned,\n       EventData.ProcessId as PID\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 7 \nAND EventData.Image =~ '''(?i)w3wp\\.exe'''\nAND (EventData.ImageLoaded =~ '''(?i)(inetsrv|inetpub).*\\.dll''' OR\n     EventData.ImageLoaded =~ '''(?i)\\\\(temp|users|programdata).*\\.dll''')\n"
- name: IISManagementActivity
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage,
           EventData.CommandLine as CommandLine,
           EventData.User as User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
    AND (EventData.Image =~ '''(?i)appcmd\.exe''' OR
         EventData.CommandLine =~ '(?i)(module|isapi|filter)')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1505.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '099574d5c0acdfaeb34ef68eef65559d';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, EventData.Image as ProcessImage, EventData.ImageLoaded as LoadedDLL, EventData.ProcessId as PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND EventData.Image =~ '''w3wp\.exe''' AND EventData.ImageLoaded =~ '''(?i)(inetsrv|inetpub|system32).*\.dll''' AND NOT EventData.ImageLoaded =~ '(?i)microsoft'$orcafix$, updated_at = NOW()
