UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.TerminalServicesDLL
description: Detects Terminal Services DLL tampering through registry modifications, file changes, and abnormal module loads by Terminal Services processes.
sources:
- name: RegistryModifications
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.ProcessName AS ProcessName,
           EventData.ObjectName AS ObjectName,
           EventData.ObjectValueName AS ValueName,
           EventData.NewValue AS NewValue,
           EventData.OldValue AS OldValue
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4657
      AND EventData.ObjectName =~ '''(?i).*\\services\\TermService\\Parameters.*'''
      AND EventData.ObjectValueName = 'ServiceDll'
- name: SuspiciousDLLLoads
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.Image AS ProcessName,
           EventData.ImageLoaded AS ImageLoaded,
           EventData.ProcessId AS PID,
           EventData.Hashes AS Hashes
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7
      AND EventData.Image =~ 'svchost.exe'
      AND NOT EventData.ImageLoaded =~ '''(?i)C:\\Windows\\System32\\termsrv\.dll$'''
- name: FileCreationEvents
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.Image AS ProcessName,
           EventData.TargetFilename AS TargetFilename,
           EventData.ProcessId AS PID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11
      AND EventData.TargetFilename =~ '''(?i).*termsrv\.dll.*'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1505.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '264c139fe168b7e4c0ac94f96a8b03d9';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image, EventData.ImageLoaded, EventData.ProcessId, EventData.Hashes FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND (EventData.Image =~ 'svchost.exe' AND EventData.ImageLoaded =~ '''(?i)termsrv\.dll|termdd\.dll''') OR (NOT EventData.ImageLoaded =~ '''(?i)C:\\Windows\\System32\\termsrv\.dll$''' AND EventData.Image =~ 'svchost.exe')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1505.005' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'c9ac0da4c545ede4cfe4cda4c5e56e4a';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.SoftwareDiscovery.MultiPlatform
description: Detect software discovery commands across Windows, PowerShell, and command line interfaces
sources:
- name: Windows Security Events
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           EventData.NewProcessName as ProcessName,
           EventData.CommandLine as CommandLine,
           EventData.ParentProcessName as ParentProcess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND CommandLine =~ 'wmic.*product|Get-WmiObject.*Win32_Product|Get-Package'
- name: PowerShell Script Blocks
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           EventData.ScriptBlockText as ScriptContent,
           EventData.Path as ScriptPath
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104 AND EventData.ScriptBlockText =~ 'Win32_Product|Get-WmiObject|Get-Package|Get-ItemProperty.*Software'
- name: PowerShell History
  query: |
    SELECT OSPath, Mtime, read_file(filename=OSPath) as Content
    FROM glob(globs='C:/Users/*/AppData/Roaming/Microsoft/Windows/PowerShell/PSReadLine/ConsoleHost_history.txt')
    WHERE Content =~ 'Win32_Product|Get-WmiObject|Get-Package|wmic.*product'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1518' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '471c7dd78465517f1414ca6097f99d97';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)(wmic.*product|Get-WmiObject.*Win32_Product|Get-Package|dpkg\s+-l|rpm\s+-qa)''') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.CommandLine =~ '''(?i)(wmic.*product|Get-WmiObject.*Win32_Product|Get-Package|dpkg\s+-l|rpm\s+-qa)''') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1518' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '95db865ec91b59c166c938c1eab61737';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.SecuritySoftwareDiscovery
description: Detect security software discovery across multiple Windows log sources
sources:
- name: SecurityLogs
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.NewProcessName as ProcessName, \n       EventData.CommandLine as CommandLine, EventData.ParentProcessName as ParentProcess\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') \nWHERE System.EventID.Value = 4688 AND \n      (CommandLine =~ '(?i)(tasklist|netsh|sc query|fltmc|wmic.*product|reg query.*uninstall)' OR \n       CommandLine =~ '(?i)(crowdstrike|carbonblack|sentinel|defender|symantec|mcafee|kaspersky)')\n"
- name: SysmonLogs
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image AS Image, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentImage\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 AND \n      (EventData.CommandLine =~ '(?i)(tasklist|netsh|sc query|fltmc|wmic.*product|reg query.*uninstall)' OR \n       EventData.CommandLine =~ '(?i)(crowdstrike|carbonblack|sentinel|defender|symantec|mcafee|kaspersky)')\n"
- name: RegistryUninstall
  query: "SELECT Key.Name as SoftwareName, Key.ModTime as LastModified\nFROM Artifact.Windows.Registry.LocalMachine.Software() \nWHERE Key.Name =~ 'Microsoft/Windows/CurrentVersion/Uninstall' AND \n      Key.Name =~ '(?i)(crowdstrike|carbonblack|sentinel|defender|symantec|mcafee|kaspersky|bitdefender)'\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1518.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '8f15d02e305b005b9dfdf85f5df94616';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.BackupSoftwareDiscovery
description: Detect adversary enumeration of backup software via multiple vectors
sources:
- name: ProcessCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId, EventData.Image, EventData.CommandLine, EventData.ParentImage \nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '(?i)(tasklist|sc query|reg query).*(veeam|acronis|crashplan|backup)' OR EventData.CommandLine =~ '(?i)Get-WmiObject.*(Win32_Product|Win32_Service).*(backup)')\n"
- name: RegistryAccess
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId, EventData.Image, EventData.TargetObject, EventData.Details\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value IN (12,13,14) AND EventData.TargetObject =~ '(?i)SOFTWARE.*(Veeam|Acronis|BackupExec|Carbonite)'\n"
- name: PowerShellHistory
  query: "SELECT OSPath, Line\nFROM Artifact.Windows.Forensics.PowershellHistory() \nWHERE Line =~ '(?i)(Get-WmiObject|tasklist|sc query).*(veeam|acronis|backup|crashplan)'\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1518.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '3f87e6bb75f7229c032c992c8df1a4cd';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as Image, EventData.CommandLine as CommandLine, EventData.ParentImage as ParentImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (CommandLine =~ '(?i)(tasklist|sc query|reg query).*(veeam|acronis|crashplan|backblaze|backup)' OR CommandLine =~ '(?i)(Get-WmiObject|gwmi).*(Win32_Product|Win32_Service).*(veeam|acronis|backup)' OR (Image =~ '''(?i)(cmd\.exe|powershell\.exe)''' AND CommandLine =~ '(?i)(dir|ls).*(program files|programdata).*(veeam|acronis|backup)'))$orcafix$, updated_at = NOW()
