UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData, System FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 'AwsApiCall' AND (EventData.eventName = 'RegisterImage' OR EventData.eventName = 'ModifyImageAttribute' OR EventData.eventName = 'RunInstances') AND NOT (EventData.sourceIPAddress IN ('known_admin_ips')) ORDER BY timestamp$orcafix$, updated_at = NOW()
