    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104 AND EventData.ScriptBlockText =~ '''(?i)(aws\s+(describe|list)|az\s+(resource|ad)|gcloud\s+(projects|services)|pacu|stormspotter)'''
- name: ProcessCreationCloudTools
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.NewProcessName as Process, EventData.CommandLine as CommandLine, EventData.SubjectUserName as User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
