sources:
- name: BrowserHistory
  query: "SELECT Timestamp, URL, Title, VisitCount, User\nFROM glob(globs='C:/Users/*/AppData/Local/Google/Chrome/User Data/*/History')\nWHERE URL =~ '''(?i)(console\\.aws\\.amazon\\.com|portal\\.azure\\.com|admin\\.google\\.com|admin\\.microsoft\\.com|.*\\.okta\\.com)'''\nUNION ALL\nSELECT Timestamp, URL, Title, VisitCount, User  \nFROM glob(globs='C:/Users/*/AppData/Roaming/Mozilla/Firefox/Profiles/*/places.sqlite')\nWHERE URL =~ '''(?i)(console\\.aws\\.amazon\\.com|portal\\.azure\\.com|admin\\.google\\.com|admin\\.microsoft\\.com|.*\\.okta\\.com)'''\n"
- name: AuthenticationEvents
  query: |
    SELECT timestamp, EventData.IpAddress as SourceIP, EventData.SubjectUserName as Username, EventData.WorkstationName as Workstation
    FROM parse_evtx(filename=expand(path='%SystemRoot%/System32/winevt/Logs/Security.evtx'))
    WHERE System.EventID.Value IN (4624, 4648, 4672)
- name: PowerShellHistory
  query: |
    SELECT Line, User, timestamp
    FROM Artifact.Windows.Forensics.PowershellHistory()
    WHERE Line =~ '(?i)(aws|az|gcloud|kubectl|terraform)\\s+(console|dashboard|portal)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1538' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'dbbdeb31ff07039e11c0044ec3db2009';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, EventData.IpAddress as SourceIP, EventData.LogonType as LogonType, EventData.SubjectUserName as Username, EventData.WorkstationName as Workstation, EventData.ProcessName as ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4624 AND EventData.LogonType IN (2, 3, 10)$orcafix$, updated_at = NOW()
WHERE t_code = 'T1538' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '90e87f8065ff2bf863269d6d24ab793b';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.CookieTheft
description: Detect web session cookie theft through file access and process injection
sources:
- name: BrowserProcessAccess
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.SourceImage AS SourceProcess,
           EventData.TargetImage AS TargetProcess,
           EventData.SourceProcessId AS SourcePID,
           EventData.TargetProcessId AS TargetPID,
           EventData.GrantedAccess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10
      AND (EventData.TargetImage =~ '''chrome\.exe$|firefox\.exe$|msedge\.exe$''')
      AND NOT (EventData.SourceImage =~ '''chrome\.exe$|firefox\.exe$|msedge\.exe$|dwm\.exe$|csrss\.exe$''')
- name: CookieFileAccess
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.Image AS ProcessName,
           EventData.TargetFilename AS FilePath,
           EventData.ProcessId AS PID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 2
      AND (EventData.TargetFilename =~ '''(?i)cookies$|cookies\.sqlite$'''
           OR EventData.TargetFilename =~ '''(?i)\\Chrome\\User Data\\.*\\Cookies'''
           OR EventData.TargetFilename =~ '''(?i)\\Firefox\\Profiles\\.*\.default.*\\cookies\.sqlite''')
      AND NOT (EventData.Image =~ '''(?i)chrome\.exe$|firefox\.exe$|msedge\.exe$''')
- name: SuspiciousProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated,
           EventData.NewProcessName AS ProcessName,
           EventData.ProcessId AS ProcessId,
           EventData.CommandLine AS CommandLine,
           EventData.ParentProcessName AS ParentProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688
      AND (EventData.NewProcessName =~ '(?i)procdump|mimikatz|dump'
           OR EventData.CommandLine =~ '''(?i)cookies|chrome\.exe|firefox\.exe|browser''')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1539' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'b5cb7e57429a161344b0ec34743a9329';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, EventData.SourceImage AS SourceProcess, EventData.TargetImage AS TargetProcess, EventData.SourceProcessId AS SourcePID, EventData.TargetProcessId AS TargetPID, EventData.GrantedAccess FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 10 AND (EventData.TargetImage =~ '''chrome\.exe$|firefox\.exe$|msedge\.exe$|brave\.exe$''') AND NOT (EventData.SourceImage =~ '''chrome\.exe$|firefox\.exe$|msedge\.exe$|brave\.exe$|dwm\.exe$|csrss\.exe$|winlogon\.exe$''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1539' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'fdef3b01aee64892f89f5fb1d5ec605d';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1542.PreOSBoot
description: Detect Pre-OS Boot modifications across boot sectors, firmware tools, and EFI partitions
sources:
- name: RawDiskAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.Device as TargetDevice, EventData.ProcessId as PID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 9 AND EventData.Device =~ 'PhysicalDrive'
- name: FirmwareTools
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer AS Computer, EventData.NewProcessName as ProcessName, EventData.ParentProcessName as ParentProcess, EventData.CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND EventData.NewProcessName =~ '(flashrom|fwupdmgr|nvflash|bcdedit)'
- name: EFIFileModification
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.TargetFilename as ModifiedFile
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '(EFI|bootmgfw|winload)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1542' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '50561df0a22533770ec3967d25374d42';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.Device as TargetDevice, EventData.ProcessId as PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 9 AND EventData.Device =~ 'PhysicalDrive'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1542' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '5be306ce89f2347b0f33caf8a902bc7f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1542001.SystemFirmware
description: Detect system firmware modification attempts via process execution and raw disk access
sources:
- name: FirmwareToolExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.NewProcessName as Image, EventData.CommandLine as CommandLine, EventData.SubjectUserName as User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '(?i)(fwupdate|flash|bios|uefi|firmware)' OR EventData.CommandLine =~ '(?i)(bios|uefi|firmware|flash|efi)')
- name: RawDiskAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.Device AS Device, EventData.ProcessGuid as ProcessGuid
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 9 AND EventData.Device =~ '(?i)(physicaldrive|harddisk.*volume1|efi)'
- name: EFIFileModifications
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.TargetFilename AS TargetFilename, EventData.ProcessGuid as ProcessGuid
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\\efi\\(boot|microsoft)\\'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1542.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '116ae26285b3c1d8081518cdcf82ee1d';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.ComponentFirmware
description: Detect component firmware manipulation via driver loads and firmware integrity events
sources:
- name: SuspiciousFirmwareDrivers
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.ImageLoaded, EventData.Hashes, EventData.Signed, EventData.ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 6 \nAND (EventData.ImageLoaded =~ '(?i)(firmware|flash|nvme|controller|bios|uefi)' OR EventData.Description =~ '(?i)(firmware|flash|controller)')\nAND (EventData.Signed = 'false' OR EventData.SignatureStatus != 'Valid')\n"
- name: FirmwareUpdateEvents
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.DeviceInstanceId, EventData.DriverName, EventData.DriverVersion
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx')
    WHERE System.EventID.Value = 219
    AND EventData.DeviceInstanceId =~ '(?i)(nvme|sata|usb|pci)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1542.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'abdbbf8c2e51c8e021cfb318bf2a6160';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.ImageLoaded, EventData.Hashes, EventData.Signed, EventData.Signature, EventData.SignatureStatus FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 6 AND (EventData.ImageLoaded =~ '(?i)(firmware|flash|nvme|controller|bios|uefi)' OR EventData.Description =~ '(?i)(firmware|flash|controller)') AND EventData.Signed = 'false'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1542.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'f835099b28a96c92f60c263e0cdff136';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1542_003.Bootkit
description: Detect bootkit installation via raw disk access and EFI file modifications
sources:
- name: SysmonRawDiskAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.EventID.Value, EventData.Image, EventData.Device, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 9 AND EventData.Device =~ '''\\\?\\PhysicalDrive|\\Device\\Harddisk'''
- name: SysmonESPFileCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.EventID.Value, EventData.Image, EventData.TargetFilename, EventData.ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\\\\EFI\\\\.*\\.efi$'''\n"
- name: MBRCollection
  query: |
    SELECT OSPath, Size, hash(path=OSPath, hashselect='SHA256') AS SHA256
    FROM glob(globs='\\\\?\\PhysicalDrive*', accessor='raw_ntfs')
    WHERE Size >= 512
    LIMIT 10
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1542.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a4dd487c80a630fe5d9fb87db0be0fd5';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.EventID.Value, EventData.Image, EventData.Device, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 9 AND EventData.Device =~ '''\\\?\\PhysicalDrive|\\Device\\Harddisk'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1542.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '2ed842c24d9255861e3c3a74d454b355';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1543.SystemProcessCreation
description: Detect creation and modification of system processes across Windows services, registry, and process execution
sources:
- name: WindowsServiceCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ServiceName, EventData.ServiceFileName, EventData.ServiceAccount
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4697
    ORDER BY EventTime DESC
- name: ServiceRegistryModifications
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetObject, EventData.Details, EventData.Image
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value IN (13, 14) AND EventData.TargetObject =~ '(?i)HKLM.*CurrentControlSet.*Services'
- name: ServiceManagementProcesses
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(sc\\.exe|net\\.exe)$''' OR EventData.CommandLine =~ '(?i)(new-service|set-service|Install-Service)')\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1543' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '33d3cc1a77dafc646d40af943cad75c3';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ServiceName, EventData.ServiceType, EventData.StartType, EventData.ServiceAccount, EventData.ServiceFileName, EventData.ServiceFileName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4697 AND EventData.ServiceFileName =~ '(?i)(users|temp|appdata|programdata)' ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1543' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'aaee0eb2e411ab922e3430fb207d16f0';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.ServiceCreationDetection
description: Detect Windows service creation and modification through multiple data sources
sources:
- name: ServiceInstallation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ServiceName as ServiceName,
           EventData.ServiceFileName as ImagePath, EventData.ServiceType,
           EventData.ServiceStartType, EventData.ServiceAccount
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.Channel = 'Security' AND System.EventID.Value = 4697
- name: ServiceProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine,
           EventData.ParentImage, EventData.ParentCommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.Channel = 'Microsoft-Windows-Sysmon/Operational' AND System.EventID.Value = 1
    AND (EventData.Image =~ '''(?i).*sc\.exe$''' OR EventData.CommandLine =~ '(?i).*(new-service|sc create)')
- name: ServiceRegistryModifications
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetObject, EventData.Details,
           EventData.Image, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.Channel = 'Microsoft-Windows-Sysmon/Operational' AND System.EventID.Value IN (13,14)
    AND EventData.TargetObject =~ '''(?i).*\\services\\.*\\(imagepath|start|type)'''
- name: DriverLoading
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ImageLoaded, EventData.Signed,
           EventData.SignatureStatus, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.Channel = 'Microsoft-Windows-Sysmon/Operational' AND System.EventID.Value = 6
    AND EventData.ImageLoaded =~ '''(?i).*\.(sys)$'''
    AND NOT EventData.ImageLoaded =~ '''(?i).*\\(system32|syswow64)\\.*'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1543.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'c2d0f1e94d735c67db5993f305374914';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ServiceName as ServiceName, EventData.ServiceFileName as ImagePath, EventData.ServiceType as ServiceType, EventData.ServiceStartType as StartType, EventData.AccountName as RunAsAccount FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') AND System.EventID.Value = 4697 AND (EventData.ServiceFileName =~ '''(?i).*\\(users|temp|public|programdata)\\.*\.(exe|bat|cmd|ps1)''' OR EventData.ServiceName =~ '(?i).*(update|security|system|windows|microsoft).*(svc|service|helper)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1543.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '0ec540f7b15fb94891ad80a0f3d692a0';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.EventTriggeredExecution
description: Detects event-triggered execution mechanisms including WMI subscriptions, scheduled tasks, and registry autoruns
sources:
- name: ScheduledTaskCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TaskName as TaskName, \n       EventData.TaskContent as UserContext, EventData.TaskContent as TaskContent\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value = 4698 \n  AND EventData.TaskContent =~ '(?i)(SYSTEM|LOCAL SERVICE)'\n  AND EventData.TaskContent =~ '(?i)(powershell|cmd|wscript|cscript)'\n"
- name: WMIEventSubscriptions
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Operation as Operation,
           EventData.User as User, EventData.NamespaceName as Namespace
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-WMI-Activity%4Operational.evtx')
    WHERE System.EventID.Value IN (5857, 5858, 5859, 5860, 5861)
      AND EventData.Operation =~ '(?i)(Created|Modified)'
- name: SuspiciousProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ParentUser as ParentUser,
           EventData.Image as ProcessPath, EventData.CommandLine as CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND EventData.ParentUser =~ '(?i)(SYSTEM|LOCAL SERVICE)'
      AND EventData.Image =~ '''(?i)\\(powershell|cmd|wscript|cscript|regsvr32)\.exe$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1546' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '554cb10400d0b527a1614300f5f09da6';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TaskName as TaskName, EventData.TaskContent as UserContext, EventData.TaskContent as TaskContent FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4698 AND EventData.TaskContent =~ '(?i)(SYSTEM|LOCAL SERVICE)' AND EventData.TaskContent =~ '(?i)(powershell|cmd|wscript|cscript|regsvr32)' ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1546' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'a8dec23104824ffbbcaf47e1c60cf85f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: T1546_001_FileAssociationHijack
description: Detect file association hijacking via registry modifications and process execution correlation
sources:
- name: RegistryModifications
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.TargetObject AS RegistryKey,
           EventData.Details AS NewValue,
           EventData.ProcessId AS PID,
           EventData.Image AS ProcessPath
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value IN (13,14)
      AND EventData.TargetObject =~ '''(?i)(shell\\open\\command|UserChoice)'''
- name: SuspiciousProcessExecution
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ProcessId AS PID,
           EventData.Image AS ProcessPath,
           EventData.CommandLine AS CommandLine,
           EventData.ParentImage AS ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.Image =~ '(?i)(powershell|cmd|wscript|cscript|rundll32)'
           OR EventData.CommandLine =~ '''(?i)\.(txt|pdf|doc|zip)''')
- name: FileAssociationRegistry
  query: |
    SELECT Key.OSPath.Path AS RegistryPath,
           Key.Name AS KeyName,
           Value.ValueName AS ValueName,
           Value.ValueData.value AS ValueData
    FROM glob(globs='C:/Users/*/NTUSER.DAT', accessor='registry')
    WHERE RegistryPath =~ '''(?i)Software\\Classes.*\\shell\\open\\command'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1546.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '39328e93a4fb27c8f3749a858637d945';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, EventData.TargetObject AS RegistryKey, EventData.Details AS NewValue, EventData.ProcessId AS PID, EventData.Image AS ProcessPath FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value IN (13,14) AND EventData.TargetObject =~ '''(?i)(HKLM|HKCU).*\\(shell\\open\\command|UserChoice)'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1546.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'ae915fd3b7a9e5c5b582bd7199d7fc10';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Persistence.ScreensaverT1546002
description: Detects screensaver-based persistence via registry modifications and .scr executions
sources:
- name: ScreensaverRegistryConfig
  query: |
    SELECT Key.ModTime, Key.OSPath, ValueName, ValueData.value
    FROM Artifact.Windows.Registry.NTUser()
    WHERE Key.OSPath =~ "Control Panel/Desktop$"
    AND ValueName IN ("SCRNSAVE.exe", "ScreenSaveActive", "ScreenSaverIsSecure", "ScreenSaveTimeout")
- name: ScreensaverProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.EventID.Value AS EventID, EventData.NewProcessName, EventData.CommandLine, EventData.ParentProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''\.scr$''' OR EventData.CommandLine =~ '''\.scr''')
- name: ScreensaverRegistryModifications
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.EventID.Value AS EventID, EventData.TargetObject, EventData.Details, EventData.Image
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value IN (13, 14) AND EventData.TargetObject =~ "Control Panel.*Desktop"
$orcafix$, updated_at = NOW()
