UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.WMI.EventSubscriptions
description: Detect WMI Event Subscription persistence via multiple log sources
sources:
- name: WMI_Activity_Logs
  query: |
    SELECT EventTime, Computer, EventID, EventData.NamespaceName as Namespace,
           EventData.Query as WMIQuery, EventData.User as User
    FROM parse(filename='Microsoft-Windows-WMI-Activity%4Operational.evtx', accessor='file')
