- name: MOF_Compilation_Activity
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image AS NewProcessName, EventData.CommandLine AS CommandLine, EventData.User AS User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.Channel = 'Microsoft-Windows-Sysmon/Operational'
      AND System.EventID.Value = 1
      AND EventData.Image =~ 'mofcomp.exe'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1546.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '929190bd7a41e3494f7e9c180511dd92';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime), System.Computer, System.Channel AS Channel, System.EventID.Value, EventData FROM parse_evtx(filename='Microsoft-Windows-WMI-Activity%4Operational.evtx', accessor='file') WHERE System.Channel = 'Microsoft-Windows-WMI-Activity/Operational' AND System.EventID.Value IN (5857, 5858, 5860, 5861)$orcafix$, updated_at = NOW()
