  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.ProcessId, EventData.ParentProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.ParentImage =~ '''netsh\.exe$'''
- name: Registry_Modifications
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.ObjectName, EventData.ProcessName, EventData.SubjectUserName FROM parse_evtx(filename='C:/Windows/System32/winevt/logs/Security.evtx') WHERE System.EventID.Value = 4657 AND EventData.ObjectName =~ 'Microsoft\\\\Netsh'
$orcafix$, updated_at = NOW()
