UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.AccessibilityHijacking
description: Detect accessibility feature hijacking via binary replacement or registry modification
sources:
- name: RegistryDebuggers
  query: |
    SELECT Key.OSPath as KeyPath, Key.ModTime as ModTime, ValueName, ValueData.value as DebuggerPath
    FROM read_reg_key(globs='HKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Image File Execution Options\\*', accessor='registry')
    WHERE ValueName = 'Debugger' AND Key.OSPath =~ '''(sethc|utilman|osk|magnify|narrator|displayswitch|atbroker)\.exe$'''
- name: BinaryIntegrity
  query: |
    SELECT OSPath, Size, hash(path=OSPath, hashselect='SHA256') as SHA256, Mtime, Ctime
    FROM glob(globs='C:/Windows/System32/{sethc,utilman,osk,magnify,narrator,displayswitch,atbroker}.exe')
- name: SuspiciousExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.EventID.Value as EventID, EventData.Image as Image, EventData.ParentImage as ParentImage, EventData.CommandLine as CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.ParentImage =~ '''(sethc|utilman|osk|magnify|narrator|displayswitch|atbroker)\.exe$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1546.008' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '8f7e9fdd72593247a28ea0e2755543d6';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ParentImage as ParentImage, EventData.CommandLine as CommandLine, EventData.User as User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ 'sethc.exe|utilman.exe|osk.exe|magnify.exe|narrator.exe|displayswitch.exe|atbroker.exe' OR (EventData.ParentImage =~ 'winlogon.exe' AND EventData.Image =~ 'cmd.exe|powershell.exe' AND EventData.User =~ 'SYSTEM'))$orcafix$, updated_at = NOW()
WHERE t_code = 'T1546.008' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'd635672d36b62e905258f5d5be799976';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: T1546_009_AppCert_DLLs_Detection
description: Detect AppCert DLL persistence via registry modifications and subsequent DLL injection
sources:
- name: Registry_Modifications
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.Image, EventData.TargetObject, EventData.Details, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 13 AND EventData.TargetObject =~ '.*Session Manager.*AppCertDLLs'
- name: DLL_Load_Events
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.ProcessId, EventData.Image, EventData.ImageLoaded, EventData.Signature, EventData.Signed FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7
- name: AppCert_Registry_Key
  query: |
    SELECT Key.OSPath, Key.Name, Data.value FROM read_reg_key(key='HKEY_LOCAL_MACHINE\\System\\CurrentControlSet\\Control\\Session Manager\\AppCertDLLs') WHERE Data.value
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1546.009' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a9e488461b4df0d097f62acd7e17b7f8';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image, EventData.TargetObject, EventData.Details FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 13 AND EventData.TargetObject =~ '.*Session Manager.*AppCertDLLs' ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1546.009' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '777633a731882f227cb9b683051418f6';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.AppInitDLLs
description: Detect AppInit DLL persistence via registry and DLL loading correlation
sources:
- name: AppInitRegistryKeys
  query: |
    SELECT Key.OSPath as RegistryPath, Key.Name as ValueName, Key.Data.value as DLLPath, Key.ModTime as ModifiedTime
    FROM glob(globs=['HKEY_LOCAL_MACHINE/Software/Microsoft/Windows NT/CurrentVersion/Windows/AppInit_DLLs', 'HKEY_LOCAL_MACHINE/Software/Wow6432Node/Microsoft/Windows NT/CurrentVersion/Windows/AppInit_DLLs'], accessor='registry')
    WHERE Key.Data.value
- name: SuspiciousDLLLoads
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ImageLoaded as DLLPath, EventData.Signed as IsSigned, EventData.ProcessId as PID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7 AND (EventData.Signed = 'false' OR EventData.ImageLoaded =~ '''(?i)\\(temp|programdata|users)\\.*\.dll$''')
- name: RegistryModifications
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetObject as RegistryKey, EventData.Details as NewValue, EventData.ProcessId as PID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value IN (13, 14) AND EventData.TargetObject =~ '(?i).*AppInit_DLLs.*'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1546.010' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '1b3503ea2c94b0567c3bf20e243e858c';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ImageLoaded as DLLPath, EventData.Signed as IsSigned, EventData.ProcessId as PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND EventData.ImageLoaded =~ '(?i)(appinit|user32)' AND (EventData.Signed = 'false' OR EventData.ImageLoaded =~ '''(?i)\\(temp|programdata|users)\\.*\.dll$''')$orcafix$, updated_at = NOW()
