UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.ApplicationShimming
description: Detect application shimming through sdbinst.exe execution and custom shim database analysis
sources:
- name: SdbinstExecution
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.NewProcessName as ProcessName, \n       EventData.CommandLine, EventData.SubjectUserName as User,\n       EventData.ParentProcessName as Parent\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') \nWHERE System.EventID.Value = 4688 AND EventData.NewProcessName =~ '''(?i)sdbinst\\.exe'''\n"
- name: CustomShimFiles
  query: |
    SELECT OSPath, Size, Mtime, Ctime, Btime
    FROM glob(globs=['C:/Windows/AppPatch/Custom/*.sdb', 'C:/Windows/AppPatch/AppPatch64/Custom/*.sdb'])
- name: ShimRegistryKeys
  query: |
    SELECT Key.OSPath as KeyPath, Key.ModTime, ValueName, ValueData.value as Value
    FROM Artifact.Windows.Registry.NTUser()
    WHERE Key.OSPath =~ '(?i)AppCompatFlags/(Custom|InstalledSDB)'
- name: DLLInjectionEvents
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId, EventData.Image as TargetProcess,
           EventData.ImageLoaded as LoadedDLL, EventData.User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7 AND EventData.ImageLoaded =~ '(?i)AppPatch'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1546.011' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '0bc043a13fa2ae582cbbff2b69eecfc4';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)sdbinst\.exe''') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''(?i)sdbinst\.exe''') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1546.011' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'ff6d11dee8ab182c47322a3f0efb2ac3';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.IFEO.Detection
description: |
  Detects Image File Execution Options injection by correlating registry modifications with process execution
sources:
- name: IFEORegistryModifications
  query: "SELECT System.TimeCreated.SystemTime AS Timestamp,\n       EventData.ObjectName AS RegistryPath,\n       EventData.ObjectValueName AS ValueName,\n       EventData.NewValue AS NewValue,\n       EventData.ProcessName AS ModifyingProcess\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value = 4657 \n  AND EventData.ObjectName =~ 'Image File Execution Options|SilentProcessExit'\n  AND EventData.ObjectValueName =~ 'Debugger|MonitorProcess'\n"
- name: DebuggerProcessExecution
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.Image AS ProcessPath,
           EventData.CommandLine AS CommandLine,
           EventData.ParentImage AS ParentProcess,
           EventData.User AS ExecutionUser
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.CommandLine =~ '''-g\s+\w+\.exe|ntsd\.exe|windbg\.exe'''
           OR EventData.ParentImage =~ '''winlogon\.exe|userinit\.exe'''
           AND EventData.Image =~ '''cmd\.exe|powershell\.exe|utilman\.exe''')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1546.012' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'f30425f4a4c0548864ab8eafdd4557f8';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.PowerShellProfilePersistence
description: Detects PowerShell profile-based persistence by correlating profile modifications with subsequent PowerShell executions
sources:
- name: ProfileFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetFilename as TargetFile, EventData.ProcessId as PID, EventData.Image as ProcessImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''profile\.ps1$'''
- name: PowerShellExecution
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.CommandLine as CommandLine, EventData.ProcessId as PID\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 1 AND EventData.Image =~ 'powershell' AND NOT EventData.CommandLine =~ '-NoProfile'\n"
- name: ProfileFiles
  query: |
    SELECT OSPath, Size, Mtime, Ctime, Btime, read_file(filename=OSPath) as Content
    FROM glob(globs=['C:/Users/*/Documents/WindowsPowerShell/*profile*.ps1', 'C:/Users/*/Documents/PowerShell/*profile*.ps1', 'C:/Windows/System32/WindowsPowerShell/v1.0/*profile*.ps1'])
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1546.013' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '97180f62da7df5a1f2e7f5cdfefa9eb9';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.CommandLine as CommandLine, EventData.ProcessId as PID, EventData.ParentProcessId as PPID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.Image =~ 'powershell' AND NOT EventData.CommandLine =~ '-NoProfile'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1546.013' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '5eec300665d6ee1e69b91cd6a9ac0e45';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.COMHijacking
description: Detect COM object hijacking through registry monitoring and DLL load correlation
sources:
- name: RegistryModifications
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ObjectName as RegistryPath, EventData.ProcessName, EventData.SubjectUserName, EventData.NewValue, EventData.OldValue\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value = 4657 \nAND EventData.ObjectName =~ 'Software\\\\\\\\Classes\\\\\\\\CLSID.*InprocServer32'\nAND (EventData.ObjectName =~ 'HKEY_CURRENT_USER' OR EventData.ObjectName =~ 'HKU\\\\\\\\.+')\n"
- name: SuspiciousDLLLoads
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ImageLoaded, EventData.ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 7\nAND (EventData.ImageLoaded =~ '(?i)C:\\\\\\\\Users\\\\\\\\.*\\\\\\\\.+\\\\\\\\.dll$' \n     OR EventData.ImageLoaded =~ '(?i)C:\\\\\\\\temp\\\\\\\\.*\\\\\\\\.dll$'\n     OR EventData.ImageLoaded =~ '(?i)C:\\\\\\\\programdata\\\\\\\\.*\\\\\\\\.dll$')\n"
- name: CLSIDRegistryKeys
  query: |
    SELECT OSPath, Data.value as DLLPath, Mtime
    FROM glob(globs='C:/Users/*/NTUSER.DAT', accessor='registry')
    WHERE OSPath =~ 'Software/Classes/CLSID/.*/InprocServer32'
    AND Data.value =~ '(?i)C:\\\\(Users|temp|programdata)\\\\'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1546.015' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'ea2b1e4ade301ba43b3f49d2aa5ece5b';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ObjectName as RegistryPath, EventData.ProcessName, EventData.SubjectUserName, EventData.NewValue FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4657 AND EventData.ObjectName =~ '''Software\\Classes\\CLSID.*InprocServer32''' AND (EventData.ObjectName =~ 'HKEY_CURRENT_USER' OR EventData.ObjectName =~ '''HKU\\.*\\Software''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1546.015' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'c65c1d5a17d7cc717fbea06ecb11c7ea';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime), System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as Image, EventData.CommandLine as CommandLine, EventData.ParentImage as ParentImage, EventData.ParentCommandLine as ParentCommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)msiexec\.exe''' OR EventData.Image =~ '''(?i)msiexec\.exe''') AND EventData.CommandLine != NULL$orcafix$, updated_at = NOW()
WHERE t_code = 'T1546.016' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '633ac62b6398eb76515ef886d8dc0813';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1547.AutostartExecution
description: Detect Boot or Logon Autostart Execution by correlating registry modifications with process execution
sources:
- name: RegistryModifications
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetObject as RegistryPath, EventData.Details as Value, EventData.ProcessId as ProcessId, EventData.Image as ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value IN (13, 14) AND EventData.TargetObject =~ '(?i)(Run|RunOnce|Winlogon)'
- name: ProcessCreationAtStartup
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.NewProcessName as ProcessName, EventData.CommandLine as CommandLine, EventData.ParentProcessName as ParentProcess FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND EventData.ParentProcessName =~ '''(?i)(winlogon\.exe|explorer\.exe|userinit\.exe)'''
- name: AutostartRegistryKeys
