    SELECT OSPath, ModTime, Data.value as Value FROM Artifact.Windows.Registry.NTUser() WHERE OSPath =~ '(?i)(Run|RunOnce)' OR OSPath =~ '''Microsoft\\Windows\\CurrentVersion\\Run'''
