UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Persistence.RunKeysAndStartup
description: Detect persistence via Registry Run keys and Startup folders using registry monitoring and process execution correlation
sources:
- name: RegistryRunKeyModifications
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetObject as RegistryPath, EventData.Details as Value, EventData.ProcessGuid FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 13 AND (EventData.TargetObject =~ '''.*\\CurrentVersion\\Run.*''' OR EventData.TargetObject =~ '''.*\\CurrentVersion\\Policies\\Explorer\\Run.*''' OR EventData.TargetObject =~ '''.*\\Session Manager.*BootExecute.*''')
- name: StartupFolderExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath, EventData.CommandLine, EventData.ParentImage, EventData.ProcessGuid FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '.*(Startup|StartUp).*' OR EventData.ParentCommandLine =~ '''.*explorer\.exe.*''')
- name: RegistryRunKeys
  query: |
    SELECT OSPath, ModTime, Data.value as Command FROM Artifact.Windows.Registry.NTUser() WHERE OSPath =~ '.*(Run|RunOnce|RunServices).*' AND NOT Data.value =~ '^(Windows|Microsoft|Adobe|Google).*'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1547.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'd198db2982abc98d5e7f678322ab790b';

