WHERE t_code = 'T1547.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'ff7973033cbaf4a878abdd2ebfa109e0';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1547_002.AuthenticationPackage
description: Detect LSA Authentication Package persistence via registry modifications and LSASS DLL loads
sources:
