    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ObjectName, EventData.ObjectValueName, EventData.NewValue, EventData.ProcessName, EventData.SubjectUserName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4657 AND EventData.ObjectName =~ 'CurrentControlSet.*Lsa' AND EventData.ObjectValueName =~ '(?i)(Authentication|Security|Notification).*Packages'
- name: LSASSDLLLoads
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.Image, EventData.ImageLoaded, EventData.Signed, EventData.SignatureStatus, EventData.Company FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND EventData.Image =~ 'lsass.exe'
- name: LSARegistryKeys
  query: |
    SELECT Key.OSPath.Path as KeyPath, Data.value as AuthPackages, Key.ModTime FROM Artifact.Windows.Registry.NTUser() WHERE KeyPath =~ 'HKEY_LOCAL_MACHINE.*CurrentControlSet.*Control.*Lsa' AND Data.value_name =~ '(?i)Authentication.*Packages'
$orcafix$, updated_at = NOW()
