UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.TimeProviderPersistence
description: Detect T1547.003 Time Provider persistence through registry modifications and DLL analysis
sources:
- name: TimeProviderRegistry
  query: |
    SELECT Key.OSPath.Path as RegistryPath, Key.Name as ProviderName, Data.value as DllName, Key.ModTime as LastModified FROM Artifact.Windows.Registry.NTUser(key_globs='HKEY_LOCAL_MACHINE\\System\\CurrentControlSet\\Services\\W32Time\\TimeProviders\\*') WHERE Data.value_name = 'DllName'
- name: CorrelatedSysmonEvents
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.EventID.Value AS EventID, EventData.TargetObject as Target, EventData.Details as Details, EventData.Image as Image FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value IN (1, 7, 11, 13, 14) AND (EventData.TargetObject =~ '.*TimeProviders.*' OR EventData.User =~ '.*LOCAL SERVICE.*' OR (System.EventID.Value = 11 AND EventData.TargetFilename =~ '''.*\.dll$'''))
- name: W32TimeServiceDLLs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image as ProcessImage, EventData.ImageLoaded as LoadedDLL, EventData.Signed as IsSigned, EventData.Signature as SignatureInfo FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND EventData.Image =~ '''.*svchost\.exe.*'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1547.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '13bd001ad17fb70bd2d8dd9515a49150';

