UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.LSASSDriverPersistence
description: Detect LSASS driver-based persistence via LSA package abuse
sources:
- name: SecurityEventLog
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.PackageName as PackageName, EventData.PackageFilePath as PackageFilePath \nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-CodeIntegrity%4Operational.evtx') \nWHERE System.EventID.Value = 3033\n"
- name: SysmonImageLoads
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as Image, EventData.ImageLoaded as ImageLoaded, EventData.Signed as Signed, EventData.SignatureStatus as SignatureStatus \nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 7 AND EventData.Image =~ '''lsass\\.exe$'''\n"
- name: LSARegistryKeys
  query: "SELECT OSPath, ModTime, Data.value as Value \nFROM Artifact.Windows.Registry.NTUser() \nWHERE OSPath =~ '''HKEY_LOCAL_MACHINE\\\\SYSTEM\\\\.*Control\\\\Lsa\\\\(Authentication Packages|Security Packages)'''\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1547.008' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '6146a0d17d79653cefd3ec9a05177b99';

