UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1547009.ShortcutModification
description: Detect malicious shortcut creation and modification for persistence
sources:
- name: SysmonLnkCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as CreatingProcess, EventData.TargetFilename, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\.lnk$'''
    AND (EventData.TargetFilename =~ '(?i)startup' OR EventData.TargetFilename =~ '(?i)desktop')
- name: LnkFileAnalysis
  query: |
    SELECT OSPath, Mtime, Ctime, Size, hash(path=OSPath).SHA256 as Hash
    FROM glob(globs=['C:/Users/*/AppData/Roaming/Microsoft/Windows/Start Menu/Programs/Startup/*.lnk',
                    'C:/ProgramData/Microsoft/Windows/Start Menu/Programs/StartUp/*.lnk',
                    'C:/Users/*/Desktop/*.lnk'])
- name: ZoneIdentifierStreams
  query: |
    SELECT OSPath, Data
    FROM glob(globs=['C:/Users/*/Desktop/*.lnk:Zone.Identifier',
                    'C:/Users/*/AppData/Roaming/Microsoft/Windows/Start Menu/Programs/Startup/*.lnk:Zone.Identifier'])
    WHERE Data =~ 'ZoneId=3'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1547.009' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '81ba9ddc21502d6a2e210b39ac1e0180';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.CommandLine, EventData.ParentImage, EventData.ParentCommandLine, EventData.TargetFilename FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\.lnk$''' AND (EventData.TargetFilename =~ '(?i)startup' OR EventData.TargetFilename =~ '(?i)desktop' OR EventData.TargetFilename =~ '(?i)start menu')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1547.009' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '1f4d7f019502f26bcf20ef6ed1f6947b';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.PortMonitorPersistence
description: |
  Detects Port Monitor persistence technique by monitoring registry modifications,
  DLL loads by spoolsv.exe, and file creation in system directories.
sources:
- name: PortMonitorRegistry
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetObject, EventData.Details, EventData.Image\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.Channel = 'Microsoft-Windows-Sysmon/Operational' \nAND System.EventID.Value = 13\nAND EventData.TargetObject =~ '''(?i)HKLM\\\\SYSTEM\\\\.*\\\\Control\\\\Print\\\\Monitors\\\\.*\\\\Driver'''\n"
- name: SpoolsvDLLLoads
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ImageLoaded, EventData.Signed
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.Channel = 'Microsoft-Windows-Sysmon/Operational'
    AND System.EventID.Value = 7
    AND EventData.Image =~ '''(?i)spoolsv\.exe'''
    AND (NOT EventData.Signed = 'true' OR EventData.ImageLoaded =~ '(?i)^(?!.*\\(system32|syswow64)\\(localspl|tcpmon|usbmon|wsdmon)\.dll)')
- name: SystemDLLCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetFilename, EventData.Image
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.Channel = 'Microsoft-Windows-Sysmon/Operational'
    AND System.EventID.Value = 11
    AND EventData.TargetFilename =~ '''(?i)C:\\Windows\\System32\\.*\.dll'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1547.010' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'e21d46c60d8a2787d3bafaceee5b7b23';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ImageLoaded, EventData.Signed, EventData.SignatureStatus FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.Channel = 'Microsoft-Windows-Sysmon/Operational' AND System.EventID.Value = 7 AND EventData.Image =~ '''spoolsv\.exe''' AND (NOT EventData.Signed = 'true' OR EventData.ImageLoaded =~ '(?i)^(?!.*\\(system32|syswow64)\\(localspl|tcpmon|usbmon|wsdmon)\.dll)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1547.010' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'a860acb808954a81d8f4d1535bcab434';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.PrintProcessorPersistence
description: Detect malicious print processor DLL persistence via registry, file system, and process monitoring correlation
sources:
- name: PrintProcessorRegistry
  query: |
    SELECT Key.OSPath, Key.ModTime, Value.ValueName, Value.ValueData.value FROM glob(globs=srcDir + '/Windows/System32/config/SYSTEM', accessor='file') FOREACH registry(filename=OSPath, accessor='file', query='SELECT Key.ModTime, Key.OSPath, ValueData, ValueName FROM values(OSPath="ControlSet001\\Control\\Print\\Environments\\*\\Print Processors\\*\\Driver")')
- name: PrintProcessorFiles
  query: |
    SELECT OSPath, Mode.String, Size, Mtime, Atime, Ctime FROM glob(globs=[srcDir + '/Windows/System32/spool/prtprocs/**/*.dll'], accessor='file')
- name: SpoolsvImageLoads
  query: |
    SELECT System.TimeCreated.SystemTime, EventData.Image, EventData.ImageLoaded, EventData.Signed, EventData.SignatureStatus FROM parse_evtx(filename=srcDir + '/Windows/System32/winevt/logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND EventData.Image =~ '''spoolsv\.exe$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1547.012' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '56ae06e55ccc585b85ab83d4745fec9a';

