WHERE t_code = 'T1547.012' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '7b8e67e025c16bf7369171cf86792911';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Persistence.ActiveSetup
description: Detect Active Setup persistence via registry modifications and process execution correlation
sources:
- name: ActiveSetupRegistry
  query: |
    SELECT Key.OSPath.Path as RegistryPath, Key.ModTime as ModifiedTime, Data.value as StubPath FROM Artifact.Windows.Registry.NTUser() WHERE Key.OSPath.Path =~ 'SOFTWARE/Microsoft/Active Setup/Installed Components' AND Data.value != ''
- name: ProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.NewProcessName as ProcessPath, EventData.ParentProcessName as ParentProcess, EventData.CommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND EventData.ParentProcessName =~ 'explorer.exe'
- name: RegistryModifications
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetObject as RegistryKey, EventData.Details as NewValue FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value IN (12,13,14) AND EventData.TargetObject =~ 'Active Setup'
$orcafix$, updated_at = NOW()
