UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.ElevationControlAbuse
description: Detect abuse of Windows elevation control mechanisms including UAC bypasses
sources:
- name: ProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime as EventTime, EventData.NewProcessName as ProcessName, EventData.ParentProcessName as ParentProcess, EventData.TokenElevationType as ElevationType, EventData.ProcessId as PID, EventData.SubjectUserName as User, EventData.CommandLine as CommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.TokenElevationType = '%%1937' OR EventData.ParentProcessName =~ '''(?i)(eventvwr\.exe|sdclt\.exe|control\.exe|computerdefaults\.exe)$''') AND EventData.NewProcessName =~ '''(?i)(cmd\.exe|powershell\.exe|wscript\.exe|cscript\.exe)$'''
- name: RegistryModifications
  query: |
    SELECT System.TimeCreated.SystemTime as EventTime, EventData.Image as ProcessName, EventData.TargetObject as RegistryKey, EventData.Details as NewValue FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value IN (13,14) AND EventData.TargetObject =~ '(?i)(mscfile|exefile|ms-settings).*shell.*open.*command'
- name: PrivilegeAssignment
  query: |
    SELECT System.TimeCreated.SystemTime as EventTime, EventData.SubjectUserName as User, EventData.PrivilegeList as Privileges, EventData.SubjectLogonId as LogonId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4672 AND EventData.PrivilegeList =~ 'SeDebugPrivilege|SeTakeOwnershipPrivilege|SeLoadDriverPrivilege'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1548' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'e5cef2dfb243442093087c3e60daae91';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)(eventvwr\.exe|sdclt\.exe|control\.exe|computerdefaults\.exe)$''' AND EventData.Image =~ '''(?i)(cmd\.exe|powershell\.exe|wscript\.exe|cscript\.exe)$''') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.ParentProcessName =~ '''(?i)(eventvwr\.exe|sdclt\.exe|control\.exe|computerdefaults\.exe)$''' AND EventData.NewProcessName =~ '''(?i)(cmd\.exe|powershell\.exe|wscript\.exe|cscript\.exe)$''') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1548' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'ab33c9a03a65d99a73ae0468661365c7';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.UACBypass
description: Detect UAC bypass attempts through registry tampering and suspicious process elevation
sources:
- name: RegistryModifications
  query: "SELECT System.TimeCreated.SystemTime AS EventTime, \n       EventData.TargetObject AS RegistryPath,\n       EventData.Details AS Value,\n       EventData.ProcessId AS PID,\n       EventData.Image AS ProcessImage\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value IN (13, 14)\n  AND EventData.TargetObject =~ '(?i)(ms-settings|exefile|mscfile).*shell.*(open|runas).*command'\n"
- name: SuspiciousProcessElevation
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.Image AS ProcessImage,
           EventData.ParentImage AS ParentImage,
           EventData.CommandLine AS CommandLine,
           EventData.IntegrityLevel AS IntegrityLevel,
           EventData.ProcessId AS PID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.Image =~ '''(?i)(eventvwr|sdclt|computerdefaults|fodhelper)\.exe'''
           OR EventData.IntegrityLevel = 'High')
      AND NOT EventData.ParentImage =~ '''(?i)C:\\Windows\\explorer\.exe'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1548.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '27a07ba279f3415ab2f689ab2d4dcdc4';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(eventvwr|sdclt|computerdefaults|fodhelper)\.exe''' AND NOT EventData.ParentImage =~ '''(?i)(explorer|cmd|powershell)\.exe''') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''(?i)(eventvwr|sdclt|computerdefaults|fodhelper)\.exe''' AND NOT EventData.ParentProcessName =~ '''(?i)(explorer|cmd|powershell)\.exe''') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1548.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '88131a5be1a8548cbdc59e9232841a18';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.TemporaryElevatedCloudAccess
description: Detect temporary elevated cloud access abuse across multiple artifact sources
sources:
- name: PowerShellHistory
  query: |
    SELECT Mtime, OSPath, read_file(filename=OSPath) as Content
    FROM glob(globs="%USERPROFILE%\\AppData\\Roaming\\Microsoft\\Windows\\PowerShell\\PSReadline\\*history*.txt")
    WHERE Content =~ "(?i)(PassRole|AssumeRole|Add-MailboxPermission|serviceAccountTokenCreator|impersonat)"
- name: CloudCredentials
  query: |
    SELECT Mtime, OSPath, Size
    FROM glob(globs=["%USERPROFILE%\\.aws\\**", "%USERPROFILE%\\.azure\\**", "%USERPROFILE%\\.config\\gcloud\\**"])
    WHERE Mtime > now() - 604800
- name: AuthenticationEvents
  query: |
    SELECT System.TimeCreated, EventData.SubjectUserName, EventData.TargetUserName, EventData.IpAddress
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4624, 4648, 4769) AND EventData.AuthenticationPackageName =~ ".*OAuth.*|.*SAML.*"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1548.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'f161b578a372ce2f8e4b1cf33027c3ad';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer, System.EventID.Value, UserName, EventData.LogonType AS LogonType, EventData.IpAddress AS IpAddress, EventData.LogonProcessName AS LogonProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4648) AND (LogonType = 3 OR LogonType = 9) AND UserName != 'SYSTEM' AND UserName != 'ANONYMOUS LOGON'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1550' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'd0ec1dbe2b7809a25aba7f3d6bdaeea1';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: T1550_001.TokenAbuse
description: Detect use of alternate authentication materials including OAuth tokens and cloud service tokens
sources:
- name: AzureTokenCache
  query: |
    SELECT OSPath, Mtime, Size, upload(file=OSPath) AS Upload
    FROM glob(globs=['C:/Users/*/.*azure*/accessTokens.json', 'C:/Users/*/.*azure*/tokenCache.json'])
    WHERE Size > 0
- name: AWSCredentials
  query: |
    SELECT OSPath, Mtime, read_file(filename=OSPath) AS Content
    FROM glob(globs=['C:/Users/*/.*aws*/credentials', 'C:/Users/*/.*aws*/config'])
    WHERE Content =~ 'aws_access_key_id|aws_session_token'
- name: BrowserTokens
  query: |
    SELECT Key, Value, OSPath
    FROM Artifact.Windows.Applications.Chrome.LocalStorage()
    WHERE Key =~ 'access_token|refresh_token|bearer_token|id_token'
- name: ContainerTokens
  query: |
    SELECT OSPath, read_file(filename=OSPath) AS Token
    FROM glob(globs=['**/serviceaccount/token', '**/run/secrets/**/token'])
    WHERE Token
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1550.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '38a690b4ffbf6e9f4165435ff3bb1ab9';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData, Message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4624 AND EventData.LogonType = 3 AND EventData.AuthenticationPackageName =~ 'Negotiate|Kerberos' AND EventData.LogonProcessName != 'Advapi'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1550.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '2d9ab3029b39513906dbb7fc656f5768';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.PassTheHash
description: Detects Pass-the-Hash attacks by correlating NTLM network logons with process execution and Kerberos activity
sources:
- name: NTLM_Network_Logons
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.TargetUserName AS Username, EventData.IpAddress AS SourceIP, EventData.WorkstationName AS Workstation, EventData.TargetLogonId AS LogonId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4624 AND EventData.LogonType = 3 AND EventData.AuthenticationPackageName = 'NTLM'
- name: Explicit_Credential_Use
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.SubjectUserName AS SourceUser, EventData.TargetUserName AS TargetUser, EventData.TargetServerName AS TargetServer, EventData.ProcessName AS ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4648
- name: Kerberos_TGT_Requests
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.TargetUserName AS Username, EventData.IpAddress AS ClientIP, EventData.Status AS Status FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4768
- name: SMB_Connections
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.SourceIp AS SourceIP, EventData.DestinationIp AS DestIP, EventData.DestinationPort AS Port, EventData.ProcessId AS PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.DestinationPort = 445
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1550.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'b69180460b903d58ab4f2e14cf9d32f3';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, EventData.TargetUserName AS Username, EventData.IpAddress AS SourceIP, EventData.WorkstationName AS Workstation, EventData.LogonType AS LogonType, EventData.AuthenticationPackageName AS AuthPackage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4624 AND EventData.LogonType = 3 AND EventData.AuthenticationPackageName = 'NTLM' AND EventData.IpAddress != '' AND EventData.IpAddress != EventData.WorkstationName$orcafix$, updated_at = NOW()
WHERE t_code = 'T1550.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '8986ef97e03bab7273e117dbe286b369';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.PassTheTicket
description: Detect Pass the Ticket attacks by correlating Kerberos authentication events
sources:
- name: KerberosServiceTickets
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.TargetUserName AS User,
           EventData.ServiceName AS Service,
           EventData.IpAddress AS SourceIP,
           EventData.TicketOptions AS Options
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4769 AND EventData.Status = '0x0'
- name: KerberosTGTRequests
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.TargetUserName AS User,
           EventData.IpAddress AS SourceIP,
           EventData.PreAuthType AS PreAuth
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4768 AND EventData.Status = '0x0'
- name: LSASSAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.SourceProcessId AS SourceProcessId, EventData.SourceImage AS SourceImage, EventData.TargetImage AS TargetImage,
           EventData.GrantedAccess AS GrantedAccess, EventData.CallTrace AS CallTrace
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10 AND EventData.TargetImage =~ 'lsass.exe'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1550.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '925fe2c47aa459c086d06b994e53462c';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.WebSessionCookie.Analysis
description: Collect web session cookie artifacts and authentication events for T1550.004 analysis
sources:
- name: BrowserCookies
  query: |
    SELECT OSPath, Name, Domain, Path, Value, Creation_utc, Last_access_utc, Expires_utc, Is_secure, Is_httponly
    FROM glob(globs='C:/Users/*/AppData/Local/Google/Chrome/User Data/*/History')
    WHERE Domain =~ '(office|microsoft|aws|google|okta)'
    UNION
    SELECT OSPath, name AS Name, host AS Domain, path AS Path, value AS Value, creationTime AS Creation_utc, lastAccessed AS Last_access_utc, expiry AS Expires_utc, isSecure AS Is_secure, isHttpOnly AS Is_httponly
    FROM Artifact.Windows.Forensics.Firefox.Cookies()
    WHERE host =~ '(office|microsoft|aws|google|okta)'
- name: AuthenticationEvents
  query: |
    SELECT timestamp(epoch=EventTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.LogonType, EventData.IpAddress, EventData.WorkstationName, EventData.TargetUserName, EventData.AuthenticationPackageName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4624, 4625, 4648) AND EventData.LogonType IN (3, 10, 11)
    ORDER BY EventTime DESC LIMIT 1000
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1550.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '6defdb88e091c0bdf084f51c8b6c446b';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=EventTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, EventData.LogonType, EventData.AuthenticationPackageName, EventData.IpAddress, EventData.WorkstationName, EventData.TargetUserName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4625, 4648) AND EventData.LogonType IN (3, 10)$orcafix$, updated_at = NOW()
WHERE t_code = 'T1550.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '4a412c2667c723352b043531cd2b258c';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: T1552.UnsecuredCredentials
description: Detect access to unsecured credential files and registry locations across multiple data sources
sources:
- name: CredentialFileAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.TargetFilename as AccessedFile, EventData.ProcessId as PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '''(?i)(unattend\.xml|web\.config|sysprep\.inf|\.ssh[\\/]id_rsa|credentials?\.txt|\.kdbx)''' OR EventData.TargetFilename =~ '''(?i)\\(passwords?|creds?|keys?)\\''')
- name: CredentialProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.NewProcessName as ProcessName, EventData.CommandLine, EventData.ParentProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.CommandLine =~ '''(?i)(reg\s+query.*winlogon|findstr.*password|grep.*password)''' OR EventData.NewProcessName =~ '''(?i)(reg\.exe|findstr\.exe)$''')
- name: CredentialRegistryAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.TargetObject as RegistryPath FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value IN (13, 14) AND EventData.TargetObject =~ '''(?i)(winlogon|credentials|passwords|lsa\\secrets)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1552' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '327be678287efe5c2b401f81ad020d25';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.TargetFilename as AccessedFile, EventData.ProcessId as PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '''(?i)(unattend\.xml|web\.config|sysprep\.inf|\.ssh[\\/]id_rsa|credentials?\.txt|\.kdbx)''' OR EventData.TargetFilename =~ '''(?i)\\(passwords?|creds?|keys?)\\''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1552' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'cd25dd0ce80ab07472f3a62226af5bd9';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.CredentialsInFiles
description: Detects access to unsecured credential files through file access and process execution correlation
sources:
- name: SysmonFileAccess
  query: |
    SELECT System.TimeCreated as Timestamp, EventData.Image, EventData.TargetFilename, EventData.ProcessId, EventData.User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND (
      EventData.TargetFilename =~ '''(?i)\.(env|xml|ps1|config|ini|kdbx)$''' OR
      EventData.TargetFilename =~ '(?i)(password|credential|secret|login|unattend)'
    )
- name: CredentialHarvestingProcesses
  query: |
    SELECT System.TimeCreated as Timestamp, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (
      EventData.CommandLine =~ '(?i)(findstr|select-string).*(password|credential)' OR
      EventData.CommandLine =~ '''(?i)type.*\.(xml|ini|env)''' OR
      EventData.CommandLine =~ '(?i)Get-Content.*(credential|password)'
    )
- name: AuthenticationEvents
  query: |
    SELECT System.TimeCreated as Timestamp, EventData.LogonType, EventData.TargetUserName, EventData.IpAddress, EventData.WorkstationName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4624, 4648) AND EventData.LogonType IN (2, 3, 9, 10)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1552.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'aceb99d29bf33f51785e5379321ed9b3';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS TimeCreated, EventData.Image, EventData.TargetFilename, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '''(?i)\.(env|xml|ps1|config|ini|kdbx)$''' OR EventData.TargetFilename =~ '(?i)(password|credential|secret|login)' OR EventData.TargetFilename =~ '''(?i)(unattend\.xml|sysprep\.inf|groups\.xml)''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1552.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '1dd96ef085a36274fd7ef8bd8689c83e';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.T1552_002_RegistryCredentials
description: Detect credential discovery in Windows Registry via process execution and registry modifications
sources:
- name: ProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.Image AS ProcessPath, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.CommandLine =~ '(?i)(reg query|Get-ItemProperty).*(HKLM|HKCU).*(password|credential)'
- name: RegistryModification
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.TargetObject AS RegistryKey, EventData.Image AS ProcessPath FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value IN (12,13,14) AND EventData.TargetObject =~ '(?i)(Winlogon|PuTTY|VNC|RDP).*'
- name: StoredCredentials
  query: |
    SELECT OSPath, Data.value AS CredentialData FROM Artifact.Windows.Registry.NTUser() WHERE OSPath =~ '(?i)(Winlogon|PuTTY|Sessions)' AND Data.value != ''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1552.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '0ad417372a1a2fc77b53f469f708350a';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, EventData.Image AS ProcessPath, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.ProcessId AS PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)reg\.exe$''' OR EventData.Image =~ '''(?i)powershell\.exe$''') AND EventData.CommandLine =~ '(?i)(HKLM|HKCU).*(password|credential|logon|cred)' ORDER BY Timestamp DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1552.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '463423f8994b155ddcaa6a6b261f1d91';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.PrivateKeyAccess
description: Detect access to private key files and certificates across multiple data sources
sources:
- name: SysmonFileAccess
  query: "SELECT System.TimeCreated.SystemTime AS Timestamp,\n       EventData.Image,\n       EventData.Image, \n       EventData.TargetFilename,\n       EventData.ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 11 \n  AND EventData.TargetFilename =~ '''(?i)\\.(pem|pfx|ppk|p12|key|cer|p7b|asc|gpg)$|[\\\\\\/]\\.ssh[\\\\\\/]'''\n"
