    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.SubjectUserName,
           EventData.RelativeTargetName,
           EventData.ProcessName,
           EventData.AccessMask
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 5145
      AND EventData.RelativeTargetName =~ '''(?i)\.(pem|pfx|ppk|p12|key|cer|p7b)$'''
- name: ProcessCreation
  query: "SELECT System.TimeCreated.SystemTime AS Timestamp,\n       EventData.Image,\n       EventData.CommandLine,\n       EventData.ParentImage,\n       EventData.ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 1\n  AND (EventData.CommandLine =~ '''(?i)\\.(pem|pfx|ppk|key|p12)''' OR EventData.CommandLine =~ '''(?i)\\.ssh''')\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1552.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '009a132966f38fab84035a72ad406707';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, EventData.Image, EventData.Image, EventData.TargetFilename, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\.(pem|pfx|ppk|p12|key|cer|p7b|asc|gpg)$|[\\\/]\.ssh[\\\/]|[\\\/]Crypto[\\\/]'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1552.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '41ced98e6f9f72916de317a9d0c2ba92';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.GPPCredentialAccess
description: Detects Group Policy Preferences credential extraction attempts
sources:
- name: SysvolFileAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.SubjectUserName, EventData.ShareName, EventData.RelativeTargetName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 5145
      AND EventData.ShareName =~ '(?i)SYSVOL'
      AND EventData.RelativeTargetName =~ '''(?i)\.xml$'''
- name: GPPToolExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.ProcessId, EventData.Image, EventData.CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.CommandLine =~ '(?i)(Get-GPPPassword|gpprefdecrypt|post/windows/gather/credentials/gpp)'
           OR EventData.CommandLine =~ '(?i)(cpassword|AES.*decrypt.*GPP)')
- name: PowerShellGPPActivity
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.ScriptBlockText
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104
      AND EventData.ScriptBlockText =~ '(?i)(cpassword|ConvertFrom-SecureString.*GPP|xml.*decrypt)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1552.006' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '08586cef92f1bfdef38381818c362a04';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.ProcessId, EventData.Image, EventData.CommandLine, EventData.ParentImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '(?i)(Get-GPPPassword|gpprefdecrypt|gpp.*decrypt|cpassword)' OR EventData.Image =~ '(?i)(powershell|python|ruby).*' AND EventData.CommandLine =~ '''(?i)(SYSVOL.*xml|Groups\.xml|Services\.xml|ScheduledTasks\.xml)''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1552.006' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '18b1ac686f10e55469de5dbaedcd8745';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS TimeCreated, System.Computer, System.EventID.Value, EventData.ScriptBlockText FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx') WHERE System.EventID.Value IN (4103, 4104) AND EventData.ScriptBlockText =~ '(?i)(Get-UnifiedAuditLog|Search-UnifiedAuditLog|MessageSend|MessageRead|FileAttached)' AND (EventData.ScriptBlockText =~ '''(?i)(api[_-]?key|bearer\s+token|password\s*=|secret\s*=|token\s*=)''' OR EventData.ScriptBlockText =~ '(?i)(slack|teams|jira|trello)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1552.008' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '95edd499f415f431375ca7879d32cede';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.TrustControlSubversion
description: Detect subversion of Windows trust controls through certificate and registry monitoring
sources:
- name: CertificateRegistryModifications
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.ObjectName as RegistryPath, EventData.ProcessName, EventData.SubjectUserName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4657 AND (EventData.ObjectName =~ '''SOFTWARE\\Microsoft\\Cryptography''' OR EventData.ObjectName =~ 'AuthRoot' OR EventData.ObjectName =~ 'TrustedPublisher')
- name: SuspiciousFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.TargetFilename, EventData.ProcessId, EventData.Image
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '\\.cer$' OR EventData.TargetFilename =~ '\\.crt$' OR EventData.TargetFilename =~ 'CertSrv')
- name: UnsignedProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.Image, EventData.CommandLine, EventData.ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.Signed = 'false'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1553' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'c73ad0a91e8742fad73a6f3ce1abf9ac';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, EventData.ObjectName as RegistryKey, EventData.ProcessName, EventData.SubjectUserName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4657 AND (EventData.ObjectName =~ '''SOFTWARE\\Microsoft\\Cryptography''' OR EventData.ObjectName =~ 'AuthRoot' OR EventData.ObjectName =~ 'TrustedPublisher' OR EventData.ObjectName =~ 'CryptSIPDll')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1553' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'eb97787a27856a800a285dc01fc73f0c';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.SIPTrustProviderHijack
description: Detect SIP and Trust Provider hijacking through registry modifications and DLL loading analysis
sources:
- name: RegistryModifications
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.ObjectName as RegistryPath, \n       EventData.ObjectValueName as ValueName, EventData.NewValue as NewValue,\n       EventData.ProcessName as ProcessName\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value = 4657 \n  AND EventData.ObjectName =~ '(?i)SOFTWARE.*Microsoft.*Cryptography.*(OID.*EncodingType|Providers.*Trust.*FinalPolicy)'\n  AND EventData.ObjectValueName =~ '(?i)(Dll|FuncName|Function)'\n"
- name: SuspiciousDLLLoads
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.Image as ProcessImage,
           EventData.ImageLoaded as LoadedDLL, EventData.ProcessId as PID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7
      AND (EventData.Image =~ '(?i)(explorer|winlogon|services|lsass|csrss)'
           OR EventData.ImageLoaded =~ '(?i)(wintrust|crypt32|cryptsp)')
      AND EventData.ImageLoaded =~ '''(?i)\.(dll)$'''
      AND NOT EventData.ImageLoaded =~ '(?i)windows.*system32'
- name: TrustValidationFailures
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, Message
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-CodeIntegrity%4Operational.evtx')
    WHERE System.EventID.Value = 3033
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1553.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '5c197609d0d7f6ed07d1d86104ad0d9c';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, Message, EventData FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4657 AND Message =~ '(?i)(Cryptography.*OID.*EncodingType|Cryptography.*Providers.*Trust.*FinalPolicy|CryptSIPDll|FinalPolicy)' AND (EventData.ObjectName =~ '(?i)SOFTWARE.*Microsoft.*Cryptography.*(OID|Providers.*Trust)' OR EventData.ObjectValueName =~ '(?i)(Dll|FuncName|Function)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1553.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'bbf36e9f0fb7cbfc5e8e18de66410eed';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ 'certutil.*-addstore.*root' OR EventData.CommandLine =~ 'Import-Certificate.*-CertStoreLocation.*Root' OR EventData.CommandLine =~ 'security.*add-trusted-cert')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1553.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'd41231c0ca42e77e5dabb4ebbea8fcc2';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.MOTW.Bypass
description: Detect Mark-of-the-Web bypass via container files
sources:
- name: ContainerFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           EventData.TargetFilename as FilePath,
           EventData.Image as ProcessName,
           'Container File' as ArtifactType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11
      AND EventData.TargetFilename =~ '(?i)\\.(iso|vhd|zip|rar|7z)$'
- name: FileAccessWithoutMOTW
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           EventData.ObjectName as FilePath,
           EventData.ProcessName as ProcessName,
           'File Access' as ArtifactType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4663, 4656)
      AND EventData.AccessMask = 0x100001
      AND NOT EventData.ObjectName =~ 'Zone.Identifier'
- name: ExecutionFromExtracted
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           EventData.Image as ProcessPath,
           EventData.CommandLine as CommandLine,
           'Process Execution' as ArtifactType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.Image =~ '(?i)temp|downloads|desktop|users'
           OR EventData.Image =~ '(?i)[a-z]:\\[^\\]*\.(exe|com|scr|bat|cmd)$')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1553.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '4a3876bfed4cc435cb211f07885cc8a2';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.CodeSigningPolicyModification
description: Detect modifications to Windows code signing enforcement policies
sources:
- name: BCDEditExecution
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.NewProcessName, EventData.CommandLine, EventData.ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value = 4688 AND EventData.NewProcessName =~ 'bcdedit.exe' \nAND EventData.CommandLine =~ '(?i)(TESTSIGNING|loadoptions|bootdebug)'\n"
- name: RegistryModifications
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ObjectName, EventData.ProcessName, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4657 AND EventData.ObjectName =~ '''(?i)(CI\\Policy|SecureBoot|CodeIntegrity)'''
- name: SigningPolicyRegistry
  query: |
    SELECT OSPath, Name, Data.value as Value, Mtime
    FROM Artifact.Windows.Registry.NTUser()
    WHERE Key =~ '''SYSTEM\\.*Control\\(CI|SecureBoot|CodeIntegrity)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1553.006' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'cbbb2e3035c52ce169b661a4bcee39d2';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND ((EventData.Image =~ '''(?i)bcdedit\.exe''' AND EventData.CommandLine =~ '(?i)(TESTSIGNING|loadoptions|bootdebug)') OR (EventData.Image =~ '''(?i)reg\.exe''' AND EventData.CommandLine =~ '''(?i)(CI\\Policy|SecureBoot)''')) LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND ((EventData.NewProcessName =~ '''(?i)bcdedit\.exe''' AND EventData.CommandLine =~ '(?i)(TESTSIGNING|loadoptions|bootdebug)') OR (EventData.NewProcessName =~ '''(?i)reg\.exe''' AND EventData.CommandLine =~ '''(?i)(CI\\Policy|SecureBoot)''')) SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1553.006' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'd15675e63fe118733c2e617263d881f0';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.T1554.CompromiseHostBinary
description: Detect modification and execution of host software binaries indicating T1554 activity
sources:
- name: BinaryModifications
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetFilename as ModifiedFile, EventData.ProcessId, EventData.Image as ModifyingProcess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\.(exe|dll|sys)$'''
    AND (EventData.TargetFilename =~ '''(?i)C:\\Windows\\System32\\''' OR EventData.TargetFilename =~ '''(?i)C:\\Program Files\\''')
- name: ProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.NewProcessName as ExecutablePath, EventData.CommandLine, EventData.ParentProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND EventData.NewProcessName =~ '''(?i)\.(exe|dll|sys)$'''
- name: SignatureChanges
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetFilename, EventData.Hashes, EventData.Signed, EventData.Signature
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 2 AND EventData.TargetFilename =~ '''(?i)\.(exe|dll|sys)$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1554' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '0f07c2291de20f873f10a4d775ea9a3f';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath, EventData.OriginalFileName, EventData.CommandLine, EventData.ParentImage, EventData.User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\.(exe|dll|sys)$''' AND (EventData.TargetFilename =~ '''(?i)C:\\Windows\\System32\\''' OR EventData.TargetFilename =~ '''(?i)C:\\Program Files\\''') ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1554' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '9755f67bd7db5b0500b51963707a5aff';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.CredentialStoreAccess
description: Detect credential access from password stores across multiple sources
sources:
- name: SysmonProcessAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceImage AS SourceProcessName, EventData.TargetImage AS TargetProcessName, EventData.GrantedAccess AS GrantedAccess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10 AND EventData.TargetImage =~ 'lsass.exe'
    AND format(format='0x%x', args=EventData.GrantedAccess) =~ '(0x1010|0x1038|0x143a)'
- name: SecurityObjectAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName AS SubjectUserName, EventData.ProcessName AS ProcessName, EventData.ObjectName AS ObjectName, EventData.AccessMask AS AccessMask
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4656, 4663) AND EventData.ObjectName =~ '(Credentials|Vault)'
- name: BrowserCredentialFiles
  query: |
    SELECT OSPath, Size, Mtime, Atime FROM glob(globs=[
      'C:/Users/*/AppData/Local/Google/Chrome/User Data/*/Login Data',
      'C:/Users/*/AppData/Roaming/Mozilla/Firefox/Profiles/*/logins.json'
    ])
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1555' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a52f682712180325f1efdccbe67d8f91';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceImage AS SourceProcessName, EventData.SourceProcessId AS SourceProcessId, EventData.TargetImage AS TargetProcessName, EventData.TargetProcessId AS TargetProcessId, EventData.GrantedAccess AS GrantedAccess, EventData.CallTrace AS CallTrace FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 10 AND EventData.TargetImage =~ 'lsass.exe' AND format(format='0x%x', args=EventData.GrantedAccess) =~ '(0x1010|0x1038|0x143a|0xFFFF)' AND NOT EventData.SourceImage =~ '(wininit.exe|services.exe|winlogon.exe|csrss.exe|smss.exe)'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1555' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'a3c4447e3069aa565e1da5eeb5ab8d08';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessName as ProcessName, EventData.ProcessId as ProcessId, EventData.ObjectName as ObjectName, EventData.AccessMask as AccessMask FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4663 AND (ObjectName =~ '(?i).*Login Data.*' OR ObjectName =~ '''(?i).*logins\.json.*''' OR ObjectName =~ '(?i).*Credential.*Locker.*') AND NOT ProcessName =~ '''(?i).*(chrome|firefox|msedge|iexplore)\.exe$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1555.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '83ca501fd9800cd6f3045769996211c1';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.CredentialManager.Detection
description: Detect access to Windows Credential Manager through process execution, API calls, and file access
sources:
- name: ProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.NewProcessName AS ProcessPath, EventData.CommandLine AS CommandLine, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE EventData.NewProcessName =~ '''(?i)(vaultcmd\.exe|rundll32\.exe)''' AND (EventData.CommandLine =~ '(?i)vaultcmd' OR EventData.CommandLine =~ '''(?i)keymgr\.dll''')
- name: APIMonitoring
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.SourceImage AS SourceProcess, EventData.TargetImage AS TargetProcess, EventData.CallTrace AS CallTrace FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE EventData.CallTrace =~ '(?i)CredEnumerate'
- name: FileAccess
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.NewProcessName AS ProcessPath, EventData.TargetFilename AS FilePath, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE EventData.TargetFilename =~ '''(?i)(\\Credentials\\.*\.vcrd|\\Vault\\.*\.vpol|Policy\.vpol)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1555.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'eb8ae85e389ad62ee46c94e4b4cdca24';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(vaultcmd\.exe|rundll32\.exe)''' AND (EventData.CommandLine =~ '(?i)vaultcmd' OR EventData.CommandLine =~ '''(?i)keymgr\.dll''')) LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''(?i)(vaultcmd\.exe|rundll32\.exe)''' AND (EventData.CommandLine =~ '(?i)vaultcmd' OR EventData.CommandLine =~ '''(?i)keymgr\.dll''')) SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1555.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '893686f098bb36b2fcfc3086c6315d04';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.PasswordManagerAccess
description: Detect unauthorized access to password manager processes and vault files
sources:
- name: PasswordManagerProcessAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.SourceImage as SourceProcess, EventData.TargetImage as TargetProcess, EventData.GrantedAccess as Access, EventData.ProcessId as PID, EventData.TargetProcessId as TargetPID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 10 AND (EventData.TargetImage =~ '(?i)(keepass|1password|lastpass|bitwarden)' OR EventData.TargetImage =~ '(?i)(keepass|1password|lastpass|bitwarden)') AND EventData.GrantedAccess IN (0x1f0fff, 0x1fffff, 0x143a, 0x1410)
- name: PasswordVaultFileAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image as ProcessName, EventData.TargetFilename as VaultFile, EventData.Hash as FileHash FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 15 AND EventData.TargetFilename =~ '''(?i)\.(kdbx|opvault|ldb)$'''
- name: ProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.NewProcessName as ProcessName, EventData.ParentProcessName as ParentProcess, EventData.CommandLine as CommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '(?i)(keepass|1password|lastpass|bitwarden)' OR EventData.CommandLine =~ '(?i)(kdbx|opvault|vault)')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1555.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a40a0a527bfa4e2b1eb3429111f07103';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.SourceImage as ProcessName, EventData.TargetImage as TargetProcess, EventData.GrantedAccess as Access, EventData.ProcessId as PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 10 AND (EventData.TargetImage =~ '(?i)(keepass|1password|lastpass|bitwarden)' OR EventData.TargetImage =~ '(?i)(keepass|1password|lastpass|bitwarden)') AND EventData.GrantedAccess IN (0x1f0fff, 0x1fffff, 0x143a, 0x1410)$orcafix$, updated_at = NOW()
WHERE t_code = 'T1555.005' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '6d6b7345e61350227fffd9b68958b0e4';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.AuthenticationModification
description: Detect modification of Windows authentication processes via registry changes and suspicious LSASS access
sources:
- name: RegistryModifications
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.ObjectName as RegistryPath, \n       EventData.ObjectValueName as ValueName, EventData.NewValue as NewValue, \n       EventData.ProcessName as ProcessName \nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') \nWHERE System.EventID.Value = 4657 \n  AND (EventData.ObjectName =~ '''SYSTEM\\\\CurrentControlSet\\\\Control\\\\Lsa''' \n       OR EventData.ObjectName =~ '''SYSTEM\\\\CurrentControlSet\\\\Control\\\\SecurityProviders''')\n"
- name: SuspiciousLSASSAccess
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceImage AS SourceImage, EventData.TargetImage AS TargetImage, EventData.GrantedAccess AS GrantedAccess, EventData.CallTrace AS CallTrace \nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 10 \n  AND EventData.TargetImage =~ 'lsass.exe' \n  AND format(format='0x%x', args=EventData.GrantedAccess) =~ '(0x1010|0x1038|0x143a|0x1fffff)'\n"
- name: AuthenticationDLLLoads
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.ImageLoaded AS ImageLoaded, EventData.Signed AS Signed, EventData.Signature AS Signature \nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 7 \n  AND EventData.Image =~ 'lsass.exe' \n  AND (Signed = 'false' OR EventData.ImageLoaded =~ '(?i)(temp|users|appdata)')\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1556' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '4cf91dbb9bdbaccc85bca9cb4e1b5b84';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, EventData.ObjectName as RegistryPath, EventData.ObjectValueName as ValueName, EventData.NewValue as NewValue, EventData.ProcessName as ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4657 AND (EventData.ObjectName =~ '''SYSTEM\\CurrentControlSet\\Control\\Lsa''' OR EventData.ObjectName =~ '''SYSTEM\\CurrentControlSet\\Control\\SecurityProviders''') AND EventData.ObjectValueName =~ '(Authentication Packages|Notification Packages|Security Packages)'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1556' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'a5bb13010d1f98ea0a603dd9cf9d2a03';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.T1556_001.SkeletonKey
description: Detect Skeleton Key attacks on domain controllers through LSASS access and authentication anomalies
sources:
- name: SuspiciousLSASSAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceImage as SourceProcess, EventData.TargetImage, EventData.SourceProcessId, EventData.TargetProcessId, EventData.GrantedAccess, EventData.CallTrace
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10 AND EventData.TargetImage =~ '''lsass\.exe$''' AND format(format='0x%x', args=EventData.GrantedAccess) =~ '0x1010|0x1038|0x1FFFFF'
- name: AuthenticationDLLLoads
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId, EventData.Image as ProcessImage, EventData.ImageLoaded, EventData.Hashes, EventData.Signed
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7 AND EventData.Image =~ '''lsass\.exe$''' AND EventData.ImageLoaded =~ '''cryptdll\.dll|samsrv\.dll|kdcsvc\.dll'''
- name: AnomalousAuthentications
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetUserName, EventData.IpAddress, EventData.LogonType, EventData.AuthenticationPackageName, EventData.SubjectUserName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4624, 4648) AND EventData.LogonType = 3 AND EventData.AuthenticationPackageName = 'NTLM'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1556.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '1e806e67b4401608e3f990c9fef5db5c';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceImage as ProcessImage, EventData.TargetImage as TargetImage, EventData.SourceProcessId as SourcePID, EventData.TargetProcessId as TargetPID, EventData.CallTrace as CallTrace FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 10 AND EventData.TargetImage =~ '''lsass\.exe$''' AND format(format='0x%x', args=EventData.GrantedAccess) =~ '0x1010|0x1038|0x1FFFFF'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1556.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '80809e83db9ec83faa5ced5cb384141e';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.PasswordFilterDLL
description: Detect malicious password filter DLL registration through registry monitoring and LSASS module loading correlation
sources:
- name: RegistryModification
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessName, EventData.ObjectName, EventData.ObjectValueName, EventData.NewValue
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4657
    AND EventData.ObjectName =~ 'Notification Packages'
- name: DLLFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.TargetFilename, EventData.CreationUtcTime
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11
    AND EventData.TargetFilename =~ '''System32.*\.dll$'''
- name: LSASSModuleLoad
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ImageLoaded, EventData.Signed, EventData.SignatureStatus
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7
    AND EventData.Image =~ '''lsass\.exe''' AND EventData.ImageLoaded =~ '''\.dll$'''
- name: NotificationPackagesRegistry
  query: |
    SELECT OSPath, Data.value
    FROM Artifact.Windows.Registry.NTUser()
    WHERE Key.OSPath =~ '''HKEY_LOCAL_MACHINE\\SYSTEM\\.*Control\\Lsa$'''
    AND Data.value =~ 'Notification Packages'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1556.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '5762dac1bb9013487059bf8e2d32ed56';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.Image, EventData.ImageLoaded, EventData.Signed, EventData.SignatureStatus FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND EventData.Image =~ '''lsass\.exe''' AND (EventData.ImageLoaded =~ '\\.dll$' AND EventData.Signed = 'false' OR EventData.SignatureStatus != 'Valid')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1556.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'b342604ed45cc1099f2a50db3f56847b';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1556_005.ReversibleEncryption
description: Detects enabling of reversible password encryption through multiple log sources
sources:
- name: SecurityEventLog
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData,
           parse_json_array(data=EventData.PolicyChanges) AS PolicyChanges
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4739 AND EventData =~ '(?i)AllowReversiblePasswordEncryption|reversible.+password'
- name: PowerShellLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.ScriptBlockText AS Command
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value IN (4103, 4104, 4105, 4106) AND EventData.ScriptBlockText =~ '(?i)Set-ADUser.*AllowReversiblePasswordEncryption.*true'
- name: SysmonProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)gpedit\.msc|Set-ADUser.*AllowReversiblePasswordEncryption''' OR EventData.Image =~ '(?i)powershell.*exe$')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1556.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '5be23f6865e3b14c9aae135629df9a40';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer, System.EventID.Value, EventData.SubjectUserName as User, EventData.SubjectDomainName as Domain, EventData.CategoryId, EventData.SubcategoryId, EventData.Changes FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4739 AND EventData.Changes =~ '(?i)(MFA|Multi.Factor|Authentication.Policy|Conditional.Access)'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1556.006' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '6541fd5f54245a410875ab56b9163517';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.HybridIdentityTampering
description: Detects modification of hybrid identity authentication processes including Azure AD Connect PTA agents and AD FS configurations
sources:
- name: SecurityEventLogs
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.SubjectUserName as User, EventData.ProcessName as Process, Message\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value IN (4624, 5136, 4648) \nAND (Message =~ '(?i)(azure.*ad.*connect|adfs|federation|hybrid|pta)' OR EventData.ProcessName =~ '(?i)(azureadconnect|identityserver)')\n"
- name: SysmonImageLoads
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as PID, EventData.Image as Process, EventData.ImageLoaded as LoadedDLL, EventData.Signed, EventData.Signature
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7
    AND EventData.Image =~ '''(?i)(AzureADConnectAuthenticationAgentService|Microsoft\.IdentityServer|lsass)'''
- name: HybridIdentityFiles
  query: |
    SELECT OSPath, Size, Mtime, Atime, Ctime, hash(path=OSPath) as Hash
    FROM glob(globs=['C:/Program Files/ADFS/**', 'C:/Program Files/Microsoft Azure AD Sync/**', 'C:/Program Files/Microsoft Azure AD Connect Authentication Agent/**'])
    WHERE NOT IsDir
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1556.007' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '3517402e8f4195585105f1bfec443315';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.NetworkProviderDLL
description: Detect Network Provider DLL credential capture technique T1556.008
sources:
- name: RegistryModifications
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, System.Computer, EventData.ObjectName, EventData.ProcessName, EventData.HandleId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4657 AND EventData.ObjectName =~ '(?i).*NetworkProvider.*'
- name: SuspiciousDLLLoads
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, System.Computer, EventData.Image, EventData.ImageLoaded, EventData.Signed
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7 AND EventData.Image =~ '''(?i)mpnotify\.exe'''
- name: NetworkProviderRegistry
  query: |
    SELECT OSPath, Data.value AS ProviderOrder, Mtime
    FROM read_reg_key(key='HKEY_LOCAL_MACHINE/SYSTEM/CurrentControlSet/Control/NetworkProvider/Order')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1556.008' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'baddef5d725c17a43791c1c253ac4c40';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.EventID.Value, System.Computer, EventData.Image, EventData.Image, EventData.ImageLoaded, EventData.Signed, EventData.Signature FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND (EventData.Image =~ '''mpnotify\.exe''' OR EventData.ImageLoaded =~ '(?i).*\\(system32|syswow64)\\[^\\]*\.dll$') AND NOT EventData.ImageLoaded =~ '(?i).*(microsoft|windows|system)'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1556.008' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'a14835d1eb855a8027999f9c0c410f16';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.ConditionalAccessPolicyModification
description: Detect modifications to authentication policies and conditional access controls
sources:
- name: SecurityEventLogs
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.EventID.Value AS EventID, EventData.SubjectUserName as User, EventData.PolicyType, EventData.AuditPolicyChanges as Changes, System.Computer AS Computer\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') \nWHERE System.Channel = 'Security' AND System.EventID.Value IN (4719, 4739) AND EventData.SubjectUserName != 'SYSTEM'\n"
- name: PowerShellCommandHistory
  query: |
    SELECT Mtime, OSPath, Line
    FROM Artifact.Windows.Forensics.Timeline()
    WHERE OSPath =~ 'PSReadLine.*history'
    AND Line =~ '(?i)(Set-MsolDomainAuthentication|Set-AzureADPolicy|New-AzureADMSConditionalAccessPolicy|Set-AzureADMSConditionalAccessPolicy)'
- name: AzureADLogs
  query: |
    SELECT timestamp, OSPath, Size
    FROM glob(globs='C:/Users/*/AppData/Local/Microsoft/Azure/AzureAD/Telemetry/**')
    WHERE Size > 0
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1556.009' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'fb4af825adb4d6370078e43d7ec7c16e';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.EventID.Value, EventData.SubjectUserName as User, EventData.PolicyType as PolicyType, EventData.CategoryId as Category, EventData.AuditPolicyChanges as Changes, System.Computer AS Computer FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') AND System.EventID.Value IN (4719, 4739) AND EventData.SubjectUserName != 'SYSTEM'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1556.009' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'eb1b47327724f9b1b099d4babb8fef11';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.LLMNR_NBT_NS_Poisoning
description: |
  Detects LLMNR/NBT-NS poisoning through service creation, registry modifications, and network authentication patterns.
sources:
- name: ServiceCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ServiceName, EventData.ServiceFileName, EventData.ServiceType, EventData.ServiceAccount\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') \nWHERE System.EventID.Value = 4697 AND (EventData.ServiceFileName =~ '(?i)(responder|inveigh|nbtns|llmnr)' OR EventData.ServiceName =~ '(?i)(responder|inveigh|poison)')\nORDER BY EventTime DESC\n"
- name: RegistryModifications
  query: "SELECT ModTime, OSPath, Data.value as EnableMulticast\nFROM Artifact.Windows.Registry.NTUser() \nWHERE OSPath =~ '''SOFTWARE\\\\Policies\\\\Microsoft\\\\Windows NT\\\\DNSClient\\\\EnableMulticast'''\n"
- name: SuspiciousLogons
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.LogonType, EventData.AuthenticationPackageName, EventData.IpAddress, EventData.TargetUserName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4624 AND EventData.LogonType = 3 AND EventData.AuthenticationPackageName = 'NTLM' AND EventData.IpAddress =~ '^(10\\.|172\\.(1[6-9]|2[0-9]|3[0-1])\\.|192\\.168\\.)'
    ORDER BY EventTime DESC
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1557.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '2e57c74acd45247b1e163d7ce5941979';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ServiceName, EventData.ServiceFileName, EventData.ServiceType, EventData.ServiceStartType, EventData.ServiceAccount FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4697 AND (EventData.ServiceFileName =~ '(?i)(responder|inveigh|nbtns|llmnr)' OR EventData.ServiceName =~ '(?i)(responder|inveigh|poison)') ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1557.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '2066d1413b6935d53b82cfe62546aa08';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceIp as SrcIP, EventData.DestinationIp as DstIP, EventData.Protocol, EventData.Image, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.Protocol = 'arp' OR (System.EventID.Value = 22 AND EventData.QueryName =~ '''.*\.(arpa|local)$''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1557.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '2022b088283e63ecb658d2cdc436e1c5';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.DHCPSpoofing
description: Detect DHCP spoofing attacks through event logs and network configurations
sources:
- name: DHCP Events
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, Message, EventData
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx')
    WHERE System.EventID.Value IN (1020, 1341, 1342, 1063)
    AND Message =~ '(?i)(dhcp|unauthorized|exhaustion|rogue)'
    ORDER BY EventTime DESC
- name: Network Configuration
  query: |
    SELECT Key, Name, Data.value as Value, Data.type as Type
    FROM read_reg_key(key='HKEY_LOCAL_MACHINE/SYSTEM/CurrentControlSet/Services/Tcpip/Parameters/Interfaces/*')
    WHERE Name IN ('DhcpServer', 'DhcpNameServer', 'DhcpDefaultGateway', 'LeaseObtainedTime')
    ORDER BY Key
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1557.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'f2b2086bc15afceeed11344120a5ef8a';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer, System.EventID.Value, Message, EventData FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx') WHERE System.EventID.Value IN (1020, 1341, 1342, 1063) AND Message =~ '(?i)(dhcp|unauthorized|exhaustion|rogue)' ORDER BY TimeCreated DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1557.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '8035dd791f77d621d8387dcb210cbe94';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Evil.Twin.Detection
description: Detects potential Evil Twin Wi-Fi attacks through wireless events and network artifacts
sources:
- name: WirelessConnectionEvents
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, \n       EventData.param1 as SSID,\n       EventData.param2 as BSSID,\n       EventData.param3 as AuthenticationMethod\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value IN (8001, 8002, 8003, 11000, 11001) AND System.Channel = 'System'\n"
- name: WirelessProfiles
  query: |
    SELECT Name, OSPath, Mtime, Atime,
           parse_xml(file=OSPath).profileXML.SSIDConfig.SSID.name as ProfileSSID,
           parse_xml(file=OSPath).profileXML.connectionType as ConnectionType
    FROM glob(globs='C:/ProgramData/Microsoft/Wlansvc/Profiles/Interfaces/*/**.xml')
    WHERE Mtime > now() - 604800
- name: NetworkProfileRegistry
  query: |
    SELECT Key.ModTime, Key.OSPath,
           Key.ProfileName as NetworkName,
           Key.Description,
           Key.Category
    FROM Artifact.Windows.Registry.NTUser()
    WHERE Key.OSPath =~ 'SOFTWARE/Microsoft/Windows NT/CurrentVersion/NetworkList/Profiles/.*'
      AND Key.ModTime > now() - 604800
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1557.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'e40e4b9674908d2af33ad618044a244e';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, EventData.param1 as SSID, EventData.param2 as BSSID, EventData.param3 as AuthType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx') WHERE System.EventID.Value IN (8001, 8002, 8003) AND System.Channel = 'System'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1557.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'ed4e4688351ca5e06a86885bb48a396b';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.KerberosTicketAnomaly
description: Detects Kerberos ticket theft and forgery through TGT/TGS analysis and LSASS access monitoring
sources:
- name: KerberosTGSRequests
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetUserName as Username, EventData.ServiceName as Service, EventData.TicketEncryptionType as EncryptionType, EventData.IpAddress as ClientIP FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4769 AND (EventData.TicketEncryptionType = '0x17' OR EventData.PreAuthType = '0')
- name: LSASSMemoryAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceImage as ProcessPath, EventData.TargetImage as TargetProcess, EventData.GrantedAccess as AccessRights FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 10 AND EventData.TargetImage =~ 'lsass.exe' AND NOT EventData.SourceImage =~ '''(csrss|winlogon|services)\.exe'''
- name: TGTRequests
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetUserName as Username, EventData.TicketEncryptionType as EncryptionType, EventData.IpAddress as ClientIP FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4768 AND (EventData.TicketEncryptionType = '0x17' OR EventData.Status = '0x6')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1558' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '3f9a55a5391fa70903b96fe6d4e5d5c5';

