UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.GoldenTicket
description: Detect Golden Ticket attacks through Kerberos anomalies and credential access patterns
sources:
- name: KerberosTGSAnomalies
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TicketEncryptionType as EncryptionType,
           EventData.ServiceName, EventData.TargetUserName, EventData.IpAddress
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4769 AND EventData.TicketEncryptionType IN ('0x17', '0x18')
- name: PrivilegedLogonPatterns
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName, EventData.SubjectLogonId,
           EventData.PrivilegeList
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4672
- name: LsassAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceProcessId, EventData.SourceImage,
           EventData.TargetImage, EventData.GrantedAccess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10 AND EventData.TargetImage =~ 'lsass.exe' AND format(format='0x%x', args=EventData.GrantedAccess) =~ '0x1010|0x1038|0x143A'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1558.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'f869c84c06f7db9a1b8c8b1524635f5d';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer, EventData.TicketEncryptionType as EncryptionType, EventData.ServiceName, EventData.TargetUserName, EventData.IpAddress, EventData.TicketOptions FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4769 AND (EventData.TicketEncryptionType = '0x17' OR EventData.TicketEncryptionType = '0x18')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1558.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'adfeca02c5608a07d668d5e397f97e38';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Silver_Ticket_Detection
description: Detects forged Kerberos Silver Tickets through anomalous TGS activity and LSASS access
sources:
- name: Kerberos TGS Events
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.TargetUserName AS ServiceAccount,
           EventData.ServiceName AS Service,
           EventData.ClientAddress AS ClientIP,
           EventData.Status AS AuthStatus
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4769 AND EventData.ServiceName != 'krbtgt'
- name: LSASS Process Access
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.SourceImage AS SourceProcess,
           EventData.SourceProcessId AS SourcePID,
           EventData.TargetImage AS TargetProcess,
           EventData.GrantedAccess AS Access
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10 AND EventData.TargetImage =~ 'lsass.exe'
- name: Service Account Logons
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.TargetUserName AS Account,
           EventData.WorkstationName AS Workstation,
           EventData.LogonType AS LogonType,
           EventData.IpAddress AS SourceIP
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4624 AND EventData.TargetUserName =~ '''\$$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1558.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '7d5cc617f2c56d56f0c6709ab13ae9b7';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.Kerberoasting
description: Detect Kerberoasting attacks through TGS request analysis and process monitoring
sources:
- name: SuspiciousTGSRequests
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ServiceName as ServiceName, EventData.TargetUserName as TargetUser, EventData.IpAddress as ClientIP, EventData.TicketEncryptionType as EncryptionType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4769 AND (EventData.TicketEncryptionType = '0x17' OR EventData.ServiceName =~ '^[^$]*$')
- name: LSASSAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceProcessId, EventData.SourceImage, EventData.TargetImage, EventData.GrantedAccess, EventData.CallTrace FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 10 AND EventData.TargetImage =~ 'lsass.exe' AND format(format='0x%x', args=EventData.GrantedAccess) =~ '0x1010|0x1410'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1558.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '526b737a42af66ace825e388cded6034';

