UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.ASREPRoasting.Detection
description: Detect AS-REP Roasting attack patterns through Kerberos authentication analysis
sources:
- name: KerberosASREQ
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetUserName as TargetUser, EventData.IpAddress as SourceIP, EventData.PreAuthType as PreAuthType, EventData.TicketEncryptionType as EncryptionType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4768 AND EventData.PreAuthType = 0
- name: PowerShellEnumeration
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ScriptBlockText as Command
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104 AND EventData.ScriptBlockText =~ '(?i)(DoesNotRequirePreAuth|userAccountControl|DONT_REQ_PREAUTH)'
- name: ToolExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.CommandLine as CmdLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.CommandLine =~ '(?i)(GetNPUsers|Rubeus|ASREPRoast)'
$orcafix$, updated_at = NOW()
