UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.COMExecution
description: Detect COM object abuse through process creation, DLL loads, and registry access
sources:
- name: ProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as Image, EventData.ParentImage as ParentImage, EventData.CommandLine as CommandLine, EventData.ProcessGuid as ProcessGuid FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '(?i)-embedding' OR EventData.ParentImage =~ '''(?i)(dllhost\.exe|svchost\.exe.*DcomLaunch)''' OR EventData.Image =~ '''(?i)(wscript\.exe|cscript\.exe).*\.js|\.vbs''')
- name: DLLLoads
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ImageLoaded as DLLLoaded, EventData.ProcessGuid as ProcessGuid FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND EventData.ImageLoaded =~ '''(?i)(ole32\.dll|oleaut32\.dll|combase\.dll)''' AND EventData.Image =~ '''(?i)(powershell\.exe|cmd\.exe|wscript\.exe|cscript\.exe)'''
- name: COMRegistry
  query: |
    SELECT OSPath, ModTime, Data.value as ServerPath FROM Artifact.Windows.Registry.NTUser() WHERE OSPath =~ '(?i)Classes/CLSID/.*/InprocServer32|LocalServer32' AND ModTime > timestamp(epoch=now() - 86400*7)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1559.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'f3fa4516e2d226cc94439599b13c4270';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ParentImage as ParentImage, EventData.CommandLine as CommandLine, EventData.ProcessGuid as ProcessGuid FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '(?i)-embedding' OR EventData.ParentImage =~ '''(?i)(dllhost\.exe|rundll32\.exe)''' OR (EventData.ParentImage =~ '''(?i)(winword\.exe|excel\.exe|powerpnt\.exe|outlook\.exe)''' AND EventData.Image =~ '''(?i)(wscript\.exe|cscript\.exe|powershell\.exe)'''))$orcafix$, updated_at = NOW()
WHERE t_code = 'T1559.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '1ff27f0a0efce1efdca0728ad3f00ede';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.DDE.Analysis
description: Comprehensive DDE abuse detection across process creation, module loads, and registry access
sources:
- name: SuspiciousOfficeProcesses
  query: |
    SELECT System.TimeCreated, EventData.ParentImage, EventData.Image, EventData.CommandLine, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
    AND EventData.ParentImage =~ '''(?i)(winword\.exe|excel\.exe|powerpnt\.exe)$'''
    AND EventData.Image =~ '''(?i)(cmd\.exe|powershell\.exe|wscript\.exe|cscript\.exe|rundll32\.exe)$'''
- name: OfficeModuleLoads
  query: |
    SELECT System.TimeCreated, EventData.Image, EventData.ImageLoaded, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7
    AND EventData.Image =~ '''(?i)(winword\.exe|excel\.exe|powerpnt\.exe)$'''
    AND EventData.ImageLoaded =~ '''(?i)(kernel32\.dll|advapi32\.dll|shell32\.dll)$'''
- name: DDERegistryAccess
  query: |
    SELECT System.TimeCreated, EventData.ProcessName, EventData.ObjectName, EventData.AccessMask
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4663
    AND EventData.ObjectName =~ '(?i).*Office.*Options.*(DontUpdateLinks|DisableDDEServerLaunch).*'
    AND EventData.ProcessName =~ '''(?i)(winword\.exe|excel\.exe|powerpnt\.exe)$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1559.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '7c7e0746aa425a9a3326563acf2f07cf';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.T1560.ArchiveCollectedData
description: Detect archiving of collected data through process execution and file creation correlation
sources:
- name: CompressionProcesses
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,\n       System.EventID.Value, EventData.ProcessId, EventData.Image,\n       EventData.CommandLine, EventData.ParentImage\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 \n  AND (EventData.Image =~ '''(?i)(7z\\.exe|rar\\.exe|makecab\\.exe)$''' \n       OR (EventData.Image =~ '(?i)powershell' AND EventData.CommandLine =~ '(?i)compress-archive'))\n"
- name: ArchiveFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           System.EventID.Value, EventData.ProcessId, EventData.TargetFilename,
           EventData.Image
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11
      AND EventData.TargetFilename =~ '''(?i)\.(7z|rar|zip|tar|gz|bz2)$'''
      AND EventData.TargetFilename =~ '(?i)(temp|public|appdata)'
- name: CryptoLibraryLoads
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           System.EventID.Value, EventData.ProcessId, EventData.Image,
           EventData.ImageLoaded
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7
      AND EventData.ImageLoaded =~ '''(?i)crypt32\.dll'''
      AND EventData.Image =~ '(?i)(7z|rar|makecab|powershell)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1560' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'cfe087a1958c5f076d9d3566a70301ab';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.EventID.Value, EventData.ProcessId, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.ParentCommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(7z\.exe|rar\.exe|makecab\.exe)$''' OR (EventData.Image =~ '(?i)powershell' AND EventData.CommandLine =~ '(?i)compress-archive')) AND (EventData.CommandLine =~ '(?i)(temp|public|appdata)' OR EventData.CommandLine =~ '(?i)(-a|-m0|-mx)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1560' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '859a8daecab1482a5796b2e20767c0fd';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1560_001.ArchiveViaUtility
description: Detect archiving utilities and correlate with archive file creation
sources:
- name: ProcessCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.NewProcessName as ProcessName, \n       EventData.CommandLine, EventData.ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') \nWHERE System.EventID.Value = 4688 \n  AND (EventData.NewProcessName =~ '''makecab\\.exe$''' OR \n       EventData.NewProcessName =~ '''diantz\\.exe$''' OR \n       EventData.NewProcessName =~ '''7z\\.exe$''' OR \n       EventData.NewProcessName =~ '''rar\\.exe$''' OR \n       EventData.NewProcessName =~ '''certutil\\.exe$''')\n"
- name: FileCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetFilename, \n       EventData.ProcessId, EventData.Image\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 11 \n  AND (EventData.TargetFilename =~ '''\\.cab$''' OR \n       EventData.TargetFilename =~ '''\\.zip$''' OR \n       EventData.TargetFilename =~ '''\\.7z$''' OR \n       EventData.TargetFilename =~ '''\\.rar$''')\n"
- name: ImageLoads
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ImageLoaded\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 7 \n  AND EventData.ImageLoaded =~ '''crypt32\\.dll$'''\n  AND NOT EventData.Image =~ '''(svchost|explorer|winlogon)\\.exe$'''\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1560.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'ed06df80158ae0deb3c7fbf46deeacb2';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(makecab|diantz|7z|rar|winrar|certutil)\.exe$''') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''(?i)(makecab|diantz|7z|rar|winrar|certutil)\.exe$''') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1560.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'a29736afea51ddc3fbfb91542c555e9b';

