UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(python|powershell|cscript|wscript)\.exe$''' AND EventData.CommandLine =~ '(?i)(zip|compress|archive|gzip|bzip|rarfile|libzip|zlib)') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''(?i)(python|powershell|cscript|wscript)\.exe$''' AND EventData.CommandLine =~ '(?i)(zip|compress|archive|gzip|bzip|rarfile|libzip|zlib)') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1560.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '9379c12d9b206cbbbccf121da0c3ef0e';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.T1560_003_CustomArchiving
description: Detect custom archiving methods by correlating process execution with high-entropy file creation
sources:
- name: ProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.NewProcessName as ProcessName, EventData.CommandLine as CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND EventData.NewProcessName =~ '''(?i)(powershell|python|perl|cmd)\.exe$'''
