    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SourceProcessId as SourcePID, EventData.TargetProcessId as TargetPID, EventData.GrantedAccess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 10 AND format(format='0x%x', args=EventData.GrantedAccess) =~ '0x1F3FFF|0x1FFFFF'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1560.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'b1cb61371c6a3679964fa3b4953d124f';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as ProcessName, EventData.CommandLine as CommandLine, EventData.TargetFilename as CreatedFile FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\\(temp|appdata|users)\\.*\.(dat|tmp|enc|crypt|arc)$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1560.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '8522ebc591a1082694d1bac61d63ed19';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: T1561.DiskWipeDetection
description: |
  Detects disk wipe activities across multiple event sources including driver loads,
  process execution, and privilege escalation events.
sources:
- name: SuspiciousDriverLoads
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           System.EventID.Value, System.Computer,
           EventData.ProcessName, EventData.ImageLoaded,
           EventData.Signed, EventData.Signature
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 6 AND
          (NOT EventData.Signed = 'true' OR
           EventData.ImageLoaded =~ '(?i)(disk|wipe|erase|format)' OR
           EventData.ProcessName =~ '''(?i)(sdelete|cipher|dd\.exe)''')
- name: PrivilegeEscalation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           System.EventID.Value, System.Computer,
           EventData.SubjectUserName, EventData.ProcessName,
           EventData.PrivilegeList
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4673 AND
          EventData.PrivilegeList =~ '(?i)(SeBackupPrivilege|SeDebugPrivilege|SeSystemtimePrivilege)'
- name: RawDiskAccess
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           System.EventID.Value, System.Computer,
           EventData.ProcessGuid, EventData.Image,
           EventData.CommandLine, EventData.TargetFilename
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND
          EventData.TargetFilename =~ '''(?i)(\\\.\\PhysicalDrive|\\\.\\[A-Z]:)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1561' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '69b0415ed6b085c0752ddb318175c171';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, System.EventID.Value, System.Computer, EventData.ProcessName, EventData.ImageLoaded, EventData.Signed, EventData.Signature FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 6 AND (NOT EventData.Signed = 'true' OR EventData.ImageLoaded =~ '(?i)(disk|wipe|erase|format)' OR EventData.ProcessName =~ '''(?i)(sdelete|cipher|dd\.exe)''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1561' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '284b01830355f96bcee152d4584f528f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.DiskStructureWipe
description: |
  Detects potential disk structure wipe attempts by monitoring Sysmon driver loads,
  Security privilege escalation events, and process execution of disk utilities.
sources:
- name: SysmonDriverLoads
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image as ProcessImage,\n       EventData.ImageLoaded as DriverPath, Message\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 6 \n  AND (EventData.ImageLoaded =~ '(?i)physicaldrive|raw.*disk'\n       OR Message =~ '(?i)physicaldrive|sector.*0')\n"
- name: PrivilegeEscalation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.SubjectUserName as User,
           EventData.PrivilegeList as Privilege, EventData.ProcessName as Process
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4673
      AND EventData.PrivilegeList =~ '(?i)SeManageVolumePrivilege|SeBackupPrivilege'
- name: DiskUtilityExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image as ProcessImage,
           EventData.CommandLine as CommandLine, EventData.User as User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND (EventData.Image =~ '''(?i)(diskpart|format|dd)\.exe$'''
           OR EventData.CommandLine =~ '(?i)physicaldrive|win32_diskdrive|sector.*0')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1561.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '4011200d94cd05cacdd504322be9954a';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData, Message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 6 AND (EventData.ImageLoaded =~ '''(?i)physicaldrive|\\.*\\.*physicaldrive''' OR Message =~ '(?i)physicaldrive|raw.*disk')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1561.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '3ee16b91d1da71c4ee933d5b4597ee05';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.SessionHijacking
description: Detect RDP and remote service session hijacking by correlating authentication events with session management logs
sources:
- name: SecurityLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.TargetUserName as User, EventData.SourceNetworkAddress as SourceIP, EventData.TargetLogonId as LogonID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4624, 4648) AND EventData.LogonType = 10
- name: TerminalServicesLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData, Message
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (1149, 261, 1158)
- name: ProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.CommandLine, EventData.User, EventData.ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.Image =~ 'tscon.exe'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1563' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'c0fad505e9fdf1d1cc9790494d7ca051';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.Channel AS Channel, System.EventID.Value, EventData, Message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4648) AND EventData.LogonType = 10$orcafix$, updated_at = NOW()
WHERE t_code = 'T1563' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '495dfc926dc1e83c0517c511228a19c3';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.RDPHijacking
description: Detect RDP session hijacking through tscon.exe usage and session anomalies
sources:
- name: TsconExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.User, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.Image =~ '''tscon\.exe$'''
- name: RDPSessions
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.User, EventData.Source, EventData.SessionID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (1149, 261, 1158)
- name: SuspiciousLogons
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.LogonType, EventData.TargetUserName, EventData.IpAddress, EventData.LogonProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4624 AND int(int=EventData.LogonType) = 10
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1563.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '5b1050888139e4ddf5a1dcb2f1cd9e7b';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, UserData, EventData FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (1149, 261, 1158) AND EventData.User AND EventData.Source$orcafix$, updated_at = NOW()
WHERE t_code = 'T1563.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '668c303109689fec41606ab6e9bc9c0d';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessPath, EventData.CommandLine, EventData.User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''attrib.*\+[hs]''' OR EventData.CommandLine =~ '''chattr.*\+[ia]''' OR EventData.CommandLine =~ 'chflags.*hidden')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '1c08c23405d8229975e60ba61e7cd5d8';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime), System.Computer AS Computer, System.EventID.Value, EventData.ProcessGuid AS ProcessGuid, EventData.Image AS Image, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentImage, EventData.ParentCommandLine AS ParentCommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)attrib.*\+h''' OR EventData.CommandLine =~ '(?i)Set-ItemProperty.*Hidden' OR EventData.CommandLine =~ '(?i)chflags.*hidden')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '812768aac4bbf46e8e84d9779797f8ba';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.HiddenUsers
description: Detect hidden user account creation through registry modifications and user creation correlation
sources:
- name: UserCreationEvents
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName as Actor, EventData.SamAccountName as CreatedUser
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4720
- name: SpecialAccountsRegistry
  query: |
    SELECT OSPath, Data.value as HiddenStatus, Data.type as RegType
    FROM Artifact.Windows.Registry.NTUser()
    WHERE OSPath =~ '''SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Winlogon\\SpecialAccounts\\UserList'''
- name: RegistryModifications
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.TargetObject, EventData.Details
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value IN (13, 14) AND EventData.TargetObject =~ '''SpecialAccounts\\UserList'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'c18a4fbfd1bf27193ca0f0f6b23dd9aa';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName as Actor, EventData.SamAccountName as CreatedUser, EventData.SidHistory as UserSID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4720$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '54a8eb4e955f4c842aaa263031ab06aa';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.HiddenWindows
description: Detect hidden window techniques including PowerShell flags, registry modifications, and LOLBin abuse
sources:
- name: HiddenProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '(?i)-WindowStyle\\s+Hidden' OR EventData.CommandLine =~ '(?i)-W\\s+Hidden')
- name: RegistryWindowPositions
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.TargetObject, EventData.Details
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value IN (13,14) AND EventData.TargetObject =~ '(?i)Console.*WindowPosition'
- name: LOLBinHiddenExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.ParentImage =~ '''(?i)cmd\.exe''' AND EventData.Image =~ '''(?i)(DeviceCredentialDeployment|Utilman|Narrator)\.exe'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '88ffaa3db1ac825c42ad6a8db746fc44';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.ParentCommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)-WindowStyle\s+Hidden''' OR EventData.CommandLine =~ '''(?i)-W\s+Hidden''' OR (EventData.ParentImage =~ '''(?i)cmd\.exe''' AND EventData.Image =~ '''(?i)DeviceCredentialDeployment\.exe'''))$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'b228d5c956dc053bcdb870d9bee788cd';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.NTFS.AlternateDataStreams
description: Detect NTFS Alternate Data Streams creation and execution.
sources:
- name: SysmonADSCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           System.Computer AS Computer,
           EventData.Image AS Image,
           EventData.TargetFilename AS TargetFilename,
           EventData.Hashes AS Hashes
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 15
- name: ProcessExecutionWithADS
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           System.Computer AS Computer,
           EventData.Image AS Image,
           EventData.CommandLine AS CommandLine,
           EventData.ParentImage AS ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
      AND EventData.CommandLine =~ '.*:.*'
- name: MFTADSAnalysis
  query: |
    SELECT OSPath, Created0x10, Modified0x10, Accessed0x10, HasAds, AdsInfo
    FROM Artifact.Windows.Forensics.MFT()
    WHERE HasAds = TRUE
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '319c4cd7ef678a9aea89b2066b25b58a';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.CommandLine, EventData.TargetFilename FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '.*:.*[^:]$' AND NOT EventData.TargetFilename =~ '''.*:Zone\.Identifier$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '76dc048fb9cb564749a23dff6f8ea04c';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.HiddenFileSystem
description: Detect hidden file system usage through registry changes and raw disk access
sources:
- name: RawDiskAccess
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.ObjectName AS ObjectName, EventData.ProcessName AS ProcessName, EventData.ProcessId AS ProcessId, EventData.SubjectUserName AS SubjectUserName, EventData.AccessMask AS AccessMask\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value IN (4656, 4663, 4670) \n  AND EventData.ObjectName =~ '''(?i).*PhysicalDrive.*|.*\\\\.\\\\.*[A-Z]:.*'''\n  AND NOT (EventData.ProcessName IN ('System', 'csrss.exe', 'winlogon.exe', 'services.exe'))\n"
- name: MountRegistryChanges
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.TargetObject AS TargetObject, EventData.Details AS Details, EventData.Image AS ProcessName, EventData.ProcessId AS ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value IN (13, 14)
      AND EventData.TargetObject =~ '(?i).*MountedDevices.*|.*MountPoints.*'
- name: CurrentMountPoints
  query: |
    SELECT OSPath, Name, Data
    FROM Artifact.Windows.Registry.NTUser()
    WHERE Key =~ '(?i).*System.*MountedDevices.*'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '5246f60212b6cbc32ed914e22134da14';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, System.EventID.Value, EventData.ObjectName, EventData.ProcessName, EventData.ProcessId, EventData.SubjectUserName, EventData.AccessMask FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4656, 4663, 4670) AND EventData.ObjectName =~ '''(?i).*PhysicalDrive.*|.*\\.\\.*[A-Z]:.*''' AND NOT EventData.ProcessName IN ('System', 'csrss.exe', 'winlogon.exe', 'services.exe')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.005' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '4f3114a5bfbbc4018442cd7ab7b904a6';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.T1564_006_VirtualInstance
description: Detect hidden virtual instance execution across multiple data sources
sources:
- name: VirtualizationProcesses
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.Image AS ProcessPath, EventData.CommandLine AS CommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND EventData.Image =~ '''(?i)(VBoxManage\.exe|vmware-vmx\.exe|vmwp\.exe|VBoxHeadless\.exe)$'''
- name: ServiceInstallations
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.ServiceName AS ServiceName, EventData.ServiceType AS ServiceType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx') WHERE System.EventID.Value = 7045 AND EventData.ServiceName =~ '(?i)(VBox|VMware|Virtual)'
- name: RegistryModifications
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.ObjectName AS RegistryPath FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4657 AND EventData.ObjectName =~ '(?i)(VirtualBox|VMware)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.006' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '0692e7b5899fde0ad51ac703823f0d1e';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image AS ProcessPath, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(VBoxManage\.exe|vmware-vmx\.exe|vmwp\.exe|VBoxHeadless\.exe)$''' OR EventData.CommandLine =~ '(?i)(--type headless|--startvm|--vrde|nographic|snapshot)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.006' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'd72a950e1d4381232359f5590f092593';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: VBAStomping.Detection
description: Detect VBA Stomping through Office document analysis and process monitoring
sources:
- name: OfficeProcessExecution
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.ProcessId, EventData.Image, EventData.CommandLine, EventData.ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(winword|excel|powerpnt)\.exe$''')
- name: OfficeDocumentCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.ProcessId, EventData.Image, EventData.TargetFilename
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\.(docm|xlsm|pptm)$'''
- name: OfficeDocumentsOnDisk
  query: |
    SELECT OSPath, Size, Mtime, Atime, Ctime
    FROM glob(globs=['C:/Users/*/Documents/*.docm', 'C:/Users/*/Documents/*.xlsm', 'C:/Users/*/Documents/*.pptm', 'C:/Users/*/Downloads/*.docm', 'C:/Users/*/Downloads/*.xlsm', 'C:/Users/*/Downloads/*.pptm'])
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.007' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '1608f386f4c991ba7c0d67f5ca3d8328';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.ProcessId, EventData.Image, EventData.CommandLine, EventData.TargetFilename FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '''(?i)\.(docm|xlsm|pptm|doc|xls|ppt)$''' OR EventData.TargetFilename =~ '''(?i)vbaProject\.bin''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.007' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '56d5dc6646567ea84acb7ca2a4b93d94';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, Message, ScriptBlockText FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell/Operational.evtx') WHERE System.EventID.Value IN (4103, 4104, 4105, 4106) AND (Message =~ '(?i)(New-InboxRule|Set-InboxRule)' OR ScriptBlockText =~ '(?i)(New-InboxRule|Set-InboxRule)') AND (Message =~ '(?i)(DeleteMessage|MoveToFolder|MarkAsRead)' OR ScriptBlockText =~ '(?i)(phish|malware|suspicious|hack|alert|security)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.008' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '6034f6372d5a0521704dc9012b189b99';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.ProcessArgumentSpoofing
description: Detect process argument spoofing by correlating Security and Sysmon logs
sources:
- name: SecurityProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ProcessId AS PID, EventData.ProcessId AS PPID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND EventData.CommandLine != NULL
- name: SysmonProcessAccess
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.SourceProcessId AS SourcePID, EventData.TargetProcessId AS TargetPID, EventData.SourceImage AS SourceImage, EventData.TargetImage AS TargetImage, EventData.CallTrace AS CallTrace FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 10 AND EventData.CallTrace =~ 'WriteProcessMemory'
- name: SysmonProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp, EventData.Image AS ProcessImage, EventData.CommandLine AS CommandLine, EventData.ProcessId AS PID, EventData.ParentProcessId AS PPID, EventData.ParentImage AS ParentImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.010' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '8f4510a331396159384858cbaf916b3f';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)(svchost|explorer|winlogon|lsass)\.exe$''' OR EventData.CommandLine =~ '(?i)\\Windows\\System32\\[^\\]+\.exe$') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.CommandLine =~ '''(?i)(svchost|explorer|winlogon|lsass)\.exe$''' OR EventData.CommandLine =~ '(?i)\\Windows\\System32\\[^\\]+\.exe$') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.010' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '802bcf4218bcbcefb9dd467789041727';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.CommandLine as CommandLine, EventData.ProcessId as PID, EventData.ParentProcessId as PPID, EventData.User as User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell/Operational.evtx') WHERE System.EventID.Value IN (4103, 4104) AND EventData.CommandLine =~ '(?i).*(ErrorAction.*SilentlyContinue|ErrorAction.*Ignore|WarningAction.*SilentlyContinue).*'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.011' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '89de4a738835d736c9ad347d7207060d';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.FilePathExclusions
description: Detect file creation in AV exclusion paths correlated with process execution
sources:
- name: SysmonFileCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetFilename AS FilePath, \n       EventData.ProcessId AS PID, EventData.Image AS ProcessImage,\n       EventData.ProcessGuid AS ProcessGuid, EventData.User AS User\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.Channel = 'Microsoft-Windows-Sysmon/Operational' AND System.EventID.Value = 11\n  AND (EventData.TargetFilename =~ 'C:\\\\\\\\Windows\\\\\\\\Temp\\\\\\\\' OR \n       EventData.TargetFilename =~ 'C:\\\\\\\\ProgramData\\\\\\\\' OR\n       EventData.TargetFilename =~ '\\\\\\\\AppData\\\\\\\\Local\\\\\\\\Temp\\\\\\\\')\n  AND EventData.TargetFilename =~ '\\\\.(exe|dll|bat|ps1|vbs|scr)$'\n"
- name: SecurityObjectAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ObjectName AS ObjectPath,
           EventData.ProcessName AS ProcessName, EventData.SubjectUserName AS User,
           EventData.AccessMask AS AccessMask
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.Channel = 'Security' AND System.EventID.Value IN (4663, 4656)
      AND EventData.ObjectName =~ '(?i)(temp|programdata|appdata)'
      AND format(format='0x%x', args=EventData.AccessMask) =~ '(0x2|0x40000)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.012' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'c53e70937ed6940975e80a19ad612590';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.TargetFilename AS FilePath, EventData.ProcessId AS PID, EventData.Image AS ProcessPath, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '''C:\\Windows\\Temp\\.*\.(exe|dll|bat|ps1|vbs)$''' OR EventData.TargetFilename =~ '''C:\\ProgramData\\.*\.(exe|dll|bat|ps1|vbs)$''' OR EventData.TargetFilename =~ '''C:\\Users\\.*\\AppData\\Local\\Temp\\.*\.(exe|dll|bat|ps1|vbs)$''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1564.012' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '9f163126d9d9f1c857200bf55a9753b6';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.DataManipulationHunting
description: Detect data manipulation across file creation, timestamp changes, and security events
sources:
- name: SysmonFileCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.Image AS ProcessName, EventData.TargetFilename AS ModifiedFile, 'FileCreate' AS EventType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '(?i)\\.(mdb|accdb|sql|db|xlsx?|csv)$' OR EventData.TargetFilename =~ '(?i)(database|financial)')
- name: SysmonTimestampManipulation
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.Image AS ProcessName, EventData.TargetFilename AS ModifiedFile, EventData.CreationTime AS NewTimestamp, 'TimestampChange' AS EventType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 2
- name: SecurityFileAccess
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.ProcessName AS ProcessName, EventData.ObjectName AS AccessedFile, EventData.AccessMask AS AccessType, 'SecurityAccess' AS EventType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4663, 4656, 4670) AND EventData.ObjectName =~ '(?i)\\.(mdb|accdb|sql|db|xlsx?|csv)$'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1565' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '4c1b58497ca0a129e7c26b3e0492dd51';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.ProcessId as PID, EventData.TargetFilename as FilePath, EventData.Hashes as FileHashes FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.Channel = 'Microsoft-Windows-Sysmon/Operational' AND System.EventID.Value IN (11, 23, 15) AND EventData.TargetFilename =~ '(?i)\\.(mdb|db|sqlite|pst|ost|xlsx?|docx?)$' AND NOT EventData.Image =~ '''(?i)(outlook|msaccess|excel|winword|sqlservr)\.exe$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1565.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '7661b8f7ee8561641d861b6a608286f9';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.TransmittedDataManipulation
description: Detect potential transmitted data manipulation through network monitoring and integrity checks
sources:
- name: SuspiciousNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.ProcessId as PID, EventData.Protocol, EventData.SourceIp, EventData.SourcePort, EventData.DestinationIp, EventData.DestinationPort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND (EventData.DestinationPort IN (80, 443, 8080, 8443) OR EventData.SourcePort IN (80, 443, 8080, 8443))
    AND NOT EventData.Image =~ '''(chrome\.exe|firefox\.exe|msedge\.exe|iexplore\.exe)$'''
- name: FileIntegrityEvents
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.TargetFilename, EventData.Hash
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 15 AND EventData.TargetFilename =~ '''\\(Temp|Downloads|AppData)\\'''
- name: DNSQueries
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.QueryName, EventData.QueryResults
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 22 AND (EventData.QueryName =~ '(proxy|mitm|intercept)' OR EventData.QueryResults =~ '''^(10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.).*''')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1565.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '39b648193a8d3d6fe67b31e980c66b58';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.ProcessId as PID, EventData.Protocol, EventData.SourceIp, EventData.SourcePort, EventData.DestinationIp, EventData.DestinationPort FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (EventData.DestinationPort IN (80, 443, 8080, 8443) OR EventData.SourcePort IN (80, 443, 8080, 8443)) AND NOT EventData.Image =~ '''(chrome\.exe|firefox\.exe|msedge\.exe|iexplore\.exe)$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1565.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '8abbc808473adff48c548635fdfa4bfb';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.RuntimeDataManipulation
description: Detect runtime data manipulation through binary modification and registry changes
sources:
- name: SysmonBinaryChanges
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.Image as ProcessImage, EventData.TargetFilename as ModifiedFile, EventData.Hashes as FileHashes\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value IN (11, 15) AND (EventData.TargetFilename =~ '(?i)\\\\\\\\Program Files.*\\\\\\\\.*\\\\.(exe|dll)$' \n     OR EventData.TargetFilename =~ '(?i)\\\\\\\\Windows\\\\\\\\System32\\\\\\\\.*\\\\.(exe|dll)$')\n"
- name: RegistryFileAssociations
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.ObjectName as RegistryKey, EventData.ObjectValueName as ValueName, EventData.NewValue as NewValue\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value = 4657 AND (EventData.ObjectName =~ '(?i)HKEY_CLASSES_ROOT' \n     OR EventData.ObjectName =~ '(?i)HKEY_LOCAL_MACHINE\\\\\\\\SOFTWARE.*\\\\\\\\Classes')\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1565.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '2bd575bd48d1ae6e753692f6489acc57';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, System.EventID.Value, EventData.Image as ProcessImage, EventData.TargetFilename as ModifiedFile, EventData.Hashes as FileHashes FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value IN (11, 15) AND (EventData.TargetFilename =~ '''(?i)\\Program Files.*\\.*\.(exe|dll)$''' OR EventData.TargetFilename =~ '''(?i)\\Windows\\System32\\.*\.(exe|dll)$''')*24*60*60$orcafix$, updated_at = NOW()
WHERE t_code = 'T1565.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'df4acb82fd4e1cfea57d5c0c0b802a36';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.Phishing
description: Correlate email delivery with suspicious process execution and file creation
sources:
- name: SysmonProcessCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.CommandLine, EventData.ParentImage\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 \nAND (EventData.ParentImage =~ '''(outlook|winword|excel|powerpnt)\\.exe$''')\nAND EventData.Image =~ '''\\.(exe|scr|bat|cmd|ps1|vbs|js)$'''\n"
- name: SysmonFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetFilename, EventData.Image as CreatingProcess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11
    AND (EventData.TargetFilename =~ '''(Downloads|Desktop|AppData.*Temp).*\.(exe|scr|lnk|iso|vbs|js|zip)$''')
- name: OutlookAttachments
  query: |
    SELECT OSPath, Size, Mtime, Ctime
    FROM glob(globs=['C:/Users/*/AppData/Local/Microsoft/Windows/INetCache/Content.Outlook/**'], accessor='file')
    WHERE OSPath =~ '''\.(exe|scr|lnk|iso|vbs|js|zip|doc[mx]?|xls[mx]?|ppt[mx]?)$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1566' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'd998d9d5eb0de0c7d4be28cd2c6538c8';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.CommandLine, EventData.ParentImage, EventData.ParentCommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''outlook\.exe$''' OR EventData.ParentImage =~ '''winword\.exe$''' OR EventData.ParentImage =~ '''excel\.exe$''' OR EventData.ParentImage =~ '''powerpnt\.exe$''') AND EventData.Image =~ '''\.(exe|scr|bat|cmd|ps1|vbs|js)$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1566' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'b156a7f206a4fd54693e62fb3a9afa69';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.SpearphishingAttachment
description: Detect spearphishing attachments through email delivery correlation with suspicious process execution
imports:
- Windows.Forensics.NTFS.ZoneIdentifier
sources:
- name: SuspiciousOfficeChildProcesses
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.ParentImage AS ParentImage, EventData.CommandLine AS CommandLine\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 \n  AND EventData.ParentImage =~ '(?i)(outlook|winword|excel|powerpnt|acrord)'\n  AND EventData.Image =~ '(?i)(powershell|cmd|wscript|cscript|mshta|rundll32)'\n"
- name: AttachmentFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.Computer AS Computer, EventData.TargetFilename AS TargetFilename, EventData.ProcessId AS ProcessId, EventData.Image AS Image
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11
      AND (EventData.TargetFilename =~ '(?i)(downloads|temp|attachments)'
           OR EventData.TargetFilename =~ '''(?i)\.(exe|scr|bat|cmd|js|vbs|ps1|docm|xlsm)$''')
- name: ZoneIdentifierStreams
  query: |
    SELECT OSPath, Mtime, ZoneId, ReferrerUrl, HostUrl
    FROM Artifact.Windows.Forensics.NTFS.ZoneIdentifier()
    WHERE OSPath =~ '(?i)(downloads|temp|desktop|documents)'
      AND ZoneId IN (3, 4)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1566.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '81e6e84ccc1ebb6e19e43fe987702e86';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime), System.Computer AS Computer, System.EventID.Value, EventData.ProcessId AS ProcessId, EventData.ParentProcessId AS ParentProcessId, EventData.Image AS Image, EventData.ParentImage AS ParentImage, EventData.CommandLine AS CommandLine, EventData.ParentCommandLine AS ParentCommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '(?i)(outlook|winword|excel|powerpnt|acrobat|acrord)' AND EventData.Image =~ '(?i)(powershell|cmd|wscript|cscript|mshta|rundll32|regsvr32)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1566.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'd426fc2fe6ef3bd8aaaad86616cc839f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1566_002.SpearphishingLinkDetection
description: |
  Detects spearphishing link attacks by correlating email events with browser activity and suspicious process execution
sources:
- name: EmailWithSuspiciousLinks
  query: |
    SELECT timestamp, sender, recipient, subject, urls
    FROM source(artifact='Exchange.MessageTrace')
    WHERE urls =~ '''(?i)(bit\.ly|tinyurl|t\.co|[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3})'''
- name: BrowserLaunchedFromEmail
  query: "SELECT System.TimeCreated.SystemTime AS EventTime, \n       EventData.NewProcessName AS ProcessName,\n       EventData.ParentProcessName AS ParentProcess,\n       EventData.CommandLine AS CommandLine\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value = 4688 \n  AND EventData.ParentProcessName =~ '''(?i)(outlook|thunderbird)\\.exe$'''\n  AND EventData.NewProcessName =~ '''(?i)(chrome|firefox|msedge|iexplore)\\.exe$'''\n"
- name: SuspiciousNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.SourceIp AS SourceIp, EventData.DestinationHostname AS DestinationHostname, EventData.DestinationPort AS DestinationPort, EventData.ProcessId AS ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
      AND EventData.DestinationHostname =~ '''(?i)\.(tk|ml|ga|cf|xyz|top|click|download)$'''
      AND EventData.Image =~ '''(?i)(chrome|firefox|msedge|iexplore)\.exe$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1566.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '554b756d3f22811d962cba845e368983';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)(chrome|firefox|msedge|iexplore)\.exe$''' AND EventData.Image =~ '''(?i)(powershell|cmd|wscript|cscript)\.exe$''') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.ParentProcessName =~ '''(?i)(chrome|firefox|msedge|iexplore)\.exe$''' AND EventData.NewProcessName =~ '''(?i)(powershell|cmd|wscript|cscript)\.exe$''') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1566.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'c946b4f619010fd64691f7ed1dd9e7e8';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.SpearphishingViaService
description: Detect spearphishing via third-party services through process execution and file creation correlation
sources:
- name: SuspiciousProcessChains
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId, EventData.ParentProcessName as Parent, EventData.NewProcessName as Child, EventData.CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND EventData.ParentProcessName =~ '''(?i)(chrome|firefox|outlook|msedge)\.exe$''' AND EventData.NewProcessName =~ '''(?i)(powershell|cmd|wscript|rundll32)\.exe$'''
- name: SuspiciousFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as Process, EventData.TargetFilename as FilePath
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)(Downloads|Temp|AppData).*\.(exe|scr|bat|ps1|vbs)$'''
- name: ThirdPartyServiceConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as Process, EventData.DestinationHostname as Destination, EventData.DestinationPort as Port
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.DestinationHostname =~ '''(?i)(gmail|linkedin|dropbox|facebook|twitter)\.com$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1566.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '06acb92a6d55d42f175bc8f38a7a13e7';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)(chrome|firefox|outlook|msedge|iexplore)\.exe$''' AND EventData.Image =~ '''(?i)(powershell|cmd|wscript|cscript|rundll32)\.exe$''') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.ParentProcessName =~ '''(?i)(chrome|firefox|outlook|msedge|iexplore)\.exe$''' AND EventData.NewProcessName =~ '''(?i)(powershell|cmd|wscript|cscript|rundll32)\.exe$''') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1566.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '16ba420eba2beb41b3a435e41d0b856a';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.VishingCorrelation
description: Correlate voice phishing indicators across call logs, authentication events, and user execution
sources:
- name: AuthenticationEvents
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.TargetUserName AS Username,
           EventData.IpAddress AS SourceIP,
           EventData.LogonType AS LogonType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4624, 4625, 4648)
- name: BrowserHistory
  query: |
    SELECT url, title, visit_time,
           timestamp(winfiletime=visit_time * 1000000 + 11644473600000000) AS VisitTimestamp
    FROM sqlite(file=expand(path='%USERPROFILE%/AppData/Local/Google/Chrome/User Data/Default/History'),
                query='SELECT url, title, last_visit_time as visit_time FROM urls ORDER BY last_visit_time DESC LIMIT 1000')
    WHERE VisitTimestamp > timestamp(epoch=now() - 172800)
- name: RecentlyInstalledPrograms
  query: |
    SELECT Key.Name AS ProgramName,
           Key.ModTime AS InstallTime,
           DisplayName, Publisher, InstallDate
    FROM Artifact.Windows.Registry.NTUser(globs='SOFTWARE/Microsoft/Windows/CurrentVersion/Uninstall/*'
    WHERE Key.ModTime > timestamp(epoch=now() - 172800)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1566.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '243c8cf3d071d9205ece4454ab7bedeb';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.TargetUserName AS Username, EventData.IpAddress AS SourceIP, EventData.LogonType AS LogonType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4624 AND EventData.LogonType IN (2, 3, 10) AND timestamp(epoch=System.TimeCreated.SystemTime) > timestamp(epoch=now() - 86400)$orcafix$, updated_at = NOW()
WHERE t_code = 'T1566.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '6693d90849310b87796ed78b8a8153c0';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.T1567.ExfiltrationOverWebService
description: Detect exfiltration over web services by correlating process execution with network connections to cloud storage services
sources:
- name: ProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as PID, EventData.NewProcessName as ProcessName, EventData.CommandLine as CmdLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''(?i)(winword|excel|powershell|outlook)\.exe''' OR EventData.CommandLine =~ "(?i)(curl|wget|python)")
- name: NetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as PID, EventData.Image as ProcessName, EventData.DestinationHostname as DestHost, EventData.DestinationIp as DestIP
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.DestinationPort = 443 AND EventData.DestinationHostname =~ '''(?i)(dropbox|drive\.google|onedrive|mega\.nz|box\.com|icloud)'''
- name: FileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as PID, EventData.Image as ProcessName, EventData.TargetFilename as FilePath
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\\(temp|tmp|appdata)\\.*\.(zip|rar|7z|tar|gz)$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1567' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '87cc18f63ce1b5a0e558aa9b7c355edf';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as ProcessName, EventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort, EventData.DestinationHostname as DestHost FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.DestinationPort = 443 AND (EventData.DestinationHostname =~ '''dropbox|drive\.google|onedrive|mega\.nz|box\.com|icloud''' OR EventData.Image =~ '''(?i)(winword|excel|powershell|outlook)\.exe''') AND EventData.Initiated = "true"$orcafix$, updated_at = NOW()
WHERE t_code = 'T1567' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '4922dbb375a29cf036526ab245ab4a02';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1567_001.CodeRepositoryExfiltration
