UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.ExfiltrationToCloudStorage
description: Detect exfiltration to cloud storage services by correlating file access with network connections
sources:
- name: SensitiveFileAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, EventData.ProcessName AS ProcessName, EventData.ObjectName AS ObjectName, EventData.AccessMask AS AccessMask FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4663, 4656) AND EventData.ObjectName =~ '(?i)(Documents|Desktop|Users|ProgramData)' AND EventData.AccessMask =~ 'READ_CONTROL'
- name: CloudStorageConnections
