- name: ProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '(?i)(rclone|gsutil|aws)' OR EventData.CommandLine =~ '''(?i)(curl.*dropbox|wget.*drive\.google)''')
