UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.ProcessId AS ProcessId, EventData.Image AS Image, EventData.DestinationHostname AS DestinationHostname, EventData.DestinationPort AS DestinationPort, EventData.Protocol AS Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (EventData.DestinationHostname =~ '''pastebin\.com|hastebin\.com|ghostbin\.com|paste\.ee|dpaste\.com''' OR EventData.DestinationHostname =~ '''.*paste.*\..*''') AND EventData.DestinationPort IN (80, 443) ORDER BY timestamp DESC$orcafix$, updated_at = NOW()
