UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.WebhookExfiltration
description: |
  Detect exfiltration over webhook endpoints by correlating process execution,
  network connections, and file access events across multiple log sources.
sources:
- name: SysmonProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName,
           EventData.CommandLine, EventData.User, EventData.ProcessId,
           EventData.ParentImage, EventData.ParentCommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)(discord\.com/api/webhooks|slack\.com/api|webhook\.site|Invoke-RestMethod|Invoke-WebRequest.*-Method.*POST)'''
           OR EventData.Image =~ '''(?i)(powershell|wscript|mshta|curl)\.exe$''')
- name: SysmonNetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ProcessId,
           EventData.DestinationHostname, EventData.DestinationPort,
           EventData.Protocol
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.DestinationHostname =~ '''(?i)(discord\.com|slack\.com|webhook\.site)''' AND EventData.DestinationPort IN (443, 80)
- name: PowerShellCommandHistory
  query: |
    SELECT OSPath, read_file(filename=OSPath) as Content
    FROM glob(globs='C:/Users/*/AppData/Roaming/Microsoft/Windows/PowerShell/PSReadLine/ConsoleHost_history.txt')
    WHERE Content =~ '(?i)(Invoke-RestMethod|Invoke-WebRequest|curl).*(?:discord|slack|webhook)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1567.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '72da0e5340fabfb3ed503a64dd070e52';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessName, EventData.CommandLine, EventData.User, EventData.ProcessId, EventData.ParentImage, EventData.ParentCommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''(?i)(discord\.com/api/webhooks|slack\.com/api|webhook\.site|Invoke-RestMethod|Invoke-WebRequest.*-Method.*POST)''' OR EventData.Image =~ '''(?i)(powershell|wscript|mshta|curl)\.exe$''')$orcafix$, updated_at = NOW()
