UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.DynamicResolution
description: Detect Domain Generation Algorithm patterns and correlate DNS queries with network connections
sources:
- name: SuspiciousDNSQueries
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as PID, EventData.Image as Process, EventData.QueryName as Domain, EventData.QueryResults as IP,\nregex_replace(source=EventData.QueryName, re='[a-z0-9]', replace='x') as Pattern\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 22 \nAND len(list=EventData.QueryName) > 8\nAND EventData.QueryName =~ '''[a-z0-9]{6,}\\.[a-z]{2,10}$'''\nAND NOT EventData.QueryName =~ '(microsoft|google|amazon|cloudfront|akamai|office|windows)'\n"
- name: NetworkConnections
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as PID, EventData.Image as Process, \nEventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 3\nAND EventData.Initiated = 'true'\n"
- name: ProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as PID, EventData.Image as Process,
    EventData.ParentImage as ParentProcess, EventData.CommandLine as CmdLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1568' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '63fbcddc5bcb751a349d61f90472008e';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, EventData.Image as ProcessName, EventData.QueryName as Domain, EventData.QueryResults as ResolvedIP FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 22 AND len(str=EventData.QueryName) > 10 AND EventData.QueryName =~ '''[a-z0-9]{8,}\.[a-z]{2,10}$''' AND NOT EventData.QueryName =~ '(microsoft|google|amazon|cloudfront|akamai)' ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1568' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '8f3035689ef4f28b27d55e2a492b6991';

