UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Hunt.DGADetection
description: Hunt for Domain Generation Algorithm (DGA) activity across DNS queries and network connections
sources:
- name: SysmonDNSQueries
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.QueryName as Domain, \n       EventData.ProcessId as PID, EventData.Image as ProcessPath,\n       len(list=EventData.QueryName) as DomainLength\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 22 AND len(list=EventData.QueryName) > 15\n  AND regex(EventData.QueryName, '^[a-z0-9]{8,}\\\\.[a-z]{2,4}$')\n  AND NOT regex(EventData.QueryName, '(?:microsoft|google|amazon|mozilla|adobe)')\n"
