UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1568003.DNSCalculation
description: Detect DNS calculation technique by correlating DNS queries with subsequent network connections to calculated ports
sources:
- name: DNSQueries
  query: |
    SELECT System.TimeCreated as DNSTime, EventData.QueryName as Domain, EventData.QueryResults as ResolvedIP, EventData.ProcessId as PID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 22 AND EventData.QueryResults =~ '''^[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}$'''
- name: NetworkConnections
  query: |
    SELECT System.TimeCreated as ConnTime, EventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort, EventData.ProcessId as PID, EventData.Image as ProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND NOT (EventData.DestinationPort IN (80, 443, 53, 25, 110, 143, 993, 995))
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1568.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'ea7f8c467fbbd2d8a5fffbec7b56d6d2';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS SystemTime, EventData.QueryName as Domain, EventData.QueryResults as ResolvedIP, System.Computer as Hostname FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 22 AND EventData.QueryResults =~ '''^[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}$'''$orcafix$, updated_at = NOW()
