UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1569.SystemServices
description: Detect System Services abuse across Windows registry and event logs
sources:
- name: ServiceInstallations
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ServiceName as ServiceName,
           EventData.ServiceFileName as ImagePath, EventData.ServiceType as ServiceType,
           EventData.StartType as StartType, EventData.ServiceAccount as AccountName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4697 AND EventData.ServiceFileName
      AND NOT EventData.ServiceFileName =~ '(?i)C:\\\\Windows\\\\System32'
      AND NOT EventData.ServiceFileName =~ '(?i)C:\\\\Program Files'
- name: ServiceRegistryKeys
  query: |
    SELECT OSPath, Name, Data.value as ImagePath, Mtime
    FROM Artifact.Windows.Registry.Services()
    WHERE Name = 'ImagePath' AND Data.value
      AND NOT Data.value =~ '(?i)C:\\\\Windows\\\\System32'
      AND NOT Data.value =~ '(?i)C:\\\\Program Files'
      AND Mtime > timestamp(epoch='2024-01-01')
- name: SuspiciousProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as Image,
           EventData.CommandLine as CommandLine, EventData.ParentImage as ParentImage,
           EventData.User as User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.ParentImage =~ '''(?i)services\.exe'''
      AND NOT EventData.Image =~ '(?i)C:\\\\Windows\\\\System32'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1569' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'efcdcf341a349e2d92bc5da954948468';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ServiceName as ServiceName, EventData.ServiceFileName as ImagePath, EventData.ServiceType as ServiceType, EventData.StartType as StartType, EventData.ServiceAccount as AccountName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4697 AND EventData.ServiceFileName AND NOT EventData.ServiceFileName =~ '(?i)C:\\\\Windows\\\\System32' AND NOT EventData.ServiceFileName =~ '(?i)C:\\\\Program Files'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1569' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '7c0e93ef04a72d9af6c4307eaf1aca4f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.ServiceExecution.T1569002
description: |
  Detects malicious service execution by correlating service installations,
  process creation, and registry modifications for T1569.002.
sources:
- name: ServiceInstallations
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.ServiceName AS ServiceName,
           EventData.ServiceFileName AS ImagePath,
           EventData.ServiceType AS ServiceType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4697
- name: ServiceProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.ParentImage AS ParentImage,
           EventData.Image AS Image,
           EventData.CommandLine AS CommandLine,
           EventData.ProcessId AS ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.ParentImage =~ '''services\.exe$'''
- name: ServiceRegistryModifications
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.TargetObject AS RegistryKey,
           EventData.Details AS Value,
           EventData.EventType AS EventType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value IN (13, 14) AND EventData.TargetObject =~ '''SYSTEM\\.*ControlSet.*\\Services'''
- name: ServiceNetworkConnections
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.Image AS Image,
           EventData.DestinationIp AS DestIP,
           EventData.DestinationPort AS DestPort,
           EventData.ProcessId AS ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3 AND EventData.Image =~ '''(psexec|paexec|sc)\.exe$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1569.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '298e0598b707e15032f9842982a6307c';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.ServiceName AS ServiceName, EventData.ServiceFileName AS ImagePath, EventData.ServiceType AS ServiceType, EventData.ServiceStartType AS StartType, EventData.ServiceAccount AS Account FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4697 ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1569.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '7009cf9514bd17d66bf3825a7207c378';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.LateralToolTransfer
description: Detect lateral tool transfer via SMB shares with subsequent execution
sources:
- name: SMBShareAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName as User, EventData.ShareName as Share, EventData.RelativeTargetName as TargetFile, EventData.IpAddress as SourceIP
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 5140 AND EventData.ShareName =~ '''C\$|ADMIN\$''' AND EventData.RelativeTargetName =~ '''\.(exe|dll|bat|ps1)$'''
- name: FileCreationEvents
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as Process, EventData.TargetFilename as CreatedFile, EventData.User as User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''\.(exe|dll|bat|ps1|vbs)$''' AND EventData.TargetFilename =~ '(Temp|Public|ProgramData)'
- name: ProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ExecutedProcess, EventData.CommandLine as CommandLine, EventData.User as User, EventData.ParentImage as Parent
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.Image =~ '''(Temp|Public|ProgramData).*\.(exe|bat)$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1570' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '6b15129e45f5dbb5bf56aa9a9e35ddd4';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName as User, EventData.ShareName as Share, EventData.RelativeTargetName as TargetFile, EventData.IpAddress as SourceIP FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 5140 AND EventData.ShareName =~ '''C\$|ADMIN\$|IPC\$''' AND EventData.RelativeTargetName =~ '''\.(exe|dll|bat|ps1|vbs)$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1570' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '999d8542190d59f78cf1df112d32ed37';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.NonStandardPorts
description: Detect processes using non-standard ports for C2 communication
imports:
- Windows.EventLogs.Evtx
sources:
- name: SecurityEventLogs
  query: "SELECT System.TimeCreated.SystemTime AS Timestamp,\n       EventData.ProcessID AS PID,\n       EventData.Application AS ProcessPath,\n       EventData.Protocol,\n       EventData.DestPort,\n       EventData.DestAddress\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value IN (5156, 5157)\n  AND (EventData.DestPort IN ('8088', '587', '4444') \n       OR (EventData.DestPort > 8000 AND EventData.DestAddress NOT =~ '127.0.0.1' AND EventData.DestAddress NOT =~ '::1'))\n"
- name: SysmonNetworkConnections
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ProcessId AS PID,
           EventData.Image AS ProcessPath,
           EventData.Protocol,
           EventData.DestinationPort,
           EventData.DestinationIp
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
      AND (EventData.DestinationPort IN (8088, 587, 4444)
           OR (EventData.DestinationPort > 8000 AND EventData.Initiated = 'true'))
- name: RegistryPortChanges
  query: |
    SELECT OSPath, Data.value AS PortNumber
    FROM read_reg_key(key='HKEY_LOCAL_MACHINE/SYSTEM/CurrentControlSet/Control/Terminal Server/WinStations/RDP-Tcp/*')
    WHERE Name = 'PortNumber' AND Data.value != 3389
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1571' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '2c7d0fd4d44bbd1006bb5b1d86b72ed7';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, EventData.ProcessID AS PID, EventData.Application AS ProcessPath, EventData.Protocol, EventData.DestPort, EventData.DestAddress, EventData.SourcePort FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 5156 AND (EventData.DestPort = '8088' OR EventData.DestPort = '587' OR EventData.DestPort = '4444' OR (EventData.DestPort > 8000 AND NOT (EventData.DestAddress IN ('127.0.0.1', '::1'))))$orcafix$, updated_at = NOW()
WHERE t_code = 'T1571' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'c6821e64e41ca663cf438c72766d67d0';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Protocol.Tunneling.Detection
description: Detect protocol tunneling through process execution and network connections
sources:
- name: TunnelingProcesses
  query: |
    SELECT System.TimeCreated.SystemTime as EventTime, EventData.ProcessId as PID, EventData.Image as Image, EventData.CommandLine as CommandLine, EventData.ParentImage as ParentImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(plink|ssh|netsh|chisel|ligolo|socat)\.exe$''' OR EventData.CommandLine =~ '(?i)(-L|-R|-D|portproxy|tunnel|forward)')
- name: SuspiciousConnections
  query: |
    SELECT System.TimeCreated.SystemTime as EventTime, EventData.ProcessId as PID, EventData.Image as Image, EventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort, EventData.Protocol as Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.Initiated = 'true' AND (EventData.DestinationPort IN (22,443,80,53) OR EventData.Image =~ '''(?i)(plink|ssh|netsh)\.exe$''')
- name: DNSQueries
  query: |
    SELECT System.TimeCreated.SystemTime as EventTime, EventData.ProcessId as PID, EventData.Image as Image, EventData.QueryName as QueryName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 22 AND (len(list=EventData.QueryName) > 50 OR EventData.QueryName =~ '''(?i)(cloudflare-dns|dns\.google|quad9)''')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1572' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '378f9013226f5824ee6b7fd6827d425d';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) as EventTime, EventData.ProcessId as PID, EventData.Image as ProcessName, EventData.CommandLine as CmdLine, EventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort, EventData.Protocol as Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (EventData.Image =~ '''(?i)(plink|ssh|netsh|chisel|socat)\.exe$''' OR EventData.CommandLine =~ '(?i)(-L|-R|-D|portproxy|tunnel)') AND EventData.Initiated = 'true'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1572' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '93268d63fdcb4b4794cf371cf092e6b8';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.EncryptedChannel
description: Detect processes establishing encrypted channels through TLS/SSL analysis
sources:
- name: SysmonNetworkConnections
  query: "SELECT System.TimeCreated.SystemTime AS Timestamp,\n       EventData.ProcessId, EventData.Image, EventData.DestinationIp,\n       EventData.DestinationPort, EventData.Protocol\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 3 \n  AND EventData.DestinationPort IN (443, 993, 995, 8443, 4444)\n  AND NOT EventData.Image =~ '''(?i)(chrome\\.exe|firefox\\.exe|outlook\\.exe|iexplore\\.exe)$'''\n"
- name: SysmonImageLoads
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ProcessId, EventData.Image, EventData.ImageLoaded
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7
      AND EventData.ImageLoaded =~ '''(?i)(ssleay32\.dll|libeay32\.dll|bcrypt\.dll|schannel\.dll)'''
      AND NOT EventData.Image =~ '''(?i)(svchost\.exe|chrome\.exe|firefox\.exe)$'''
- name: SysmonDNSQueries
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ProcessId, EventData.Image, EventData.QueryName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 22
      AND EventData.QueryName =~ '''(?i)(dns\.google|cloudflare-dns\.com|quad9\.net)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1573' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '6681c187a1b86945bcfe02dfded4b7e7';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, EventData.ProcessId, EventData.Image, EventData.DestinationIp, EventData.DestinationPort, EventData.Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.DestinationPort IN (443, 993, 995, 8443, 4444) AND NOT EventData.Image =~ '''(?i)(chrome\.exe|firefox\.exe|outlook\.exe|iexplore\.exe|msedge\.exe)$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1573' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'da1744c25dde5b925a3addfdcc6c12c4';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.SymmetricCrypto.Detection
description: Detect processes loading crypto libraries and making network connections for T1573.001
sources:
- name: CryptoLibraryLoads
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as Process, EventData.ImageLoaded as CryptoDLL, EventData.ProcessId as PID, EventData.ProcessGuid as ProcessGuid\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 7 \nAND EventData.ImageLoaded =~ '''(?i)(bcryptprimitives\\.dll|aes\\.dll|advapi32\\.dll|kernel32\\.dll)'''\nAND NOT EventData.Image =~ '''(?i)(svchost\\.exe|explorer\\.exe|chrome\\.exe|firefox\\.exe|teams\\.exe|outlook\\.exe)'''\n"
- name: NetworkConnections
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as Process, EventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort, EventData.ProcessId as PID, EventData.ProcessGuid as ProcessGuid\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 3\nAND EventData.Initiated = 'true'\nAND NOT EventData.DestinationIp =~ '''^(10\\.|172\\.(1[6-9]|2[0-9]|3[01])\\.|192\\.168\\.|127\\.)'''\n"
- name: ProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as Process, EventData.CommandLine as CmdLine, EventData.ProcessId as PID, EventData.ProcessGuid as ProcessGuid, EventData.ParentImage as Parent
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1
    AND (EventData.CommandLine =~ '(?i)(aes|rc4|3des|blowfish|encrypt|crypto)'
    OR EventData.Image =~ '''(?i)(powershell|python|wscript|cscript)\.exe''')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1573.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'e663c79986dbfd8f2e3f481a5344bc6f';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as Process, EventData.ImageLoaded as LoadedDLL, EventData.ProcessId as PID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND (EventData.ImageLoaded =~ '''(?i)(bcryptprimitives\.dll|aes\.dll|advapi32\.dll)''' AND NOT EventData.Image =~ '''(?i)(svchost\.exe|explorer\.exe|chrome\.exe|firefox\.exe|winlogon\.exe)''') ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1573.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '0ec50713b32f772fa11f7175a295fc22';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: T1573_002_AsymmetricCrypto_Detection
description: Detect asymmetric cryptography usage for C2 by correlating crypto library loads with network connections
sources:
- name: CryptoLibraryLoads
  query: "SELECT System.TimeCreated.SystemTime as Timestamp, EventData.ProcessId as PID, EventData.Image as ProcessPath, EventData.ImageLoaded as CryptoDLL\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 7 \nAND (EventData.ImageLoaded =~ 'rsaenh.dll' OR EventData.ImageLoaded =~ 'crypt32.dll' OR EventData.ImageLoaded =~ 'bcrypt.dll')\nAND NOT (EventData.Image =~ 'chrome.exe' OR EventData.Image =~ 'firefox.exe' OR EventData.Image =~ 'outlook.exe')\n"
- name: NetworkConnections
  query: "SELECT System.TimeCreated.SystemTime as Timestamp, EventData.ProcessId as PID, EventData.Image as ProcessPath, \n       EventData.DestinationIp as DestIP, EventData.DestinationPort as DestPort, EventData.Protocol as Protocol\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 3 AND EventData.DestinationPort IN (443, 993, 995, 465)\nAND EventData.DestinationIp =~ '''^[0-9]+\\.[0-9]+\\.[0-9]+\\.[0-9]+$'''\n"
- name: CertificateStoreArtifacts
  query: |
    SELECT OSPath, Data.subject as Subject, Data.issuer as Issuer, Data.not_before as NotBefore, Data.not_after as NotAfter
    FROM Artifact.Windows.Registry.Certificates()
    WHERE Data.subject =~ '[A-Fa-f0-9]{8,}' OR Data.issuer = Data.subject
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1573.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '6aa84f6a2e65f5dde68d1176f3ef5c66';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.HijackExecutionFlow
description: Detect execution flow hijacking through DLL hijacking, service path modification, and suspicious process execution
sources:
- name: SuspiciousDLLLoads
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ImageLoaded, EventData.ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7 AND (EventData.ImageLoaded =~ '(?i).*\\\\(temp|users|appdata)\\\\.*\\.dll$' OR EventData.ImageLoaded =~ '(?i).*\\\\windows\\\\[^\\\\]*\\.dll$')
- name: ServicePathModifications
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ObjectName, EventData.NewValue, EventData.ProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4657 AND EventData.ObjectName =~ 'MACHINE\\\\SYSTEM\\\\.*Services\\\\.*\\\\ImagePath'
- name: SuspiciousFileCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.TargetFilename, EventData.ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '(?i).*\\\\\\\\(system32|syswow64|program files)\\\\\\\\.*\\\\\\\\[^\\\\\\\\]*\\\\\\\\[^\\\\\\\\]*\\\\\\\\.*\\\\\\\\(dll|exe)$' OR EventData.TargetFilename =~ '(?i).*\\\\\\\\windows\\\\\\\\[^\\\\\\\\]*\\\\\\\\.*\\\\\\\\(dll|exe)$')\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1574' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '45e0f892ca5eefec8a38e1e792933639';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ImageLoaded, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND (EventData.ImageLoaded =~ '''(?i).*\\(temp|users|appdata|programdata)\\.*\.(dll|exe)$''' OR NOT EventData.ImageLoaded =~ '(?i).*(system32|syswow64|program files).*')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1574' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'd5be2d2b7f1807cff779027e75c5aa94';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image AS ProcessPath, EventData.ImageLoaded AS DLLPath, EventData.Signed AS IsSigned, EventData.Company AS Company, EventData.Product AS Product FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND (EventData.ImageLoaded =~ '(?i)^(?!C:\\Windows\\(System32|SysWOW64)).*\.dll$' OR EventData.Signed = 'false') AND EventData.ImageLoaded =~ '''(?i)\.(dll)$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1574.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '442d60b1499d94e23951e0d24008821f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.T1574_005_InstallerHijack
description: Detect executable installer file permissions weakness exploitation
sources:
- name: SuspiciousProcessCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, \n       EventData.ParentImage as ParentImage, EventData.CommandLine as CommandLine,\n       EventData.User as User, EventData.IntegrityLevel as IntegrityLevel\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') \nWHERE System.EventID.Value = 1 AND (ProcessImage =~ '(?i).*\\\\\\\\temp\\\\\\\\.*\\\\.(exe|dll)$' OR ProcessImage =~ '(?i).*\\\\\\\\programdata\\\\\\\\.*\\\\.(exe|dll)$')\n  AND (ParentImage =~ '(?i).*(install|setup|update).*\\\\.exe$' OR IntegrityLevel =~ '(?i)high|system')\n"
- name: FileCreationInTempDirs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetFilename as FilePath,
           EventData.Image as WritingProcess, EventData.User as User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '(?i).*\\\\temp\\\\.*\\.(exe|dll)$'
- name: ModuleLoadsFromTemp
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ImageLoaded as ModulePath,
           EventData.Image as ProcessImage, EventData.User as User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7 AND EventData.ImageLoaded =~ '(?i).*\\\\temp\\\\.*\\.(exe|dll)$'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1574.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '87e7e1ae90206a5184104de3b39408b9';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ProcessImage, EventData.ParentImage as ParentImage, EventData.CommandLine as CommandLine, EventData.User as User, EventData.IntegrityLevel as IntegrityLevel FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (ProcessImage =~ '''(?i).*\\temp\\.*\.(exe|dll)$''' OR ProcessImage =~ '''(?i).*\\programdata\\.*\.(exe|dll)$''') AND (ParentImage =~ '''(?i).*(install|setup|update).*\.exe$''' OR IntegrityLevel =~ '(?i)high|system')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1574.005' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '88b1608e5763748fed4430fba60ed3e3';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.PathInterceptionHunt
description: Detect PATH environment variable hijacking through registry monitoring and suspicious process execution correlation
sources:
- name: PathRegistryModifications
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, SecurityID, EventData.ObjectName AS ObjectName, EventData.ProcessName AS ProcessName, EventData.NewValue AS NewValue, EventData.OldValue AS OldValue
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4657 AND EventData.ObjectName =~ '(?i)environment' AND (ObjectValueName = 'PATH' OR ObjectValueName = 'Path')
- name: SuspiciousProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image AS Image, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentImage, EventData.CurrentDirectory AS CurrentDirectory
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.Image =~ '(?i)temp|users|appdata' OR EventData.CurrentDirectory =~ '(?i)temp|users|appdata') AND (EventData.Image =~ '''(?i)(net|powershell|python|cmd|wmic|netsh)\.exe$''')
- name: SuspiciousFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetFilename AS TargetFilename, EventData.Image as ProcessImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)(temp|users|appdata).*\\(net|powershell|python|cmd|wmic|netsh)\.exe$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1574.007' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '4ee8928d5e765c9e6c831e41870ca768';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, SecurityID, EventData.ObjectName AS ObjectName, EventData.HandleId AS HandleId, EventData.ProcessName AS ProcessName, EventData.NewValue AS NewValue, EventData.OldValue AS OldValue FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4657 AND EventData.ObjectName =~ '(?i)environment' AND (ObjectValueName = 'PATH' OR ObjectValueName = 'Path')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1574.007' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'cd4d55508fc1705471a5594da6fdd050';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.PathInterceptionHijacking
description: Detects path interception by search order hijacking through correlation of file creation and process execution events
sources:
- name: SuspiciousProcessExecution
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.Computer AS Computer, EventData.Image as ProcessPath, EventData.CommandLine, EventData.ParentImage, EventData.ProcessGuid, EventData.ParentProcessGuid\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 \nAND EventData.Image =~ '''(?i)\\\\(net|cmd|powershell|python|findstr|whoami|ipconfig|tasklist|systeminfo)\\.exe$'''\nAND NOT EventData.Image =~ '(?i)(system32|syswow64)'\n"
- name: SuspiciousFileCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.Computer AS Computer, EventData.TargetFilename, EventData.ProcessGuid, EventData.Image as CreatingProcess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11
    AND EventData.TargetFilename =~ '''(?i)(net|cmd|powershell|python|findstr|whoami|ipconfig|tasklist|systeminfo)\.exe$'''
    AND NOT EventData.TargetFilename =~ '(?i)(system32|syswow64)'
- name: PathExtEnvironment
  query: |
    SELECT Key.OSPath, Key.ModTime, ValueName, ValueData.value as PathExtValue
    FROM read_reg_key(key='Environment')
    WHERE ValueName = 'PATHEXT' OR ValueName = 'PATH'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1574.008' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '19678fb21a26d8086e22746495edc817';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime), System.Computer AS Computer, EventData.Image as ProcessPath, EventData.CommandLine, EventData.ParentImage, EventData.ProcessGuid FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)\\(net|cmd|powershell|python|findstr|whoami|ipconfig)\.exe$''' AND NOT EventData.Image =~ '(?i)(system32|syswow64)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1574.008' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '354364b99aafb784cda576f55651697d';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.UnquotedPathInterception
description: Detects path interception via unquoted service paths and suspicious executable placement
sources:
- name: UnquotedServicePaths
  query: |
    SELECT Key.Name AS ServiceName, Key.Data.value AS ImagePath, Key.Mtime AS LastModified FROM glob(globs='HKEY_LOCAL_MACHINE/SYSTEM/CurrentControlSet/Services/*/ImagePath', accessor='registry') WHERE ImagePath =~ '''[a-zA-Z]:\\.*\s+.*\.exe''' AND NOT ImagePath =~ '^".*"$'
- name: SuspiciousExecutableCreation
  query: |
    SELECT System.TimeCreated, EventData.TargetFilename, EventData.ProcessId, EventData.Image FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''[a-zA-Z]:\\[^\\]*\.exe$''' AND EventData.TargetFilename =~ '''(program|microsoft|windows|system|service)\.exe$'''
- name: InterceptedProcessExecution
  query: |
    SELECT System.TimeCreated, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''^[a-zA-Z]:\\[^\\]+\.exe$''' OR EventData.Image =~ '''^[a-zA-Z]:\\Program Files\\[^\\]+\.exe$''')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1574.009' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'd4228b561acd910c28d51fc5e2f7123f';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated, System.EventID.Value, EventData.ObjectName, EventData.NewValue, EventData.ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4657 AND EventData.ObjectName =~ 'Services' AND EventData.NewValue =~ '''[a-zA-Z]:\\.*\s+.*\.exe''' AND NOT EventData.NewValue =~ '^".*"$'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1574.009' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '3fda18bf4179bed6fcbfdc9d576e2f16';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime), System.Computer, System.EventID.Value, System.Channel AS Channel, EventData.Image as ServiceExecutable, EventData.Hashes as FileHashes, EventData.TargetFilename as FilePath FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value IN (11,15) AND (EventData.TargetFilename =~ '''(?i)\\system32\\.*\.exe$''' OR EventData.TargetFilename =~ '''(?i)\\program files\\.*\.exe$''' OR EventData.TargetFilename =~ '(?i)service')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1574.010' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'a00b9edc4e82856f1b5dd746d88f4dfa';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.ServiceRegistryHijack
description: Detect service registry hijacking through permissions weakness
sources:
- name: RegistryModifications
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.ObjectName as RegistryPath, EventData.ObjectValueName as ValueName, EventData.NewValue as NewValue, EventData.SubjectUserName as User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4657 AND EventData.ObjectName =~ "HKLM\\\\SYSTEM\\\\CurrentControlSet\\\\Services"
    AND (EventData.ObjectValueName IN ("ImagePath", "ServiceDll", "FailureCommand", "AutodialDLL") OR EventData.ObjectName =~ "Parameters|Performance")
- name: ServiceStateChanges
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.param1 as ServiceName, EventData.param2 as NewState
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx')
    WHERE System.EventID.Value IN (7036, 7040)
- name: SuspiciousProcesses
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.Image, EventData.CommandLine, EventData.ParentImage
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ "services.exe" OR EventData.Image =~ "temp|programdata|users")
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1574.011' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '8a06e7b2256fa28749e8786e4c23aae0';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, EventData.ObjectName as RegistryPath, EventData.ObjectValueName as ValueName, EventData.NewValue as NewValue, EventData.SubjectUserName as User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4657 AND EventData.ObjectName =~ "HKLM\\\\SYSTEM\\\\CurrentControlSet\\\\Services" AND (EventData.ObjectValueName = "ImagePath" OR EventData.ObjectValueName = "ServiceDll" OR EventData.ObjectValueName = "FailureCommand" OR EventData.ObjectName =~ "Parameters|Performance")$orcafix$, updated_at = NOW()
WHERE t_code = 'T1574.011' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '21f5743d5dc7d30342197530ff087845';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image, EventData.ImageLoaded, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND (EventData.Image =~ '(?i)(dotnet|aspnet|w3wp|msbuild)' OR EventData.Image =~ '''(?i)\.net''') AND EventData.ImageLoaded =~ '''(?i)\.(dll)$''' AND NOT EventData.ImageLoaded =~ '(?i)(microsoft|system32|program files)'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1574.012' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '93989780c73e969e5d9a55c50b92cbc8';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.AppDomainManagerHijack
description: Detect AppDomainManager hijacking via configuration tampering and assembly loading
sources:
- name: SuspiciousAssemblyLoads
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.Image, EventData.ProcessId, EventData.ImageLoaded, EventData.Hashes, EventData.Signed FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND EventData.Image =~ '''(?i)(w3wp|powershell|svchost)\.exe''' AND (EventData.ImageLoaded =~ '''(?i)(temp|appdata|programdata).*\.dll$''' OR EventData.Signed = 'false')
- name: ConfigFileModifications
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.TargetFilename, EventData.Image, EventData.ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND EventData.TargetFilename =~ '''(?i)\.config$''' AND EventData.TargetFilename =~ '(?i)(program files|system32|windows)'
- name: DotNetProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.NewProcessName, EventData.CommandLine, EventData.ParentProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND EventData.NewProcessName =~ '''(?i)(w3wp|powershell|svchost)\.exe''' AND EventData.CommandLine =~ '(?i)(appdomain|config)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1574.014' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'bcb504b07d457b38e3e8a8344ae54655';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image, EventData.ProcessId, EventData.ImageLoaded, EventData.Hashes FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 7 AND (EventData.Image =~ '''(?i)(w3wp|powershell|svchost)\.exe''' AND EventData.ImageLoaded =~ '''(?i)\.dll$''' AND EventData.ImageLoaded =~ '(?i)(temp|appdata|programdata)' OR EventData.ImageLoaded =~ '(?i)appdomain')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1574.014' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '4e215120210c8081a26dede17c78d6b2';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Acquire_Infrastructure_Detection
description: Detect adversary infrastructure acquisition through DNS queries and network connections
sources:
- name: Suspicious_DNS_Queries
  query: |
    SELECT timestamp(epoch=winlog.TimeCreated.SystemTime) AS Timestamp,
           winlog.EventData.QueryName AS Domain,
           winlog.EventData.QueryType AS QueryType,
           winlog.EventData.QueryResults AS Results
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE winlog.System.EventID = 3008
      AND winlog.EventData.QueryName =~ '''(?i)\.(tk|ml|ga|cf|gq)$|[0-9]{1,3}-[0-9]{1,3}-[0-9]{1,3}-[0-9]{1,3}\.'''
      AND timestamp(epoch=winlog.TimeCreated.SystemTime) > now() - 604800
- name: Network_Connections_C2
  query: |
    SELECT timestamp(epoch=winlog.TimeCreated.SystemTime) AS Timestamp,
           winlog.EventData.SourceIp AS SourceIP,
           winlog.EventData.DestinationIp AS DestIP,
           winlog.EventData.DestinationPort AS DestPort,
           winlog.EventData.ProcessId AS PID,
           winlog.EventData.Image AS ProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE winlog.System.EventID = 3
      AND winlog.EventData.DestinationPort IN ('8080', '8443', '9999', '4444', '5555')
      AND NOT winlog.EventData.DestinationIp =~ '''^(10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01]))'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1583' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'fca9f4723aa9805401479650bcbcb197';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=winlog.TimeCreated.SystemTime) AS SystemTime, winlog.EventData.QueryName AS Domain, winlog.EventData.QueryType AS QueryType, winlog.EventData.QueryResults AS Results FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client/Operational.evtx') WHERE winlog.System.EventID.Value = 3008 AND winlog.EventData.QueryName =~ '''(?i)\.(tk|ml|ga|cf|gq)$|[0-9]{1,3}-[0-9]{1,3}-[0-9]{1,3}-[0-9]{1,3}\.''' AND timestamp(epoch=winlog.TimeCreated.SystemTime) > now() - 86400$orcafix$, updated_at = NOW()
WHERE t_code = 'T1583' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'd00d7792129500a9ca33f6298fd8a5b1';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: T1583_001_Domain_Infrastructure_Analysis
description: Detect adversary domain acquisition through DNS analysis and browser artifacts
sources:
- name: DNS_Resolution_Events
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeStamp, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.QueryName as Domain, EventData.QueryType, EventData.QueryResults\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client%4Operational.evtx') \nWHERE System.Channel = 'DNS Client Events' AND System.EventID.Value IN (3008, 3020)\n"
- name: Browser_Domain_History
  query: |
    SELECT url, title, visit_count, last_visit_time, typed_count
    FROM glob(globs='C:/Users/*/AppData/Local/Google/Chrome/User Data/*/History')
    WHERE url =~ '^https?://[^/]+' AND last_visit_time > now() - 7*24*3600
- name: DNS_Cache_Analysis
  query: |
    SELECT Name, Data, Type, TimeToLive
    FROM Artifact.Windows.Registry.DNSCache()
    WHERE Name =~ '''(?i)\.(com|net|org|info|biz)$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1583.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'bf48cc0a55831824a90f1419b2615c0b';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeStamp, System.Computer AS Computer, System.EventID.Value, EventData, Message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx') WHERE System.Channel = 'DNS Client Events' AND System.EventID.Value IN (3008, 3020) AND EventData =~ '(?i)(recently|suspicious|domain|resolution)'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1583.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'e451837176101387923c614af3c38e74';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1583_002.DNSServer
description: Detect DNS server acquisition and configuration changes
sources:
- name: DNSServerEvents
  query: |
    SELECT System.TimeCreated.SystemTime as Timestamp, System.EventID.Value as EventID, System.Computer as Computer, EventData.Data as EventData FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (2, 4013, 6527, 770)
- name: DNSRegistryConfig
  query: |
    SELECT OSPath, Name, Data.value as Value, Data.type as Type FROM Artifact.Windows.Registry.Glob(globs='HKEY_LOCAL_MACHINE/SYSTEM/CurrentControlSet/Services/DNS/**') WHERE Name =~ '(ServerLevelPluginDll|ForwardDelegations|Forwarders)'
- name: NetworkDNSConfig
  query: |
    SELECT OSPath, Name, Data.value as DNSServers FROM Artifact.Windows.Registry.Glob(globs='HKEY_LOCAL_MACHINE/SYSTEM/CurrentControlSet/Services/Tcpip/Parameters/Interfaces/*/NameServer')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1583.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '1c26bfb2b282a2ad3e7d4b391faaef44';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: VPS_Infrastructure_Detection
description: Detect connections and artifacts related to VPS acquisition and usage
imports:
- Windows.Forensics.Chrome
sources:
- name: Network_Connections
  query: |
    SELECT System.TimeCreated.SystemTime as EventTime, EventData.DestAddress as RemoteIP, EventData.ProcessName as Process
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 5156 AND EventData.Direction = 'Outbound'
- name: DNS_Queries
  query: |
    SELECT System.TimeCreated.SystemTime as EventTime, EventData.QueryName as Domain, EventData.QueryType as Type
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client%4Operational.evtx')
    WHERE System.EventID.Value = 3008 AND (EventData.QueryName =~ '(?i)(vultr|digitalocean|linode|aws|azure|ovh)'
- name: Browser_History
  query: |
    SELECT Timestamp, URL, Title, VisitCount
    FROM glob(globs='C:/Users/*/AppData/Local/Google/Chrome/User Data/*/History')
    WHERE URL =~ '(?i)(vps|hosting|cloud|server|infrastructure)'
$orcafix$, updated_at = NOW()
