UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Hunt.WebServiceInfrastructure
description: Detect adversary use of legitimate web services as infrastructure
sources:
- name: ProxyLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, src_ip, dest_host, url, user_agent, bytes_out
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE dest_host =~ '''(?i)(github|pastebin|dropbox|discord|telegram)\.(com|org)'''
    AND (bytes_out > 1024 OR user_agent =~ '(?i)(curl|wget|powershell)')
- name: DNSQueries
  query: |
    SELECT timestamp, query_name, query_type, response
    FROM Artifact.Windows.EventLogs.DNS
    WHERE query_name =~ '''(?i)(raw\.githubusercontent|cdn\.discordapp|api\.(github|dropbox))'''
- name: BrowserActivity
  query: |
    SELECT url, title, visit_count, last_visit_time
    FROM glob(globs='C:/Users/*/AppData/Local/Google/Chrome/User Data/*/History')(github\.com.*\.txt|pastebin\.com|discord\.com/api)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1583.006' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'eb524d946da62cc044b1565766dfc5ef';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS TimeCreated, EventData.SourceIp AS SourceIP, EventData.DestAddress AS DestIP, EventData.DestPort AS DestPort FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND (EventData.DestinationHostname =~ '''(?i)(github\.com|dropbox\.com|drive\.google\.com|pastebin\.com|discord\.com)''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1583.006' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '9a398d34ec34b5fe2e5533370a64061e';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Hunt.T1583_007.ServerlessInfrastructure
description: Detect acquisition and use of serverless infrastructure for C2
imports:
- Windows.Forensics.Chrome.History
sources:
- name: PowerShellServerlessCommands
  query: |
    SELECT System.TimeStamp as Timestamp, EventData.ProcessId, EventData.ScriptBlockText as Command FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx') WHERE System.EventID.Value = 4104 AND EventData.ScriptBlockText =~ '''(?i)(aws\s+lambda|gcloud\s+functions|wrangler\s+deploy|workers\.dev|lambda-url.*\.on\.aws|cloudfunctions\.net)'''
- name: BrowserServerlessActivity
  query: |
    SELECT Timestamp, URL, Title FROM glob(globs='C:/Users/*/AppData/Local/Google/Chrome/User Data/*/History') WHERE URL =~ '''(?i)(workers\.cloudflare\.com|console\.aws\.amazon\.com/lambda|console\.cloud\.google\.com/functions|.*\.workers\.dev|.*\.lambda-url\..*\.on\.aws|.*\.cloudfunctions\.net)'''
- name: ServerlessConfigFiles
  query: |
    SELECT OSPath, Size, Mtime, Atime FROM glob(globs=['C:/Users/*/wrangler.toml', 'C:/Users/*/.aws/config', 'C:/Users/*/.aws/credentials', 'C:/Users/*/serverless.yml']) WHERE log(message='Found serverless config: ' + OSPath)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1583.007' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '648ab1ce2c3313274153b44852047582';

