WHERE t_code = 'T1583.007' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '00fdb611b3c9dc318dc5947ea9a96b07';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Malvertising.Investigation
description: Collect malvertising-related artifacts including browser history, DNS logs, and suspicious downloads
sources:
- name: BrowserHistory
  query: |
    SELECT url, title, visit_count, last_visit_time
    FROM glob(globs='C:/Users/*/AppData/Local/Google/Chrome/User Data/*/History')
    WHERE url =~ '(?i)(ads|advertisement|adnxs|doubleclick|googlesyndication)'
    OR title =~ '(?i)(download|software|free|crack|keygen)'
- name: DNSLogs
  query: |
    SELECT System.TimeCreated.SystemTime AS timestamp, EventData.QueryName, EventData.QueryType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client%4Operational.evtx')
    WHERE System.EventID.Value = 3008
    AND EventData.QueryName =~ '(?i)(ads|advertisement|adnxs|doubleclick)'
- name: SuspiciousDownloads
  query: |
    SELECT OSPath, Size, Mtime, Atime, Ctime
    FROM glob(globs='C:/Users/*/Downloads/*', 'C:/Windows/Temp/*')
    WHERE OSPath =~ '(?i)/(downloads|temp|appdata)/.*(exe|msi|zip|rar)$'
    AND Mtime > now() - 604800
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1583.008' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '2cc2ac0f7a08b160441ff4f9fdf38bab';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT Fqdn, timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, ProcessName, ProcessId FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client/Operational.evtx') WHERE System.EventID.Value = 3008 AND EventData.QueryName =~ '(?i)(ads|advertisement|adnxs|doubleclick|googlesyndication)'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1583.008' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'ec9054e22512d6f8e0909b4b8555915c';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: CompromisedInfrastructureDetection
description: Detect connections and DNS queries to compromised infrastructure
sources:
- name: DNSQueries
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, \n       get(field=EventData, member='QueryName') AS QueryName,\n       get(field=EventData, member='QueryResults') AS QueryResults\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client%4Operational.evtx')\nWHERE System.EventID.Value = 3008\n"
- name: NetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId AS ProcessId,
           EventData.Image AS Image, EventData.DestinationIp AS DestIP,
           EventData.DestinationPort AS DestPort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 3
- name: SSLCertificates
  query: |
    SELECT OSPath, ModTime, Size
    FROM glob(globs=['C:/Users/*/AppData/Roaming/Microsoft/SystemCertificates/**/*.crt',
                     'C:/Users/*/AppData/Local/Google/Chrome/User Data/**/Certificates/**'])
    WHERE ModTime > now() - 604800
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1584' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '46e090793badec617453e04a3f4c7dfc';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, Message, EventData FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client%4Operational.evtx') WHERE System.EventID.Value IN (3008, 3020) AND Message =~ '''(?i)(suspicious_domain\.com|known_compromised_ip)'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1584' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '820524b63e6788e431b8e4df6254372c';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.DomainHijackingIndicators
description: Detect indicators of domain hijacking and suspicious DNS activity
sources:
- name: DNSClientLogs
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, \n       EventData.QueryName as Domain,\n       EventData.QueryResults as Resolution,\n       EventData.QueryType as Type\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client%4Operational.evtx')\nWHERE System.Channel = 'Microsoft-Windows-DNS-Client/Operational' AND System.EventID.Value IN (3008, 3006, 3020)\n"
- name: NetworkConfig
  query: |
    SELECT Key.OSPath as RegistryPath,
           Key.ModTime as LastModified,
           Data.value as DNSServers
    FROM Artifact.Windows.Registry.NTUser()
    WHERE Key.OSPath =~ 'HKEY_LOCAL_MACHINE/SYSTEM/.*/Services/Tcpip/Parameters'
      AND Data.name IN ('NameServer', 'DhcpNameServer')
- name: BrowserDNSCache
  query: |
    SELECT OSPath, Mtime, Size
    FROM glob(globs=[
      'C:/Users/*/AppData/Local/Google/Chrome/User Data/Default/History',
      'C:/Users/*/AppData/Local/Microsoft/Edge/User Data/Default/History'
    ])
    WHERE Mtime > now() - 2592000
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1584.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'cb1b9c946f0c59fe7c76132d155c2916';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.Channel AS Channel, System.EventID.Value, EventData.QueryName as QueryName, EventData.QueryType as QueryType, EventData.QueryResults as QueryResults FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client%4Operational.evtx') WHERE System.Channel = 'Microsoft-Windows-DNS-Client/Operational' AND (System.EventID.Value = 3008 OR System.EventID.Value = 3006 OR System.EventID.Value = 3020) AND QueryName =~ '''(?i)(suspicious|temp|[0-9a-f]{8,}\.)''' ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1584.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'bc8a8f3403a3703db50cefc3f6bbaec3';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.QueryName as Domain, EventData.QueryType as RecordType, EventData.QueryResults as IPAddress FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client/Operational.evtx') WHERE System.EventID.Value = 3008 AND (EventData.QueryName =~ '(?i)(suspicious|known_bad_domains)' OR EventData.QueryResults =~ '^(?!10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.).*')$orcafix$, updated_at = NOW()
