UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime), System.Computer AS Computer, System.EventID.Value, EventData, Message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4625, 4648) AND EventData.LogonType = 3 AND EventData.IpAddress =~ '^(?!10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[0-1])\.).*' AND EventData.ProcessName != 'winlogon.exe'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1584.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '1c436b25daa9dcc17228de77afb5bb36';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Server.Compromise.Detection
description: Detect indicators of compromised servers used for adversary infrastructure
sources:
- name: SuspiciousProcesses
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '(?i)(socat|chisel|ngrok|frp|plink)' OR EventData.CommandLine =~ '(?i)(tunnel|proxy|relay|webshell)')
- name: WebShells
  query: |
    SELECT OSPath, Size, Mtime, Atime, Ctime FROM glob(globs=['C:/inetpub/wwwroot/**/*.aspx', 'C:/inetpub/wwwroot/**/*.php', 'C:/inetpub/wwwroot/**/*.jsp', 'C:/xampp/htdocs/**/*.php']) WHERE NOT IsDir AND Mtime > timestamp(epoch=now() - 2592000)
- name: NetworkConnections
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.ProcessId AS PID, EventData.Image AS ProcessName, EventData.DestinationIp AS DestIP, EventData.DestinationPort AS DestPort FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND NOT EventData.DestinationIp =~ '''^(10\.|192\.168\.|172\.(1[6-9]|2[0-9]|3[01])\.)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1584.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '41165a258a8369681d6376420bcd08c4';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(socat|chisel|ngrok|frp|plink|netcat|nc\.exe)''' OR EventData.CommandLine =~ '(?i)(reverse_tcp|bind_tcp|tunnel|proxy|relay|webshell)') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''(?i)(socat|chisel|ngrok|frp|plink|netcat|nc\.exe)''' OR EventData.CommandLine =~ '(?i)(reverse_tcp|bind_tcp|tunnel|proxy|relay|webshell)') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1584.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'c32e335353a23fce5373cfa8e258bc4f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: BotnetDetection
description: Detect potential botnet communication and infrastructure usage
sources:
- name: NetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessID, EventData.Application, EventData.SourceAddress, EventData.DestAddress, EventData.DestPort
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 5156 AND EventData.DestPort IN ('80', '443', '8080', '53')
    AND NOT EventData.DestAddress =~ '''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|127\.)'''
- name: DNSQueries
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.QueryName, EventData.QueryType, EventData.QueryResults
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client%4Operational.evtx')
    WHERE System.EventID.Value = 3008 AND (len(list=EventData.QueryName) > 20 OR EventData.QueryName =~ '\\.(tk|ml|ga|cf)$')
- name: SuspiciousProcesses
  query: |
    SELECT Fqdn, Name, Pid, Ppid, CommandLine, Exe, Hash.SHA256
    FROM Artifact.Windows.System.Pslist()
    WHERE CommandLine =~ '(svchost|rundll32|regsvr32).*\\.(tmp|dat|log)' OR Name =~ '''^[a-f0-9]{8,16}\.exe$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1584.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '1397ab7bef8f2054036938833c9c1009';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessID as ProcessId, EventData.Application as Application, EventData.SourceAddress as SourceIP, EventData.DestAddress as DestIP, EventData.DestPort as DestPort FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 5156 AND (EventData.DestPort = '80' OR EventData.DestPort = '443' OR EventData.DestPort = '8080') AND NOT EventData.DestAddress =~ '''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|127\.)'''$orcafix$, updated_at = NOW()
