UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.CompromisedWebServices
description: Detect indicators of compromised web service infrastructure usage
sources:
- name: AuthenticationEvents
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetUserName as Username, EventData.IpAddress as SourceIP, EventData.ProcessName as Process
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.Channel = 'Security' AND System.EventID.Value IN (4624, 4648) AND EventData.LogonType = 3
    AND (EventData.ProcessName =~ '(?i)(chrome|firefox|curl|powershell|python)' OR EventData.TargetUserName =~ '(?i)(api|service|git)')
- name: NetworkConnections
  query: |
    SELECT Fqdn, timestamp(epoch=CreationTime) as ConnectionTime, Pid, Name as ProcessName
    FROM glob(globs='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE Fqdn =~ '''(?i)(github\.com|dropbox\.com|twitter\.com|googleapis\.com|sendgrid\.)'''
    AND State = 'ESTABLISHED'
- name: BrowserCredentials
  query: |
    SELECT URL, username_value as Username, date_created as DateCreated
    FROM glob(globs='C:/Users/*/AppData/Local/Google/Chrome/User Data/*/Login Data')
    WHERE URL =~ '(?i)(github|dropbox|twitter|googleapis|sendgrid)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1584.006' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a5cc87e6dafe78216f0fa545bf0fcb00';

