UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.SocialMediaForensics
description: Collect social media related forensic artifacts for T1585.001
sources:
- name: BrowserHistory
  query: |
    SELECT Timestamp, URL, Title, VisitCount, Browser
    FROM Artifact.Windows.Forensics.BrowserHistory()
    WHERE URL =~ '''(?i)(facebook|linkedin|twitter|instagram|tiktok)\.com'''
    ORDER BY Timestamp DESC
- name: NetworkConnections
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, System.EventID.Value AS EventID, System.Computer AS Computer, EventData
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (5156, 5158)
    AND EventData.DestinationAddress =~ '(?i)(facebook|linkedin|twitter|instagram)'
- name: BrowserDownloads
  query: |
    SELECT SourceURL, TargetPath, StartTime, EndTime, State
    FROM Artifact.Windows.Forensics.Downloads()
    WHERE SourceURL =~ '(?i)(facebook|linkedin|twitter|instagram|social)'
    ORDER BY StartTime DESC
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1585.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '5d5eb6f416973f701f1ad43954ef1f1e';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime), System.EventID.Value, System.Computer AS Computer, EventData.SubjectUserName as Username, EventData.IpAddress as SourceIP, EventData.LogonType as LogonType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4625, 4648)*24*60*60 AND (EventData.LogonType = 3 OR EventData.LogonType = 10) ORDER BY Timestamp DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1585.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '7589cf865f5226064693cb918f183e6f';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.T1585_002.EmailAccountEstablishment
description: Detect evidence of email account establishment activities
sources:
- name: BrowserHistory
  query: "SELECT Timestamp, URL, Title, visit_count FROM glob(globs='C:/Users/*/AppData/Local/Google/Chrome/User Data/*/History') \nWHERE URL =~ '''(?i)(gmail\\.com.*signup|outlook\\.com.*signup|protonmail\\.com.*signup|create.*account)'''\nUNION ALL\nSELECT last_visit_date as Timestamp, url as URL, title as Title, visit_count FROM glob(globs='C:/Users/*/AppData/Roaming/Mozilla/Firefox/Profiles/*/places.sqlite')\nWHERE url =~ '''(?i)(gmail\\.com.*signup|outlook\\.com.*signup|protonmail\\.com.*signup|create.*account)'''\n"
- name: NetworkConnections
  query: |
    SELECT Timestamp, ProcessName, RemoteAddress, RemotePort FROM glob(globs='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE RemoteAddress =~ '(?i)(gmail|outlook|protonmail|tempmail)' OR RemotePort IN (25, 587, 993, 995, 110, 143)
- name: OutlookProfiles
  query: |
    SELECT Key.OSPath, Key.ModTime, Data.value as EmailAccount FROM Artifact.Windows.Registry.NTUser()
    WHERE Key.OSPath =~ 'SOFTWARE.*Outlook.*Profiles.*Account.*Email' AND Key.ModTime > timestamp(epoch=now() - 2592000)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1585.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'a37538a0ee364a9443470adee98faf08';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime), System.Computer AS Computer, System.EventID.Value, Message, EventData FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx') WHERE (System.EventID.Value = 1 AND Message =~ '(?i)(protonmail|tutanota|guerrillamail|10minutemail|tempmail)') OR (System.EventID.Value = 4648 AND Message =~ '''(?i)(smtp|pop3|imap).*(@gmail\.com|@outlook\.com|@yahoo\.com)''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1585.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '3274fed9ad1af5f7b6c3f6547a494223';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.CloudAccountEstablishment
description: Collect evidence of cloud account establishment activities
sources:
- name: ProcessExecution
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, EventData.Data[1] as ProcessName, EventData.Data[5] as CommandLine\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.Channel = 'Security' AND System.EventID.Value = 4688 \nAND (CommandLine =~ '(?i)(aws|azure|gcloud|dropbox|mega)' OR ProcessName =~ '(?i)(aws|azure|gcloud|dropbox|mega)')\n"
- name: BrowserHistory
  query: |
    SELECT url, title, visit_time
    FROM glob(globs='C:/Users/*/AppData/Local/Google/Chrome/User Data/*/History')
    WHERE url =~ '''(?i)(amazonaws\.com|azure\.microsoft\.com|dropbox\.com|mega\.nz|console\.cloud\.google)'''
- name: TypedURLs
  query: |
    SELECT Key.Name as User, Name, Data.value as URL
    FROM Artifact.Windows.Registry.NTUser()
    WHERE Key.Name =~ '''Software\\Microsoft\\Internet Explorer\\TypedURLs'''
    AND Data.value =~ '''(?i)(amazonaws\.com|azure\.microsoft\.com|dropbox\.com|mega\.nz)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1585.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '6634798043a51dbeb54657ba96e8ffbf';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: T1586.CompromiseAccounts.Collection
description: Collect artifacts related to account compromise activities including authentication logs and browser credential access
sources:
- name: AuthenticationEvents
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, System.EventRecordID AS EventRecordID, UserName, EventData.LogonType AS LogonType, EventData.IpAddress AS IpAddress, EventData.WorkstationName AS WorkstationName, EventData.Status AS Status, EventData.SubStatus AS SubStatus,
           EventData.ProcessName AS ProcessName, CommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4624, 4625, 4648, 4768, 4769)
- name: BrowserCredentialAccess
  query: |
    SELECT OSPath, Mtime, Size, hash(path=OSPath) as Hash FROM glob(globs=['C:/Users/*/AppData/Local/*/User Data/*/Login Data',
           'C:/Users/*/AppData/Roaming/Mozilla/Firefox/Profiles/*/logins.json',
           'C:/Users/*/AppData/Local/Microsoft/Edge/User Data/*/Login Data'])
    WHERE Mtime > now() - 604800
- name: SuspiciousNetworkActivity
  query: |
    SELECT Name, CommandLine, Pid, Ppid, CreateTime FROM pslist()
    WHERE Name =~ '''(?i)(chrome|firefox|msedge|iexplore)\.exe''' AND
          CommandLine =~ '(?i)(password|login|signin|account|credential)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1586' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'c07a09224c1d65ae45c360d851a1e44b';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.Channel AS Channel, System.EventID.Value, System.EventRecordID AS EventRecordID, UserName, EventData.LogonType AS LogonType, EventData.IpAddress AS IpAddress, EventData.WorkstationName AS WorkstationName, EventData.Status AS Status, EventData.SubStatus AS SubStatus FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4625) ORDER BY EventTime$orcafix$, updated_at = NOW()
WHERE t_code = 'T1586' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'cd9024dae90f2c1892d00aa9ceef6b51';

