UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS TimeCreated, System.Computer, EventData.Image, EventData.DestinationHostname AS Fqdn, EventData.DestinationPort AS DestPort FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 3 AND EventData.DestinationHostname =~ '''(?i)(facebook|twitter|linkedin|instagram|tiktok)\.(com|net)'''$orcafix$, updated_at = NOW()
