UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.EmailAccountCompromise
description: Detect indicators of email account compromise including authentication anomalies and mailbox rule changes
sources:
- name: AuthenticationEvents
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.LogonType as LogonType, EventData.IpAddress as SourceIP, EventData.TargetUserName as Username, EventData.ProcessName as Process FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4625, 4648) AND EventData.LogonType IN (2, 3, 10)
- name: OutlookRules
  query: |
    SELECT Key, Name, Data.value as RuleData, Data.type as DataType FROM Artifact.Windows.Registry.NTUser() WHERE Key =~ '''Software\\Microsoft\\Office\\.*\\Outlook\\Rules''' OR Key =~ '''Software\\Microsoft\\Exchange\\Client\\Options'''
- name: EmailClientArtifacts
  query: |
    SELECT OSPath, Size, Mtime, Ctime FROM glob(globs=['**/*.ost', '**/*.pst', '**/outlook.exe'], root='C:/') WHERE Mtime > now() - 1209600
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1586.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '7610bd64fa29ed77016e7e6a75041fac';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.LogonType as LogonType, EventData.IpAddress as SourceIP, EventData.TargetUserName as Username, EventData.WorkstationName as Workstation FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4625, 4648) AND EventData.LogonType IN (3, 10) AND EventData.IpAddress != '' AND EventData.IpAddress != '-'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1586.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '8e70a7b9accc4f9b63e01a6c2674db24';

