description: Detect signs of cloud account compromise through local artifacts
sources:
- name: BrowserCredentials
  query: |
    SELECT OSPath, Mtime, Atime, Name, URL, Username
    FROM glob(globs='C:/Users/*/AppData/Local/Google/Chrome/User Data/*/Login Data')
    WHERE URL =~ '''(?i)(aws\.amazon\.com|portal\.azure\.com|console\.cloud\.google\.com|login\.microsoftonline\.com)'''
- name: CloudCLIConfigs
  query: |
    SELECT OSPath, Mtime, Size, Name
    FROM glob(globs=['C:\\Users\\*\\.aws\\**', 'C:\\Users\\*\\.azure\\**', 'C:\\Users\\*\\AppData\\Roaming\\gcloud\\**'])
    WHERE NOT IsDir
- name: CredentialManager
  query: |
    SELECT OSPath, PolicyGuid, Resource, Identity, Mtime
    FROM Artifact.Windows.Sys.CredentialManager()
    WHERE Resource =~ '(?i)(aws|azure|google|cloud)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1586.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '39c04cc53bd9fba494144f6a77a46a54';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName as Username, EventData.TargetUserName as TargetUser, EventData.IpAddress as SourceIP, EventData.LogonType as LogonType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4625, 4648) AND (EventData.ProcessName =~ '(?i)(powershell|cmd|aws|az|gcloud)' OR EventData.TargetUserName =~ '(?i)(aws|azure|gcp|cloud)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1586.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '0d1a4350c03a26326b0a6b1b4fe030e3';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Malware.Development.Indicators
description: Detect indicators of malware development activity including recent executables, compilation artifacts, and development patterns
imports:
- Windows.EventLogs.Evtx
sources:
- name: RecentExecutables
  query: |
    SELECT OSPath, Size, Mtime, Ctime, hash(path=OSPath) AS Hash
    FROM glob(globs=['C:/Users/*/Desktop/*.exe', 'C:/Users/*/Documents/*.exe', 'C:/Users/*/Downloads/*.exe'], accessor='file')
    WHERE NOT IsDir AND Size > 0 AND Mtime > timestamp(epoch=now() - 604800)
- name: PowerShellHistory
  query: |
    LET _hist = SELECT OSPath FROM glob(globs='C:/Users/*/AppData/Roaming/Microsoft/Windows/PowerShell/PSReadLine/ConsoleHost_history.txt')
    SELECT _hist.OSPath AS OSPath, Line, LineNumber
    FROM parse_lines(filename=_hist.OSPath)
    WHERE Line =~ '''(?i)(invoke-obfuscation|invoke-expression|downloadstring|compile|csc\.exe|msbuild)'''
- name: ProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime,
           EventData.ProcessId AS ProcessId,
           EventData.NewProcessName AS Image,
           EventData.CommandLine AS CommandLine
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688
      AND EventData.CommandLine =~ '''(?i)(csc\.exe|msbuild\.exe|devenv\.exe)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1587.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '3fed892793f55427d14d0dc5061e111d';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.T1587002.CodeSigningCertificates
description: Detect development and use of self-signed code signing certificates
sources:
- name: CertificateStores
  query: |
    SELECT Key, Name, Data.value as CertData, Data.type as DataType
    FROM read_reg_key(globs='HKEY_LOCAL_MACHINE/SOFTWARE/Microsoft/SystemCertificates/*/Certificates/*')
    WHERE Name = 'Blob'
- name: CertificateEvents
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, event_id, event_data, EventData.Message AS message
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx')
    WHERE event_id IN (90, 4876, 4877)
- name: CertificateFiles
  query: |
    SELECT OSPath, Size, Created, Modified, Accessed
    FROM glob(globs=['C:/**/*.{cer,crt,p12,pfx}', 'C:/**/cert*'])
    WHERE Size > 0 AND Created > timestamp(epoch=now() - 2592000)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1587.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '15eec3858777b14384c3c1d87d7aedd6';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, computer_name, System.Channel AS channel, event_id, event_data, EventData.Message AS message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx') WHERE event_id = 90 OR (event_id = 4876 OR event_id = 4877) AND EventData.Message =~ '(?i)certificate|signing'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1587.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'a4018471f00710b184224a48e0d24c0b';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: T1587_003_DigitalCertificates
description: Detect creation and installation of self-signed SSL/TLS certificates
sources:
- name: CertificateFiles
  query: |
    SELECT OSPath, Mtime, Ctime, Size, Name,
           upload(file=OSPath) as Upload
    FROM glob(globs=['C:\\Users\\*\\**\\*.{pfx,p12,crt,pem,cer}', 'C:\\Windows\\**\\*.{pfx,p12,crt,pem,cer}'])
    WHERE Mtime > timestamp(epoch=now() - 2592000)
- name: PowerShellCertCommands
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.EventID.Value AS EventID, Message, EventData.ScriptBlockText AS ScriptBlockText
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value IN (4103, 4104)
      AND (Message =~ 'New-SelfSignedCertificate'
           OR Message =~ 'openssl'
           OR Message =~ 'makecert'
           OR EventData.ScriptBlockText =~ '(?i)(certificate|ssl|tls).*(create|generate|new)')
- name: CertificateStores
  query: |
    SELECT Key.OSPath, Key.ModTime, Data.value as CertData
    FROM read_reg_key(globs=['HKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\SystemCertificates\\**', 'HKEY_USERS\\*\\SOFTWARE\\Microsoft\\SystemCertificates\\**'])
    WHERE Key.ModTime > timestamp(epoch=now() - 2592000)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1587.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '418e5788c78402a0b12366eb764d295f';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT OSPath, Mtime, Ctime, Size, Name FROM glob(globs=['C:\Users\*\Documents\**\*.{pfx,p12,crt,pem,cer}', 'C:\\Windows\\Temp\\**\\*.{pfx,p12,crt,pem,cer}', 'C:\\Users\\*\\AppData\\**\\*.{pfx,p12,crt,pem,cer}']) WHERE Mtime > timestamp(epoch=now() - 2592000)$orcafix$, updated_at = NOW()
WHERE t_code = 'T1587.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'da0741cec03042b19e2b1a9a79d4a4f7';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.ExploitDevelopment
description: Detect exploit development activities across multiple data sources
sources:
- name: DebuggingTools
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.NewProcessName AS ProcessImage, EventData.CommandLine AS CommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND EventData.CommandLine =~ '(?i)(windbg|x64dbg|ollydbg|ida|ghidra|immunity|afl-fuzz|peach|boofuzz)'
- name: SuspiciousFiles
  query: |
    SELECT OSPath, Size, Mtime, Atime FROM glob(globs='C:/Users/*/Documents/**/*.{py,c,cpp,exe}', accessor='file') WHERE Data =~ '''(?i)(shellcode|\\x90|\\xcc|ROP|exploit|CVE-)''' AND Mtime > now() - 2592000
- name: CompilerActivity
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime, EventData.NewProcessName AS ProcessImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE EventData.NewProcessName =~ '''(?i)(gcc|cl\.exe|link\.exe|python\.exe)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1587.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'c64e99c69772d8c6dfc4fd9da659ce9e';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '(?i)(windbg|x64dbg|ollydbg|ida|ghidra|immunity|afl-fuzz|peach|boofuzz)' OR EventData.Image =~ '''(?i)(compiler|gcc|cl\.exe|link\.exe)''') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.CommandLine =~ '(?i)(windbg|x64dbg|ollydbg|ida|ghidra|immunity|afl-fuzz|peach|boofuzz)' OR EventData.NewProcessName =~ '''(?i)(compiler|gcc|cl\.exe|link\.exe)''') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1587.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'e2e74eb29962b5e4027e07b46ce4eabb';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: T1588_ObtainCapabilities_Detection
description: Detect evidence of adversaries obtaining capabilities through downloads, purchases, or theft
imports:
- Windows.Forensics.Chrome
sources:
- name: WindowsDefenderMalwareDetection
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ThreatName AS ThreatName,
           EventData.Path AS FilePath,
           EventData.ProcessName AS Process,
           System.EventRecordID AS EventRecordID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Windows Defender%4Operational.evtx')
    WHERE System.EventID.Value IN (1116, 1117, 1006, 1007) AND EventData.ThreatName
- name: PowerShellDownloadActivity
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.ScriptBlockText AS Command,
           EventData.Path AS ScriptPath,
           System.Security.UserID AS UserSID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104 AND EventData.ScriptBlockText =~ '(?i)(downloadstring|downloadfile|invoke-webrequest|wget|curl|iwr)'
- name: BrowserDownloadHistory
  query: |
    SELECT url, title, visit_time, download_path
    FROM glob(globs='C:/Users/*/AppData/Local/Google/Chrome/User Data/*/History')
    WHERE url =~ '''(?i)(github\.com.*\.(exe|zip|rar|7z|ps1|bat|py)|pastebin\.com|exploit|payload|malware)'''
       OR title =~ '(?i)(exploit|payload|hack|tool|rat|backdoor)'
$orcafix$, updated_at = NOW()
