UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1588_002.ToolAcquisition
description: Detect acquisition and use of offensive security tools
sources:
- name: OffensiveToolExecution
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, EventData.NewProcessName, EventData.CommandLine, EventData.ParentProcessName\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value = 4688 \nAND (EventData.NewProcessName =~ '(?i)(mimikatz|rubeus|bloodhound|cobalt|beacon)'\nOR EventData.CommandLine =~ '(?i)(invoke-mimikatz|invoke-bloodhound|powersploit)')\n"
- name: BrowserDownloads
  query: |
    SELECT url, visit_time, download_path
    FROM glob(globs='C:/Users/*/AppData/Local/Google/Chrome/User Data/*/History')
    WHERE url =~ '''(?i)(github\.com.*(mimikatz|bloodhound|rubeus|empire)|exploit-db\.com)'''
- name: PowerShellToolDownloads
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, EventData.ScriptBlockText
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value = 4104
    AND EventData.ScriptBlockText =~ '(?i)(invoke-webrequest|wget|curl).*(mimikatz|bloodhound|rubeus|github)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1588.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '2741884b052d137f91110411960f22b6';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.CodeSigningCertificates
description: |
  Detect acquisition and installation of code signing certificates across multiple sources
  including certificate stores, event logs, and file system artifacts.
sources:
- name: CertificateStoreAnalysis
  query: |
    SELECT Key.OSPath as StorePath,
           Key.ModTime as ModificationTime,
           Data.value as CertificateData
    FROM Artifact.Windows.Registry.Sysinternals.Handles()
    WHERE Key.OSPath =~ '''SOFTWARE\\Microsoft\\SystemCertificates'''
- name: CertificateEvents
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           System.EventID.Value AS EventID,
           System.Computer AS Computer,
           EventData.Data AS EventData
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Application.evtx')
    WHERE System.EventID.Value IN (1000, 1001, 1002)
    AND EventData.Data =~ "(?i)(certificate|signing|pfx|p12)"
- name: CertificateFiles
  query: |
    SELECT OSPath, Size, Mtime, Atime, Ctime
    FROM glob(globs="/**/*.{pfx,p12,cer,crt}")
    WHERE Size > 0 AND Mtime > timestamp(epoch="2024-01-01")
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1588.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'ff47b6d3c26509d7a455c348ac262ad7';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, System.Channel AS Channel, System.EventID.Value, EventData.param1 as CertificateThumbprint, EventData.param2 as Subject, EventData.param3 as Issuer FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx') WHERE System.Channel = 'System' AND (System.EventID.Value = 1001 OR System.EventID.Value = 36870 OR System.EventID.Value = 36888)*24*60*60$orcafix$, updated_at = NOW()
WHERE t_code = 'T1588.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '25b0e4c13f144feaba46a26704d21bd1';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: T1588_006.VulnerabilityResearch
description: Detect evidence of vulnerability research and acquisition activities
sources:
