    SELECT downloaded_time, target_path, url FROM Artifact.Windows.Forensics.Downloads() WHERE (target_path =~ '(?i)(exploit|poc|cve|vulnerability)' OR url =~ '''(?i)(github.*exploit|cve|nvd\.nist|exploit-db)''')
- name: RecentFileCreation
  query: |
    SELECT OSPath, Created0x10, Modified0x10, FileSize FROM Artifact.Windows.NTFS.MFT() WHERE Created0x10 > now() - 86400*30 AND OSPath =~ '(?i)(exploit|poc|cve-|vulnerability)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1588.006' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'c60b4cb50a240a227bf1540d116bdda4';

