UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1590_002.DNS.Reconnaissance
description: Detect DNS reconnaissance including zone transfers and subdomain enumeration
sources:
- name: DNSServerLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, System.Channel AS Channel, Message
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.Channel =~ 'DNS Server' AND System.EventID.Value IN (256, 257, 275)
    AND (Message =~ '(?i)axfr' OR Message =~ '(?i)zone transfer')
- name: DNSClientQueries
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, Message
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client%4Operational.evtx')
    WHERE System.EventID.Value = 3008 AND Message =~ '(?i)(nxdomain|query.*fail)'
- name: DNSCache
  query: |
    SELECT OSPath, Mtime, Data
    FROM Artifact.Windows.Registry.NTUser()
    WHERE OSPath =~ '''SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\DNS Client\\Cache'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1590.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '201fb3a4d259358bc86dc3a995054fa5';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, Message, System.EventRecordID AS EventRecordID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client/Operational.evtx') WHERE System.EventID.Value IN (3008, 3020) AND (Message =~ '(?i)(axfr|zone transfer|subdomain|brute|enum)' OR Message =~ '''(?i)[a-z0-9\-]{8,}\.[a-z0-9\-\.]+''' AND Message =~ '(?i)(nxdomain|query failed)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1590.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '6c99a1621b405bf72f4b1dfc4052580b';

