  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.TargetDomainName as TargetDomain, EventData.SubjectDomainName as SourceDomain, EventData.TargetUserName as User, Message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4625, 4648, 4769, 4771) AND EventData.TargetDomainName != EventData.SubjectDomainName
- name: TrustEnumerationCommands
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.ScriptBlockText as Command FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx') WHERE System.EventID.Value = 4104 AND EventData.ScriptBlockText =~ '(?i)(nltest|get-adtrust|get-addomain|dsquery.*trust)'
- name: DNSTrustQueries
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.QueryName as Domain, EventData.QueryType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client%4Operational.evtx') WHERE System.EventID.Value = 3008 AND EventData.QueryName =~ '''(?i)(_ldap\._tcp\.|_kerberos\._tcp\.|_gc\._tcp\.)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1590.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'b6b981549dbc916fba771353cbfd22f6';

