UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: T1598_001_SpearphishingService_Detection
description: Collect evidence of spearphishing via third-party services
sources:
- name: BrowserHistory
  query: |
    SELECT url, title, visit_count, last_visit_time, typed_count
    FROM sqlite(filename=expand(path='%USERPROFILE%/AppData/Local/Google/Chrome/User Data/Default/History'), query='SELECT url, title, visit_count, last_visit_time, typed_count FROM urls')
    WHERE url =~ '(?i)(gmail|yahoo|facebook|linkedin|twitter|instagram|social|webmail|protonmail)'
    AND last_visit_time > timestamp(epoch=now() - 604800)
- name: NetworkConnections
  query: "SELECT Name, CommandLine, Pid, Ppid, Username, \n       {SELECT * FROM connections(pid=Pid)} AS Connections\nFROM pslist()\nWHERE Name =~ '(?i)(chrome|firefox|msedge|opera)'\nAND Connections\n"
- name: RecentFiles
  query: |
    SELECT OSPath, Name, Size, Mtime, Atime, Ctime
    FROM glob(globs=['%USERPROFILE%/AppData/Local/*/User Data/Default/Cache/**', '%USERPROFILE%/AppData/Roaming/Mozilla/Firefox/Profiles/*/cache2/**'])
    WHERE Mtime > timestamp(epoch=now() - 604800)
    AND Size > 0
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1598.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '1e108df6dc4bf0f5dea303c2f56eff9f';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.Channel AS Channel, System.EventID.Value, EventData, Message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Application.evtx') WHERE System.Channel =~ 'Application' AND (Message =~ '(?i)(gmail|yahoo|facebook|linkedin|twitter|instagram|social|webmail)' OR EventData.Data =~ '''(?i)(chrome\.exe|firefox\.exe|msedge\.exe).*--(incognito|private)''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1598.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '77a588c05b47458f26139d93e187429b';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS TimeCreated, System.Computer, System.EventID.Value, EventData.LogonType, EventData.ProcessName, EventData.TargetUserName, EventData.IpAddress FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4625, 4648, 4656) AND (EventData.LogonType = 3 OR EventData.ProcessName =~ '(?i)(outlook|thunderbird|winmail)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1598.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '1e7bf74e63cd83c40e76e58ae0a2bb0a';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.SpearphishingLinks
description: Detect spearphishing link activities across email, browser, and network artifacts
sources:
- name: SuspiciousDNSQueries
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.QueryName as Domain, EventData.QueryType as QueryType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client%4Operational.evtx')
    WHERE System.EventID.Value IN (3008, 3020) AND (
      EventData.QueryName =~ '''(?i)(bit\.ly|tinyurl|goo\.gl|t\.co)''' OR
      EventData.QueryName =~ '(?i)[а-я]' OR
      EventData.QueryName =~ '''(?i)\b(login|secure|account|verify).*\.(tk|ml|ga|cf)\b'''
    )
- name: BrowserPhishingVisits
  query: |
    SELECT url, title, visit_count, last_visit_time
    FROM Artifact.Windows.Applications.Chrome.History()
    WHERE url =~ '(?i)(login|signin|account|verify|secure|update)' AND (
      url =~ '''(?i)\.(tk|ml|ga|cf|bit\.ly)''' OR
      url =~ '(?i)[а-я]' OR
      url =~ '@[0-9]+' OR
      title =~ '(?i)(verify|suspended|locked|expired)'
    )
- name: EmailTrackingPixels
  query: |
    SELECT OSPath, Size, Mtime, Content
    FROM glob(globs='/**/*.{eml,msg}')
    WHERE Content =~ '''(?i)<img[^>]*src=["\']?https?://[^"\'>]*\.(png|gif|jpg)[^"\'>]*["\']?[^>]*>''' AND
    Size < 1000
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1598.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '9900b9e73189820b5e5d5f2548b90b2a';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.QueryName as Domain, EventData.QueryType as QueryType, EventData.QueryResults as Results FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client/Operational.evtx') WHERE System.EventID.Value IN (3008, 3020) AND (EventData.QueryName =~ '''(?i)(bit\.ly|tinyurl|goo\.gl|t\.co)''' OR EventData.QueryName =~ '(?i)[а-я]' OR EventData.QueryName =~ '''(?i)\b(login|secure|account|verify|update|confirm).*\.(tk|ml|ga|cf)\b''')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1598.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '0cb80617a8c685ec1927e7dafb8a0c90';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Network.BoundaryBridging
description: Detect network boundary bridging through firewall events and dual-homed system analysis
sources:
- name: WindowsFilteringPlatformEvents
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, Message,
           EventData.RuleName as RuleName,
           EventData.Direction as Direction,
           EventData.SourceAddress as SourceIP,
           EventData.DestAddress as DestIP,
           EventData.SourcePort as SourcePort,
           EventData.DestPort as DestPort,
           EventData.Protocol as Protocol
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (5152, 5154, 5156, 5157)
      AND EventData.FilterRTID != 0
- name: NetworkAdapterConfigurations
  query: |
    SELECT Key.Name as InterfaceGUID,
           Key.ModTime as LastModified,
           IPAddress, SubnetMask, DefaultGateway, DHCPEnabled
    FROM read_reg_key(globs='HKEY_LOCAL_MACHINE/SYSTEM/CurrentControlSet/Services/Tcpip/Parameters/Interfaces/*')
    WHERE IPAddress OR DefaultGateway
- name: AuditPolicyChanges
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.SubjectUserName as User,
           EventData.CategoryId as Category,
           EventData.AuditPolicyChanges as Changes
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4719
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1599' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'bebd47bccb633460d06512a0af909b9d';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, Message, EventData.RuleName as RuleName, EventData.Direction as Direction, EventData.SourceAddress as SourceIP, EventData.DestAddress as DestIP, EventData.SourcePort as SourcePort, EventData.DestPort as DestPort, EventData.Protocol as Protocol FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (5152, 5154, 5156, 5157) AND EventData.FilterRTID != 0$orcafix$, updated_at = NOW()
WHERE t_code = 'T1599' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '6f0ee12f164a68e127783c95d0e7bb4e';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime), System.Computer AS Computer, System.Channel AS Channel, System.EventID.Value, EventData, EventData.Message AS Message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.Channel =~ '(?i)(System|Security|Application)' AND (Message =~ '(?i)(snmp|netconf|restconf|161|830)' OR EventData =~ '(?i)(configuration.*repository|network.*device.*access|management.*protocol)')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1602' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '4016684a56779c2c1f2e2c23cee6b11e';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.ForgedWebCredentials
description: Detect forged web credentials through authentication anomalies and credential access
sources:
- name: SuspiciousLogons
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.TargetUserName as Username, EventData.IpAddress as SourceIP, \n       EventData.LogonType as LogonType, EventData.AuthenticationPackageName as AuthPackage\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value = 4624 \n  AND EventData.LogonType IN (2, 3, 10)\n  AND EventData.IpAddress != '-'\n  AND NOT EventData.IpAddress =~ '''^(10\\.|172\\.(1[6-9]|2[0-9]|3[01])\\.|192\\.168\\.)'''\n"
- name: CredentialAccess
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.SourceProcessId, EventData.TargetProcessId, \n       EventData.SourceImage, EventData.TargetImage, EventData.CallTrace\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 10\n  AND (EventData.TargetImage =~ 'lsass.exe' \n       OR EventData.TargetImage =~ 'chrome.exe' \n       OR EventData.TargetImage =~ 'firefox.exe')\n"
- name: BrowserCookies
  query: |
    SELECT Mtime, OSPath, Size
    FROM glob(globs=['C:/Users/*/AppData/Local/Google/Chrome/User Data/Default/Cookies',
                     'C:/Users/*/AppData/Local/Google/Chrome/User Data/Default/Network/Cookies',
                     'C:/Users/*/AppData/Roaming/Mozilla/Firefox/Profiles/*/cookies.sqlite'])
    WHERE Mtime > timestamp(epoch=now() - 7*24*60*60)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1606' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '5752110d0282fd538545afd4d8e7e668';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData, System FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4624 AND EventData.LogonType IN (2, 3, 10) AND EventData.IpAddress != '-' AND NOT EventData.IpAddress =~ '''^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.)''' ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1606' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'c2ec3bcee522406d8900c3cb91dc9677';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.ForgedWebCookies
description: Detect forged web cookie activity through browser cookie modification monitoring and authentication correlation
sources:
- name: SuspiciousCookieModification
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, EventData.Image AS ProcessName, EventData.ProcessId AS ProcessId, EventData.TargetFilename AS TargetFilename, EventData.User AS User,\n       hash(function='MD5', string=ProcessName + TargetFilename) as EventHash\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 11 \n  AND (EventData.TargetFilename =~ '''(?i)\\\\(Chrome|Edge|Firefox)\\\\.*\\\\(Cookies|cookies\\.sqlite)$''' \n       OR EventData.TargetFilename =~ '''(?i)\\\\AppData\\\\.*\\\\Cookies''')\n  AND NOT EventData.Image =~ '''(?i)(chrome\\.exe|msedge\\.exe|firefox\\.exe)$'''\n"
- name: AuthenticationWithoutMFA
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.EventID.Value AS EventID, System.Computer AS Computer, EventData.SubjectUserName AS SubjectUserName, EventData.LogonType AS LogonType, EventData.IpAddress AS IpAddress,
           EventData.AuthenticationPackageName AS AuthenticationPackageName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4624, 4648)
      AND EventData.LogonType IN (2, 3, 10)
      AND NOT EventData.AuthenticationPackageName =~ '(?i)(kerberos|ntlm)'
      AND EventData.IpAddress != '-'
- name: BrowserCookieFiles
  query: "SELECT OSPath, Size, Mtime, Atime, Ctime, \n       sqlite(file=OSPath, query='SELECT host_key, name, encrypted_value, creation_utc, last_access_utc FROM cookies ORDER BY creation_utc DESC LIMIT 100') as RecentCookies\nFROM glob(globs=['C:/Users/*/AppData/Local/Google/Chrome/User Data/*/Cookies',\n                'C:/Users/*/AppData/Local/Microsoft/Edge/User Data/*/Cookies',\n                'C:/Users/*/AppData/Roaming/Mozilla/Firefox/Profiles/*/cookies.sqlite'])\nWHERE Size > 0\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1606.001' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'e5a717f74589a83c03887226624343cf';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime), EventData.Image AS ProcessName, EventData.ProcessId AS ProcessId, EventData.TargetFilename AS TargetFilename, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '''(?i)\\(Chrome|Edge|Firefox)\\.*\\(Cookies|cookies\.sqlite)$''' OR EventData.TargetFilename =~ '''(?i)\\AppData\\.*\\Cookies''') AND NOT EventData.Image =~ '''(?i)(chrome\.exe|msedge\.exe|firefox\.exe)$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1606.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'faf1a58b061795db023a1baa069078ed';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.SAMLTokenForging
description: Detect forged SAML tokens by analyzing Windows authentication events and AD FS logs
sources:
- name: SecurityEvents
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.LogonType as LogonType, EventData.TargetUserName as User, EventData.IpAddress as SourceIP
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4624, 4648, 4769, 1200, 1202)
    ORDER BY EventTime DESC
- name: ADFSLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.Message AS Message, EventData
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE (Message =~ 'token' OR Message =~ 'SAML' OR Message =~ 'certificate')
    ORDER BY EventTime DESC
- name: PowerShellHistory
  query: |
    SELECT OSPath, Mtime, Data
    FROM glob(globs='C:/Users/*/AppData/Roaming/Microsoft/Windows/PowerShell/PSReadLine/ConsoleHost_history.txt')
    WHERE Data =~ '(?i)(saml|token|certificate|adfs)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1606.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '8cfef39199df26cd83445817877786d1';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData, Message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4648, 4769) ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1606.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'b05a46124b122fa0c9f446ca7ce1a7e9';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.StageCapabilities
description: Detect adversary staging of capabilities on infrastructure
sources:
- name: DNS_Queries_Staging_Domains
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.QueryName as Domain, EventData.QueryType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/logs/Microsoft-Windows-DNS-Client%4Operational.evtx')
    WHERE System.EventID.Value = 3008 AND EventData.QueryName =~ '''\.(tk|ml|ga|cf|xyz|top)$|pastebin|github|heroku|amazonaws'''
- name: Recent_Downloads_Staging_Tools
  query: |
    SELECT OSPath, Name, Size, Mtime, Ctime
    FROM glob(globs=['C:/Users/*/Downloads/**', 'C:/temp/**', 'C:/Windows/temp/**'])
    WHERE Name =~ '''\.(exe|zip|ps1|bat|dll|scr)$''' AND Ctime > timestamp(epoch=now() - 604800)
- name: Certificate_Store_Analysis
  query: |
    SELECT Key.OSPath.Path as CertPath, Key.ModTime as InstallTime
    FROM glob(globs='HKEY_LOCAL_MACHINE/SOFTWARE/Microsoft/SystemCertificates/*/Certificates/*', accessor='registry')
    WHERE Key.ModTime > timestamp(epoch=now() - 2592000)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1608' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '7d09677cdb206c8a9a394896def86d94';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.QueryName as Domain, EventData.QueryType as RecordType FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client/Operational.evtx') WHERE System.EventID.Value = 3008 AND EventData.QueryName =~ '''\.(tk|ml|ga|cf|xyz|top)$|pastebin|github|heroku|amazonaws'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1608' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '215859a4ab68465b12f47c09110656b3';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.T1608002.ToolStaging
description: Detect evidence of tool staging activities including downloads and web server uploads
sources:
- name: ProcessExecution
  query: |
    SELECT Fqdn, timestamp(epoch=EventTime) AS EventTime, EventData.NewProcessName, EventData.CommandLine, EventData.ParentProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND (EventData.CommandLine =~ '''(?i)(download|wget|curl|invoke-webrequest|github\.com|pastebin\.com)''' OR EventData.NewProcessName =~ '(?i)(psexec|mimikatz|cobalt|beacon)')
- name: FileCreation
  query: |
    SELECT Fqdn, timestamp(epoch=EventTime) AS EventTime, EventData.ObjectName, EventData.ProcessName, EventData.AccessMask
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4656 AND EventData.ObjectName =~ '''(?i)(temp|inetpub|wwwroot).*\.(exe|ps1|bat|vbs|dll)$'''
- name: BrowserDownloads
  query: |
    SELECT OSPath, Name, Mtime, Size
    FROM glob(globs=['C:/Users/*/Downloads/*', 'C:/Users/*/AppData/Local/Temp/*'])
    WHERE Name =~ '''(?i)\.(exe|zip|rar|ps1|bat|dll)$''' AND Mtime > now() - 7*24*60*60
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1608.002' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '5a9264bb7448cbaae29ade01bc636419';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '(?i)(powershell|cmd|cscript|wscript)' AND EventData.CommandLine =~ '''(?i)(download|wget|curl|invoke-webrequest|github\.com|pastebin\.com)''') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '(?i)(powershell|cmd|cscript|wscript)' AND EventData.CommandLine =~ '''(?i)(download|wget|curl|invoke-webrequest|github\.com|pastebin\.com)''') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1608.002' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '480cc1ed6c9503d4ddceba30e200ca42';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1608_003.CertificateInstallation
description: Detect SSL/TLS certificate installation activities across multiple sources
sources:
- name: CertificateEvents
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.Channel AS Channel, System.EventID.Value AS EventID, EventData, \n       get(field='EventData.SubjectName') as SubjectName,\n       get(field='EventData.Issuer') as Issuer\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.Channel =~ '(System|Security)' AND System.EventID.Value IN (1007, 4720)\n"
- name: PowerShellCertificateCommands
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, \n       get(field='EventData.ScriptBlockText') as ScriptBlock\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')\nWHERE System.Channel = 'Microsoft-Windows-PowerShell/Operational' AND System.EventID.Value = 4103 AND EventData =~ '.*(Import-Certificate|New-SelfSignedCertificate|Add-Certificate).*'\n"
- name: CertificateFiles
  query: |
    SELECT OSPath, Size, Mtime, Ctime, Btime
    FROM glob(globs=['C:/Users/*/AppData/Roaming/Microsoft/SystemCertificates/**/*.cer',
                    'C:/ProgramData/Microsoft/Crypto/RSA/MachineKeys/*',
                    'C:/**/*.{crt,cer,p12,pfx}'])
    WHERE Mtime > timestamp(epoch=now() - 2592000)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1608.003' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '872c9d00d7741f27fce2c0dde5eff631';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.Channel AS Channel, System.EventID.Value, EventData FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.Channel =~ '(System|Security|Microsoft-Windows-PowerShell/Operational)' AND (System.EventID.Value = 1007 OR System.EventID.Value = 4720 OR (System.EventID.Value = 4103 AND EventData =~ '.*(Import-Certificate|New-SelfSignedCertificate|Add-Certificate).*'))$orcafix$, updated_at = NOW()
WHERE t_code = 'T1608.003' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '8c6994bf09ffc15daf1640b056b0772a';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.DriveByTargetDetection
description: Detect potential drive-by target staging through browser artifacts and DNS analysis
sources:
- name: BrowserHistory
  query: |
    SELECT url, title, visit_count, last_visit_time
    FROM sqlite(file=expand(path='%USERPROFILE%/AppData/Local/Google/Chrome/User Data/Default/History'), query='SELECT url, title, visit_count, last_visit_time FROM urls WHERE last_visit_time > ?', args=[timestamp(epoch=now() - 604800)])
    WHERE url =~ '(?i)(suspicious|typo|homoglyph)'
- name: DNSResolution
  query: |
    SELECT System.TimeCreated as Timestamp, EventData.QueryName as Domain, EventData.QueryResults as IP
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client%4Operational.evtx')
    WHERE System.EventID.Value = 3008
- name: BrowserCache
  query: |
    SELECT OSPath, Size, Mtime, hash(path=OSPath) as Hash
    FROM glob(globs=['%USERPROFILE%/AppData/Local/*/Cache/**/*.js', '%USERPROFILE%/AppData/Local/*/Cache/**/*.html'])
    WHERE Mtime > now() - 604800
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1608.004' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'ac2f2be4887e95e2d01e426ecde58597';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS SystemTime, EventData.QueryName as Domain, EventData.QueryType as QueryType, EventData.QueryResults as Results FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx') WHERE System.EventID.Value = 3008 AND EventData.QueryName =~ '(?i)(homoglyph|typo|suspicious_tld_pattern)'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1608.004' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'b7854832becc2a0720719caf2e7b1bcf';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.LinkTargetAnalysis
description: Detect staging of malicious link targets through DNS queries, browser activity, and network connections
imports:
- Windows.EventLogs.Evtx
- Windows.Forensics.Srum
sources:
- name: SuspiciousDNSQueries
  query: |
    SELECT System.TimeCreated as Timestamp, EventData.QueryName as Domain, EventData.QueryType as Type, System.Computer as Host
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client%4Operational.evtx')
    WHERE System.EventID.Value = 3008 AND (EventData.QueryName =~ '''(?i)(bit\.ly|tinyurl|goo\.gl|t\.co|short|redirect)''' OR EventData.QueryName =~ '''(?i)[0-9a-f]{8,}\.''' OR len(list=EventData.QueryName) > 50)
- name: BrowserHistoryAnalysis
  query: |
    SELECT url, title, visit_count, last_visit_time, typed_count
    FROM sqlite(file=expand(path='%USERPROFILE%/AppData/Local/Google/Chrome/User Data/Default/History'), query='SELECT url, title, visit_count, last_visit_time, typed_count FROM urls')
    WHERE url =~ '''(?i)(bit\.ly|tinyurl|goo\.gl|t\.co|short|redirect)''' OR url =~ '''(?i)https?://[0-9a-f]{8,}\.''' OR len(list=url) > 100
- name: NetworkConnections
  query: |
    SELECT TimeStamp, AppId, ConnectedTime, ConnectStartTime, InterfaceLuid, L2ProfileId
    FROM Artifact.Windows.Forensics.Srum()
    WHERE AppId =~ '(?i)(chrome|firefox|edge|iexplore)' AND ConnectedTime > 0
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1608.005' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '47fd31a6a6501aebacba7b4254f4c5f2';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT System.TimeCreated AS SystemTime, EventData.QueryName as DomainQueried, EventData.QueryType as QueryType, System.Computer as Hostname FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-DNS-Client/Operational.evtx') WHERE System.EventID.Value = 3008 AND EventData.QueryName =~ '''(?i)(bit\.ly|tinyurl|goo\.gl|t\.co|short|redirect)''' OR EventData.QueryName =~ '''(?i)[0-9a-f]{8,}\.''' OR len(str=EventData.QueryName) > 50$orcafix$, updated_at = NOW()
WHERE t_code = 'T1608.005' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '432e3c8b8727a434457f8d2784fc3850';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: SEO_Poisoning_Investigation
description: Collect artifacts related to SEO poisoning and drive-by compromise attempts
sources:
- name: Browser_History_Analysis
  query: |
    SELECT OSPath, Mtime, url, title, visit_count, typed_count
    FROM Artifact.Windows.Applications.Chrome.History()
    WHERE url =~ '(?i)(search|google|bing|yahoo)' AND visit_count > 0
    UNION ALL
    SELECT OSPath, Mtime, url, title, visit_count, typed_count
    FROM Artifact.Windows.Applications.Firefox.History()
    WHERE url =~ '(?i)(search|google|bing|yahoo)' AND visit_count > 0
- name: Suspicious_Process_Creation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.NewProcessName as ProcessName,
           EventData.CommandLine as CommandLine,
           EventData.ParentProcessName as ParentProcess
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND EventData.ParentProcessName =~ '''(?i)(chrome\.exe|firefox\.exe|msedge\.exe|iexplore\.exe)'''
- name: Downloaded_Files_Timeline
  query: |
    SELECT OSPath, Name, Size, Mtime, Ctime
    FROM Artifact.Windows.NTFS.MFT()
    WHERE OSPath =~ '(?i)(downloads|temp|cache)'
      AND Name =~ '''\.(exe|zip|rar|js|vbs|ps1|bat|cmd)$'''
      AND Mtime > timestamp(epoch=now() - 604800)
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1608.006' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '24c80a2b66fae8092de4c1f5e61b8dd2';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)(chrome\.exe|firefox\.exe|msedge\.exe|iexplore\.exe)''' OR EventData.Image =~ '''(?i)(powershell\.exe|cmd\.exe|wscript\.exe|cscript\.exe|mshta\.exe)''') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.ParentProcessName =~ '''(?i)(chrome\.exe|firefox\.exe|msedge\.exe|iexplore\.exe)''' OR EventData.NewProcessName =~ '''(?i)(powershell\.exe|cmd\.exe|wscript\.exe|cscript\.exe|mshta\.exe)''') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1608.006' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '7465b8f3104a221d2431f193ca315c5a';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Containers.DeployContainer
description: Detect malicious container deployment across Docker and Kubernetes environments
sources:
- name: DockerDaemonLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Channel AS Channel, System.EventID.Value AS EventID, EventData.Image as ContainerImage,
           EventData.ContainerID, EventData.CommandLine, EventData.User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.Channel = 'Microsoft-Windows-Containers/Admin'
      AND (System.EventID.Value = 1 OR System.EventID.Value = 5)
      AND (EventData.Image =~ '(?i)(latest|unknown|public)'
           OR EventData.CommandLine =~ '(?i)(--privileged|--cap-add=SYS_ADMIN|hostPID|hostNetwork)')
- name: KubernetesAuditLogs
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.verb as Action,
           EventData.objectRef.resource as Resource,
           EventData.user.username as User,
           EventData.requestObject.spec.containers.securityContext as SecurityContext
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.Channel = 'Application'
      AND EventData.verb IN ('create', 'update')
      AND EventData.objectRef.resource IN ('pods', 'deployments', 'daemonsets')
      AND (EventData.requestObject.spec.containers.securityContext.privileged = 'true'
           OR EventData.requestObject.spec.hostPID = 'true'
           OR EventData.requestObject.spec.hostNetwork = 'true')
- name: ContainerProcessExecution
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS NewProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcessName,
           EventData.ProcessId AS ProcessId, EventData.ProcessId AS ParentProcessId, EventData.SubjectUserName AS User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.Channel = 'Security'
      AND System.EventID.Value = 4688
      AND (EventData.ParentProcessName =~ '(?i)(dockerd|containerd|runc)'
           OR EventData.NewProcessName =~ '(?i)container')
      AND EventData.CommandLine =~ '(?i)(wget|curl|bash|sh|powershell|cmd)'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1610' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '809667ebf21170559fff93a1cf3b120c';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.Image as ContainerImage, EventData.ContainerName, EventData.CommandLine, EventData.PrivilegedMode FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.Channel = 'Microsoft-Windows-Containers/Admin' AND (System.EventID.Value = 1 OR System.EventID.Value = 5) AND (EventData.PrivilegedMode = 'true' OR EventData.Image =~ '(?i)(latest|unknown)' OR EventData.CommandLine =~ '(?i)(--privileged|--cap-add|hostPID|hostNetwork)') ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1610' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '79a6826902efd42be901f527982c2f5b';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, EventData.Image, EventData.CommandLine, EventData.ParentImage, EventData.ParentCommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ 'GetUserDefaultUILanguage|GetSystemDefaultUILanguage|GetKeyboardLayoutList|Get-Culture|Get-SystemPreferredUILanguages|wmic.*oslanguage|locale' OR EventData.CommandLine =~ 'HKLM.*Nls.*Language')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1614.001' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '3894739ab743d08cb2233c762294ce37';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.GroupPolicyDiscovery
description: Detect Group Policy Discovery techniques including gpresult execution and PowerShell GPO enumeration
sources:
- name: SysmonProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime as Timestamp,
           EventData.ProcessId as ProcessId,
           EventData.Image as Image,
           EventData.CommandLine as CommandLine,
           EventData.ParentImage as ParentImage,
           'ProcessCreation' as EventType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND
          (EventData.Image =~ '''gpresult\.exe''' OR
           (EventData.Image =~ '''powershell\.exe''' AND
            EventData.CommandLine =~ '(?i)(Get-DomainGPO|Get-DomainGPOLocalGroup|Get-GPO)'))
- name: PowerShellScriptBlocks
  query: |
    SELECT System.TimeCreated.SystemTime as Timestamp,
           EventData.ScriptBlockText as ScriptBlockText,
           EventData.ScriptBlockId as ScriptBlockId,
           'PowerShellScriptBlock' as EventType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value IN (4103, 4104) AND
          EventData.ScriptBlockText =~ '(?i)(Get-DomainGPO|Get-DomainGPOLocalGroup|Get-GPO|gpresult)'
- name: SecurityLDAPAccess
  query: |
    SELECT System.TimeCreated.SystemTime as Timestamp,
           EventData.SubjectUserName as SubjectUserName,
           EventData.ObjectName as ObjectName,
           EventData.AccessMask as AccessMask,
           'LDAPAccess' as EventType
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4661 AND
          EventData.ObjectName =~ '(?i)groupPolicyContainer'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1615' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '485475da96e89bc331bd37a2d7a167fb';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, System.EventID.Value as EventID, EventData.ProcessId as ProcessId, EventData.Image as Image, EventData.CommandLine as CommandLine, EventData.ParentImage as ParentImage FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''gpresult\.exe''' OR (EventData.Image =~ '''powershell\.exe''' AND EventData.CommandLine =~ '(?i)(Get-DomainGPO|Get-DomainGPOLocalGroup|Get-GPO|gpresult)'))$orcafix$, updated_at = NOW()
WHERE t_code = 'T1615' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '2977212db0dd15f0a3b4259a1151824f';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.TargetUserName as Username, EventData.IpAddress as SourceIP, EventData.LogonType, EventData.Status, EventData.SubStatus FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4625 AND EventData.Status = 0xc000006d ORDER BY Username$orcafix$, updated_at = NOW()
WHERE t_code = 'T1621' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '250f2965608f8e170a4ca204098a069a';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData, Message FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '(?i)(IsDebuggerPresent|CheckRemoteDebuggerPresent|NtQueryInformationProcess|OutputDebugString)' OR EventData.CommandLine =~ '(?i)(BeingDebugged|ProcessDebugPort|TracerPID)' OR EventData.OriginalFileName =~ '(?i)debug')$orcafix$, updated_at = NOW()
WHERE t_code = 'T1622' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '173447b6363a8f4ae1eebe07934ad017';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.CertificateAbuse
description: Detect certificate theft and abuse across multiple Windows log sources
sources:
- name: SecurityEventsCertificates
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.SubjectUserName, EventData.TargetUserName, EventData.CertThumbprint, EventData.ServiceName, Message\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value IN (4768, 4886, 4887, 4657) \nAND (EventData.CertThumbprint OR Message =~ 'PKINIT' OR Message =~ 'SystemCertificates')\n"
- name: CertificateServicesClient
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData, Message
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Windows Defender%4Operational.evtx')
    WHERE System.EventID.Value IN (1003, 1006, 1007)
- name: CertificateRegistryAccess
  query: |
    SELECT OSPath, ModTime, Mtime, Data
    FROM Artifact.Windows.Registry.NTUser()
    WHERE OSPath =~ 'SOFTWARE.Microsoft.SystemCertificates'
    OR OSPath =~ 'SOFTWARE.Microsoft.Crypto'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1649' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'd8b38112f15b06cf87141db7a24b5ec6';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value, EventData.SubjectUserName, EventData.SubjectDomainName, EventData.TargetUserName, EventData.ServiceName, EventData.CertThumbprint, EventData.CertIssuerName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4768, 4886, 4887) AND (EventData.CertThumbprint OR Message =~ 'PKINIT' OR EventData.RequestType)$orcafix$, updated_at = NOW()
WHERE t_code = 'T1649' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'f2d2d5a23916d76cb2438b4628661207';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.TargetUserName AS Username, EventData.IpAddress AS SourceIP, EventData.LogonType AS LogonType, EventData.ProcessName AS ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4624 AND EventData.LogonType IN (2, 3, 10) AND EventData.IpAddress != '-' AND EventData.IpAddress != '127.0.0.1'$orcafix$, updated_at = NOW()
WHERE t_code = 'T1650' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '75b7cf5e7b743e37b494a21730d2613e';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.CloudAdminCommand.Detection
description: Detect cloud administration command execution across multiple sources
sources:
- name: WindowsSSMExecution
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.NewProcessName as ProcessName, \n       EventData.ParentProcessName as ParentProcess, EventData.CommandLine as CommandLine\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') \nWHERE System.EventID.Value = 4688 AND EventData.ParentProcessName =~ '(?i)amazon-ssm-agent|WindowsAzureGuestAgent'\n"
- name: SSMAgentLogs
  query: "SELECT OSPath, Mtime, Size, \n       read_file(filename=OSPath, length=10000) as Content\nFROM glob(globs='C:/ProgramData/Amazon/SSM/Logs/amazon-ssm-agent.log*')\nWHERE Mtime > now() - 86400\n"
- name: AzureGuestAgentLogs
  query: |
    SELECT OSPath, Mtime,
           regex_replace(source=read_file(filename=OSPath, length=50000),
                       re='(?m)^.*RunCommand.*$', replace='$0') as RunCommandEntries
    FROM glob(globs='C:/WindowsAzure/Logs/WaAppAgent.log*')
    WHERE Mtime > now() - 86400 AND RunCommandEntries
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1651' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'df60b7d57385e84babe7e360c4d71dda';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(ssm-session-worker\.exe|WindowsAzureGuestAgent\.exe|powershell\.exe|cmd\.exe)''' AND EventData.ParentImage =~ '(?i)(amazon-ssm-agent|WindowsAzureGuestAgent)') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''(?i)(ssm-session-worker\.exe|WindowsAzureGuestAgent\.exe|powershell\.exe|cmd\.exe)''' AND EventData.ParentProcessName =~ '(?i)(amazon-ssm-agent|WindowsAzureGuestAgent)') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1651' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '373774dee7a07f91b7175a17a23ff623';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.DeviceDriverDiscovery
description: Detect device driver discovery activities across multiple data sources
sources:
- name: ProcessCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS Timestamp, EventData.NewProcessName, EventData.CommandLine, EventData.ParentProcessName, System.Computer AS Computer\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value = 4688 \nAND (EventData.NewProcessName =~ 'driverquery.exe' OR EventData.CommandLine =~ '(?i)(driverquery|Win32_PnPSignedDriver|EnumDeviceDrivers|Get-WmiObject.*Driver)')\nORDER BY Timestamp DESC\n"
- name: RegistryAccess
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image AS Image, EventData.TargetObject AS TargetObject, EventData.Details AS Details, EventData.ProcessId AS ProcessId
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value IN (13, 14)
    AND EventData.TargetObject =~ '''(?i)(HKLM\\SYSTEM\\CurrentControlSet\\Services|HKLM\\SYSTEM\\CurrentControlSet\\Enum)'''
    ORDER BY EventTime DESC
- name: PrefetchAnalysis
  query: |
    SELECT OSPath, Name, Mtime, Atime
    FROM glob(globs='C:/Windows/Prefetch/DRIVERQUERY.EXE-*.pf')
    UNION ALL
    SELECT OSPath, Name, Mtime, Atime
    FROM glob(globs='C:/Windows/Prefetch/POWERSHELL.EXE-*.pf')
    WHERE Mtime > now() - 86400
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1652' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'fc98b1b939aec9913fa11aeb89561027';

