UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.PowerSettingsAbuse
description: Detect T1653 Power Settings modifications for persistence
sources:
- name: PowerCfgProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.NewProcessName, EventData.CommandLine, EventData.ParentProcessName, EventData.SubjectUserName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688 AND EventData.NewProcessName =~ '''(?i)powercfg\.exe'''
    AND EventData.CommandLine =~ '(?i)(sleep|hibernate|standby|timeout|scheme|/change|/setactive)'
- name: PowerShellHistory
  query: |
    SELECT OSPath, Mtime, Size, read_file(filename=OSPath) AS Content
    FROM glob(globs='C:/Users/*/AppData/Roaming/Microsoft/Windows/PowerShell/PSReadLine/ConsoleHost_history.txt')
    WHERE Content =~ '(?i)(powercfg|sleep|hibernate|standby)'
- name: PowerRegistryKeys
  query: |
    SELECT Key.OSPath, Key.ModTime, Key.Name, Data.Name AS ValueName, Data.Value
    FROM Artifact.Windows.Registry.NTUser()
    WHERE Key.OSPath =~ '(?i)HKEY_LOCAL_MACHINE.+Control.+Power'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1653' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'df44649964bc4b6a82dc87ef1ae2ba7f';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)powercfg\.exe''' AND EventData.CommandLine =~ '(?i)(sleep|hibernate|standby|timeout|scheme)') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''(?i)powercfg\.exe''' AND EventData.CommandLine =~ '(?i)(sleep|hibernate|standby|timeout|scheme)') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1653' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '045c04eaf97e2f688c9485b6c83fd03d';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.T1654.LogEnumeration
description: Detect log enumeration activities across multiple event sources
sources:
- name: ProcessExecution
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId, \n       EventData.NewProcessName as Image, EventData.CommandLine as CommandLine\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value = 4688 AND (EventData.CommandLine =~ '(?i)wevtutil' OR \n                          EventData.CommandLine =~ '(?i)Get-WinEvent' OR \n                          EventData.CommandLine =~ '(?i)Get-EventLog')\n"
- name: ObjectAccess
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ProcessId as ProcessId,\n       EventData.ObjectName as ObjectName, EventData.AccessMask as AccessMask\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value IN (4656, 4663, 4670) AND \n      EventData.ObjectName =~ '''(?i).*\\.evtx$|.*\\\\winevt\\\\logs\\\\'''\n"
- name: PowerShellActivity
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.ScriptBlockText as ScriptBlock\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')\nWHERE System.EventID.Value IN (4103, 4104) AND \n      EventData.ScriptBlockText =~ '(?i)Get-WinEvent|Get-EventLog|Export.*Log'\n"
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1654' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '65fb2ff3da573cff45e4ff38d26c0a86';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.FinancialTheft
description: Detect financial theft indicators across multiple Windows artifacts
sources:
- name: SuspiciousFinanceLogins
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.EventID.Value AS EventID, System.Computer AS Computer, AccountName, EventData.LogonType AS LogonType, EventData.IpAddress AS IpAddress, EventData.ProcessName AS ProcessName\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value IN (4624, 4648) \nAND (EventData.ProcessName =~ '(?i)(QuickBooks|SAP|Workday|Oracle)' \n     OR AccountName =~ '(?i)(finance|treasury|accounting)')\n"
- name: OutlookRuleChanges
  query: |
    SELECT Key, timestamp, Data
    FROM Artifact.Windows.Registry.NTUser()
    WHERE Key =~ 'Software/Microsoft/Office/.*/Outlook/Rules'
- name: ClipboardCryptoWallets
  query: |
    SELECT EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 1 AND EventData.CommandLine =~ '[13][a-km-zA-HJ-NP-Z1-9]{25,34}|bc1[a-z0-9]{39,59}'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1657' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '60ffac05c6d48e58a463de7757314e56';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.EventID.Value, System.Computer AS Computer, SecurityID, AccountName, EventData.LogonType AS LogonType, EventData.IpAddress AS IpAddress, EventData.ProcessName AS ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (4624, 4648) AND (EventData.ProcessName =~ '(?i)(QuickBooks|SAP|Workday|Oracle|Peachtree)' OR AccountName =~ '(?i)(finance|treasury|accounting|payroll)' OR NOT (EventData.IpAddress IN ('127.0.0.1', '::1')) AND EventData.LogonType IN (2, 3, 10))$orcafix$, updated_at = NOW()
WHERE t_code = 'T1657' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '57fb9819a4a05708ff4a53918bd1a2d6';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: ContentInjectionDetection
description: Detect T1659 Content Injection through browser-spawned processes and suspicious file creation
sources:
- name: BrowserChildProcesses
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.NewProcessName AS ProcessName,
           EventData.ParentProcessName AS ParentProcess,
           EventData.CommandLine AS CommandLine,
           EventData.ProcessId AS PID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688
      AND EventData.ParentProcessName =~ '''(?i)(chrome\.exe|firefox\.exe|msedge\.exe|iexplore\.exe)$'''
      AND (EventData.NewProcessName =~ '''(?i)\.(exe|scr|bat|cmd|ps1|vbs|js)$'''
           OR EventData.CommandLine =~ '(?i)(powershell|cmd|wscript|cscript)')
- name: SuspiciousFileCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.TargetFilename AS FilePath,
           EventData.ProcessId AS PID,
           EventData.Image AS ProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 11
      AND EventData.Image =~ '''(?i)(chrome\.exe|firefox\.exe|msedge\.exe|iexplore\.exe)$'''
      AND EventData.TargetFilename =~ '''(?i)(temp|appdata|downloads).*\.(exe|dll|js|vbs|bat|cmd|ps1|scr)$'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1659' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '0e9a2288ff346176d4c80ad117d4f406';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.ParentImage =~ '''(?i)(chrome\.exe|firefox\.exe|msedge\.exe|iexplore\.exe)$''' AND EventData.Image =~ '(?i)(temp|appdata|downloads)') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.ParentProcessName =~ '''(?i)(chrome\.exe|firefox\.exe|msedge\.exe|iexplore\.exe)$''' AND EventData.NewProcessName =~ '(?i)(temp|appdata|downloads)') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1659' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '65b6b94ef06450d9341ef5dafb420274';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.DestAddress as DestIP, EventData.DestPort, EventData.Protocol, EventData.ProcessID, EventData.Application FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value IN (5156, 5157) AND EventData.DestAddress =~ '^(?!10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.)' ORDER BY EventTime DESC$orcafix$, updated_at = NOW()
WHERE t_code = 'T1665' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'b45a0f5b3f99d5366f15203e4409bb04';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, EventData.TargetFilename AS FilePath, EventData.ProcessId AS PID, EventData.Image AS ProcessName FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 11 AND (EventData.TargetFilename =~ '''(?i)\\mail\|\\pst\|\\ost\|\.pst$|\.ost$|\.eml$|\.msg$''') AND timestamp(epoch=System.TimeCreated.SystemTime) > timestamp(epoch=now() - 86400)$orcafix$, updated_at = NOW()
WHERE t_code = 'T1667' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '8a78d35abf0bebb298af730ce6dcb0b2';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.ExclusiveControl
description: Detect adversary attempts to maintain exclusive control by disabling services and terminating competing processes
sources:
- name: ServiceStopCommands
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.NewProcessName AS ProcessName,
           EventData.CommandLine AS CommandLine,
           EventData.SubjectUserName AS User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688
      AND EventData.CommandLine =~ '(?i)(net\\s+stop|sc\\s+stop|Stop-Service)'
      AND EventData.CommandLine =~ '(?i)(rdp|ssh|ftp|http|mysql|vulnerable)'
- name: ProcessTerminations
  query: |
    SELECT System.TimeCreated.SystemTime AS Timestamp,
           EventData.Image AS ProcessImage,
           EventData.ProcessId AS PID,
           EventData.User AS User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 5
      AND EventData.Image =~ '(?i)(malware|competitor|vulnerable)'
- name: ServiceRegistryChanges
  query: |
    SELECT OSPath, Mtime, Data.value AS ServiceConfig
    FROM glob(globs='HKEY_LOCAL_MACHINE/SYSTEM/CurrentControlSet/Services/*/Start')
    WHERE Mtime > now() - 86400
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1668' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '6f02cb499eb3d671b2f5316d4891fc33';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND ((EventData.CommandLine =~ '''(?i)(net\s+stop|sc\s+stop|Stop-Service|kill\s+-9)''' OR EventData.Image =~ '''(?i)(net\.exe|sc\.exe|powershell\.exe)$''') AND EventData.CommandLine =~ '(?i)(rdp|ssh|telnet|ftp|http|apache|nginx|iis|mysql|postgres|oracle)') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND ((EventData.CommandLine =~ '''(?i)(net\s+stop|sc\s+stop|Stop-Service|kill\s+-9)''' OR EventData.NewProcessName =~ '''(?i)(net\.exe|sc\.exe|powershell\.exe)$''') AND EventData.CommandLine =~ '(?i)(rdp|ssh|telnet|ftp|http|apache|nginx|iis|mysql|postgres|oracle)') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1668' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'd7f8485feeb471daab4924dcca2e2d89';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Custom.Windows.WiFiActivity
description: Collect Wi-Fi network connection events and authentication attempts across multiple log sources
sources:
- name: WLANAutoConfigEvents
  query: |
    SELECT System.TimeCreated.SystemTime as Timestamp, System.EventID.Value as EventID, System.Computer as Computer, EventData.SSID as SSID, EventData.ProfileName as ProfileName, EventData.ConnectionMode as ConnectionMode, EventData.ReasonCode as ReasonCode
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx')
    WHERE System.EventID.Value IN (8001, 8002, 8003) AND EventData.SSID != ''
- name: SecurityAuthEvents
  query: |
    SELECT System.TimeCreated.SystemTime as Timestamp, System.EventID.Value as EventID, EventData.LogonType as LogonType, EventData.Status as Status, EventData.SubStatus as SubStatus, EventData.TargetUserName as TargetUserName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value IN (4776, 4625) AND (EventData.LogonProcessName =~ 'Wireless' OR EventRecordID IN (SELECT EventRecordID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE Message =~ '''802\.1[Xx]'''))
- name: WirelessProfiles
  query: |
    SELECT OSPath, Size, Mtime as Modified, read_file(filename=OSPath) as ProfileContent
    FROM glob(globs='C:/ProgramData/Microsoft/Wlansvc/Profiles/Interfaces/*/{}*', accessor='file')
    WHERE Size > 0
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1669' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '846865749e283088b094cf06a6792c8e';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS TimeCreated, System.Computer, EventData.SubjectUserName as User, EventData.ApplicationName as Application, EventData.ConsentType as ConsentType, EventData.Scope as Permissions FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-AAD.evtx') WHERE System.EventID.Value IN (1006, 1007, 1008) AND EventData.ApplicationName$orcafix$, updated_at = NOW()
WHERE t_code = 'T1671' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = 'b6bee469ba985091417561c101d49e7a';

UPDATE ref_artifact_library SET custom_vql = $orcafix$LET sysmon = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.Image AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.User AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.Image =~ '''(?i)(vmrun\.exe|VBoxManage\.exe|powershell\.exe)''' OR EventData.CommandLine =~ '(?i)(Get-VM|Get-HyperVVM|esxcli vm|vim-cmd vmsvc)') LET security = SELECT System.TimeCreated AS EventTime, System.Computer AS Computer, EventData.NewProcessName AS ProcessName, EventData.CommandLine AS CommandLine, EventData.ParentProcessName AS ParentProcess, EventData.SubjectUserName AS User FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx') WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ '''(?i)(vmrun\.exe|VBoxManage\.exe|powershell\.exe)''' OR EventData.CommandLine =~ '(?i)(Get-VM|Get-HyperVVM|esxcli vm|vim-cmd vmsvc)') SELECT * FROM chain(a={SELECT * FROM sysmon}, b={SELECT * FROM if(condition=len(list=sysmon)=0, then={SELECT * FROM security})})$orcafix$, updated_at = NOW()
WHERE t_code = 'T1673' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '1ffbb21994b3f8c7db5f93b9d3070b6a';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.InputInjection
description: Detect USB HID keystroke injection attacks by correlating device enumeration with rapid script execution
sources:
- name: USBDeviceEnumeration
  query: |
    SELECT System.TimeCreated.SystemTime AS USBTime, EventData.VendorID, EventData.ProductID, EventData.DeviceInstanceID
    FROM parse_evtx(filename=expand(path='%SystemRoot%/System32/winevt/Logs/System.evtx'))
    WHERE System.EventID.Value = 2003 AND EventData.CompatibleIDs =~ 'USB\\\\Class_03'
- name: PowerShellExecution
  query: |
    SELECT System.TimeCreated.SystemTime AS PSTime, EventData.ScriptBlockText, EventData.Path
    FROM parse_evtx(filename=expand(path='%SystemRoot%/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx'))
    WHERE System.EventID.Value IN (4103, 4104) AND EventData.ScriptBlockText != ''
- name: ProcessCreation
  query: |
    SELECT System.TimeCreated.SystemTime AS ProcTime, EventData.NewProcessName, EventData.CommandLine, EventData.ParentProcessName
    FROM parse_evtx(filename=expand(path='%SystemRoot%/System32/winevt/Logs/Security.evtx'))
    WHERE System.EventID.Value = 4688 AND (EventData.NewProcessName =~ 'powershell.exe' OR EventData.NewProcessName =~ 'cmd.exe')
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1674' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '58520e37e737181e108333bd6deef42f';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS SystemTime, EventData.VendorID, EventData.ProductID, EventData.DeviceInstanceID FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/System.evtx') WHERE System.EventID.Value = 2003 AND EventData.CompatibleIDs =~ '''USB\\Class_03''' AND timestamp(epoch=System.TimeCreated.SystemTime) > now() - 86400$orcafix$, updated_at = NOW()
WHERE t_code = 'T1674' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '93d6eed0916b2223d50339c7f63906db';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Custom.DelayExecution.T1678
description: Detect time-based evasion techniques including sleep commands, API delays, and scheduled execution patterns
sources:
- name: SysmonProcessCreation
  query: "SELECT System.TimeCreated.SystemTime AS EventTime,\n       EventData.Image AS ProcessPath,\n       EventData.CommandLine AS CommandLine,\n       EventData.ParentImage AS ParentProcess,\n       EventData.ProcessId AS PID\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 \n  AND (EventData.CommandLine =~ '''sleep|timeout|ping\\s+-[nt]|Start-Sleep|Thread\\.Sleep'''\n       OR (EventData.Image =~ '''(wscript|cscript|powershell)\\.exe$''' AND EventData.ParentImage =~ '''cmd\\.exe$'''))\n"
- name: SysmonImageLoads
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.Image AS ProcessPath,
           EventData.ImageLoaded AS LoadedModule,
           EventData.ProcessId AS PID
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')
    WHERE System.EventID.Value = 7
      AND EventData.ImageLoaded =~ '''(kernel32|ntdll)\.dll$'''
      AND EventData.Image =~ '''(wscript|cscript|powershell|rundll32)\.exe$'''
- name: PowerShellDelayCommands
  query: |
    SELECT System.TimeCreated.SystemTime AS EventTime,
           EventData.ScriptBlockText AS ScriptContent,
           EventData.Path AS ScriptPath
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value IN (4103, 4104)
      AND EventData.ScriptBlockText =~ '''Start-Sleep|Thread::Sleep|\[Threading\.Thread\]::Sleep'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1678' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'b4a9ccf83599cb6a5f77f52d9de7de27';

UPDATE ref_artifact_library SET custom_vql = $orcafix$SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, EventData.Image AS ProcessPath, EventData.CommandLine AS CommandLine, EventData.ParentImage AS ParentProcess, EventData.ParentCommandLine AS ParentCommandLine FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx') WHERE System.EventID.Value = 1 AND (EventData.CommandLine =~ '''sleep|timeout|ping\s+-[nt]|Start-Sleep|Thread\.Sleep|NtDelayExecution''' OR EventData.Image =~ '''(wscript|cscript|powershell|cmd)\.exe$''') AND EventData.ParentImage =~ '''(wscript|cscript|powershell|rundll32|regsvr32)\.exe$'''$orcafix$, updated_at = NOW()
WHERE t_code = 'T1678' AND md5(replace(COALESCE(custom_vql, ''), chr(13), '')) = '0d190fb318db9f7d4111dbd9d34d17f3';

UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Ransomware.SelectiveExclusion
description: Detect selective exclusion behavior indicating ransomware file enumeration and targeting
sources:
- name: PowerShellEnumeration
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.ProcessName, EventData.ScriptBlockText, EventData.ProcessId\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')\nWHERE System.EventID.Value IN (4103, 4104, 4105, 4106) \nAND EventData.ScriptBlockText =~ '''(?i)(Get-ChildItem|dir).*(\\.(dll|exe|sys|lnk))|exclude.*Program Files'''\n"
- name: FileAccessPatterns
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, System.EventID.Value AS EventID, EventData.ProcessName, EventData.ObjectName, EventData.AccessMask\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')\nWHERE System.EventID.Value IN (4663, 4656) \nAND EventData.ObjectName =~ '''(?i)\\.(dll|exe|sys)$|Program Files|Windows\\\\System32'''\n"
- name: ProcessCreation
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS EventTime, System.Computer AS Computer, EventData.NewProcessName, EventData.CommandLine, EventData.ParentProcessName
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Security.evtx')
    WHERE System.EventID.Value = 4688
    AND EventData.CommandLine =~ '''(?i)(encrypt|exclude|skip).*\.(dll|exe|sys)'''
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1679' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = '8157d9538bad60c3ee9657e8821c6ac7';

