UPDATE ref_artifact_library SET surgical_yaml = $orcafix$name: Windows.Detection.LocalStorageDiscovery
description: |
  Detects local storage discovery techniques across Windows systems including
  PowerShell, WMIC, and API-based enumeration methods.
sources:
- name: SysmonProcessCreation
  query: "SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.CommandLine as CommandLine,\n       EventData.User as User, EventData.ParentImage as ParentImage\nFROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-Sysmon%4Operational.evtx')\nWHERE System.EventID.Value = 1 \nAND (EventData.CommandLine =~ 'wmic.*logicaldisk' OR \n     EventData.CommandLine =~ 'Get-PSDrive' OR \n     EventData.CommandLine =~ 'GetDriveType')\nAND NOT EventData.User =~ 'SYSTEM|NETWORK SERVICE|LOCAL SERVICE'\n"
- name: PowerShellOperational
  query: |
    SELECT timestamp(epoch=System.TimeCreated.SystemTime) AS timestamp, System.Computer AS Computer, EventData.ScriptBlockText as ScriptContent,
           UserData.EventXML.User as User
    FROM parse_evtx(filename='C:/Windows/System32/winevt/Logs/Microsoft-Windows-PowerShell%4Operational.evtx')
    WHERE System.EventID.Value IN (4103, 4104)
    AND EventData.ScriptBlockText =~ 'Get-PSDrive'
- name: ShellHistory
  query: |
    SELECT OSPath, read_file(filename=OSPath) as Content,
           Mtime, Atime, Ctime
    FROM glob(globs='C:/Users/*/AppData/Roaming/Microsoft/Windows/PowerShell/PSReadline/ConsoleHost_history.txt')
    WHERE Content =~ 'Get-PSDrive|wmic.*logicaldisk'
$orcafix$, updated_at = NOW()
WHERE t_code = 'T1680' AND md5(replace(COALESCE(surgical_yaml, ''), chr(13), '')) = 'e97afdc274b9eb06b9f6239c3cd23dfe';

